def validate_config(cfg: dict[str, Any] | None) -> dict[str, Any]:
    c = deep_merge(DEFAULT_CONFIG, cfg or {})
    unknown = sorted(set(c) - set(DEFAULT_CONFIG))
    if unknown:
        raise ConfigError(f"알 수 없는 설정 키: {unknown}")

    def pos_int(v: Any, what: str, lo: int = 1) -> int:
        if isinstance(v, bool) or int(v) != float(v) or int(v) < lo:
            raise ConfigError(f"{what} 는 {lo} 이상 정수다: {v!r}")
        return int(v)

    def num(v: Any, what: str, lo: float | None = None, hi: float | None = None, lo_open: bool = False) -> float:
        f = float(v)
        if not math.isfinite(f) or (lo is not None and (f <= lo if lo_open else f < lo)) or (hi is not None and f > hi):
            raise ConfigError(f"{what} 범위 오류: {v!r}")
        return f

    d = c["data"]
    if d["source"] not in ("mnist", "folder"):
        raise ConfigError("data.source 는 mnist 또는 folder 다.")
    pos_int(d["mnist_dev_size"], "data.mnist_dev_size", 10)
    if int(d["mnist_dev_size"]) > 59990:
        raise ConfigError("data.mnist_dev_size 는 59990 이하다 (클래스별 train/dev 확보).")
    if not isinstance(d["mnist_download"], bool):
        raise ConfigError("data.mnist_download 는 true 또는 false 다.")
    pos_int(d["image_size"], "data.image_size", 16)
    r = d["split_ratios"]
    if set(r) != {"train", "dev", "test"} or any(float(v) <= 0 for v in r.values()) or abs(sum(map(float, r.values())) - 1.0) > 1e-9:
        raise ConfigError("data.split_ratios 는 train/dev/test 가 모두 양수이고 합이 1 이다.")
    re.compile(str(d["group_suffix_regex"]))
    num(d["transparent_background"], "data.transparent_background", 0.0, 1.0)
    rt = c["retina"]
    num(rt["sigma_center_px"], "retina.sigma_center_px", 0.0, lo_open=True)
    if float(rt["sigma_surround_px"]) <= float(rt["sigma_center_px"]):
        raise ConfigError("retina.sigma_surround_px 는 sigma_center_px 보다 커야 한다.")
    num(rt["truncate_sigma"], "retina.truncate_sigma", 1.0)
    num(rt["gain"], "retina.gain", 0.0, lo_open=True)
    lp = c["logpolar"]
    pos_int(lp["n_r"], "logpolar.n_r", 2)
    pos_int(lp["n_phi"], "logpolar.n_phi", 2)
    num(lp["r0_px"], "logpolar.r0_px", 0.0, lo_open=True)
    num(lp["rmax_margin_px"], "logpolar.rmax_margin_px", 0.0)
    num(lp["phi_offset_bins"], "logpolar.phi_offset_bins", 0.0, 1.0)
    num(lp["blur_beta"], "logpolar.blur_beta", 0.0)
    if not lp["blur_levels_px"] or any(float(x) < 0 for x in lp["blur_levels_px"]):
        raise ConfigError("logpolar.blur_levels_px 는 0 이상 값의 목록이다.")
    S = int(d["image_size"])
    if S / 2.0 - float(lp["rmax_margin_px"]) <= float(lp["r0_px"]):
        raise ConfigError("Rmax = S/2 − margin 이 r0 보다 커야 한다.")
    ne = c["neuron"]
    if not (0.0 <= float(ne["q_min"]) <= float(ne["q_init"]) <= float(ne["q_max"])):
        raise ConfigError("neuron: 0 <= q_min <= q_init <= q_max 이어야 한다.")
    num(ne["threshold"], "neuron.threshold")
    a = c["areas"]
    v1 = a["V1"]
    pos_int(v1["n_r"], "areas.V1.n_r")
    pos_int(v1["n_phi"], "areas.V1.n_phi")
    if not v1["orientations_deg"] or not v1["phases_rad"] or not v1["polarities"]:
        raise ConfigError("areas.V1 방향·위상·극성 목록이 비어 있다.")
    if any(int(p) not in (1, -1) for p in v1["polarities"]) or len(set(int(p) for p in v1["polarities"])) != len(v1["polarities"]):
        raise ConfigError("areas.V1.polarities 는 1 과 -1 중에서 중복 없이 고른다.")
    if not v1["color_channels"] or any(ch not in ("lum", "rg", "by") for ch in v1["color_channels"]):
        raise ConfigError("areas.V1.color_channels 는 lum/rg/by 중에서 고른다.")
    for k in ("gabor_sigma_factor", "gabor_sigma_min_px", "gabor_wavelength_factor", "rf_radius_sigma"):
        num(v1[k], f"areas.V1.{k}", 0.0, lo_open=True)
    for name, prev in (("V2", "V1"), ("V4", "V2")):
        g = a[name]
        pos_int(g["n_r"], f"areas.{name}.n_r")
        pos_int(g["n_phi"], f"areas.{name}.n_phi")
        if int(a[prev]["n_r"]) % int(g["n_r"]) or int(a[prev]["n_phi"]) % int(g["n_phi"]):
            raise ConfigError(f"areas.{prev} 격자 ({a[prev]['n_r']}×{a[prev]['n_phi']}) 가 {name} 격자 "
                              f"({g['n_r']}×{g['n_phi']}) 의 정수배여야 한다 (블록 풀링).")
        num(g["offset_factor"], f"areas.{name}.offset_factor", 0.0, lo_open=True)
    num(a["V2"]["endstop_inhibition"], "areas.V2.endstop_inhibition", 0.0)
    pos_int(a["V4"]["l3_grid_radius"], "areas.V4.l3_grid_radius", 0)
    it = a["IT"]
    pos_int(it["region_r"], "areas.IT.region_r")
    pos_int(it["region_phi"], "areas.IT.region_phi")
    if int(a["V4"]["n_r"]) % int(it["region_r"]) or int(a["V4"]["n_phi"]) % int(it["region_phi"]):
        raise ConfigError("areas.V4 격자가 IT 영역 격자 (region_r × region_phi) 의 정수배여야 한다.")
    l6 = c["l6"]
    if any(x not in ("L2", "L3") for x in l6["layers"]):
        raise ConfigError("l6.layers 는 L2/L3 중에서 고른다 (L6 조절은 L2/L3 에만 적용).")
    num(l6["epsilon"], "l6.epsilon", 0.0, lo_open=True)
    num(l6["kappa"], "l6.kappa", 0.0)
    if not (0.0 < float(l6["g_min"]) <= 1.0 <= float(l6["g_max"])):
        raise ConfigError("l6: 0 < g_min <= 1 <= g_max 이어야 한다.")
    pos_int(l6["neighbor_grid_radius"], "l6.neighbor_grid_radius", 0)
    le = c["learning"]
    for k in ("alpha2", "alpha3", "eta"):
        num(le[k], f"learning.{k}", 0.0)
    num(le["e0"], "learning.e0", 0.0, lo_open=True)
    num(le["rho"], "learning.rho", 0.0, 1.0)
    pos_int(le["batch_size"], "learning.batch_size")
    pos_int(le["max_epochs"], "learning.max_epochs", 0)
    pos_int(le["patience"], "learning.patience")
    num(le["min_delta"], "learning.min_delta", 0.0)
    if le["success_dev_accuracy"] is not None:
        num(le["success_dev_accuracy"], "learning.success_dev_accuracy", 0.0, 1.0)
    num(le["change_tol"], "learning.change_tol", 0.0)
    num(le["eps_norm"], "learning.eps_norm", 0.0, lo_open=True)
    rc = c["records"]
    for k in ("correction_samples_per_epoch", "correction_samples_max_per_stage", "checkpoint_every_batches",
              "keep_periodic_checkpoints", "store_train_h_max_mb"):
        pos_int(rc[k], f"records.{k}", 0)
    pos_int(rc["diagnostic_samples"], "records.diagnostic_samples", 2)
    cp = c["compute"]
    if cp["dtype"] != "float32":
        raise ConfigError("compute.dtype 는 float32 로 시작한다 (혼합 정밀도는 기본으로 쓰지 않는다).")
    pos_int(cp["max_gather_elements"], "compute.max_gather_elements", 1024)
    ro = c["routing"]
    if ro["mode"] not in ("legacy", "geometry_only", "v1_guided", "expanded_pool", "band_gated", DEST_MODE, RATIO_MODE):
        raise ConfigError("routing.mode 는 legacy / geometry_only / v1_guided / expanded_pool / band_gated / v1_destination_guided / "
                          f"{RATIO_MODE} 중 하나다.")
    rc_ = ro.get("ratio_codebook")
    if not isinstance(rc_, dict):
        raise ConfigError("routing.ratio_codebook 은 사전이다.")
    unk = sorted(set(rc_) - set(DEFAULT_CONFIG["routing"]["ratio_codebook"]))
    if unk:
        raise ConfigError(f"routing.ratio_codebook 에 알 수 없는 키: {unk} (q 학습·안내·구간 게이트 설정은 이 모드에 없다)")
    if rc_["selection_group"] != "position_role":
        raise ConfigError("routing.ratio_codebook.selection_group 은 position_role 만 지원한다.")
    if isinstance(rc_["top_k"], bool) or int(rc_["top_k"]) != 1 or float(rc_["top_k"]) != 1.0:
        raise ConfigError("routing.ratio_codebook.top_k 는 1 만 지원한다 (hard top-1).")
    num(rc_["routing_min_total"], "routing.ratio_codebook.routing_min_total", 0.0)
    num(rc_["norm_epsilon"], "routing.ratio_codebook.norm_epsilon", 0.0, lo_open=True)
    num(rc_["eta_codebook"], "routing.ratio_codebook.eta_codebook", 0.0, 1.0, lo_open=True)
    pos_int(rc_["init_samples"], "routing.ratio_codebook.init_samples", 1)
    pos_int(rc_["init_seed_offset"], "routing.ratio_codebook.init_seed_offset", 0)
    num(rc_["init_duplicate_cos_tol"], "routing.ratio_codebook.init_duplicate_cos_tol", 0.0, 1.0)
    pos_int(rc_["init_alternatives"], "routing.ratio_codebook.init_alternatives", 1)
    num(rc_["near_tie_gap"], "routing.ratio_codebook.near_tie_gap", 0.0)
    pos_int(rc_["curve_path_points"], "routing.ratio_codebook.curve_path_points", 3)
    num(rc_["bucket_padding_max"], "routing.ratio_codebook.bucket_padding_max", 1.0)
    pos_int(rc_["bucket_max_elements"], "routing.ratio_codebook.bucket_max_elements", 1024)
    for k_ in ("detail_samples_per_epoch", "detail_samples_max_per_stage"):
        pos_int(rc_[k_], f"routing.ratio_codebook.{k_}", 0)
    qf = num(rc_["v4_q_fixed"], "routing.ratio_codebook.v4_q_fixed", 0.0)
    if not (float(ne["q_min"]) <= qf <= float(ne["q_max"])):
        raise ConfigError("routing.ratio_codebook.v4_q_fixed 는 neuron.q_min ~ q_max 안이어야 한다 (저장 q 검증 규칙).")
    if not isinstance(rc_["v4_reference_path"], str):
        raise ConfigError("routing.ratio_codebook.v4_reference_path 는 문자열이다.")
    if ro["target"] != "V4_L2_curve_second_input" or ro["guide_source"] != "V1/L3" or ro["guide_color"] != "lum":
        raise ConfigError("이번 버전의 라우팅 대상은 V4 L2 곡선 두 번째 입력, 안내는 V1 L3 휘도 채널만 지원한다.")
    pos_int(ro["max_candidates"], "routing.max_candidates")
    pos_int(ro["path_points"], "routing.path_points", 3)
    if not (0.0 < float(ro["dist_min_factor"]) < float(ro["dist_max_factor"])):
        raise ConfigError("routing: 0 < dist_min_factor < dist_max_factor 이어야 한다.")
    num(ro["max_chord_dev_deg"], "routing.max_chord_dev_deg", 0.0, 180.0, lo_open=True)
    num(ro["curvature_turn_tol_deg"], "routing.curvature_turn_tol_deg", 0.0)
    num(ro["guide_epsilon"], "routing.guide_epsilon", 0.0, lo_open=True)
    num(ro["guide_min_total"], "routing.guide_min_total", 0.0)
    num(ro["high_guide_score"], "routing.high_guide_score", 0.0, 1.0)
    for k in ("samples_per_epoch", "samples_max_per_stage", "oom_retry_halvings"):
        pos_int(ro[k], f"routing.{k}", 0)
    bc = c["band"]
    num(bc["w_floor"], "band.w_floor", 0.0, 1.0, lo_open=True)
    num(bc["epsilon_norm"], "band.epsilon_norm", 0.0, lo_open=True)
    pos_int(bc["norm_grid_radius"], "band.norm_grid_radius", 0)
    num(bc["gate_floor"], "band.gate_floor", 0.0, 1.0, lo_open=True)
    pos_int(bc["calibration_max_samples"], "band.calibration_max_samples", 1)
    pos_int(bc["min_calibration_count"], "band.min_calibration_count", 1)
    num(bc["activity_epsilon"], "band.activity_epsilon", 0.0)
    num(bc["mad_scale"], "band.mad_scale", 0.0, lo_open=True)
    num(bc["sigma_floor"], "band.sigma_floor", 0.0, lo_open=True)
    num(bc["default_sigma"], "band.default_sigma", 0.0, lo_open=True)
    num(bc["default_mu"], "band.default_mu")
    for k in ("samples_per_epoch", "samples_max_per_stage", "calibration_seed_offset"):
        pos_int(bc[k], f"band.{k}", 0)
    if not bc["norm_include_self"] and int(bc["norm_grid_radius"]) == 0:
        raise ConfigError("band: 자기 자신을 빼면 정규화 이웃 반경이 1 이상이어야 한다.")
    dcf = c["destination"]
    if dcf["selection_group"] != "position_role":
        raise ConfigError("destination.selection_group 은 이 버전에서 position_role 만 지원한다.")
    if isinstance(dcf["top_k"], bool) or int(dcf["top_k"]) != 1 or float(dcf["top_k"]) != 1.0:
        raise ConfigError("destination.top_k 는 이 버전에서 1 만 지원한다 (hard top-1).")
    num(dcf["guide_epsilon"], "destination.guide_epsilon", 0.0, lo_open=True)
    num(dcf["evidence_floor"], "destination.evidence_floor", 0.0)
    pos_int(dcf["path_points"], "destination.path_points", 3)
    num(dcf["softmax_temperature"], "destination.softmax_temperature", 0.0, lo_open=True)
    num(dcf["high_score"], "destination.high_score", 0.0, 1.0)
    for k in ("detail_samples_per_epoch", "detail_samples_max_per_stage"):
        pos_int(dcf[k], f"destination.{k}", 0)
    if not isinstance(dcf["v3_reference_path"], str):
        raise ConfigError("destination.v3_reference_path 는 문자열이다.")
    return c


def config_structure_sha(cfg: dict[str, Any]) -> str:
    part = {"image_size": cfg["data"]["image_size"], "transparent_background": cfg["data"]["transparent_background"],
            "retina": cfg["retina"], "logpolar": cfg["logpolar"], "neuron": cfg["neuron"], "areas": cfg["areas"], "l6": cfg["l6"],
            "dtype": cfg["compute"]["dtype"]}
    ro = cfg.get("routing") or {}
    mode = ro.get("mode", "legacy")
    if mode in ("expanded_pool", "band_gated"):          # v3: 모드와 강도 구간 설정만 (v2 라우팅 값은 쓰지 않는다)
        part["routing"] = {"mode": mode}
        part["band"] = {k: v for k, v in (cfg.get("band") or {}).items() if k not in BAND_RECORD_ONLY_KEYS}
    elif mode == DEST_MODE:                              # v4: 모드와 목적지 선택 설정만 (이전 모드의 해시는 그대로)
        part["routing"] = {"mode": mode}
        part["destination"] = {k: v for k, v in (cfg.get("destination") or {}).items() if k not in DEST_RECORD_ONLY_KEYS}
    elif mode == RATIO_MODE:                             # v6: 모드와 비율 라우팅 구조 설정만 (다른 모드의 해시는 그대로)
        rc_ = ro.get("ratio_codebook") or {}
        part["routing"] = {"mode": mode, "ratio_codebook": {k: rc_.get(k) for k in RATIO_STRUCT_KEYS}}
    elif mode != "legacy":                               # v2 모드: v2 와 같은 해시 (v2 checkpoint 를 그대로 읽는다)
        part["routing"] = {k: v for k, v in ro.items() if k not in ROUTING_RECORD_ONLY_KEYS}
    return sha256_text(dumps(part, indent=None))


def saved_config_with_mode(raw: dict[str, Any]) -> dict[str, Any]:
    """저장된 실행의 설정. routing 기록이 없는 실행 (v1 프로그램이 만든 것) 은 legacy 로 본다 (새 기본값을 덮어쓰지 않는다)."""
    raw = copy.deepcopy(raw)
    raw.setdefault("data", {}).setdefault("source", "folder")
    if "routing" not in raw:
        raw["routing"] = {"mode": "legacy"}
    return validate_config(raw)


def config_learning_sha(cfg: dict[str, Any]) -> str:
    le = {k: v for k, v in cfg["learning"].items() if k not in RESUME_MUTABLE_LEARNING}
    part = {"learning": le, "seed": cfg["seed"], "split": cfg["data"]["split_ratios"],
            "group_regex": cfg["data"]["group_suffix_regex"]}
    if cfg["data"]["source"] == "mnist":
        part["dataset"] = {"source": "mnist", "dev_size": cfg["data"]["mnist_dev_size"],
                           "split_policy": "official-test-stratified-train-v1"}
    if (cfg.get("routing") or {}).get("mode") == RATIO_MODE:  # v6 모드만: V4 코드북 학습 설정 (다른 모드의 해시는 그대로)
        rc_ = cfg["routing"].get("ratio_codebook") or {}
        part["ratio_learning"] = {k: rc_.get(k) for k in RATIO_LEARN_KEYS}
    return sha256_text(dumps(part, indent=None))        # folder: 구버전 해시 그대로 유지


class Config:
    """설정 관리 (한 곳): DEFAULT_CONFIG 위에 사용자 JSON 을 덮고 validate 로 검사한다. 실제 적용값과 해시는 config.json 에 기록된다."""

    DEFAULT = DEFAULT_CONFIG
    validate = staticmethod(validate_config)
    structure_sha = staticmethod(config_structure_sha)
    learning_sha = staticmethod(config_learning_sha)

    @staticmethod
    def load(path: str | None, seed: int | None) -> dict[str, Any]:
        cfg: dict[str, Any] = {}
        if path:
            cfg = read_json(clean_user_path(path))
            cfg = cfg.get("config", cfg)                     # 실행 폴더의 config.json 도 그대로 받는다
            cfg.setdefault("data", {}).setdefault("source", "folder")  # 구버전 사용자 설정 호환
        if seed is not None:
            cfg = deep_merge(cfg, {"seed": int(seed)})
        return validate_config(cfg)


# 수식 기록 (config.json 과 architecture.json 에 그대로 남긴다)
FORMULAS: dict[str, str] = {
    "neuron": "u_j = Σ_i A_ji·transmitted_i + external_j ;  s_j = max(0, u_j − threshold_j) ;  CONF_j = q_j·s_j ;  "
              "transmitted_j = attention_gain_j·CONF_j  (attention_gain = L6 g, L4 는 1)",
    "role_op_min2": "역할 연산 min2 (교차·곡선·결합 뉴런): u_j = min(Σ_{i∈A_j} A_ji x_i, Σ_{i∈B_j} A_ji x_i)  (두 입력군이 모두 있어야 반응)",
    "l6": "같은 층 CONF 스냅샷에서 병렬:  r_j = CONF_j/(mean_{k∈N(j)} CONF_k + ε) ;  g_j = clip(1 + κ(r_j − 1), g_min, g_max) ;  "
          "transmitted_j = g_j·CONF_j ;  이웃 없음 → g=1",
    "prototype_init": "prototype_c = mean_{train, label=c} h  (모델 고정, 라벨은 출력 묶음에만)",
    "prototype_update": "에폭 끝, q 고정, train 재순방향:  prototype_c ← (1−ρ)·prototype_c + ρ·mean_{train,c} h",
    "classify": "pred = argmax_c cos(h, prototype_c) ; ‖h‖ ≤ eps_norm → unknown (실패로 집계)",
    "delta": "δ = prototype_true − h  (B × n_L3, L3 neuron_id 순서)",
    "router": "m_L3 = α3·δ ;  m_L2[i] = α2·Σ_{j: i∈P(j)} δ_j/|P(j)|  (R_ij = 1/|P(j)|, P(j) = 실제 L2→L3 부모 목록; 가중치·전치·미분 미사용)",
    "local_update": "e_j = s_j/(s_j + e0) ;  Δq_j = η·mean_batch(e_j·m_j) ;  q_j ← clip(q_j + Δq_j, q_min, q_max)  "
                    "(L2·L3 갱신량을 같은 스냅샷에서 모두 계산한 뒤 동시에 적용)",
    "cycle": "(1) 동적 상태 초기화 (2) 자유 순방향 → h_before, s, CONF, g (3) 동결 prototype 비교 (4) L1 배달 (5) 활성 영역 q 갱신 "
             "(6) 같은 입력 재순방향 → h_after (7) 같은 이전 prototype 기준 개선·악화·무변화 기록",
    "routing_directions": "곡선 뉴런 (첫 입력 위치 P, 첫 방향 θA, 곡률 부호 s, 꺾임 κ):  φA = θA,  φB = θA + s·κ (θB = φB mod 180),  "
                          "φC = φA + s·κ/2  (연속 각도로 계산, 0°/180° 를 단순 평균하지 않는다)",
    "routing_candidates": "Q ≠ P 인 V4 L4 위치 중  dist_min·D ≤ |Q−P| ≤ dist_max·D  그리고  ∠(Q−P, φC) ≤ max_chord_dev  "
                          "→ 기하 점수 |d−D|/(반폭·D) + 방향오차/max_dev 와 입력 주소 순서로 정렬 → 경로 검사 통과만 K 개.  "
                          "후보 없음 → u = 0 (missing_candidate), 같은 위치로 대체하지 않는다",
    "routing_path": "삼차 Hermite  p(t) = h00 P + h10 L·dir(φA) + h01 Q + h11 L·dir(φB),  L = |Q−P|,  t_m = m/(M−1).  "
                    "곡률 부호가 s 와 반대 (허용 curvature_turn_tol)·접힘·영 접선·수용장 밖·진행 방향 충돌이면 그 후보는 무효",
    "routing_score": "a_m = F1(p(t_m), 접선 선방향) (로그-극좌표 역보간 + 180 주기 방향 보간),  b_m = 같은 위치의 모든 방향 반응 합,  "
                     "r_m = a_m/(b_m + ε)  (b_m < b_min 이면 0),  S = (1/M) Σ r_m  — 방향 지지 정도, 확률이 아니다",
    "routing_select": "v1_guided: Q* = argmax_{유효 후보} S (같은 점수는 기하 순서), 모든 S ≤ 0 → 기하 첫 후보 + no_guidance.  "
                      "geometry_only: 기하 첫 후보.  legacy: v1 규칙.  B = transmitted_V4L4[Q*, θB],  u = min(A, B)  — S 를 곱하지 않는다",
    "band_candidates": "곡선 뉴런 j (P, θA, θB, s, κ): 후보 i = V4 L4 위치 Q ≠ P, ‖Q − P‖ ≤ R_j (V4 L2 수용장 반경, 화소), contour θB 채널. "
                       "v2 의 거리·현 방향·곡률 검사로 지우지 않는다 (진단값으로만 저장). 후보 없음 → B = 0, u = 0 (missing_candidate)",
    "band_w0": "T_j = P + D(P)·dir(φC), φC = θA + s·κ/2 (연속 각도) ;  w0_ji = w_floor + (1 − w_floor)·exp(−‖Q_i − T_j‖² / (2 D(P)²))  (고정)",
    "band_normalization": "z_i = x_i / (ε + sqrt(mean_{k∈N(i)} x_k²)),  N(i) = 같은 contour 방향의 V4 격자 반경 1 이웃 (자기 포함, 각도 wrap). "
                          "표본별, 원래 입력 뉴런마다 한 번 계산해 여러 목적 뉴런에서 재사용. z 는 구간 판단에만, 전달은 x",
    "band_calibration": "train 최대 1024 장 (고정 seed 별도 RNG, 라벨·dev·test 미사용) 에서 A_j > ε, x_i > ε 인 표본의 z_i:  "
                        "μ_ji = median(z),  σ_ji = max(1.4826·median|z − μ|, σ_floor) ;  유효 표본 < 16 → μ = 1, σ = 2 (calibration_insufficient). 1회 후 고정",
    "band_gate": "g_ji = exp(−(z_i − μ_ji)² / (2σ_ji²)) ;  w_eff = w0·g ;  B_j = Σ w_eff·x_i / Σ w_eff ;  u_j = min(A_j, B_j).  "
                 "max g < gate_floor → w0 가중평균 (all_gates_low).  expanded_pool: g = 1",
    "dest_guide": "F1 = 같은 순방향의 V1 L3 실제 전송 출력 (동결 V1 도 매 입력 계산). a(p,θ) = 보간한 휘도 방향 반응, b(p) = Σ_θ a(p,θ) (같은 공간 가중치), "
                  "r(p,θ) = a/(b + ε) (b ≥ evidence_floor), 그 밖 0. NaN 은 NaN 으로 남겨 점수에서 제외하고 센다. 방향별 상대 지지이며 정답 확률이 아니다",
    "dest_scores": "곡선 j (P, θA, θB, s, κ): S(j,Q) = min(r(P,θA), r(Q,θB))·(1/M)Σ_m r(p_m, ψ_m) (Hermite 경로, ψ = 접선 선방향), "
                   "Q*(j) = argmax_유효Q S(j,Q), S_j = S(j,Q*).  직선: min(r(P,θ), r(Q,θ))·(1/M)Σ_m r(직선 경로점, 현 방향).  "
                   "접합: min(r(P,θ1), r(P,θ2)).  선 끝: 0.5·max(r_c − r_f, 0) + 0.5·max(r_c − r_b, 0) (기존 V2 endstop 중심·전방·후방 억제 표본 평균)",
    "dest_select": "집단 = V4 위치 P × 역할. j* = argmax_{j∈집단, S_j > 0, 유한} S_j (같은 점수 → 작은 neuron_id), 없으면 선택 없음. "
                   "동점 여부와 1·2 위 차이를 기록. 화면 표시 '라우팅 선택 가중치' p_j = softmax(S_j/T) (T = 1, 선택 없음이면 0) 는 전달에 쓰지 않는다",
    "dest_deliver": "선택된 j*: 곡선 u = min(X4[P, contour θA], X4[Q*, contour θB]), 직선 u = min(X4[P,θ], X4[Q,θ]), 접합 u = X4[P, cross], "
                    "선 끝 u = 0.5·X4[P, endstop_fwd] + 0.5·X4[P, endstop_bwd].  선택되지 않은 j: u = 0, s = 0 (명시적 마스크).  "
                    "s = max(0, u − θ) ; CONF = q·s ; 전송 = L6 g·CONF (순서 그대로). 안내 점수를 곱하거나 V1 값을 더하지 않는다",
    "dest_candidates": "곡선 B 후보 = Q ≠ P, ‖Q − P‖ ≤ R_j (V4 L2 수용장, 원영상 화소), contour θB 채널 중 (Q − P)·dir(φA) > 0 (진행 방향), "
                       "s·cross(dir(φA), Q − P) > 0 (뒤집힌 굽힘 아님), Hermite 경로가 표본 원 안·영 접선 없음·접히지 않음. 조건별 제거 수 기록. "
                       "직선·접합·선 끝은 기존 원천 연결 그대로 (목적지 선택 마스크만 적용)",
    "ratio_descriptor": "v6 (V4 만): 집단 g = V4 위치 P × 역할. x_g = 고정 순서 source_ids[g] 의 V4 L4 실제 출력, S = Σ x_g. "
                        "S ≤ routing_min_total 또는 유효 대표 없음 → 선택 없음 (u = s = 0, 갱신 0). 그 밖 p = x/S, x̂ = p/‖p‖ (‖x̂‖ = 1). "
                        "NaN/Inf/음수 입력은 바꾸지 않고 계산 실패로 기록한다",
    "ratio_select": "score[g,k] = x̂_g · c[g,k] (c ≥ 0, 지원 밖 0, ‖c‖ = 1), 무효 후보 −∞, k* = argmax (같은 점수 → 작은 route_id). "
                    "후보 = 목적지 L2 하나 + 그 A/B 슬롯 원천 묶음 (곡선은 (뉴런, Q) 마다 다른 route_id). V1 안내 점수를 쓰지 않는다",
    "ratio_deliver": "선택된 후보만: A = Σ 기저 가중치 × X4[A 원천], B = Σ 기저 가중치 × X4[B 원천], 곡선·직선 u = min(A, B), 접합 u = X4[P, cross], "
                     "선 끝 u = 0.5·X4[P, fwd] + 0.5·X4[P, bwd]. 미선택 u = s = 0 (명시적 마스크). s = max(0, u − θ), CONF = q·s (V4 q 고정), "
                     "전송 = L6 g·CONF. 점수·대표·비율을 전달값에 곱하지 않는다",
    "ratio_update": "배치마다 한 번 (같은 배치는 갱신 전 코드북으로 순방향): n = 유효 승리 수, v = mean(x̂ | 승리) ⊙ 지원, "
                    "n > 0 이고 ‖v‖ > ε → c ← normalize((1 − η)·c + η·v/‖v‖), 그 밖 c 그대로. 라벨·판독기·오차·미분 미사용",
    "ratio_init": "train 만 min(init_samples, n_train) 장 (고정 seed, 라벨 미사용) 의 V4 L4 패킷. 후보마다 역할 반응 u_k > θ 인 비영 패킷 중 "
                  "u_k/S 가 큰 순서로, 같은 집단에서 아직 쓰지 않았고 기존 대표와 방향이 겹치지 않는 첫 패킷 → c = normalize(x̂ ⊙ 지원). "
                  "그런 패킷이 없으면 지원 위 에너지 ‖x̂ ⊙ 지원‖² 최대 패킷 (fallback 기록). 단위 벡터를 못 만들면 초기화 실패 (경쟁 제외)",
    "ratio_readout": "V4 판독기 (코드북과 별개): μ_y = mean(h_V4 | train, y), P_y = μ_y/‖μ_y‖, pred = argmax_y cos(h, P_y). "
                     "초기화 직후 (epoch_number 0) 와 에폭마다 고정 코드북으로 다시 계산. V1·V2·IT 는 기존 prototype (원시 평균 + ρ EMA) 그대로",
    "ratio_selection": "V4 만: dev 정확도 최고 시점 (동률 → 이른 시점, epoch_number 0 포함) 의 코드북·판독기 쌍을 단계 끝에 복원·동결. "
                       "V1·V2·IT 는 기존대로 종료 시점 상태 (best dev 는 기록만)",
}

