def assumptions_markdown() -> str:
    lines = [f"# {PROGRAM} 가정·한계 (v{VERSION})", "",
             "이 문서는 프로그램이 자동으로 쓴다. 뉴런 수·배치·층 역할·학습 규칙은 생물학에서 착안한 공학적 근사이며, "
             "인간 시각 피질의 완전한 재현이나 뇌가 아래 수식을 쓴다는 주장이 아니다. "
             "단방향 연결이라는 해부학적 비유와 알고리즘이 역전파를 쓰는지는 별개다.", ""]
    for sec, items in ASSUMPTIONS.items():
        lines += [f"## {sec}", ""] + [f"- {x}" for x in items] + [""]
    lines += ["## 수식", ""] + [f"- **{k}**: {v}" for k, v in FORMULAS.items()] + [""]
    return "\n".join(lines)


# ======================================================================
# 2. 계산 뒷단 (DeviceManager / Backend)
# ======================================================================
class Backend:
    """수치 연산 뒷단.

    kind="torch": 기본. PyTorch 텐서 (CUDA 또는 CPU). torch.set_grad_enabled(False) 로 미분 추적을 끄고 수동 갱신만 한다.
    kind="numpy": PyTorch 가 없을 때 사용자가 명시적으로 고르는 CPU 경로. 같은 수식·같은 연산 순서 (gather → 곱 → 마지막 축 합).
    쓰는 연산은 gather (고정 정수 인덱스), 원소별 곱·합·clamp·min·where 뿐이다. atomic 누적 (index_add) 을 쓰지 않으므로
    같은 입력·같은 파라미터의 순방향은 같은 결과를 낸다 (CUDA 축약도 모양이 같으면 결정적).
    """

    def __init__(self, kind: str, device: str = "cpu", *, deterministic: bool = True, max_gather_elements: int = 1 << 25):
        if kind not in ("torch", "numpy"):
            raise ValueError(f"알 수 없는 backend: {kind}")
        self.kind = kind
        self.max_gather = int(max_gather_elements)
        self.deterministic = bool(deterministic)
        self.notes: list[str] = []
        if kind == "torch":
            if torch is None:
                raise RuntimeError(f"PyTorch 를 불러올 수 없다: {_TORCH_ERROR}")
            torch.set_grad_enabled(False)
            self.dev = torch.device(device)
            if self.dev.type == "cuda" and not torch.cuda.is_available():
                raise RuntimeError("CUDA 장치를 쓸 수 없다 (torch.cuda.is_available() = False).")
            torch.backends.cuda.matmul.allow_tf32 = False
            torch.backends.cudnn.allow_tf32 = False
            if self.deterministic:
                torch.use_deterministic_algorithms(True, warn_only=True)
                self.notes.append("torch.use_deterministic_algorithms(True, warn_only=True)")
            self.device = str(self.dev)
        else:
            self.dev = None
            self.device = "cpu"

    # ---------------------------------------------------------------- 생성·변환
    @property
    def is_cuda(self) -> bool:
        return self.kind == "torch" and self.dev.type == "cuda"

    def f32(self, a: Any) -> Any:
        a = np.array(a, dtype=np.float32, copy=True, order="C")
        return a if self.kind == "numpy" else torch.from_numpy(a).to(self.dev)

    def i64(self, a: Any) -> Any:
        a = np.array(a, dtype=np.int64, copy=True, order="C")
        return a if self.kind == "numpy" else torch.from_numpy(a).to(self.dev)

    def bool_(self, a: Any) -> Any:
        a = np.array(a, dtype=bool, copy=True, order="C")
        return a if self.kind == "numpy" else torch.from_numpy(a).to(self.dev)

    def to_np(self, x: Any) -> np.ndarray:
        if self.kind == "numpy":
            return np.asarray(x)
        return x.detach().to("cpu").numpy()

    def zeros(self, shape: Sequence[int]) -> Any:
        shape = tuple(int(s) for s in shape)
        return np.zeros(shape, np.float32) if self.kind == "numpy" else torch.zeros(shape, dtype=torch.float32, device=self.dev)

    def zeros_i64(self, shape: Sequence[int]) -> Any:
        shape = tuple(int(s) for s in shape)
        return np.zeros(shape, np.int64) if self.kind == "numpy" else torch.zeros(shape, dtype=torch.int64, device=self.dev)

    def max_last(self, x: Any) -> Any:
        return x.max(-1) if self.kind == "numpy" else x.max(dim=-1).values

    def argmax_last(self, x: Any) -> Any:
        return x.argmax(-1) if self.kind == "numpy" else x.argmax(dim=-1)

    def take_last(self, table: Any, k: Any) -> Any:
        """table (n, K), k (B, n) → table[j, k[b, j]] (B, n)."""
        if self.kind == "numpy":
            return np.take_along_axis(np.broadcast_to(table, (k.shape[0],) + tuple(table.shape)), k[..., None], -1)[..., 0]
        return table.unsqueeze(0).expand(int(k.shape[0]), -1, -1).gather(-1, k.unsqueeze(-1)).squeeze(-1)

    def gather_cols(self, x: Any, idx: Any) -> Any:
        """x (B, N), idx (B, m) → x[b, idx[b, i]] (B, m)  (표본마다 다른 주소)."""
        return np.take_along_axis(x, idx, 1) if self.kind == "numpy" else torch.gather(x, 1, idx)

    def ones_like(self, x: Any) -> Any:
        return np.ones_like(x) if self.kind == "numpy" else torch.ones_like(x)

    def clone(self, x: Any) -> Any:
        return x.copy() if self.kind == "numpy" else x.clone()

    def cat1(self, xs: Sequence[Any]) -> Any:
        return np.concatenate(list(xs), axis=1) if self.kind == "numpy" else torch.cat(list(xs), dim=1)

    def cat0(self, xs: Sequence[Any]) -> Any:
        return np.concatenate(list(xs), axis=0) if self.kind == "numpy" else torch.cat(list(xs), dim=0)

    # ---------------------------------------------------------------- 연산
    def ell(self, xe: Any, idx: Any, w: Any) -> Any:
        """xe: (B, n_src+1) (마지막 열 = 0, 채움 주소), idx/w: (r, K) → (B, r) = Σ_k xe[:, idx[r,k]]·w[r,k]."""
        B = int(xe.shape[0])
        r, K = int(idx.shape[0]), int(idx.shape[1])
        rows = max(1, self.max_gather // max(1, B * K))
        if rows >= r:
            return (xe[:, idx] * w).sum(-1)
        parts = [(xe[:, idx[a:a + rows]] * w[a:a + rows]).sum(-1) for a in range(0, r, rows)]
        return self.cat1(parts)

    def pad_zero_col(self, x: Any) -> Any:
        return self.cat1([x, self.zeros((int(x.shape[0]), 1))])

    def take_cols(self, x: Any, idx: Any) -> Any:
        return x[:, idx]

    def relu(self, x: Any) -> Any:
        return np.maximum(x, np.float32(0.0)) if self.kind == "numpy" else torch.clamp(x, min=0.0)

    def clip(self, x: Any, lo: float, hi: float) -> Any:
        if self.kind == "numpy":
            return np.clip(x, np.float32(lo), np.float32(hi))
        return torch.clamp(x, min=float(lo), max=float(hi))

    def minimum(self, a: Any, b: Any) -> Any:
        return np.minimum(a, b) if self.kind == "numpy" else torch.minimum(a, b)

    def where(self, c: Any, a: Any, b: Any) -> Any:
        return np.where(c, a, b) if self.kind == "numpy" else torch.where(c, a, b)

    def repeat_cols(self, x: Any, k: int) -> Any:
        return np.repeat(x, int(k), axis=1) if self.kind == "numpy" else torch.repeat_interleave(x, int(k), dim=1)

    def mean0(self, x: Any) -> Any:
        return x.mean(axis=0) if self.kind == "numpy" else x.mean(dim=0)

    def sum0(self, x: Any) -> Any:
        return x.sum(axis=0) if self.kind == "numpy" else x.sum(dim=0)

    def exp(self, x: Any) -> Any:
        return np.exp(x) if self.kind == "numpy" else torch.exp(x)

    def isnan(self, x: Any) -> Any:
        return np.isnan(x) if self.kind == "numpy" else torch.isnan(x)

    def isfinite(self, x: Any) -> Any:
        return np.isfinite(x) if self.kind == "numpy" else torch.isfinite(x)

    def as_f32(self, x: Any) -> Any:
        return np.asarray(x, np.float32) if self.kind == "numpy" else x.to(torch.float32)

    def sqrt(self, x: Any) -> Any:
        return np.sqrt(x) if self.kind == "numpy" else torch.sqrt(x)

    def sum_last(self, x: Any) -> Any:
        return x.sum(-1)

    def norm_last(self, x: Any) -> Any:
        return np.sqrt((x * x).sum(-1)) if self.kind == "numpy" else torch.sqrt((x * x).sum(-1))

    def matmul_t(self, a: Any, b: Any) -> Any:
        return a @ b.T

    def rows(self, P: Any, idx: Any) -> Any:
        return P[idx]

    def all_finite(self, x: Any) -> bool:
        return bool(np.isfinite(x).all()) if self.kind == "numpy" else bool(torch.isfinite(x).all().item())

    def assign_(self, dst: Any, src: Any) -> None:
        if self.kind == "numpy":
            dst[...] = src
        else:
            dst.copy_(src)

    def add_row_(self, M: Any, i: int, v: Any) -> None:
        M[i] += v

    # ---------------------------------------------------------------- v6 V4 비율 라우팅 연산 (v5 참조 이식) (gather·배치 행렬곱·마스크 argmax, atomic 누적 없음)
    def bmm(self, a: Any, b: Any) -> Any:
        """(G, M, D) @ (G, D, N) → (G, M, N) (집단별 행렬곱)."""
        return np.matmul(a, b) if self.kind == "numpy" else torch.bmm(a, b)

    def permute(self, x: Any, axes: Sequence[int]) -> Any:
        return np.transpose(x, tuple(axes)) if self.kind == "numpy" else x.permute(*axes)

    def gather_last(self, x: Any, idx: Any) -> Any:
        """x (..., K), idx (...) → x[..., idx] (마지막 축에서 칸 하나)."""
        if self.kind == "numpy":
            return np.take_along_axis(x, idx[..., None], -1)[..., 0]
        return torch.gather(x, -1, idx.unsqueeze(-1)).squeeze(-1)

    def onehot_last(self, idx: Any, K: int) -> Any:
        if self.kind == "numpy":
            return (idx[..., None] == np.arange(int(K))).astype(np.float32)
        return (idx.unsqueeze(-1) == torch.arange(int(K), device=self.dev)).to(torch.float32)

    def full(self, shape: Sequence[int], value: float) -> Any:
        shape = tuple(int(s) for s in shape)
        return np.full(shape, value, np.float32) if self.kind == "numpy" else torch.full(shape, float(value), dtype=torch.float32, device=self.dev)

    def full_i64(self, shape: Sequence[int], value: int) -> Any:
        shape = tuple(int(s) for s in shape)
        return np.full(shape, value, np.int64) if self.kind == "numpy" else torch.full(shape, int(value), dtype=torch.int64, device=self.dev)

    def zeros_like(self, x: Any) -> Any:
        return np.zeros_like(x) if self.kind == "numpy" else torch.zeros_like(x)

    def all_last(self, x: Any) -> Any:
        return x.all(-1) if self.kind == "numpy" else x.all(dim=-1)

    def any_last(self, x: Any) -> Any:
        return x.any(-1) if self.kind == "numpy" else x.any(dim=-1)

    def clamp_min(self, x: Any, lo: float) -> Any:
        return np.maximum(x, np.float32(lo)) if self.kind == "numpy" else torch.clamp(x, min=float(lo))


    def sync(self) -> None:
        if self.is_cuda:
            torch.cuda.synchronize(self.dev)

    def requires_grad_any(self, xs: Sequence[Any]) -> bool:
        if self.kind == "numpy":
            return False
        return any(bool(getattr(x, "requires_grad", False)) for x in xs)

    def grad_enabled(self) -> bool:
        return False if self.kind == "numpy" else bool(torch.is_grad_enabled())

    def describe(self) -> dict[str, Any]:
        d: dict[str, Any] = {"backend": self.kind, "device": self.device, "dtype": "float32",
                             "max_gather_elements": self.max_gather, "deterministic_requested": self.deterministic,
                             "notes": list(self.notes)}
        if self.kind == "torch":
            d.update(torch_version=torch.__version__, grad_enabled=bool(torch.is_grad_enabled()),
                     matmul_allow_tf32=bool(torch.backends.cuda.matmul.allow_tf32),
                     cudnn_allow_tf32=bool(torch.backends.cudnn.allow_tf32),
                     deterministic_algorithms=bool(torch.are_deterministic_algorithms_enabled()),
                     cublas_workspace_config=os.environ.get("CUBLAS_WORKSPACE_CONFIG"))
        else:
            d.update(note_ko="NumPy CPU 경로: 사용자가 명시적으로 고른 경우에만 쓰는 같은 수식의 대체 경로 (GPU 미사용).")
        d["reduction_determinism_ko"] = ("순방향·교정·갱신은 고정 인덱스 gather 와 마지막 축 합만 쓴다 (atomic index_add 없음). "
                                         "분류 코사인의 행렬곱은 cuBLAS (TF32 끔, workspace 고정).")
        return d


def is_oom_error(exc: BaseException) -> bool:
    if torch is not None and hasattr(torch.cuda, "OutOfMemoryError") and isinstance(exc, torch.cuda.OutOfMemoryError):
        return True
    return isinstance(exc, (RuntimeError, MemoryError)) and ("out of memory" in str(exc).lower() or isinstance(exc, MemoryError))


class DeviceManager:
    """장치·라이브러리 확인과 Backend 생성. 설치 실패를 숨기지 않고, 자동 설치하지 않는다."""

    @staticmethod
    def torch_status() -> dict[str, Any]:
        st: dict[str, Any] = {"torch_available": torch is not None, "torch_error": _TORCH_ERROR}
        if torch is not None:
            st["torch_version"] = torch.__version__
            st["cuda_available"] = bool(torch.cuda.is_available())
            st["cuda_version"] = getattr(torch.version, "cuda", None)
            gpus = []
            if torch.cuda.is_available():
                for i in range(torch.cuda.device_count()):
                    g = {"index": i, "name": torch.cuda.get_device_name(i)}
                    try:
                        free, total = torch.cuda.mem_get_info(i)
                        g.update(vram_total_mb=round(total / 2 ** 20, 1), vram_free_mb=round(free / 2 ** 20, 1))
                    except Exception as exc:                 # noqa: BLE001
                        g["vram_error"] = f"{type(exc).__name__}: {exc}"
                    gpus.append(g)
            st["gpus"] = gpus
        return st

    @staticmethod
    def create(backend: str, device: str, cfg: dict[str, Any]) -> Backend:
        """backend: auto|torch|numpy, device: auto|cuda|cpu. auto 에서 torch 가 없으면 예외 (호출자가 사용자에게 묻는다)."""
        cp = cfg["compute"]
        if backend in ("auto", "torch"):
            if torch is None:
                raise RuntimeError(f"PyTorch 를 불러올 수 없다 ({_TORCH_ERROR}). 설치하거나 --backend numpy 를 명시하라.")
            if device == "cuda" and not torch.cuda.is_available():
                raise RuntimeError("--device cuda 를 골랐지만 CUDA 를 쓸 수 없다.")
            dev = "cuda" if (device in ("auto", "cuda") and torch.cuda.is_available()) else "cpu"
            return Backend("torch", dev, deterministic=bool(cp["deterministic"]), max_gather_elements=int(cp["max_gather_elements"]))
        if backend == "numpy":
            if device == "cuda":
                raise RuntimeError("NumPy 경로는 CPU 만 쓴다.")
            return Backend("numpy", "cpu", deterministic=True, max_gather_elements=int(cp["max_gather_elements"]))
        raise ValueError(f"알 수 없는 backend: {backend}")

    @staticmethod
    def environment(be: Backend | None) -> dict[str, Any]:
        mpl_ver, mpl_err = None, None
        try:
            import matplotlib
            mpl_ver = matplotlib.__version__
        except Exception as exc:                             # noqa: BLE001
            mpl_err = f"{type(exc).__name__}: {exc}"
        pil_ver = None
        if Image is not None:
            import PIL
            pil_ver = PIL.__version__
        return {"utc": utc_now(), "program": PROGRAM, "program_version": VERSION, "os": platform.platform(),
                "python": sys.version, "executable": sys.executable, "numpy": np.__version__, "pillow": pil_ver,
                "pillow_error": _PIL_ERROR, "matplotlib": mpl_ver, "matplotlib_error": mpl_err,
                **DeviceManager.torch_status(), "backend": (be.describe() if be is not None else None),
                "cpu_count": os.cpu_count(), "dataloader_ko": "프로세스 안 순차 로딩 (num_workers=0 과 같음)"}

    @staticmethod
    def print_environment(env: dict[str, Any], say: Callable[[str], None] = print) -> None:
        say(f"  Python {env['python'].split()[0]} | numpy {env['numpy']} | Pillow {env['pillow']} | matplotlib {env['matplotlib']}")
        if env.get("torch_available"):
            say(f"  PyTorch {env.get('torch_version')} | CUDA 사용 가능 {env.get('cuda_available')} (CUDA {env.get('cuda_version')})")
            for g in env.get("gpus") or []:
                say(f"    GPU {g['index']}: {g['name']} | VRAM 전체 {g.get('vram_total_mb')} MB, 여유 {g.get('vram_free_mb')} MB")
        else:
            say(f"  PyTorch 없음: {env.get('torch_error')}")
        b = env.get("backend") or {}
        if b:
            say(f"  계산 뒷단 {b.get('backend')} | 장치 {b.get('device')} | dtype {b.get('dtype')} | 결정성 요청 {b.get('deterministic_requested')}")


# ======================================================================
# 3. 실행 기록 (RunRecorder), 시간 측정, 안전한 중단
# ======================================================================
def _csv_cell(v: Any) -> Any:
    if v is None:
        return ""
    if isinstance(v, (bool, np.bool_)):
        return str(bool(v))
    if isinstance(v, (float, np.floating)):
        f = float(v)
        return repr(f) if math.isfinite(f) else ""
    if isinstance(v, (int, np.integer)):
        return int(v)
    if isinstance(v, (list, dict, tuple)):
        return dumps(v, indent=None)
    return v


class RunRecorder:
    """한 실행 폴더의 모든 기록. 파일은 임시 파일에 쓴 뒤 원자적으로 바꾼다."""

    SUBDIRS = ("checkpoints", "figures", "prototype_snapshots", "correction_samples", "diagnostics", "inference", "structure", "routing",
               "codebook", "readout", "routes", "validation")
    _count = 0

    def __init__(self, run_dir: Path, *, say: Callable[[str], None] = print):
        self.dir = Path(run_dir)
        self.dir.mkdir(parents=True, exist_ok=True)
        for s in self.SUBDIRS:
            (self.dir / s).mkdir(exist_ok=True)
        RunRecorder._count += 1
        self.log = logging.getLogger(f"{PROGRAM}.run{RunRecorder._count}.{id(self)}")
        self.log.setLevel(logging.INFO)
        self.log.propagate = False
        fmt_ = logging.Formatter("%(asctime)s %(levelname)s %(message)s")
        self._handlers = []
        for name, level in (("execution.log", logging.INFO), ("errors.log", logging.WARNING)):
            h = logging.FileHandler(self.dir / name, encoding="utf-8")
            h.setLevel(level)
            h.setFormatter(fmt_)
            self.log.addHandler(h)
            self._handlers.append(h)
        self.say = say

    def p(self, rel: str | Path) -> Path:
        return self.dir / rel

    def info(self, msg: str, echo: bool = False) -> None:
        self.log.info(msg)
        if echo:
            self.say(msg)

    def warn(self, msg: str, echo: bool = True) -> None:
        self.log.warning(msg)
        if echo:
            self.say("[경고] " + msg)

    def error(self, msg: str, exc: BaseException | None = None, echo: bool = True) -> None:
        tb = "".join(traceback.format_exception(type(exc), exc, exc.__traceback__)) if exc is not None else ""
        self.log.error(msg + ("\n" + tb if tb else ""))
        if echo:
            self.say("[오류] " + msg)

    def json(self, rel: str | Path, obj: Any) -> Path:
        path = self.p(rel)
        write_json(path, obj)
        return path

    def text(self, rel: str | Path, s: str) -> Path:
        path = self.p(rel)
        write_text(path, s)
        return path

    def npz(self, rel: str | Path, **arrays: Any) -> Path:
        path = self.p(rel)
        save_npz(path, **arrays)
        return path

    def append_jsonl(self, rel: str | Path, obj: Any) -> None:
        path = self.p(rel)
        with open(path, "a", encoding="utf-8") as f:
            f.write(dumps(obj, indent=None) + "\n")

    def read_csv(self, rel: str | Path) -> list[dict[str, str]]:
        path = self.p(rel)
        if not path.is_file():
            return []
        with open(path, newline="", encoding="utf-8") as f:
            return list(csv.DictReader(f))

    def append_csv(self, rel: str | Path, row: dict[str, Any]) -> None:
        path = self.p(rel)
        row = {k: _csv_cell(v) for k, v in row.items()}
        if path.is_file():
            with open(path, newline="", encoding="utf-8") as f:
                rd = csv.reader(f)
                header = next(rd, None) or []
            new = [k for k in row if k not in header]
            if new:                                  # 새 열이 생기면 원자적으로 다시 쓴다
                old = self.read_csv(rel)
                cols = header + new
                buf = io.StringIO()
                w = csv.DictWriter(buf, fieldnames=cols)
                w.writeheader()
                for r in old:
                    w.writerow(r)
                w.writerow(row)
                write_text(path, buf.getvalue())
                return
            with open(path, "a", newline="", encoding="utf-8") as f:
                csv.DictWriter(f, fieldnames=header).writerow(row)
            return
        buf = io.StringIO()
        w = csv.DictWriter(buf, fieldnames=list(row))
        w.writeheader()
        w.writerow(row)
        write_text(path, buf.getvalue())

    def close(self) -> None:
        for h in self._handlers:
            self.log.removeHandler(h)
            h.close()
        self._handlers = []


class PhaseTimer:
    """실행 시간 (벽시계). gpu=True 이면 CUDA 동기화 뒤에 잰다. 시뮬레이션 시간이 아니다."""

    def __init__(self, be: Backend):
        self.be = be
        self.t: dict[str, float] = {}

    @contextlib.contextmanager
    def phase(self, name: str, gpu: bool = False) -> Iterator[None]:
        if gpu:
            self.be.sync()
        t0 = time.perf_counter()
        try:
            yield
        finally:
            if gpu:
                self.be.sync()
            self.t[name] = self.t.get(name, 0.0) + time.perf_counter() - t0

    def take(self) -> dict[str, float]:
        out = {f"time_{k}_s": round(v, 4) for k, v in self.t.items()}
        self.t = {}
        return out


class StopFlag:
    """학습 중 Ctrl+C. 첫 번째: 현재 배치를 마친 안전한 경계에서 멈춤. 두 번째: 즉시 중단 (진행 중 배치의 q 는 되돌린다).
    critical() 안에서는 즉시 중단을 미뤘다가 끝에서 일으킨다 (q 적용·기록·checkpoint 를 반쯤 끝내지 않기 위해)."""

    def __init__(self, say: Callable[[str], None] = print):
        self.say = say
        self.requested = False
        self._old: Any = None
        self._in_critical = 0
        self._pending = False
        self._installed = False

    def __enter__(self) -> "StopFlag":
        if threading.current_thread() is threading.main_thread():
            try:
                self._old = signal.getsignal(signal.SIGINT)
                signal.signal(signal.SIGINT, self._handler)
                self._installed = True
            except (ValueError, OSError):
                self._installed = False
        return self

    def _handler(self, signum: int, frame: Any) -> None:
        if self.requested:
            if self._in_critical:
                self._pending = True
                return
            raise KeyboardInterrupt
        self.requested = True
        self.say("\n[중단 요청] 현재 배치를 마친 뒤 checkpoint 를 저장하고 멈춘다. 한 번 더 누르면 즉시 중단 (진행 중 배치 취소).")

    @contextlib.contextmanager
    def critical(self) -> Iterator[None]:
        self._in_critical += 1
        try:
            yield
        finally:
            self._in_critical -= 1
            if not self._in_critical and self._pending:
                self._pending = False
                raise KeyboardInterrupt

    def __exit__(self, *exc: Any) -> None:
        if self._installed:
            signal.signal(signal.SIGINT, self._old)


# ======================================================================
# 4. 이미지 입력, 데이터 검사·분할 (DatasetManager)
# ======================================================================
def _require_pil() -> None:
    if Image is None:
        raise RuntimeError(f"Pillow 를 불러올 수 없다: {_PIL_ERROR}")


def load_pil_rgb(path: Path, background: float = 1.0) -> tuple[Any, dict[str, Any]]:
    """이미지를 RGB 로 연다. 투명 화소는 background 밝기 위에 합성한다. 여러 프레임이면 첫 프레임."""
    _require_pil()
    with Image.open(path) as im:
        meta = {"width": int(im.width), "height": int(im.height), "mode": im.mode, "format": im.format,
                "n_frames": int(getattr(im, "n_frames", 1))}
        if getattr(im, "n_frames", 1) > 1:
            im.seek(0)
        if im.mode in ("RGBA", "LA", "PA") or (im.mode == "P" and "transparency" in im.info):
            rgba = im.convert("RGBA")
            v = int(round(float(background) * 255))
            base = Image.new("RGBA", rgba.size, (v, v, v, 255))
            out = Image.alpha_composite(base, rgba).convert("RGB")
            meta["alpha_composited"] = True
        else:
            out = im.convert("RGB")
            meta["alpha_composited"] = False
        out.load()
    return out, meta


class DatasetManager:
    """데이터 폴더: 하위 폴더 이름 = 클래스. 손상·미지원·빈 클래스·중복 이미지를 기록하고, 그룹을 지켜 층화 분할한다."""

    def __init__(self, cfg: dict[str, Any], root: Path):
        self.cfg = cfg
        self.root = Path(root)
        self.report: dict[str, Any] | None = None
        self.records: list[dict[str, Any]] = []
        self.manifest: dict[str, Any] | None = None
        self.classes: list[str] = []
        self.class_to_index: dict[str, int] = {}
        self._items_by_split: dict[str, list[dict[str, Any]]] = {}

    # ---------------------------------------------------------------- 검사
    def scan(self, progress: Callable[[str], None] | None = None) -> dict[str, Any]:
        _require_pil()
        if not self.root.is_dir():
            raise DataError(f"데이터 폴더가 없다: {self.root}")
        exts = {e.lower() for e in self.cfg["data"]["extensions"]}
        bg = float(self.cfg["data"]["transparent_background"])
        class_dirs = sorted([d for d in self.root.iterdir() if d.is_dir() and not d.name.startswith(".")], key=lambda d: d.name)
        root_files = sorted(p.name for p in self.root.iterdir() if p.is_file())
        recs: list[dict[str, Any]] = []
        corrupt, unsupported, hidden, empty = [], [], [], []
        per_class_files: dict[str, int] = {}
        for cdir in class_dirs:
            files = sorted([p for p in cdir.rglob("*") if p.is_file()], key=lambda p: p.relative_to(self.root).as_posix())
            n_ok = 0
            for p in files:
                rel = p.relative_to(self.root).as_posix()
                if any(part.startswith(".") for part in p.relative_to(cdir).parts):
                    hidden.append(rel)
                    continue
                if p.suffix.lower() not in exts:
                    unsupported.append(rel)
                    continue
                try:
                    with Image.open(p) as im0:
                        im0.verify()
                    im, meta = load_pil_rgb(p, bg)
                    arr = np.asarray(im, dtype=np.uint8)
                    pix = sha256_bytes(f"{arr.shape[1]}x{arr.shape[0]}|".encode() + arr.tobytes())
                except Exception as exc:                     # noqa: BLE001
                    corrupt.append({"relpath": rel, "error": f"{type(exc).__name__}: {exc}"})
                    continue
                recs.append({"relpath": rel, "class": cdir.name, "sha256": sha256_file(p), "pixel_sha256": pix,
                             "width": meta["width"], "height": meta["height"], "mode": meta["mode"], "format": meta["format"],
                             "alpha_composited": meta["alpha_composited"]})
                n_ok += 1
            per_class_files[cdir.name] = n_ok
            if n_ok == 0:
                empty.append(cdir.name)
            if progress:
                progress(f"  {cdir.name}: 유효 이미지 {n_ok}")
        by_pix: dict[str, list[dict[str, Any]]] = {}
        for r in recs:
            by_pix.setdefault(r["pixel_sha256"], []).append(r)
        conflicts = {k: v for k, v in by_pix.items() if len({r["class"] for r in v}) > 1}
        excluded = {r["relpath"] for v in conflicts.values() for r in v}
        kept = [r for r in recs if r["relpath"] not in excluded]
        dup_groups = [[r["relpath"] for r in v] for k, v in by_pix.items() if len(v) > 1 and k not in conflicts]
        self.records = kept
        self.classes = sorted({r["class"] for r in kept})
        self.class_to_index = {c: i for i, c in enumerate(self.classes)}
        ws = np.array([r["width"] for r in kept]) if kept else np.zeros(0)
        hs = np.array([r["height"] for r in kept]) if kept else np.zeros(0)
        self.report = {
            "data_root": str(self.root), "utc": utc_now(), "n_class_folders": len(class_dirs),
            "classes": self.classes, "n_classes": len(self.classes),
            "valid_images_per_class": {c: sum(1 for r in kept if r["class"] == c) for c in self.classes},
            "n_valid_images": len(kept), "corrupt": corrupt, "unsupported": unsupported, "hidden_ignored": hidden,
            "empty_classes_excluded": empty, "root_files_ignored": root_files,
            "exact_duplicate_groups": dup_groups,
            "cross_class_duplicates_excluded": [[r["relpath"] for r in v] for v in conflicts.values()],
            "original_size": {"width_min": int(ws.min()) if ws.size else None, "width_max": int(ws.max()) if ws.size else None,
                              "height_min": int(hs.min()) if hs.size else None, "height_max": int(hs.max()) if hs.size else None,
                              "width_median": float(np.median(ws)) if ws.size else None,
                              "height_median": float(np.median(hs)) if hs.size else None},
            "duplicate_rule_ko": ("같은 화소 내용 (디코드한 RGB 와 크기의 SHA256) 과 파일 이름 규칙 (group_suffix_regex 로 접미사 제거) 으로만 "
                                  "그룹을 만든다. 다시 찍은 사진 같은 근접 중복은 탐지하지 못한다. 서로 다른 클래스에 같은 화소 내용이 있으면 "
                                  "라벨 충돌로 모두 제외한다."),
        }
        if len(self.classes) < 2:
            raise DataError(f"유효 이미지가 있는 클래스가 2 개 미만이다: {self.classes}")
        return self.report

    # ---------------------------------------------------------------- 분할
    def _groups(self) -> list[int]:
        rx = re.compile(str(self.cfg["data"]["group_suffix_regex"]), re.IGNORECASE)
        n = len(self.records)
        parent = list(range(n))

        def find(i: int) -> int:
            while parent[i] != i:
                parent[i] = parent[parent[i]]
                i = parent[i]
            return i

        def union(i: int, j: int) -> None:
            a, b = find(i), find(j)
            if a != b:
                parent[max(a, b)] = min(a, b)

        first: dict[tuple[str, ...], int] = {}
        for i, r in enumerate(self.records):
            p = Path(r["relpath"])
            stem = rx.sub("", p.stem.lower()) or p.stem.lower()
            for key in (("pix", r["pixel_sha256"]), ("stem", r["class"], p.parent.as_posix(), stem)):
                if key in first:
                    union(i, first[key])
                else:
                    first[key] = i
        return [find(i) for i in range(n)]

    def split(self, seed: int) -> dict[str, Any]:
        if not self.records:
            raise SplitError("먼저 scan() 으로 데이터를 검사하라.")
        ratios = self.cfg["data"]["split_ratios"]
        gid = self._groups()
        rng = np.random.default_rng([int(seed), 7])
        assign: dict[int, str] = {}
        per_class: dict[str, Any] = {}
        for c in self.classes:
            groups = sorted({gid[i] for i, r in enumerate(self.records) if r["class"] == c},
                            key=lambda g: self.records[g]["relpath"])
            ng = len(groups)
            if ng < 3:
                raise SplitError(f"클래스 '{c}' 의 독립 그룹이 {ng} 개라 train/dev/test 로 나눌 수 없다 (이미지를 중복 배정하지 않는다).")
            n_test = max(1, int(round(ng * float(ratios["test"]))))
            n_dev = max(1, int(round(ng * float(ratios["dev"]))))
            while n_test + n_dev > ng - 1:
                if n_test >= n_dev and n_test > 1:
                    n_test -= 1
                elif n_dev > 1:
                    n_dev -= 1
                else:
                    raise SplitError(f"클래스 '{c}': 그룹 {ng} 개로 분할 불가.")
            order = [groups[k] for k in rng.permutation(ng)]
            for k, g in enumerate(order):
                assign[g] = "test" if k < n_test else ("dev" if k < n_test + n_dev else "train")
            per_class[c] = {"n_groups": ng, "n_test_groups": n_test, "n_dev_groups": n_dev, "n_train_groups": ng - n_test - n_dev}
        items = []
        for i, r in enumerate(self.records):
            items.append({"index": i, "relpath": r["relpath"], "class": r["class"], "label": self.class_to_index[r["class"]],
                          "group": f"g{gid[i]:06d}", "split": assign[gid[i]], "sha256": r["sha256"],
                          "pixel_sha256": r["pixel_sha256"], "width": r["width"], "height": r["height"]})
        for c in self.classes:
            for sp in ("train", "dev", "test"):
                per_class[c][f"n_{sp}_images"] = sum(1 for it in items if it["class"] == c and it["split"] == sp)
        self.manifest = self._finish_manifest(items, seed, per_class)
        return self.manifest

    def _finish_manifest(self, items: list[dict[str, Any]], seed: int, per_class: dict[str, Any]) -> dict[str, Any]:
        fp = sha256_text(dumps(sorted((it["relpath"], it["sha256"], it["class"]) for it in items), indent=None))
        ssha = sha256_text(dumps(sorted((it["relpath"], it["split"]) for it in items), indent=None))
        man = {"format": f"{PROGRAM}/split/1", "source": "folder", "utc": utc_now(), "data_root": str(self.root), "seed": int(seed),
               "split_ratios": self.cfg["data"]["split_ratios"], "classes": self.classes, "class_to_index": self.class_to_index,
               "n_items": len(items), "per_class": per_class, "data_fingerprint_sha256": fp, "split_sha256": ssha,
               "group_rule_ko": "같은 화소 내용 또는 같은 정규화 파일 이름 (같은 하위 폴더) 은 같은 그룹 → 같은 분할", "items": items}
        self._items_by_split = {sp: [it for it in items if it["split"] == sp] for sp in ("train", "dev", "test")}
        return man

    @classmethod
    def from_manifest(cls, cfg: dict[str, Any], root: Path, man: dict[str, Any]) -> "DatasetManager":
        source = man.get("source", "folder")
        if source != cfg["data"]["source"]:
            raise CompatibilityError("설정과 저장 분할의 데이터 종류가 다르다. 데이터 변경은 새 실행에서 한다.")
        dm = make_dataset_manager(cfg, root)
        dm.classes = list(man["classes"])
        dm.class_to_index = {str(k): int(v) for k, v in man["class_to_index"].items()}
        dm.manifest = man
        dm._items_by_split = {sp: [it for it in man["items"] if it["split"] == sp] for sp in ("train", "dev", "test")}
        return dm

    def verify_files(self) -> list[str]:
        """재개 전에 분할 목록의 파일이 그대로인지 확인 (SHA256)."""
        probs = []
        for it in (self.manifest or {}).get("items", []):
            p = self.root / it["relpath"]
            if not p.is_file():
                probs.append(f"없음: {it['relpath']}")
            elif sha256_file(p) != it["sha256"]:
                probs.append(f"내용 바뀜: {it['relpath']}")
            if len(probs) > 20:
                probs.append("... (이하 생략)")
                break
        return probs

    def items(self, split: str) -> list[dict[str, Any]]:
        return list(self._items_by_split.get(split, []))

    def load_image(self, item: dict[str, Any]) -> tuple[Any, dict[str, Any]]:
        return load_pil_rgb(self.root / item["relpath"], float(self.cfg["data"]["transparent_background"]))

    def ids_sha(self, split: str) -> str:
        return sha256_text("\n".join(sorted(it["relpath"] for it in self.items(split))))


# MNIST 공식 gzip IDX. 주소/체크섬: torchvision의 공개 MNIST 데이터 명세.
# https://docs.pytorch.org/vision/stable/_modules/torchvision/datasets/mnist.html
# torchvision 실행/설치 없이 표준 라이브러리와 NumPy만 사용한다.
MNIST_MIRROR = "https://ossci-datasets.s3.amazonaws.com/mnist/"
MNIST_RESOURCES = (
    ("train-images-idx3-ubyte.gz", "f68b3c2dcbeaaa9fbdd348bbdeb94873", "train_images", (60000, 28, 28)),
    ("train-labels-idx1-ubyte.gz", "d53e105ee54ea40749a09fcbcd1e9432", "train_labels", (60000,)),
    ("t10k-images-idx3-ubyte.gz", "9fb629c4189551a2d022fa330f9573f3", "test_images", (10000, 28, 28)),
    ("t10k-labels-idx1-ubyte.gz", "ec29112dd5afa0611ce80d1b7f02629c", "test_labels", (10000,)),
)


def _md5_file(path: Path) -> str:
    h = hashlib.md5(usedforsecurity=False)  # 공개 데이터 무결성 체크섬; 인증/암호화 용도가 아님
    with path.open("rb") as f:
        for block in iter(lambda: f.read(1024 * 1024), b""):
            h.update(block)
    return h.hexdigest()


def read_mnist_idx(path: Path, shape: tuple[int, ...]) -> tuple[np.ndarray, str]:
    """magic/type/shape/정확한 payload 길이 검사. 잘못된 IDX를 유효 이미지로 묵인하지 않는다."""
    header_size = 4 + 4 * len(shape)
    size = header_size + math.prod(shape)
    with gzip.open(path, "rb") as f:
        payload = f.read(size + 1)
    if len(payload) != size:
        raise DataError(f"MNIST IDX 길이 오류: {path.name} ({len(payload)} != {size})")
    magic = struct.unpack_from(">I", payload, 0)[0]
    actual = struct.unpack_from(">" + "I" * len(shape), payload, 4)
    if magic != 2048 + len(shape) or actual != shape:
        raise DataError(f"MNIST IDX 헤더 오류: {path.name}, magic={magic}, shape={actual}, 기대={shape}")
    arr = np.frombuffer(payload, dtype=np.uint8, offset=header_size).reshape(shape)
    if len(shape) == 1 and np.any(arr > 9):
        raise DataError(f"MNIST 라벨 범위 오류: {path.name} (0~9 필요)")
    return arr, sha256_bytes(payload)


class MNISTDatasetManager(DatasetManager):
    """공식 test를 보존하는 가상 이미지 목록. 모델/학습 경로는 폴더형과 동일하다.
    train/dev는 공식 train의 인덱스를 seed 고정 층화 분할한다. 근접 중복/필체(writer) 분할은 아니다.
    정확한 화소 중복은 보고하되 표준 test 표본을 삭제하거나 재배정하지 않는다.
    """

    def __init__(self, cfg: dict[str, Any], root: Path):
        super().__init__(cfg, root)
        self._arrays: dict[str, np.ndarray] = {}
        self._archives: dict[str, dict[str, Any]] = {}

    def _archive(self, name: str, checksum: str, download: bool,
                 progress: Callable[[str], None] | None) -> Path:
        # 이 프로그램의 캐시, torchvision 캐시, 사용자가 복사한 gzip 파일을 받는다.
        choices = [self.root / "MNIST" / "raw" / name, self.root / "raw" / name, self.root / name]
        for p in choices:
            if p.is_file():
                if _md5_file(p) != checksum:
                    raise DataError(f"MNIST 체크섬 불일치: {p}. 잘못된 파일을 별도로 옮긴 뒤 다시 준비하라.")
                return p
        if not download:
            raise DataError(f"MNIST 파일 없음: {name}. 캐시 폴더에 공식 .gz 4개를 복사하거나 내려받기를 허용하라.")
        dest = choices[0]
        dest.parent.mkdir(parents=True, exist_ok=True)
        if progress:
            progress(f"  MNIST 내려받는 중: {name}")
        fd, temporary = tempfile.mkstemp(prefix=name + ".", suffix=".part", dir=dest.parent)
        part = Path(temporary)
        try:
            with os.fdopen(fd, "wb") as out:
                request = urllib.request.Request(MNIST_MIRROR + name, headers={"User-Agent": PROGRAM + "/" + VERSION})
                with urllib.request.urlopen(request, timeout=30) as response:
                    total = 0
                    while True:
                        block = response.read(1024 * 1024)
                        if not block:
                            break
                        total += len(block)
                        if total > 64 * 1024 * 1024:
                            raise DataError("MNIST 압축 파일 크기 상한(64 MiB)을 넘었다.")
                        out.write(block)
            if _md5_file(part) != checksum:
                raise DataError(f"내려받은 MNIST 체크섬 불일치: {name}")
            os.replace(part, dest)
        except (OSError, ValueError, DataError) as exc:
            raise DataError(f"MNIST 준비 실패 ({name}): {exc}. 인터넷 연결을 확인하거나 공식 .gz 4개를 캐시에 복사하라.") from exc
        finally:
            with contextlib.suppress(FileNotFoundError):
                part.unlink()
        return dest

    def _load_archives(self, download: bool, progress: Callable[[str], None] | None = None) -> None:
        if self._arrays:
            return
        arrays, archives = {}, {}
        for name, checksum, key, shape in MNIST_RESOURCES:
            p = self._archive(name, checksum, download, progress)
            arrays[key], raw_sha = read_mnist_idx(p, shape)
            archives[name] = {"relpath": p.relative_to(self.root).as_posix(), "md5": checksum,
                              "sha256": sha256_file(p), "idx_sha256": raw_sha, "shape": list(shape)}
        for source in ("train", "test"):
            if len(arrays[source + "_images"]) != len(arrays[source + "_labels"]):
                raise DataError(f"MNIST {source} 영상/라벨 개수 불일치")
        self._arrays, self._archives = arrays, archives

    def scan(self, progress: Callable[[str], None] | None = None) -> dict[str, Any]:
        _require_pil()
        self._load_archives(bool(self.cfg["data"]["mnist_download"]), progress)
        self.classes = [str(i) for i in range(10)]
        self.class_to_index = {c: int(c) for c in self.classes}
        recs, by_pix = [], {}
        for source in ("train", "test"):
            images, labels = self._arrays[source + "_images"], self._arrays[source + "_labels"]
            for idx, (im, label) in enumerate(zip(images, labels)):
                pix = sha256_bytes(b"28x28|" + im.tobytes())
                rec = {"relpath": f"mnist/{source}/{idx:05d}.png", "class": str(int(label)),
                       "official_split": source, "official_index": idx, "virtual_image": True,
                       "sha256": sha256_bytes(im.tobytes() + bytes([int(label)])), "pixel_sha256": pix,
                       "width": 28, "height": 28}
                recs.append(rec)
                by_pix.setdefault(pix, []).append(rec)
            if progress:
                progress(f"  MNIST 공식 {source}: {len(images):,} 장 (IDX 무결성 확인)")
        self.records = recs
        dup = [v for v in by_pix.values() if len(v) > 1]
        conflicts = [v for v in dup if len({r["class"] for r in v}) > 1]
        self.report = {
            "source": "mnist", "data_root": str(self.root), "utc": utc_now(), "archives": self._archives,
            "n_class_folders": 0, "classes": self.classes, "n_classes": 10, "n_valid_images": len(recs),
            "valid_images_per_class": {c: sum(r["class"] == c for r in recs) for c in self.classes},
            "corrupt": [], "unsupported": [], "hidden_ignored": [], "empty_classes_excluded": [], "root_files_ignored": [],
            "exact_duplicate_groups": [[r["relpath"] for r in v] for v in dup],
            "cross_class_duplicates_excluded": [],
            "cross_class_duplicates_observed_not_excluded": [[r["relpath"] for r in v] for v in conflicts],
            "original_size": {"width_min": 28, "width_max": 28, "width_median": 28.0,
                              "height_min": 28, "height_max": 28, "height_median": 28.0},
            "duplicate_rule_ko": "원본 28×28 화소 완전 일치만 기록. 공식 test 구성 보존을 위해 중복을 삭제하지 않는다. "
                                 "train/dev는 인덱스 층화 분할; 중복이 경계를 넘으면 split_manifest에 수를 보고한다. writer/근접 중복 분할 아님.",
            "preprocessing_ko": f"28×28 회색조 → R=G=B 복제 → 기존 {self.cfg['data']['image_size']}×"
                                f"{self.cfg['data']['image_size']} 전처리. 반전/추가 블러/전 데이터 표준화 없음. 확대는 새 정보를 만들지 않음.",
        }
        return self.report

    def split(self, seed: int) -> dict[str, Any]:
        if not self.records:
            raise SplitError("먼저 scan()으로 MNIST를 검사하라.")
        labels = self._arrays["train_labels"]
        n_dev = int(self.cfg["data"]["mnist_dev_size"])
        counts = np.bincount(labels, minlength=10)
        if np.any(counts < 2) or not 10 <= n_dev <= len(labels) - 10:
            raise SplitError("MNIST train/dev에 각 숫자 최소 1장을 배정할 수 없다.")
        quotas = counts.astype(np.float64) * n_dev / len(labels)
        allocation = np.minimum(np.maximum(np.floor(quotas).astype(int), 1), counts - 1)
        # 최대 잔여 방식 + 클래스 순서 동률 처리. 정확히 요청한 dev 개수를 보존한다.
        while int(allocation.sum()) < n_dev:
            scores = np.where(allocation < counts - 1, quotas - allocation, -np.inf)
            allocation[int(np.argmax(scores))] += 1
        while int(allocation.sum()) > n_dev:
            scores = np.where(allocation > 1, allocation - quotas, -np.inf)
            allocation[int(np.argmax(scores))] -= 1
        rng = np.random.default_rng([int(seed), 107])  # 모델 초기화/학습 순서와 독립
        dev = set()
        for label in range(10):
            inds = np.flatnonzero(labels == label)
            dev.update(map(int, rng.permutation(inds)[:int(allocation[label])]))
        items = []
        for index, rec in enumerate(self.records):
            source, idx = rec["official_split"], rec["official_index"]
            sp = "test" if source == "test" else ("dev" if idx in dev else "train")
            items.append({**rec, "index": index, "label": int(rec["class"]),
                          "group": f"mnist-{source}-{idx:05d}", "split": sp})
        per_class = {}
        for c in self.classes:
            per_class[c] = {"n_groups": sum(it["class"] == c for it in items)}
            for sp in ("train", "dev", "test"):
                n = sum(it["class"] == c and it["split"] == sp for it in items)
                per_class[c]["n_" + sp + "_images"] = n
                per_class[c][sp + "_groups"] = n
        man = self._finish_manifest(items, seed, per_class)
        hash_splits: dict[str, set[str]] = {}
        for it in items:
            hash_splits.setdefault(it["pixel_sha256"], set()).add(it["split"])
        overlap = {f"{a}__{b}": sum(a in splits and b in splits for splits in hash_splits.values())
                   for a, b in (("train", "dev"), ("train", "test"), ("dev", "test"))}
        man.update({"source": "mnist", "archives": self._archives, "split_ratios": None,
                    "split_policy": "official-test-stratified-train-v1", "mnist_dev_size": n_dev,
                    "official_counts": {sp: len(self._arrays[sp + "_labels"]) for sp in ("train", "test")},
                    "exact_pixel_overlap_groups": overlap,
                    "group_rule_ko": "공식 test 전체 유지. 공식 train만 seed 고정 라벨 층화 분할; 인덱스별 독립 배정. "
                                     "동일 화소의 경계 중복 수는 별도 보고; 클래스별 폴더 비율은 적용하지 않음."})
        self.manifest = man
        return man

    def load_image(self, item: dict[str, Any]) -> tuple[Any, dict[str, Any]]:
        self._load_archives(download=False)        # 학습/추론 중 숨은 내려받기 없음
        source, idx = item["official_split"], int(item["official_index"])
        image = Image.fromarray(self._arrays[source + "_images"][idx]).convert("RGB")
        return image, {"width": 28, "height": 28, "mode": "L", "format": "MNIST_IDX", "alpha_composited": False}

    def verify_files(self) -> list[str]:
        """재개: 공식 checksum, IDX, 라벨/분할/샘플 해시를 재검증. 네트워크 접근 없음."""
        try:
            cfg = copy.deepcopy(self.cfg)
            cfg["data"]["mnist_download"] = False
            check = MNISTDatasetManager(cfg, self.root)
            check.scan()
            expected = check.split(int(cfg["seed"]))
            saved = self.manifest or {}
            for key in ("source", "classes", "class_to_index", "n_items", "data_fingerprint_sha256", "split_sha256",
                        "split_policy", "mnist_dev_size", "items"):
                if saved.get(key) != expected[key]:
                    return [f"MNIST 저장 목록/분할 불일치: {key}"]
            self._arrays, self._archives = check._arrays, check._archives
            return []
        except (OSError, ValueError, DataError, SplitError) as exc:
            return [f"MNIST 검증 실패: {exc}"]


def make_dataset_manager(cfg: dict[str, Any], root: Path) -> DatasetManager:
    return (MNISTDatasetManager if cfg["data"]["source"] == "mnist" else DatasetManager)(cfg, root)


# ======================================================================
# 5. 망막/LGN 근사와 로그-극좌표 표본 (RetinaLGNPreprocessor)
# ======================================================================
def logpolar_positions(n_r: int, n_phi: int, r0: float, rmax: float, cx: float, cy: float, phi_offset: float) -> dict[str, Any]:
    """r(u) = r0·(exp(u·log(1+Rmax/r0)) − 1), u_k = (k+0.5)/n_r ;  φ_m = 2π(m+offset)/n_phi ;
    x = cx + r cos φ,  y = cy − r sin φ  (화소 좌표: x 오른쪽, y 아래쪽. φ 는 위쪽 기준 반시계).  위치 순서 pos = k·n_phi + m."""
    L = math.log1p(rmax / r0)
    u = (np.arange(n_r) + 0.5) / n_r
    r = r0 * (np.exp(u * L) - 1.0)
    phi = 2.0 * math.pi * (np.arange(n_phi) + phi_offset) / n_phi
    R, PHI = np.meshgrid(r, phi, indexing="ij")
    x = cx + R * np.cos(PHI)
    y = cy - R * np.sin(PHI)
    sr = (R + r0) * L / n_r
    sp = 2.0 * math.pi * R / n_phi
    return {"n_r": n_r, "n_phi": n_phi, "x": x.ravel(), "y": y.ravel(), "r": R.ravel(), "phi": PHI.ravel(),
            "ring": np.repeat(np.arange(n_r), n_phi), "ang": np.tile(np.arange(n_phi), n_r),
            "spacing_r": sr.ravel(), "spacing_phi": sp.ravel(), "L": L, "r0": r0, "rmax": rmax}


def gauss1d(sigma: float, truncate: float, n_max: int) -> np.ndarray:
    if sigma <= 0:
        return np.ones(1, np.float64)
    r = int(min(math.ceil(truncate * sigma), max(n_max - 1, 0)))
    x = np.arange(-r, r + 1, dtype=np.float64)
    k = np.exp(-x * x / (2.0 * sigma * sigma))
    return k / k.sum()


def _conv1d_reflect(m: np.ndarray, k: np.ndarray, axis: int) -> np.ndarray:
    r = (len(k) - 1) // 2
    if r == 0:
        return m * k[0]
    pad = [(0, 0), (0, 0)]
    pad[axis] = (r, r)
    p = np.pad(m, pad, mode="reflect")
    out = np.zeros_like(m)
    n = m.shape[axis]
    for i, kv in enumerate(k):
        sl = [slice(None), slice(None)]
        sl[axis] = slice(i, i + n)
        out += kv * p[tuple(sl)]
    return out


def blur2d(m: np.ndarray, k: np.ndarray) -> np.ndarray:
    return _conv1d_reflect(_conv1d_reflect(m, k, 0), k, 1)


class RetinaLGNPreprocessor:
    """망막/LGN 근사 (디지털 RGB 계산 근사이며 생리학적 LMS 변환이 아니다).

    입력 RGB [0,1] (H,W,3) → (S,S,3) 크기 맞춤 → 대립색 lum=R+G, rg=R−G, by=B−(R+G)/2
    → DoG = G_σc * x − G_σs * x (각 커널 합 1, reflect 경계) → ON = max(0, DoG), OFF = max(0, −DoG)
    → 이심률별 저역통과 (표본 간격 × β 에 가장 가까운 Gaussian 단계) → 로그-극좌표 표본 (쌍선형 보간).
    출력: (n_pos·n_maps,) float32, index = pos·n_maps + map (위치 우선), pos = ring·n_phi + angle.
    맵은 V1 이 실제로 쓰는 색 채널의 ON/OFF 만 만든다 (기본 lum_on, lum_off).
    """

    def __init__(self, cfg: dict[str, Any]):
        d, rt, lp = cfg["data"], cfg["retina"], cfg["logpolar"]
        self.S = S = int(d["image_size"])
        self.bg = float(d["transparent_background"])
        self.cx = self.cy = (S - 1) / 2.0
        self.colors = list(cfg["areas"]["V1"]["color_channels"])
        self.maps = [f"{c}_{pol}" for c in self.colors for pol in ("on", "off")]
        self.n_maps = len(self.maps)
        self.sig_c, self.sig_s = float(rt["sigma_center_px"]), float(rt["sigma_surround_px"])
        self.trunc = float(rt["truncate_sigma"])
        self.gain = float(rt["gain"])
        self.kc = gauss1d(self.sig_c, self.trunc, S)
        self.ks = gauss1d(self.sig_s, self.trunc, S)
        self.r0 = float(lp["r0_px"])
        self.rmax = S / 2.0 - float(lp["rmax_margin_px"])
        self.phi_offset = float(lp["phi_offset_bins"])
        g = logpolar_positions(int(lp["n_r"]), int(lp["n_phi"]), self.r0, self.rmax, self.cx, self.cy, self.phi_offset)
        self.grid = g
        self.n_pos = int(lp["n_r"]) * int(lp["n_phi"])
        self.n_out = self.n_pos * self.n_maps
        x, y = g["x"], g["y"]
        if (x < 0).any() or (x > S - 1).any() or (y < 0).any() or (y > S - 1).any():
            raise ConfigError("로그-극좌표 표본이 영상 밖에 있다. rmax_margin_px 를 키워라.")
        self.levels = sorted({0.0} | {float(v) for v in lp["blur_levels_px"]})
        spacing = np.maximum(g["spacing_r"], g["spacing_phi"])
        req = float(lp["blur_beta"]) * spacing
        lv = np.asarray(self.levels)
        self.level_of_pos = np.argmin(np.abs(req[:, None] - lv[None, :]), axis=1)
        self.level_kernels = [gauss1d(s, self.trunc, S) for s in self.levels]
        x0 = np.clip(np.floor(x).astype(np.int64), 0, S - 2)
        y0 = np.clip(np.floor(y).astype(np.int64), 0, S - 2)
        self._bil = (y0, x0, (y - y0).astype(np.float64), (x - x0).astype(np.float64))
        self.sample_area_px2 = (g["spacing_r"] * g["spacing_phi"]).astype(np.float64)
        self._nearest_map: tuple[np.ndarray, np.ndarray] | None = None
        # 원점 근처 근접 중복 표본 (0.5 화소 안)
        close = 0
        for a in range(0, self.n_pos, 512):
            d2 = (x[a:a + 512, None] - x[None, :]) ** 2 + (y[a:a + 512, None] - y[None, :]) ** 2
            close += int(((d2 < 0.25).sum() - min(512, self.n_pos - a)))
        self.near_duplicate_pairs = close // 2

    # ---------------------------------------------------------------- 단계
    def resize_pad(self, im: Any) -> tuple[np.ndarray, dict[str, Any]]:
        S = self.S
        w, h = im.size
        s = S / float(max(w, h))
        nw, nh = max(1, int(round(w * s))), max(1, int(round(h * s)))
        resample = getattr(getattr(Image, "Resampling", Image), "LANCZOS")
        im2 = im.resize((nw, nh), resample) if (nw, nh) != (w, h) else im
        arr = np.asarray(im2, dtype=np.float32) / 255.0
        top, left = (S - nh) // 2, (S - nw) // 2
        arr = np.pad(arr, ((top, S - nh - top), (left, S - nw - left), (0, 0)), mode="edge")
        return arr, {"orig_w": w, "orig_h": h, "scale": s, "resized_w": nw, "resized_h": nh, "pad_top": top, "pad_left": left}

    @staticmethod
    def opponent(arr: np.ndarray) -> dict[str, np.ndarray]:
        R, G, B = (arr[..., i].astype(np.float64) for i in range(3))
        return {"lum": R + G, "rg": R - G, "by": B - 0.5 * (R + G)}

    def dog(self, m: np.ndarray) -> np.ndarray:
        return self.gain * (blur2d(m, self.kc) - blur2d(m, self.ks))

    def lgn_maps(self, arr: np.ndarray) -> dict[str, np.ndarray]:
        opp = self.opponent(arr)
        out: dict[str, np.ndarray] = {}
        for c in self.colors:
            dg = self.dog(opp[c])
            out[f"{c}_on"] = np.maximum(dg, 0.0)
            out[f"{c}_off"] = np.maximum(-dg, 0.0)
        return out

    def sample(self, maps: dict[str, np.ndarray]) -> np.ndarray:
        y0, x0, fy, fx = self._bil
        vec = np.zeros((self.n_pos, self.n_maps), np.float64)
        for li, k in enumerate(self.level_kernels):
            sel = np.nonzero(self.level_of_pos == li)[0]
            if sel.size == 0:
                continue
            for mi, name in enumerate(self.maps):
                m = maps[name] if len(k) == 1 else blur2d(maps[name], k)
                yy, xx, wy, wx = y0[sel], x0[sel], fy[sel], fx[sel]
                vec[sel, mi] = ((1 - wx) * (1 - wy) * m[yy, xx] + wx * (1 - wy) * m[yy, xx + 1]
                                + (1 - wx) * wy * m[yy + 1, xx] + wx * wy * m[yy + 1, xx + 1])
        return vec.reshape(-1).astype(np.float32)

    def from_array(self, arr: np.ndarray) -> np.ndarray:
        if arr.shape != (self.S, self.S, 3):
            raise ValueError(f"배열 모양 {arr.shape} != ({self.S},{self.S},3)")
        return self.sample(self.lgn_maps(np.asarray(arr, np.float32)))

    def from_path(self, path: Path) -> tuple[np.ndarray, dict[str, Any]]:
        im, meta = load_pil_rgb(path, self.bg)
        arr, m2 = self.resize_pad(im)
        return self.from_array(arr), {**meta, **m2}

    # ---------------------------------------------------------------- 진단
    def info(self) -> dict[str, Any]:
        g = self.grid
        counts = np.bincount(self.level_of_pos, minlength=len(self.levels))
        return {"image_size_px": self.S, "center_px": [self.cx, self.cy], "colors": self.colors, "maps": self.maps,
                "dog_sigma_center_px": self.sig_c, "dog_sigma_surround_px": self.sig_s,
                "dog_kernel_radius_px": [int((len(self.kc) - 1) // 2), int((len(self.ks) - 1) // 2)],
                "border_mode": "reflect", "resize_ko": "긴 변을 S 에 맞춤 (Lanczos), 짧은 변은 가장자리 복제 패딩, 색 범위 [0,1]",
                "logpolar": {"n_r": g["n_r"], "n_phi": g["n_phi"], "r0_px": self.r0, "rmax_px": self.rmax,
                             "phi_offset_bins": self.phi_offset, "rule": "r(u)=r0*(exp(u*log(1+Rmax/r0))-1), u=(k+0.5)/n_r",
                             "ring_radius_px": [float(v) for v in g["r"][::g["n_phi"]]],
                             "origin_sample": False, "angle_seam": "각도 이음매는 이웃 계산에서 wrap",
                             "near_duplicate_pairs_lt_0p5px": self.near_duplicate_pairs,
                             "coverage_fraction_of_image": float(math.pi * self.rmax ** 2 / self.S ** 2)},
                "lowpass_levels_px": self.levels, "positions_per_level": [int(v) for v in counts],
                "interpolation": "bilinear", "n_positions": self.n_pos, "n_maps": self.n_maps, "n_outputs": self.n_out,
                "orientation_frame_ko": "원영상 좌표 (x 오른쪽, y 위쪽, 반시계 각도). V1 필터는 표본의 원영상 좌표에서 계산한다.",
                "dog_border_affected_samples": int((g["r"] > (self.S / 2.0 - (len(self.ks) - 1) / 2.0)).sum())}

    def dc_check(self) -> dict[str, Any]:
        """균일 영상: DoG 커널이 각각 합 1 이라 내부 잔여가 0 이어야 한다. reflect 경계라 균일 영상은 경계에서도 0."""
        S, rad = self.S, int((len(self.ks) - 1) // 2)
        rows = []
        worst_int, worst_border, worst_lgn = 0.0, 0.0, 0.0
        for rgb in ((0, 0, 0), (0.5, 0.5, 0.5), (1, 1, 1), (1, 0, 0), (0, 1, 0), (0, 0, 1), (0.2, 0.6, 0.9)):
            arr = np.ones((S, S, 3), np.float32) * np.asarray(rgb, np.float32)
            opp = self.opponent(arr)
            for c in ("lum", "rg", "by"):
                dg = self.dog(opp[c])
                inner = dg[rad:S - rad, rad:S - rad] if S > 2 * rad else dg[:0, :0]
                bmask = np.ones_like(dg, bool)
                if S > 2 * rad:
                    bmask[rad:S - rad, rad:S - rad] = False
                mi = float(np.abs(inner).max()) if inner.size else 0.0
                mb = float(np.abs(dg[bmask]).max()) if bmask.any() else 0.0
                worst_int, worst_border = max(worst_int, mi), max(worst_border, mb)
                rows.append({"rgb": list(rgb), "channel": c, "max_abs_interior": mi, "max_abs_border": mb})
            worst_lgn = max(worst_lgn, float(np.abs(self.from_array(arr)).max()))
        tol = 1e-6
        return {"status": PASSED if max(worst_int, worst_border, worst_lgn) <= tol else FAILED, "tolerance": tol,
                "max_abs_interior": worst_int, "max_abs_border": worst_border, "max_abs_lgn_sample": worst_lgn,
                "valid_interior_margin_px": rad, "rows": rows,
                "note_ko": "실제 이미지는 가장자리 복제 패딩과 reflect 경계라 테두리 근처 DoG 가 내부와 다르게 계산될 수 있다 "
                           "(dog_border_affected_samples 참고)."}

    def _nearest(self) -> tuple[np.ndarray, np.ndarray]:
        if self._nearest_map is None:
            S = self.S
            yy, xx = np.mgrid[0:S, 0:S].astype(np.float64)
            vx, vy = xx - self.cx, self.cy - yy
            r = np.hypot(vx, vy)
            phi = np.mod(np.arctan2(vy, vx), 2 * math.pi)
            u = np.log1p(r / self.r0) / self.grid["L"]
            k = np.clip(np.floor(u * self.grid["n_r"]).astype(np.int64), 0, self.grid["n_r"] - 1)
            m = np.mod(np.round(phi * self.grid["n_phi"] / (2 * math.pi) - self.phi_offset).astype(np.int64), self.grid["n_phi"])
            self._nearest_map = (k * self.grid["n_phi"] + m, r)
        return self._nearest_map

    def info_loss(self, arr: np.ndarray) -> dict[str, Any]:
        """표본 → 가장 가까운 표본으로 화소 복원 → 원래 ON/OFF 맵과의 상대 오차 (이심률 구간별). 저역통과와 성긴 표본의 손실 지표."""
        maps = self.lgn_maps(arr)
        vec = self.sample(maps).reshape(self.n_pos, self.n_maps).astype(np.float64)
        near, r = self._nearest()
        inside = r <= self.rmax
        bands = np.linspace(0.0, self.rmax, 5)
        out = {"outside_rmax_pixel_fraction": float(1.0 - inside.mean()), "bands_px": bands.tolist(), "maps": {}}
        for mi, name in enumerate(self.maps):
            orig = maps[name]
            rec = vec[near, mi]
            rows = []
            for a, b in zip(bands[:-1], bands[1:]):
                sel = inside & (r >= a) & (r < b if b < self.rmax else r <= b)
                num_ = float(np.sqrt(((rec - orig)[sel] ** 2).sum()))
                den = float(np.sqrt((orig[sel] ** 2).sum()))
                rows.append({"r_from": float(a), "r_to": float(b), "rel_error": (num_ / den) if den > 0 else None,
                             "orig_energy": den})
            out["maps"][name] = rows
        return out


class BatchLoader:
    """분할 목록 → LGN 벡터 배치. 프로세스 안 순차 로딩 (num_workers=0). 전처리 결과는 RAM (CPU) 에 캐시한다.
    분할별 접근 횟수를 센다 (dev/test 사용 기록)."""

    def __init__(self, data: DatasetManager, pre: RetinaLGNPreprocessor, be: Backend, cfg: dict[str, Any], timer: PhaseTimer):
        self.data, self.pre, self.be, self.timer = data, pre, be, timer
        self.cache: dict[str, np.ndarray] = {}
        self.cache_on = bool(cfg["data"]["cache_preprocessed"])
        self.cache_cap = int(cfg["data"]["cache_max_mb"]) * 2 ** 20
        self.cache_bytes = 0
        self.access: dict[str, int] = {"train": 0, "dev": 0, "test": 0, "external": 0}

    def vector(self, item: dict[str, Any]) -> np.ndarray:
        key = item["relpath"]
        v = self.cache.get(key)
        if v is not None:
            return v
        with self.timer.phase("file_read"):
            im, _meta = self.data.load_image(item)
        with self.timer.phase("preprocess"):
            arr, _m2 = self.pre.resize_pad(im)
            v = self.pre.from_array(arr)
        if self.cache_on and self.cache_bytes + v.nbytes <= self.cache_cap:
            self.cache[key] = v
            self.cache_bytes += v.nbytes
        return v

    def batch(self, items: Sequence[dict[str, Any]], split: str) -> tuple[Any, np.ndarray]:
        self.access[split] = self.access.get(split, 0) + len(items)
        X = np.stack([self.vector(it) for it in items], axis=0)
        y = np.asarray([int(it["label"]) for it in items], np.int64)
        return self.be.f32(X), y


# ======================================================================
# 6. 통제 자극 (역할 반응 진단·자체 검사용)
# ======================================================================
class StimulusFactory:
    """처리 크기 S 의 회색조 자극 (RGB 3 채널 동일). 좌표: 화면 중심 기준, x 오른쪽, y 위쪽, 각도 반시계 (원영상 좌표)."""

    def __init__(self, S: int, supersample: int = 3):
        self.S = int(S)
        self.ss = int(supersample)
        n = self.S * self.ss
        c = (n - 1) / 2.0
        yy, xx = np.mgrid[0:n, 0:n].astype(np.float64)
        self.vx = (xx - c) / self.ss
        self.vy = (c - yy) / self.ss

    def _down(self, m: np.ndarray) -> np.ndarray:
        s = self.ss
        return m.reshape(self.S, s, self.S, s).mean(axis=(1, 3))

    @staticmethod
    def rgb(gray: np.ndarray) -> np.ndarray:
        return np.repeat(np.clip(gray, 0, 1)[..., None], 3, axis=2).astype(np.float32)

    def constant(self, v: float) -> np.ndarray:
        return self.rgb(np.full((self.S, self.S), float(v)))

    def _coords(self, theta_deg: float, center: tuple[float, float]) -> tuple[np.ndarray, np.ndarray]:
        t = math.radians(theta_deg)
        dx, dy = self.vx - center[0], self.vy - center[1]
        along = dx * math.cos(t) + dy * math.sin(t)
        perp = -dx * math.sin(t) + dy * math.cos(t)
        return along, perp

    def line_mask(self, theta_deg: float, *, width: float = 2.0, length: float | None = None,
                  center: tuple[float, float] = (0.0, 0.0), half: bool = False) -> np.ndarray:
        along, perp = self._coords(theta_deg, center)
        m = np.abs(perp) <= width / 2.0
        if length is not None:
            m &= np.abs(along) <= length / 2.0
        if half:
            m &= along >= 0
        return self._down(m.astype(np.float64))

    def line(self, theta_deg: float, *, width: float = 2.0, length: float | None = None, fg: float = 1.0, bg: float = 0.0,
             center: tuple[float, float] = (0.0, 0.0)) -> np.ndarray:
        m = self.line_mask(theta_deg, width=width, length=length, center=center)
        return self.rgb(bg + (fg - bg) * m)

    def grating(self, theta_deg: float, wavelength: float, phase: float, contrast: float = 1.0, mean: float = 0.5) -> np.ndarray:
        _along, perp = self._coords(theta_deg, (0.0, 0.0))
        g = mean + 0.5 * contrast * np.cos(2 * math.pi * perp / wavelength + phase)
        return self.rgb(self._down(g))

    def cross(self, t1: float, t2: float, *, width: float = 2.0, fg: float = 1.0, bg: float = 0.0) -> np.ndarray:
        m = np.maximum(self.line_mask(t1, width=width), self.line_mask(t2, width=width))
        return self.rgb(bg + (fg - bg) * m)

    def corner(self, t1: float, t2: float, *, width: float = 2.0, fg: float = 1.0, bg: float = 0.0) -> np.ndarray:
        m = np.maximum(self.line_mask(t1, width=width, half=True), self.line_mask(t2, width=width, half=True))
        return self.rgb(bg + (fg - bg) * m)

    def arc(self, radius: float, *, width: float = 2.0, start_deg: float = 0.0, span_deg: float = 120.0,
            center: tuple[float, float] = (0.0, 0.0), fg: float = 1.0, bg: float = 0.0) -> np.ndarray:
        dx, dy = self.vx - center[0], self.vy - center[1]
        rr = np.hypot(dx, dy)
        ang = np.mod(np.degrees(np.arctan2(dy, dx)) - start_deg, 360.0)
        m = (np.abs(rr - radius) <= width / 2.0) & (ang <= span_deg)
        return self.rgb(bg + (fg - bg) * self._down(m.astype(np.float64)))

    @staticmethod
    def _polygon(px: np.ndarray, py: np.ndarray, verts: Sequence[tuple[float, float]]) -> np.ndarray:
        inside = np.zeros(px.shape, bool)
        n = len(verts)
        for i in range(n):
            x1, y1 = verts[i]
            x2, y2 = verts[(i + 1) % n]
            cond = (y1 > py) != (y2 > py)
            xint = (x2 - x1) * (py - y1) / ((y2 - y1) if y2 != y1 else 1e-12) + x1
            inside ^= cond & (px < xint)
        return inside

    def shape(self, kind: str, size: float, *, center: tuple[float, float] = (0.0, 0.0), rotation_deg: float = 0.0,
              fg: float = 0.0, bg: float = 1.0) -> np.ndarray:
        t = math.radians(rotation_deg)
        dx, dy = self.vx - center[0], self.vy - center[1]
        ax = dx * math.cos(t) + dy * math.sin(t)
        ay = -dx * math.sin(t) + dy * math.cos(t)
        R = size / 2.0
        if kind == "circle":
            m = np.hypot(ax, ay) <= R
        elif kind == "square":
            m = np.maximum(np.abs(ax), np.abs(ay)) <= R * 0.85
        elif kind == "triangle":
            verts = [(R * math.cos(math.radians(90 + 120 * k)), R * math.sin(math.radians(90 + 120 * k))) for k in range(3)]
            m = self._polygon(ax, ay, verts)
        elif kind == "star":
            verts = []
            for k in range(10):
                rr = R if k % 2 == 0 else R * 0.45
                a = math.radians(90 + 36 * k)
                verts.append((rr * math.cos(a), rr * math.sin(a)))
            m = self._polygon(ax, ay, verts)
        else:
            raise ValueError(f"알 수 없는 도형: {kind}")
        return self.rgb(bg + (fg - bg) * self._down(m.astype(np.float64)))


# ======================================================================
# 7. 연결 구조 (LayerSpec / Connectivity) 와 영역 생성기 (V1 / V2 / V4 / IT)
# ======================================================================
@dataclass
class LayerSpec:
    """한 영역·한 층의 고정 구조 (CPU numpy).

    뉴런 순서는 위치 우선: local = pos·n_ch + ch.  입력 연결은 CSR 두 입력군 (A, B):
      A: a_ptr (n+1,), a_src (E_a,) int64 (원천 층 local 주소), a_w (E_a,) float32
      B: b_ptr, b_src, b_w — 역할 연산 min2 뉴런만 쓴다 (u = min(Σ_A, Σ_B)). 선형 뉴런은 u = Σ_A (B 비어 있음).
    좌표: x, y = 수용장 중심 (처리 영상 화소, 원점 왼쪽 위 화소 중심, x 오른쪽, y 아래쪽),
          Z = 영역 번호×10 + 피질층 번호 (무차원 계층 좌표; L6 이웃은 같은 Z 안에서만 고른다).
    """

    area: str
    name: str
    src_key: str
    n_src: int
    n_pos: int
    n_ch: int
    channel_names: list[str]
    channel_roles: list[str]
    channel_meta: dict[str, list[Any]]
    op_min: np.ndarray
    a_ptr: np.ndarray
    a_src: np.ndarray
    a_w: np.ndarray
    b_ptr: np.ndarray
    b_src: np.ndarray
    b_w: np.ndarray
    x: np.ndarray
    y: np.ndarray
    rf: np.ndarray
    ring: np.ndarray
    ang: np.ndarray
    pos_x: np.ndarray
    pos_y: np.ndarray
    pos_rf: np.ndarray
    grid_shape: tuple[int, int] | None
    pos_nb: np.ndarray
    pos_nb_count: np.ndarray
    learnable: bool
    l6_capable: bool
    description: dict[str, Any]
    build_stats: dict[str, Any] = field(default_factory=dict)
    start: int = -1
    end: int = -1
    routed: np.ndarray | None = None          # (n,) bool — 두 번째 입력을 이미지마다 라우팅으로 고르는 행 (새 모드의 V4 L2 곡선)
    missing: np.ndarray | None = None         # (n,) bool — 유효 후보 없음 (missing_candidate): u = 0
    routing: Any = None                       # RoutingTable (v2 모드: geometry_only · v1_guided) 또는 None
    band: Any = None                          # BandTable (v3 모드: expanded_pool · band_gated) 또는 None
    dest: Any = None                          # DestTable (v4 모드: v1_destination_guided) 또는 None
    ratio: Any = None                         # RouteTable (v6 모드: v4_only_ratio_codebook 의 V4/L2 만) 또는 None
    route_space: np.ndarray | None = None     # (n,) int64 — v6 선택 집단의 공간 키 (V4 위치)
    route_family: np.ndarray | None = None    # (n,) int64 — v6 선택 집단의 역할 계열 코드
    route_family_names: list[str] | None = None
    route_space_kind: str | None = None
    ropt: dict[str, np.ndarray] | None = None     # v6 곡선 B 후보 원천 (탈락 후보·사유 포함)
    ropt_removed: dict[str, Any] | None = None    # 수용장 단계에서 후보로 넣지 않은 수와 조건별 탈락 수

    @property
    def key(self) -> str:
        return f"{self.area}/{self.name}"

    @property
    def n(self) -> int:
        return int(self.n_pos * self.n_ch)

    @property
    def z(self) -> float:
        return float(AREA_INDEX[self.area] * 10 + LAYER_NUMBER[self.name])

    def fan_in(self) -> np.ndarray:
        return np.diff(self.a_ptr) + np.diff(self.b_ptr)

    def row(self, j: int) -> dict[str, np.ndarray]:
        return {"a_src": self.a_src[self.a_ptr[j]:self.a_ptr[j + 1]], "a_w": self.a_w[self.a_ptr[j]:self.a_ptr[j + 1]],
                "b_src": self.b_src[self.b_ptr[j]:self.b_ptr[j + 1]], "b_w": self.b_w[self.b_ptr[j]:self.b_ptr[j + 1]]}

    def hash(self) -> str:
        names = sha256_text(dumps([self.key, self.src_key, self.n_src, self.n_pos, self.n_ch, self.channel_names,
                                   self.channel_roles, list(self.grid_shape) if self.grid_shape else None], indent=None))
        h = sha256_text(names + sha256_array(self.op_min, self.a_ptr, self.a_src, self.a_w, self.b_ptr, self.b_src, self.b_w,
                                             self.x, self.y, self.pos_nb, self.pos_nb_count))
        if self.ratio is not None:                  # v6 비율 라우팅 V4/L2: 후보·집단·지원 마스크·설명자 스키마 (route table 해시) 를 더한다
            return sha256_text(h + sha256_array(self.routed, self.missing) + self.ratio.hash())
        if self.routing is None and self.band is None and self.dest is None:      # legacy: v1 과 같은 해시
            return h
        extra = self.routing.hash() if self.routing is not None else (self.band.hash() if self.band is not None else self.dest.hash())
        return sha256_text(h + sha256_array(self.routed, self.missing) + extra)


class CSRBuilder:
    """행별 (송신 주소 → 가중치) 사전. 같은 (수신, 입력군, 송신) 이 다시 오면 가중치를 더한다 (merge_sum 정책, 개수 기록)."""

    def __init__(self, n_rows: int, n_src: int):
        self.n, self.n_src = int(n_rows), int(n_src)
        self.a: list[dict[int, float]] = [{} for _ in range(self.n)]
        self.b: list[dict[int, float]] = [{} for _ in range(self.n)]
        self.merged = 0

    def add(self, row: int, src: int, w: float, group: str = "A") -> None:
        if not (0 <= src < self.n_src):
            raise StructureError(f"송신 주소 {src} 가 원천 층 범위 [0,{self.n_src}) 밖이다.")
        d = (self.a if group == "A" else self.b)[row]
        if src in d:
            d[src] += float(w)
            self.merged += 1
        else:
            d[src] = float(w)

    @staticmethod
    def _csr(rows: list[dict[int, float]]) -> tuple[np.ndarray, np.ndarray, np.ndarray]:
        lens = np.asarray([len(r) for r in rows], np.int64)
        ptr = np.concatenate([[0], np.cumsum(lens)]).astype(np.int64)
        src = np.empty(int(ptr[-1]), np.int64)
        w = np.empty(int(ptr[-1]), np.float32)
        for i, r in enumerate(rows):
            if r:
                ks = sorted(r)
                src[ptr[i]:ptr[i + 1]] = ks
                w[ptr[i]:ptr[i + 1]] = [r[k] for k in ks]
        return ptr, src, w

    def finalize(self) -> tuple[np.ndarray, ...]:
        return (*self._csr(self.a), *self._csr(self.b))


def identity_csr(n: int) -> tuple[np.ndarray, ...]:
    return (np.arange(n + 1, dtype=np.int64), np.arange(n, dtype=np.int64), np.ones(n, np.float32),
            np.zeros(n + 1, np.int64), np.zeros(0, np.int64), np.zeros(0, np.float32))


def grid_neighbors(n_r: int, n_phi: int, radius: int) -> tuple[np.ndarray, np.ndarray]:
    """피질 격자 Chebyshev 거리 ≤ radius 인 위치 (자기 위치 포함). 각도는 wrap, 반경은 경계에서 자른다. 채움 = n_pos."""
    n = n_r * n_phi
    rows = []
    for k in range(n_r):
        for m in range(n_phi):
            s = set()
            for dk in range(-radius, radius + 1):
                kk = k + dk
                if 0 <= kk < n_r:
                    for dm in range(-radius, radius + 1):
                        s.add(kk * n_phi + (m + dm) % n_phi)
            rows.append(sorted(s))
    K = max(len(r) for r in rows)
    idx = np.full((n, K), n, np.int64)
    for i, r in enumerate(rows):
        idx[i, :len(r)] = r
    return idx, np.asarray([len(r) for r in rows], np.int64)


def single_position_neighbors() -> tuple[np.ndarray, np.ndarray]:
    return np.zeros((1, 1), np.int64), np.ones(1, np.int64)


def validate_layer(sp: LayerSpec) -> dict[str, Any]:
    n = sp.n
    for nm in ("op_min", "x", "y", "rf", "ring", "ang"):
        if len(getattr(sp, nm)) != n:
            raise StructureError(f"{sp.key}.{nm} 길이 {len(getattr(sp, nm))} != {n}")
    if len(sp.channel_names) != sp.n_ch or len(sp.channel_roles) != sp.n_ch:
        raise StructureError(f"{sp.key}: 채널 이름·역할 수가 n_ch 와 다르다.")
    out: dict[str, Any] = {}
    for g, ptr, src, w in (("A", sp.a_ptr, sp.a_src, sp.a_w), ("B", sp.b_ptr, sp.b_src, sp.b_w)):
        if len(ptr) != n + 1 or ptr[0] != 0 or (np.diff(ptr) < 0).any() or ptr[-1] != len(src) or len(src) != len(w):
            raise StructureError(f"{sp.key}: 입력군 {g} CSR 형식 오류")
        if len(src) and (src.min() < 0 or src.max() >= sp.n_src):
            raise StructureError(f"{sp.key}: 입력군 {g} 주소가 원천 층 범위 밖")
        if not np.isfinite(w).all():
            raise StructureError(f"{sp.key}: 입력군 {g} 가중치에 NaN/Inf")
        rows = np.repeat(np.arange(n, dtype=np.int64), np.diff(ptr))
        keys = np.sort(rows * np.int64(sp.n_src) + src)
        dup = int((keys[1:] == keys[:-1]).sum()) if len(keys) > 1 else 0
        if dup:
            raise StructureError(f"{sp.key}: 입력군 {g} 에 중복 edge {dup} 개 (merge_sum 뒤에도 남음)")
        out[f"edges_{g}"] = int(len(src))
    fa, fb = np.diff(sp.a_ptr), np.diff(sp.b_ptr)
    routed = sp.routed if sp.routed is not None else np.zeros(n, bool)
    if (fb[~sp.op_min] > 0).any():
        raise StructureError(f"{sp.key}: 선형 뉴런에 입력군 B 가 있다.")
    if (routed & ~sp.op_min).any() or (fb[routed] > 0).any():
        raise StructureError(f"{sp.key}: 라우팅 행은 min2 이고 정적 입력군 B 가 비어 있어야 한다 (B 는 이미지마다 후보에서 고른다).")
    if ((fa[sp.op_min] == 0) | ((fb[sp.op_min] == 0) & ~routed[sp.op_min])).any():
        raise StructureError(f"{sp.key}: min2 뉴런은 입력군 A·B 가 모두 있어야 한다 (라우팅 행은 B 후보 표로 대신한다).")
    fan = fa + fb
    out.update(n_neurons=n, fan_in_min=int(fan.min()) if n else 0, fan_in_mean=float(fan.mean()) if n else 0.0,
               fan_in_max=int(fan.max()) if n else 0, n_without_input=int((fan == 0).sum()),
               n_min2=int(sp.op_min.sum()), n_linear=int(n - sp.op_min.sum()))
    if sp.name == "L3" and out["n_without_input"]:
        raise StructureError(f"{sp.key}: 부모 (L2 입력) 없는 L3 출력 {out['n_without_input']} 개")
    return out


def _channel_meta(n_ch: int, **cols: list[Any]) -> dict[str, list[Any]]:
    for k, v in cols.items():
        if len(v) != n_ch:
            raise StructureError(f"채널 메타 {k} 길이 {len(v)} != {n_ch}")
    return {k: list(v) for k, v in cols.items()}


def _block_children(nr_c: int, nphi_c: int, nr_p: int, nphi_p: int) -> list[list[int]]:
    fr, fa = nr_c // nr_p, nphi_c // nphi_p
    out = []
    for K in range(nr_p):
        for M in range(nphi_p):
            out.append([k * nphi_c + m for k in range(K * fr, (K + 1) * fr) for m in range(M * fa, (M + 1) * fa)])
    return out


def _pool_positions(child: LayerSpec, children: list[list[int]]) -> tuple[np.ndarray, np.ndarray, np.ndarray]:
    px = np.asarray([child.pos_x[c].mean() for c in children], np.float64)
    py = np.asarray([child.pos_y[c].mean() for c in children], np.float64)
    prf = np.asarray([float(np.max(np.hypot(child.pos_x[c] - px[i], child.pos_y[c] - py[i]) + child.pos_rf[c]))
                      for i, c in enumerate(children)], np.float64)
    return px, py, prf


def _local_spacing(px: np.ndarray, py: np.ndarray, pre: "RetinaLGNPreprocessor", n_r: int, n_phi: int) -> np.ndarray:
    r = np.hypot(px - pre.cx, pre.cy - py)
    L = pre.grid["L"]
    return np.sqrt(((r + pre.r0) * L / n_r) * (2 * math.pi * r / n_phi))


def _displaced(px: np.ndarray, py: np.ndarray, P: int, theta_deg: float, D: float, sign: int) -> int | None:
    """원영상 좌표에서 θ 방향 (sign=+1 앞, −1 뒤) 으로 D 만큼 떨어진 점에 가장 가까운 격자 위치. 자기 자신이면 None."""
    t = math.radians(theta_deg)
    tx, ty = px[P] + sign * D * math.cos(t), py[P] - sign * D * math.sin(t)
    j = int(np.argmin((px - tx) ** 2 + (py - ty) ** 2))
    return None if j == P else j


def _ori_index(oris: list[float], theta: float) -> int | None:
    th = theta % 180.0
    for i, o in enumerate(oris):
        if abs(((o - th + 90.0) % 180.0) - 90.0) < 1e-6:
            return i
    return None


def _spec(area: str, name: str, src_key: str, n_src: int, n_pos: int, n_ch: int, names: list[str], roles: list[str],
          meta: dict[str, list[Any]], op_min: np.ndarray, csr: tuple[np.ndarray, ...], x: np.ndarray, y: np.ndarray,
          rf: np.ndarray, ring: np.ndarray, ang: np.ndarray, pos: tuple[np.ndarray, np.ndarray, np.ndarray],
          grid_shape: tuple[int, int] | None, nb: tuple[np.ndarray, np.ndarray], learnable: bool, desc: dict[str, Any],
          stats: dict[str, Any] | None = None, routed: np.ndarray | None = None, missing: np.ndarray | None = None,
          routing: Any = None, band: Any = None, dest: Any = None) -> LayerSpec:
    a_ptr, a_src, a_w, b_ptr, b_src, b_w = csr
    sp = LayerSpec(area=area, name=name, src_key=src_key, n_src=int(n_src), n_pos=int(n_pos), n_ch=int(n_ch),
                   channel_names=list(names), channel_roles=list(roles), channel_meta=meta, op_min=np.asarray(op_min, bool),
                   a_ptr=a_ptr, a_src=a_src, a_w=a_w.astype(np.float32), b_ptr=b_ptr, b_src=b_src, b_w=b_w.astype(np.float32),
                   x=np.asarray(x, np.float32), y=np.asarray(y, np.float32), rf=np.asarray(rf, np.float32),
                   ring=np.asarray(ring, np.int32), ang=np.asarray(ang, np.int32),
                   pos_x=np.asarray(pos[0], np.float32), pos_y=np.asarray(pos[1], np.float32), pos_rf=np.asarray(pos[2], np.float32),
                   grid_shape=grid_shape, pos_nb=nb[0], pos_nb_count=nb[1], learnable=learnable, l6_capable=(name in ("L2", "L3")),
                   description=desc, build_stats=dict(stats or {}), routed=routed, missing=missing, routing=routing, band=band, dest=dest)
    sp.build_stats.update(validate_layer(sp))
    return sp


def _per_neuron(arr: np.ndarray, n_ch: int) -> np.ndarray:
    return np.repeat(np.asarray(arr), n_ch)


# ---------------------------------------------------------------------- V1
def build_v1(cfg: dict[str, Any], pre: "RetinaLGNPreprocessor") -> list[LayerSpec]:
    a = cfg["areas"]["V1"]
    rad6 = int(cfg["l6"]["neighbor_grid_radius"])
    lg = pre.grid
    n_maps, n4 = pre.n_maps, pre.n_out
    nb4 = grid_neighbors(lg["n_r"], lg["n_phi"], rad6)
    L4 = _spec("V1", "L4", "LGN", n4, pre.n_pos, n_maps, list(pre.maps), ["V1_L4_lgn_relay"] * n_maps,
               _channel_meta(n_maps, map=list(pre.maps), color=[m.split("_")[0] for m in pre.maps],
                             onoff=[m.split("_")[1] for m in pre.maps]),
               np.zeros(n4, bool), identity_csr(n4), _per_neuron(lg["x"], n_maps), _per_neuron(lg["y"], n_maps),
               _per_neuron(np.maximum(lg["spacing_r"], lg["spacing_phi"]), n_maps), _per_neuron(lg["ring"], n_maps),
               _per_neuron(lg["ang"], n_maps), (lg["x"], lg["y"], np.maximum(lg["spacing_r"], lg["spacing_phi"])),
               (lg["n_r"], lg["n_phi"]), nb4, False,
               {"role_ko": "감각 입력 수신·고정 일대일 중계 (LGN 표본 → V1 L4). q 학습 없음, L6 없음.",
                "operation": "u_j = LGN_j (가중치 1, 일대일)", "input_shape": [pre.n_pos, n_maps], "output_shape": [pre.n_pos, n_maps],
                "connection_rule_ko": "LGN 표본 위치·맵 하나당 L4 뉴런 하나 (위치 우선 순서 동일)"})
    # V1 단순 세포 위치 격자 (로그-극좌표, LGN 과 같은 r0·Rmax)
    g1 = logpolar_positions(int(a["n_r"]), int(a["n_phi"]), pre.r0, pre.rmax, pre.cx, pre.cy, pre.phi_offset)
    n_pos1 = int(a["n_r"]) * int(a["n_phi"])
    sp1 = np.sqrt(g1["spacing_r"] * g1["spacing_phi"])
    sigma = np.maximum(float(a["gabor_sigma_factor"]) * sp1, float(a["gabor_sigma_min_px"]))
    lam = float(a["gabor_wavelength_factor"]) * sigma
    rad = float(a["rf_radius_sigma"]) * sigma
    oris = [float(t) for t in a["orientations_deg"]]
    phases = [float(p) for p in a["phases_rad"]]
    pols = [int(p) for p in a["polarities"]]
    colors = list(pre.colors)
    n_o, n_f, n_s = len(oris), len(phases), len(pols)
    chans = [(c, o, f, s) for c in range(len(colors)) for o in range(n_o) for f in range(n_f) for s in range(n_s)]
    n_ch2 = len(chans)
    lx, ly, area_k = lg["x"], lg["y"], pre.sample_area_px2
    sels, total, n_nearest_fallback = [], 0, 0
    for p in range(n_pos1):
        d2 = (lx - g1["x"][p]) ** 2 + (ly - g1["y"][p]) ** 2
        sel = np.nonzero(d2 <= rad[p] ** 2)[0]
        if sel.size == 0:
            sel = np.asarray([int(np.argmin(d2))])
            n_nearest_fallback += 1
        sels.append(sel)
        total += n_ch2 * 2 * sel.size
    a_ptr = np.zeros(n_pos1 * n_ch2 + 1, np.int64)
    a_src = np.empty(total, np.int64)
    a_w = np.empty(total, np.float32)
    cos_t = np.cos(np.radians(oris))[:, None]
    sin_t = np.sin(np.radians(oris))[:, None]
    on_idx = [pre.maps.index(f"{c}_on") for c in colors]
    off_idx = [pre.maps.index(f"{c}_off") for c in colors]
    pos, row, degenerate = 0, 0, 0
    for p in range(n_pos1):
        sel = sels[p]
        ns = sel.size
        vx = (lx[sel] - g1["x"][p])[None, :]
        vy = (-(ly[sel] - g1["y"][p]))[None, :]
        along = vx * cos_t + vy * sin_t
        perp = -vx * sin_t + vy * cos_t
        env = area_k[sel][None, :] * np.exp(-(along ** 2 + perp ** 2) / (2.0 * sigma[p] ** 2))
        den = env.sum(1, keepdims=True)
        G = []
        for ph in phases:
            car = np.cos(2.0 * math.pi * perp / lam[p] + ph)
            cbar = (env * car).sum(1, keepdims=True) / np.where(den > 0, den, 1.0)
            gg = env * (car - cbar)
            nrm = np.abs(gg).sum(1, keepdims=True)
            degenerate += int((nrm[:, 0] <= 1e-12).sum())
            G.append(np.where(nrm > 1e-12, gg / np.where(nrm > 1e-12, nrm, 1.0), 0.0))
        for (ci, oi, fi, si) in chans:
            gw = (pols[si] * G[fi][oi]).astype(np.float32)
            a_src[pos:pos + ns] = sel * n_maps + on_idx[ci]
            a_w[pos:pos + ns] = gw
            a_src[pos + ns:pos + 2 * ns] = sel * n_maps + off_idx[ci]
            a_w[pos + ns:pos + 2 * ns] = -gw
            pos += 2 * ns
            row += 1
            a_ptr[row] = pos
    n2 = n_pos1 * n_ch2
    names2 = [f"{colors[c]}_o{oris[o]:g}_p{f}_{'+' if pols[s] > 0 else '-'}" for (c, o, f, s) in chans]
    nb1 = grid_neighbors(int(a["n_r"]), int(a["n_phi"]), rad6)
    L2 = _spec("V1", "L2", "V1/L4", n4, n_pos1, n_ch2, names2, ["V1_simple_oriented_gabor"] * n_ch2,
               _channel_meta(n_ch2, orientation_deg=[oris[o] for (_c, o, _f, _s) in chans],
                             phase_rad=[phases[f] for (_c, _o, f, _s) in chans], polarity=[pols[s] for (_c, _o, _f, s) in chans],
                             color=[colors[c] for (c, _o, _f, _s) in chans], family=["simple"] * n_ch2),
               np.zeros(n2, bool), (a_ptr, a_src, a_w, np.zeros(n2 + 1, np.int64), np.zeros(0, np.int64), np.zeros(0, np.float32)),
               _per_neuron(g1["x"], n_ch2), _per_neuron(g1["y"], n_ch2), _per_neuron(sigma, n_ch2),
               _per_neuron(g1["ring"], n_ch2), _per_neuron(g1["ang"], n_ch2), (g1["x"], g1["y"], sigma),
               (int(a["n_r"]), int(a["n_phi"])), nb1, True,
               {"role_ko": "위치별 방향·위상 고정 필터 (Gabor) 반응. 부호 있는 필터 내부 응답 u 와 비음수 출력 max(0,u−θ) 를 구분하고 "
                           "양·음 극성을 별도 뉴런으로 둔다.",
                "operation": "u_j = Σ_k g_jk·(ON_k − OFF_k),  g = 면적 가중 Gaussian envelope × (cos(2π·perp/λ + φ) − 가중 평균), Σ|g| = 1, "
                             "극성 −1 은 −g",
                "orientation_frame_ko": "원영상 좌표 기준 (x 오른쪽, y 위쪽, 반시계). perp = −vx·sinθ + vy·cosθ",
                "input_shape": [pre.n_pos, n_maps], "output_shape": [n_pos1, n_ch2],
                "channels": {"orientations_deg": oris, "phases_rad": phases, "polarities": pols, "colors": colors,
                             "n_orientation_x_phase": n_o * n_f, "polarity_multiplier": n_s, "color_multiplier": len(colors)},
                "connection_rule_ko": "V1 위치에서 반경 rf_radius_sigma·σ 안의 LGN 표본 (원영상 거리), 같은 색의 ON·OFF 맵",
                "sigma_px": {"min": float(sigma.min()), "max": float(sigma.max())},
                "wavelength_px": {"min": float(lam.min()), "max": float(lam.max())}},
               {"degenerate_filters": degenerate, "nearest_sample_fallback_positions": n_nearest_fallback,
                "inner_positions_sigma_floor": int((float(a["gabor_sigma_factor"]) * sp1 < float(a["gabor_sigma_min_px"])).sum())})
    # V1 L3: 같은 위치·색·방향의 위상×극성 풀링 (부모 n_f·n_s)
    n_ch3 = len(colors) * n_o
    kpar = n_f * n_s
    n3 = n_pos1 * n_ch3
    a3_ptr = np.arange(n3 + 1, dtype=np.int64) * kpar
    a3_src = np.empty(n3 * kpar, np.int64)
    r_ = 0
    for p in range(n_pos1):
        for c in range(len(colors)):
            for o in range(n_o):
                base = p * n_ch2 + ((c * n_o + o) * n_f) * n_s
                a3_src[r_ * kpar:(r_ + 1) * kpar] = base + np.arange(kpar)
                r_ += 1
    a3_w = np.full(n3 * kpar, 1.0 / kpar, np.float32)
    names3 = [f"{colors[c]}_o{oris[o]:g}" for c in range(len(colors)) for o in range(n_o)]
    L3 = _spec("V1", "L3", "V1/L2", n2, n_pos1, n_ch3, names3, ["V1_phase_pooled_orientation"] * n_ch3,
               _channel_meta(n_ch3, orientation_deg=[oris[o] for c in range(len(colors)) for o in range(n_o)],
                             color=[colors[c] for c in range(len(colors)) for o in range(n_o)], family=["complex_like"] * n_ch3),
               np.zeros(n3, bool), (a3_ptr, a3_src, a3_w, np.zeros(n3 + 1, np.int64), np.zeros(0, np.int64), np.zeros(0, np.float32)),
               _per_neuron(g1["x"], n_ch3), _per_neuron(g1["y"], n_ch3), _per_neuron(sigma, n_ch3),
               _per_neuron(g1["ring"], n_ch3), _per_neuron(g1["ang"], n_ch3), (g1["x"], g1["y"], sigma),
               (int(a["n_r"]), int(a["n_phi"])), nb1, True,
               {"role_ko": "같은 위치·색·방향의 위상×극성 정류 반응 평균 (국소 결합). 완전한 위상 불변성을 주장하지 않는다.",
                "operation": f"u_j = (1/{kpar})·Σ_{{phase,polarity}} transmitted_L2", "input_shape": [n_pos1, n_ch2],
                "output_shape": [n_pos1, n_ch3], "connection_rule_ko": f"수렴: L3 하나당 L2 부모 {kpar} 개 (같은 위치·색·방향)"})
    return [L4, L2, L3]


# ---------------------------------------------------------------------- V2
def build_v2(cfg: dict[str, Any], pre: "RetinaLGNPreprocessor", v1: LayerSpec) -> list[LayerSpec]:
    a = cfg["areas"]["V2"]
    rad6 = int(cfg["l6"]["neighbor_grid_radius"])
    oris = [float(t) for t in cfg["areas"]["V1"]["orientations_deg"]]
    colors = list(pre.colors)
    n_o = len(oris)
    nr1, nphi1 = v1.grid_shape
    nr2, nphi2 = int(a["n_r"]), int(a["n_phi"])
    children = _block_children(nr1, nphi1, nr2, nphi2)
    px, py, prf = _pool_positions(v1, children)
    n_pos = nr2 * nphi2
    ring = np.repeat(np.arange(nr2), nphi2)
    ang = np.tile(np.arange(nphi2), nr2)
    nb = grid_neighbors(nr2, nphi2, rad6)
    # L4: 방향별로 V1 L3 의 블록 위치·색 평균
    b4 = CSRBuilder(n_pos * n_o, v1.n)
    for P, ch in enumerate(children):
        k = 1.0 / (len(ch) * len(colors))
        for o in range(n_o):
            for c1 in ch:
                for ci in range(len(colors)):
                    b4.add(P * n_o + o, c1 * v1.n_ch + ci * n_o + o, k)
    names4 = [f"o{t:g}" for t in oris]
    L4 = _spec("V2", "L4", "V1/L3", v1.n, n_pos, n_o, names4, ["V2_L4_pooled_orientation"] * n_o,
               _channel_meta(n_o, orientation_deg=oris, family=["orientation"] * n_o), np.zeros(n_pos * n_o, bool),
               b4.finalize(), _per_neuron(px, n_o), _per_neuron(py, n_o), _per_neuron(prf, n_o), _per_neuron(ring, n_o),
               _per_neuron(ang, n_o), (px, py, prf), (nr2, nphi2), nb, False,
               {"role_ko": "고정 수렴 중계: V1 L3 의 블록 위치와 색을 방향별로 평균",
                "operation": "u = mean_{block, color} transmitted_V1L3(같은 방향)", "input_shape": [v1.n_pos, v1.n_ch],
                "output_shape": [n_pos, n_o], "connection_rule_ko": f"블록 {nr1 // nr2}×{nphi1 // nphi2} 위치 × 색 {len(colors)} → 1"})
    # L2: 윤곽 연속 / 끝점 / 교차
    sp = _local_spacing(px, py, pre, nr2, nphi2)
    D = np.maximum(float(a["offset_factor"]) * sp, 1.0)
    pairs: list[tuple[int, int]] = []
    for diff in a["cross_diffs_deg"]:
        for i in range(n_o):
            j = _ori_index(oris, oris[i] + float(diff))
            if j is not None and j != i:
                pr = (min(i, j), max(i, j))
                if pr not in pairs:
                    pairs.append(pr)
    chans: list[tuple[str, int, int]] = [("contour", o, 0) for o in range(n_o)] + \
        [("endstop", o, 1) for o in range(n_o)] + [("endstop", o, -1) for o in range(n_o)] + \
        [("cross", i, j) for (i, j) in pairs]
    n_ch = len(chans)
    b2 = CSRBuilder(n_pos * n_ch, n_pos * n_o)
    op = np.zeros(n_pos * n_ch, bool)
    st = {"contour_forward_missing": 0, "contour_backward_missing": 0, "endstop_inhibition_missing": 0}
    inh = float(a["endstop_inhibition"])
    for P in range(n_pos):
        for ci, (fam, i, j) in enumerate(chans):
            r = P * n_ch + ci
            if fam == "contour":
                f = _displaced(px, py, P, oris[i], D[P], +1)
                bk = _displaced(px, py, P, oris[i], D[P], -1)
                parts = [(P, 0.5)] + ([(f, 0.25)] if f is not None else []) + ([(bk, 0.25)] if bk is not None else [])
                st["contour_forward_missing"] += f is None
                st["contour_backward_missing"] += bk is None
                tot = sum(w for _q, w in parts)
                for q_, w in parts:
                    b2.add(r, q_ * n_o + i, w / tot)
            elif fam == "endstop":
                q_ = _displaced(px, py, P, oris[i], D[P], j)
                b2.add(r, P * n_o + i, 1.0)
                if q_ is not None and inh > 0:
                    b2.add(r, q_ * n_o + i, -inh)
                else:
                    st["endstop_inhibition_missing"] += 1
            else:
                b2.add(r, P * n_o + i, 1.0, "A")
                b2.add(r, P * n_o + j, 1.0, "B")
                op[r] = True
    st["merged_duplicate_edges"] = b2.merged
    names2 = [f"contour_o{oris[i]:g}" if f == "contour" else (f"endstop_o{oris[i]:g}_{'fwd' if j > 0 else 'bwd'}" if f == "endstop"
              else f"cross_o{oris[i]:g}_o{oris[j]:g}") for (f, i, j) in chans]
    roles2 = ["V2_contour_continuation" if f == "contour" else ("V2_end_stopped" if f == "endstop" else "V2_crossing_junction")
              for (f, _i, _j) in chans]
    L2 = _spec("V2", "L2", "V2/L4", n_pos * n_o, n_pos, n_ch, names2, roles2,
               _channel_meta(n_ch, family=[f for (f, _i, _j) in chans], orientation_deg=[oris[i] for (_f, i, _j) in chans],
                             orientation2_deg=[(oris[j] if f == "cross" else None) for (f, _i, j) in chans],
                             direction=[(j if f == "endstop" else 0) for (f, _i, j) in chans]),
               op, b2.finalize(), _per_neuron(px, n_ch), _per_neuron(py, n_ch), _per_neuron(prf + D, n_ch),
               _per_neuron(ring, n_ch), _per_neuron(ang, n_ch), (px, py, prf + D), (nr2, nphi2), nb, True,
               {"role_ko": "근처 선 반응의 조합: 윤곽 연속 (같은 방향 앞뒤 위치), 끝점 (한쪽 끝 억제), 교차·접합 (두 방향 동시, min2)",
                "operation": {"contour": "u = 0.5·o(P,θ) + 0.25·o(P+D·dir θ, θ) + 0.25·o(P−D·dir θ, θ) (없는 쪽은 빼고 재정규화)",
                              "endstop": "u = o(P,θ) − w_inh·o(P ± D·dir θ, θ)",
                              "cross": "u = min(o(P,θ1), o(P,θ2))  (역할 연산 min2)"},
                "input_shape": [n_pos, n_o], "output_shape": [n_pos, n_ch],
                "connection_rule_ko": "D = offset_factor × 국소 V2 간격 (원영상 화소). 변위 이웃은 가장 가까운 격자 위치 (자기 자신이면 생략)",
                "cross_pairs": [[oris[i], oris[j]] for (i, j) in pairs]}, st)
    L3 = _spec("V2", "L3", "V2/L2", n_pos * n_ch, n_pos, n_ch, names2, [r_ + "_L3" for r_ in roles2], dict(L2.channel_meta),
               np.zeros(n_pos * n_ch, bool), identity_csr(n_pos * n_ch), L2.x, L2.y, L2.rf, L2.ring, L2.ang,
               (px, py, prf + D), (nr2, nphi2), nb, True,
               {"role_ko": "정리 (일대일 중계) 후 다음 영역으로 출력", "operation": "u_j = transmitted_L2_j", "input_shape": [n_pos, n_ch],
                "output_shape": [n_pos, n_ch], "connection_rule_ko": "일대일 (L3 j ← L2 j)"})
    return [L4, L2, L3]


# ---------------------------------------------------------------------- V4 비율 라우팅 (v6) — 선택 집단 키와 곡선 B 후보 원천 (구조만, 데이터 미사용)
def set_route_keys(sp: LayerSpec, space: np.ndarray, family: Sequence[str], kind: str) -> None:
    """L2 뉴런마다 선택 집단 키 (공간 키, 역할 계열) 를 단다. 집단 = (공간 키, 계열)."""
    names: list[str] = []
    for f_ in family:
        if f_ not in names:
            names.append(f_)
    sp.route_space = np.asarray(space, np.int64)
    sp.route_family = np.asarray([names.index(f_) for f_ in family], np.int64)
    sp.route_family_names = names
    sp.route_space_kind = kind
    if len(sp.route_space) != sp.n or len(sp.route_family) != sp.n:
        raise StructureError(f"{sp.key}: 선택 집단 키 길이가 뉴런 수와 다르다.")


CURVE_REASONS = {0: "valid", 1: "behind_P", 2: "bend_side", 3: "path_outside_field", 4: "zero_tangent", 5: "folded_path"}
CURVE_REASONS_KO = {
    "same_position": "Q = P (같은 위치는 두 번째 위치가 아니다) — 후보 레코드에 넣지 않고 수만 센다",
    "outside_rf": "‖Q − P‖ > R_j (V4 L2 수용장 밖, 원영상 화소 거리) — 후보 레코드에 넣지 않고 수만 센다",
    "behind_P": "진행 방향 조건: (Q − P)·dir(φA) ≤ 0 (곡선 역할은 P 에서 +θA 방향으로 나아간다 — 기존 역할 정의)",
    "bend_side": "뒤집힌 굽힘: s·cross(dir(φA), Q − P) ≤ 0 (Q 가 P 접선의 굽힘 쪽 반평면 밖)",
    "path_outside_field": "Hermite 경로 점이 로그-극좌표 표본 원 (r > Rmax) 밖 (시야 밖)",
    "zero_tangent": "경로 접선 크기 0 (방향을 정의할 수 없다)",
    "folded_path": "경로가 P→Q 현 방향으로 되돌아가거나 (p'·(Q−P) ≤ 0) 총 회전 > 180° (접힘·고리)",
}


def curve_route_options(cfg: dict[str, Any], pre: "RetinaLGNPreprocessor", l4: LayerSpec, l2_rf: np.ndarray, n_ch2: int,
                        chans: list[tuple[str, int, int]], curve_info: list[tuple[int, int, int, int, float]],
                        contour: dict[int, int]) -> tuple[dict[str, np.ndarray], dict[str, Any]]:
    """V4 L2 곡선 뉴런 (P, θA → θB, 부호 s, κ) 의 B 원천 후보 = 수용장 안 θB contour 위치 Q (v4.0.0 목적지 표 build_dest_table 과 같은 합법 조건, V1 안내 없이).
    데이터·라벨을 쓰지 않는 구조 규칙이다. 탈락 후보도 사유와 함께 레코드로 남긴다 (valid = False)."""
    M = int(cfg["routing"]["ratio_codebook"]["curve_path_points"])
    oris = [float(t) for t in cfg["areas"]["V1"]["orientations_deg"]]
    px, py = l4.pos_x.astype(np.float64), l4.pos_y.astype(np.float64)
    vx, vy = px - pre.cx, pre.cy - py
    n_pos, n_in = l4.n_pos, l4.n_ch
    ring4 = l4.ring[::n_in].astype(np.int64)
    cinfo = {ch: (i, j, s, kap) for (ch, i, j, s, kap) in curve_info}
    keys = ("same_position", "outside_rf", *[CURVE_REASONS[c] for c in range(1, 6)])
    rem_total = {k: 0 for k in keys}
    rem_ring: dict[int, dict[str, int]] = {int(k): {kk: 0 for kk in keys} for k in np.unique(ring4)}
    rows, srcs, qs, reasons, dists, cdevs = [], [], [], [], [], []
    for P in range(n_pos):
        Rj = float(l2_rf[P])
        for ch in range(n_ch2):
            if chans[ch][0] != "curve":
                continue
            i, j, s, kap = cinfo[ch]
            phi_a, phi_b, phi_c = curve_directions(oris[i], s, kap)
            ta = np.asarray([math.cos(math.radians(phi_a)), math.sin(math.radians(phi_a))])
            Pv = np.asarray([vx[P], vy[P]])
            items = []
            for Q in range(n_pos):
                if Q == P:
                    rem_total["same_position"] += 1
                    rem_ring[int(ring4[P])]["same_position"] += 1
                    continue
                d = float(math.hypot(px[Q] - px[P], py[Q] - py[P]))
                if d > Rj:
                    rem_total["outside_rf"] += 1
                    rem_ring[int(ring4[P])]["outside_rf"] += 1
                    continue
                Qv = np.asarray([vx[Q], vy[Q]])
                chord = Qv - Pv
                L = float(np.hypot(*chord))
                if L <= 1e-12:
                    raise StructureError(f"V4 위치 {P} 와 {Q} 가 같은 좌표다 (곡선 후보 현 길이 0).")
                cdev = float(d_dir(math.degrees(math.atan2(chord[1], chord[0])), phi_c))
                p_, dp_ = hermite_path(Pv, Qv, phi_a, phi_b, M)
                psi = np.degrees(np.arctan2(dp_[:, 1], dp_[:, 0]))
                tot_abs = float(np.abs(wrap180(np.diff(psi))).sum())
                if float(chord @ ta) <= 0.0:
                    reason = 1
                elif s * float(ta[0] * chord[1] - ta[1] * chord[0]) <= 0.0:
                    reason = 2
                elif (np.hypot(p_[:, 0], p_[:, 1]) > pre.rmax).any():
                    reason = 3
                elif (np.hypot(dp_[:, 0], dp_[:, 1]) < 1e-9 * L).any():
                    reason = 4
                elif ((dp_ @ chord) <= 0.0).any() or tot_abs > 180.0:
                    reason = 5
                else:
                    reason = 0
                if reason:
                    rem_total[CURVE_REASONS[reason]] += 1
                    rem_ring[int(ring4[P])][CURVE_REASONS[reason]] += 1
                items.append((Q * n_in + contour[j], Q, reason, d, cdev))
            items.sort(key=lambda it: it[0])                                # 원천 L4 주소 오름차순 (route_id 순서 = 동점 해소 순서)
            for (src, Q, reason, d, cdev) in items:
                rows.append(P * n_ch2 + ch)
                srcs.append(src)
                qs.append(Q)
                reasons.append(reason)
                dists.append(d)
                cdevs.append(cdev)
    ropt = {"row": np.asarray(rows, np.int64), "src": np.asarray(srcs, np.int64), "w": np.ones(len(rows), np.float32),
            "q": np.asarray(qs, np.int64), "valid": np.asarray(reasons, np.int8) == 0, "reason": np.asarray(reasons, np.int8),
            "dist_px": np.asarray(dists, np.float32), "chord_dev_deg": np.asarray(cdevs, np.float32)}
    return ropt, {"curve_total": rem_total, "curve_by_ring": rem_ring, "path_points": M, "reasons_ko": CURVE_REASONS_KO}


# ---------------------------------------------------------------------- V4
def build_v4(cfg: dict[str, Any], pre: "RetinaLGNPreprocessor", v2: LayerSpec, v1_l3: LayerSpec | None = None,
             v2_l2: LayerSpec | None = None) -> list[LayerSpec]:
    a = cfg["areas"]["V4"]
    rmode = str(cfg["routing"]["mode"])
    routing_on = rmode != "legacy"                    # 곡선 둘째 입력을 이미지마다 계산 (v2 라우팅, v3 강도 구간, v4 목적지 선택)
    band_on = rmode in BAND_MODES
    dest_on = rmode == DEST_MODE
    ratio_on = rmode == RATIO_MODE                    # v6: 곡선 B 는 후보 원천 목록, 선택은 입력 비율 라우터 (V1 안내 없음)
    if routing_on and not band_on and not ratio_on and v1_l3 is None:
        raise StructureError("V1 안내 모드 (v2 라우팅·v4 목적지 선택) 는 V1 L3 구조가 있어야 한다.")
    if dest_on and v2_l2 is None:
        raise StructureError("v1_destination_guided 는 V2 L2 구조가 있어야 한다 (선 끝 점수의 endstop 표본 위치).")
    rad6 = int(cfg["l6"]["neighbor_grid_radius"])
    oris = [float(t) for t in cfg["areas"]["V1"]["orientations_deg"]]
    n_o = len(oris)
    nr2, nphi2 = v2.grid_shape
    nr4, nphi4 = int(a["n_r"]), int(a["n_phi"])
    children = _block_children(nr2, nphi2, nr4, nphi4)
    px, py, prf = _pool_positions(v2, children)
    n_pos = nr4 * nphi4
    ring = np.repeat(np.arange(nr4), nphi4)
    ang = np.tile(np.arange(nphi4), nr4)
    nb = grid_neighbors(nr4, nphi4, rad6)
    n_in = v2.n_ch
    b4 = CSRBuilder(n_pos * n_in, v2.n)
    for P, ch in enumerate(children):
        for cch in range(n_in):
            for c in ch:
                b4.add(P * n_in + cch, c * n_in + cch, 1.0 / len(ch))
    L4 = _spec("V4", "L4", "V2/L3", v2.n, n_pos, n_in, list(v2.channel_names), ["V4_L4_pooled_" + r for r in v2.channel_roles],
               dict(v2.channel_meta), np.zeros(n_pos * n_in, bool), b4.finalize(), _per_neuron(px, n_in), _per_neuron(py, n_in),
               _per_neuron(prf, n_in), _per_neuron(ring, n_in), _per_neuron(ang, n_in), (px, py, prf), (nr4, nphi4), nb, False,
               {"role_ko": "고정 수렴 중계: V2 L3 의 블록 위치 평균 (채널별)", "operation": "u = mean_block transmitted_V2L3",
                "input_shape": [v2.n_pos, n_in], "output_shape": [n_pos, n_in],
                "connection_rule_ko": f"블록 {nr2 // nr4}×{nphi2 // nphi4} 위치 → 1"})
    fam = v2.channel_meta["family"]
    ori_in = v2.channel_meta["orientation_deg"]
    dirs = v2.channel_meta["direction"]
    contour = {i: next(k for k in range(n_in) if fam[k] == "contour" and abs(ori_in[k] - oris[i]) < 1e-6) for i in range(n_o)}
    endf = {i: next(k for k in range(n_in) if fam[k] == "endstop" and dirs[k] > 0 and abs(ori_in[k] - oris[i]) < 1e-6) for i in range(n_o)}
    endb = {i: next(k for k in range(n_in) if fam[k] == "endstop" and dirs[k] < 0 and abs(ori_in[k] - oris[i]) < 1e-6) for i in range(n_o)}
    crosses = [k for k in range(n_in) if fam[k] == "cross"]
    chans: list[tuple[str, int, int]] = []
    curve_info: list[tuple[int, int, int, int, float]] = []          # (채널, θA, θB, 곡률 부호, κ) — 라우팅 표용 (legacy 배열에는 영향 없음)
    for kappa in a["curvature_deg"]:
        for sgn in (1, -1):
            for i in range(n_o):
                j = _ori_index(oris, oris[i] + sgn * float(kappa))
                if j is not None and j != i:
                    curve_info.append((len(chans), i, j, sgn, float(kappa)))
                    chans.append(("curve", i, j))
    chans += [("straight", i, i) for i in range(n_o)] + [("junction", k, k) for k in crosses] + [("lineend", i, i) for i in range(n_o)]
    n_ch = len(chans)
    sp = _local_spacing(px, py, pre, nr4, nphi4)
    D = np.maximum(float(a["offset_factor"]) * sp, 1.0)
    b2 = CSRBuilder(n_pos * n_ch, n_pos * n_in)
    op = np.zeros(n_pos * n_ch, bool)
    routed = np.zeros(n_pos * n_ch, bool)
    straight_q: dict[tuple[int, int], tuple[int, int]] = {}       # (P, 채널) → (B 위치, 0 앞 / 1 뒤 / 2 같은 위치) — 목적지 표용 기록
    st = {"curve_same_position_fallback": 0, "straight_backward_used": 0, "straight_same_position_fallback": 0}
    for P in range(n_pos):
        for ci, (f, i, j) in enumerate(chans):
            r = P * n_ch + ci
            if f == "curve" and routing_on:
                b2.add(r, P * n_in + contour[i], 1.0, "A")             # 첫 입력 (P, θA) 은 그대로
                op[r] = True
                routed[r] = True                                      # 두 번째 입력은 라우팅 후보 표에서 이미지마다 고른다
            elif f == "curve":
                q_ = _displaced(px, py, P, oris[i], D[P], +1)
                if q_ is None:
                    q_ = P
                    st["curve_same_position_fallback"] += 1
                b2.add(r, P * n_in + contour[i], 1.0, "A")
                b2.add(r, q_ * n_in + contour[j], 1.0, "B")
                op[r] = True
            elif f == "straight":
                q_ = _displaced(px, py, P, oris[i], D[P], +1)
                kind = 0
                if q_ is None:
                    q_ = _displaced(px, py, P, oris[i], D[P], -1)
                    st["straight_backward_used"] += q_ is not None
                    kind = 1
                if q_ is None:
                    q_ = P
                    st["straight_same_position_fallback"] += 1
                    kind = 2
                straight_q[(P, ci)] = (int(q_), kind)
                b2.add(r, P * n_in + contour[i], 1.0, "A")
                b2.add(r, q_ * n_in + contour[i], 1.0, "B")
                op[r] = True
            elif f == "junction":
                b2.add(r, P * n_in + i, 1.0)
            else:
                b2.add(r, P * n_in + endf[i], 0.5)
                b2.add(r, P * n_in + endb[i], 0.5)
    st["merged_duplicate_edges"] = b2.merged
    table = None
    band = None
    dest = None
    missing_rows = None
    if dest_on:
        st.pop("curve_same_position_fallback")
        dest = build_dest_table(cfg, pre, L4, prf + D, n_ch, chans, curve_info, contour, endf, endb, D, v1_l3, v2_l2, children, straight_q, rmode)
        missing_rows = np.zeros(n_pos * n_ch, bool)
        missing_rows[dest.c_rows[dest.c_n_cand == 0]] = True
        st.update(routing_mode=rmode, dest_destinations=int(dest.n_l2), dest_groups=int(dest.n_groups),
                  dest_curve_without_candidate=int((dest.c_n_cand == 0).sum()), dest_curve_candidates_mean=float(dest.c_n_cand.mean()),
                  dest_candidate_edges=int(dest.e_valid.sum()), dest_reads=int(len(dest.read_ori)))
    elif ratio_on:
        st.pop("curve_same_position_fallback")
        ropt, removed = curve_route_options(cfg, pre, L4, prf + D, n_ch, chans, curve_info, contour)
        has_valid = np.zeros(n_pos * n_ch, bool)
        has_valid[ropt["row"][ropt["valid"]]] = True
        missing_rows = routed & ~has_valid
        st.update(routing_mode=rmode, ratio_curve_route_options=int(len(ropt["row"])), ratio_curve_route_options_valid=int(ropt["valid"].sum()),
                  ratio_curve_neurons_without_valid_option=int(missing_rows.sum()))
    elif routing_on and not band_on:
        st.pop("curve_same_position_fallback")
        table = build_routing_table(cfg, pre, L4, n_ch, curve_info, contour, D, v1_l3, rmode)
        missing_rows = np.zeros(n_pos * n_ch, bool)
        missing_rows[table.curve_rows[table.missing]] = True
        st.update(routing_mode=rmode, routing_curve_neurons=int(len(table.curve_rows)), routing_missing_candidate=int(table.missing.sum()),
                  routing_valid_candidates_mean=float(table.cand_valid.sum(1).mean()) if len(table.curve_rows) else 0.0)
    elif band_on:
        st.pop("curve_same_position_fallback")
        band = build_band_table(cfg, pre, L4, prf + D, n_ch, curve_info, contour, D, rmode, (nr4, nphi4))
        missing_rows = np.zeros(n_pos * n_ch, bool)
        missing_rows[band.curve_rows[band.missing]] = True
        st.update(routing_mode=rmode, band_curve_neurons=int(len(band.curve_rows)), band_missing_candidate=int(band.missing.sum()),
                  band_candidates_mean=float(band.n_cand.mean()) if len(band.curve_rows) else 0.0, band_K_max=int(band.K),
                  band_edges=int(band.cand_valid.sum()))
    names2, roles2, fam2, ori2 = [], [], [], []
    for (f, i, j) in chans:
        if f == "curve":
            names2.append(f"curve_o{oris[i]:g}_to_o{oris[j]:g}")
            roles2.append("V4_curve_fragment")
            ori2.append(oris[i])
        elif f == "straight":
            names2.append(f"straight_o{oris[i]:g}")
            roles2.append("V4_straight_continuation")
            ori2.append(oris[i])
        elif f == "junction":
            names2.append("junction_" + v2.channel_names[i])
            roles2.append("V4_junction_relay")
            ori2.append(ori_in[i])
        else:
            names2.append(f"lineend_o{oris[i]:g}")
            roles2.append("V4_line_end")
            ori2.append(oris[i])
        fam2.append(f)
    csign = [None] * n_ch
    ckap = [None] * n_ch
    for (ch_, _i, _j, s_, k_) in curve_info:
        csign[ch_], ckap[ch_] = s_, k_
    L2 = _spec("V4", "L2", "V4/L4", n_pos * n_in, n_pos, n_ch, names2, roles2,
               _channel_meta(n_ch, family=fam2, orientation_deg=ori2, curve_sign=csign, curvature_deg=ckap),
               op, b2.finalize(), _per_neuron(px, n_ch), _per_neuron(py, n_ch), _per_neuron(prf + D, n_ch), _per_neuron(ring, n_ch),
               _per_neuron(ang, n_ch), (px, py, prf + D), (nr4, nphi4), nb, True,
               {"role_ko": "더 넓은 수용장에서 선 조합: 곡선 조각 (θ 다음 위치에 θ±κ, min2), 직선 연속 (min2), 접합 중계, 선 끝 합",
                "operation": {"curve": "u = min(contour(P,θ), contour(P+D·dir θ, θ±κ))", "straight": "u = min(contour(P,θ), contour(P+D·dir θ, θ))",
                              "junction": "u = cross(P)", "lineend": "u = 0.5·endstop_fwd(P,θ) + 0.5·endstop_bwd(P,θ)"},
                "input_shape": [n_pos, n_in], "output_shape": [n_pos, n_ch],
                "connection_rule_ko": "D = offset_factor × 국소 V4 간격. 앞쪽 이웃이 없으면 곡선은 같은 위치를 쓴다 (개수 기록)",
                "curvature_deg": [float(k) for k in a["curvature_deg"]],
                "routing_ko": ("legacy: 곡선 두 번째 입력 = θA 방향 D 떨어진 점의 최근접 위치, 없으면 같은 위치 (v1 그대로)" if not routing_on else
                               (f"{rmode}: V4 위치 × 역할 집단마다 V4 L4 실제 출력 패킷의 구성 비율 방향과 후보 대표 벡터의 코사인으로 후보 묶음 "
                                "(목적지 + A/B 슬롯 원천, 곡선은 (뉴런, Q)) 하나를 고른다. V1 안내 없음. 선택되지 않은 뉴런 u = s = 0. 전달값은 V4 L4 출력만"
                                if ratio_on else
                                f"{rmode}: V4 위치 × 역할 집단마다 이번 이미지의 V1 L3 안내 점수가 가장 높은 수신 뉴런 하나와 그 입력 슬롯 묶음을 고른다 "
                                "(곡선 B = 유효 θB contour 후보 중 최고 점수 Q*). 선택되지 않은 뉴런 u = s = 0. 전달값은 V4 L4 출력만" if dest_on else
                                f"{rmode}: 곡선 두 번째 입력군 B = 수용장 안 contour θB 후보 전부의 가중평균 "
                                "(expanded_pool = 기하 가중치 w0, band_gated = w0 × 연결별 활동 강도 구간 게이트 g). 후보 없음 → u = 0"
                                if band_on else
                                f"{rmode}: 곡선 두 번째 입력 위치를 고정 후보 표 (K={cfg['routing']['max_candidates']}) 에서 이미지마다 고른다 "
                                "(geometry_only = 기하 첫 후보, v1_guided = V1 L3 경로 지지 점수 최대). 후보 없음 → u = 0 (missing_candidate)"))},
               st, routed=(routed if routing_on else None), missing=missing_rows, routing=table, band=band, dest=dest)
    if ratio_on:
        L2.ropt, L2.ropt_removed = ropt, removed
        set_route_keys(L2, np.repeat(np.arange(n_pos), n_ch), fam2 * n_pos, "position")
        L2.ratio = build_route_table("V4", L4, L2, cfg)
        t_ = L2.ratio
        L2.build_stats.update(ratio_groups=int(t_.n_groups), ratio_candidate_records=int(t_.n_routes), ratio_legal_candidates=int(t_.r_legal.sum()),
                              ratio_destinations_without_legal_candidate=int((t_.l2_n_legal == 0).sum()),
                              ratio_sum_K_times_D=int((t_.g_n_routes * t_.g_D).sum()))
    r3 = int(a["l3_grid_radius"])
    nb3, nb3c = grid_neighbors(nr4, nphi4, r3)
    b3 = CSRBuilder(n_pos * n_ch, n_pos * n_ch)
    for P in range(n_pos):
        qs = [int(q) for q in nb3[P, :nb3c[P]]]
        for cch in range(n_ch):
            for q_ in qs:
                b3.add(P * n_ch + cch, q_ * n_ch + cch, 1.0 / len(qs))
    L3 = _spec("V4", "L3", "V4/L2", n_pos * n_ch, n_pos, n_ch, list(names2), [r_ + "_L3" for r_ in roles2], dict(L2.channel_meta),
               np.zeros(n_pos * n_ch, bool), b3.finalize(), L2.x, L2.y, L2.rf, L2.ring, L2.ang, (px, py, prf + D), (nr4, nphi4), nb, True,
               {"role_ko": "같은 채널의 격자 이웃 평균 (국소 결합·정리)", "operation": "u_j = mean_{Q∈N(P)} transmitted_L2(Q, 채널)",
                "input_shape": [n_pos, n_ch], "output_shape": [n_pos, n_ch],
                "connection_rule_ko": f"수렴: Chebyshev 반경 {r3} (각도 wrap) 안 위치의 같은 채널 L2 → L3"})
    return [L4, L2, L3]


# ---------------------------------------------------------------------- IT
def build_it(cfg: dict[str, Any], pre: "RetinaLGNPreprocessor", v4: LayerSpec) -> list[LayerSpec]:
    a = cfg["areas"]["IT"]
    rad6 = int(cfg["l6"]["neighbor_grid_radius"])
    nr4, nphi4 = v4.grid_shape
    rr, rp = int(a["region_r"]), int(a["region_phi"])
    children = _block_children(nr4, nphi4, rr, rp)
    px, py, prf = _pool_positions(v4, children)
    n_reg = rr * rp
    n_in = v4.n_ch
    nb4 = grid_neighbors(rr, rp, rad6)
    b4 = CSRBuilder(n_reg * n_in, v4.n)
    for R, ch in enumerate(children):
        for cch in range(n_in):
            for c in ch:
                b4.add(R * n_in + cch, c * n_in + cch, 1.0 / len(ch))
    L4 = _spec("IT", "L4", "V4/L3", v4.n, n_reg, n_in, list(v4.channel_names), ["IT_L4_region_pooled_" + r for r in v4.channel_roles],
               dict(v4.channel_meta), np.zeros(n_reg * n_in, bool), b4.finalize(), _per_neuron(px, n_in), _per_neuron(py, n_in),
               _per_neuron(prf, n_in), _per_neuron(np.repeat(np.arange(rr), rp), n_in), _per_neuron(np.tile(np.arange(rp), rr), n_in),
               (px, py, prf), (rr, rp), nb4, False,
               {"role_ko": "넓은 영역 풀링 중계: V4 L3 를 영역 (반경 블록 × 각도 블록) 별 평균", "operation": "u = mean_region transmitted_V4L3",
                "input_shape": [v4.n_pos, n_in], "output_shape": [n_reg, n_in],
                "connection_rule_ko": f"블록 {nr4 // rr}×{nphi4 // rp} 위치 → 1 영역"})
    fam = v4.channel_meta["family"]
    groups = {g: [k for k in range(n_in) if fam[k] == g] for g in ("curve", "straight", "junction", "lineend")}
    groups = {g: v for g, v in groups.items() if v}
    gnames = list(groups)
    gpairs = [(gnames[i], gnames[j]) for i in range(len(gnames)) for j in range(i + 1, len(gnames))]
    neurons: list[tuple[str, Any]] = [("global", c) for c in range(n_in)] + [("rgroup", (R, g)) for R in range(n_reg) for g in gnames] + \
        [("conj", (R, g1, g2)) for R in range(n_reg) for (g1, g2) in gpairs]
    n = len(neurons)
    b2 = CSRBuilder(n, n_reg * n_in)
    op = np.zeros(n, bool)
    xs, ys, rfs, names, roles, fams = [], [], [], [], [], []
    for j, (f, info) in enumerate(neurons):
        if f == "global":
            for R in range(n_reg):
                b2.add(j, R * n_in + info, 1.0 / n_reg)
            xs.append(pre.cx), ys.append(pre.cy), rfs.append(pre.rmax)
            names.append("global_" + v4.channel_names[info])
            roles.append("IT_global_feature")
        elif f == "rgroup":
            R, g = info
            for k in groups[g]:
                b2.add(j, R * n_in + k, 1.0 / len(groups[g]))
            xs.append(px[R]), ys.append(py[R]), rfs.append(prf[R])
            names.append(f"region{R}_{g}")
            roles.append("IT_region_group")
        else:
            R, g1, g2 = info
            for k in groups[g1]:
                b2.add(j, R * n_in + k, 1.0 / len(groups[g1]), "A")
            for k in groups[g2]:
                b2.add(j, R * n_in + k, 1.0 / len(groups[g2]), "B")
            op[j] = True
            xs.append(px[R]), ys.append(py[R]), rfs.append(prf[R])
            names.append(f"region{R}_{g1}_and_{g2}")
            roles.append("IT_conjunction")
        fams.append(f)
    nb1 = single_position_neighbors()
    zero_i = np.zeros(n, np.int32) - 1
    L2 = _spec("IT", "L2", "IT/L4", n_reg * n_in, 1, n, names, roles, _channel_meta(n, family=fams), op, b2.finalize(),
               np.asarray(xs), np.asarray(ys), np.asarray(rfs), zero_i, zero_i, (np.asarray([pre.cx]), np.asarray([pre.cy]),
                                                                                 np.asarray([pre.rmax])), None, nb1, True,
               {"role_ko": "넓은 범위 특징 결합: 전역 채널 평균 (위치 허용), 영역별 특징군 평균, 영역별 특징군 쌍 결합 (min2)",
                "operation": {"global": "u = mean_regions L4(R, c)", "rgroup": "u = mean_{c∈G} L4(R, c)",
                              "conj": "u = min(mean_{c∈G1} L4(R,c), mean_{c∈G2} L4(R,c))"},
                "groups": {g: len(v) for g, v in groups.items()}, "input_shape": [n_reg, n_in], "output_shape": [1, n],
                "connection_rule_ko": "IT 는 수용장이 전 시야라 L6 이웃은 층 전체 (위치 하나로 다룬다)"},
               {"merged_duplicate_edges": b2.merged})
    L3 = _spec("IT", "L3", "IT/L2", n, 1, n, list(names), [r_ + "_L3" for r_ in roles], dict(L2.channel_meta), np.zeros(n, bool),
               identity_csr(n), L2.x, L2.y, L2.rf, zero_i, zero_i, (np.asarray([pre.cx]), np.asarray([pre.cy]), np.asarray([pre.rmax])),
               None, nb1, True,
               {"role_ko": "최종 클래스 비교용 벡터 (일대일 정리)", "operation": "u_j = transmitted_L2_j", "input_shape": [1, n],
                "output_shape": [1, n], "connection_rule_ko": "일대일"})
    return [L4, L2, L3]


class CortexArea:
    """영역 하나 = 고정 구조 L4 → L2 → L3 (LayerSpec 3 개). 하위 클래스 V1/V2/V4/IT 가 역할 연산 (생성기) 을 정한다.
    영역 수준 교정 배분기 (LocalErrorRouter) 와 장치 쪽 배열 (LayerRuntime) 은 CortexModel.add_area 에서 붙인다."""

    name = ""
    role_ko = ""

    def __init__(self, specs: Sequence[LayerSpec]):
        self.specs = list(specs)
        self.l4, self.l2, self.l3 = self.specs

    @classmethod
    def builder(cls, cfg: dict[str, Any], pre: "RetinaLGNPreprocessor", prev_l3: LayerSpec | None,
                context: dict[str, LayerSpec]) -> list[LayerSpec]:
        raise StructureError(f"{cls.__name__} 에 생성기가 없다.")

    @classmethod
    def build(cls, cfg: dict[str, Any], pre: "RetinaLGNPreprocessor", prev_l3: LayerSpec | None,
              context: dict[str, LayerSpec] | None = None) -> "CortexArea":
        if cls.name != "V1" and prev_l3 is None:
            raise StructureError(f"{cls.name} 는 앞 영역 L3 가 있어야 만든다.")
        return cls(cls.builder(cfg, pre, prev_l3, context or {}))

    def describe(self) -> dict[str, Any]:
        return {"area": self.name, "role_ko": self.role_ko, "layers": {sp.name: sp.description for sp in self.specs},
                "h_dim": self.l3.n, "structure_sha256": area_structure_hash(self.specs)}


class V1(CortexArea):
    name = "V1"
    role_ko = "위치별 방향·위상 고정 필터 반응 (L2) 과 위상×극성 국소 결합 (L3)"

    @classmethod
    def builder(cls, cfg: dict[str, Any], pre: "RetinaLGNPreprocessor", prev_l3: LayerSpec | None,
                context: dict[str, LayerSpec]) -> list[LayerSpec]:
        return build_v1(cfg, pre)


class V2(CortexArea):
    name = "V2"
    role_ko = "근처 선 반응의 조합: 윤곽 연속·끝점·교차 (L2), 일대일 정리 (L3)"

    @classmethod
    def builder(cls, cfg: dict[str, Any], pre: "RetinaLGNPreprocessor", prev_l3: LayerSpec | None,
                context: dict[str, LayerSpec]) -> list[LayerSpec]:
        return build_v2(cfg, pre, prev_l3)


class V4(CortexArea):
    name = "V4"
    role_ko = "더 넓은 수용장의 선 조합: 곡선 조각·직선 연속·접합·선 끝 (L2), 격자 이웃 결합 (L3)"

    @classmethod
    def builder(cls, cfg: dict[str, Any], pre: "RetinaLGNPreprocessor", prev_l3: LayerSpec | None,
                context: dict[str, LayerSpec]) -> list[LayerSpec]:
        return build_v4(cfg, pre, prev_l3, context.get("V1/L3"), context.get("V2/L2"))


class IT(CortexArea):
    name = "IT"
    role_ko = "넓은 범위 특징 결합 (L2) 과 최종 클래스 비교용 벡터 (L3)"

    @classmethod
    def builder(cls, cfg: dict[str, Any], pre: "RetinaLGNPreprocessor", prev_l3: LayerSpec | None,
                context: dict[str, LayerSpec]) -> list[LayerSpec]:
        return build_it(cfg, pre, prev_l3)


AREA_CLASSES: dict[str, type[CortexArea]] = {"V1": V1, "V2": V2, "V4": V4, "IT": IT}


def area_structure_hash(specs: Sequence[LayerSpec]) -> str:
    return sha256_text("|".join(sp.hash() for sp in specs))


# ======================================================================
# 8. 뉴런 저장소 (NeuronStore) 와 조회 (NeuronInspector)
# ======================================================================
class Connectivity:
    """연결 목록. INPUT = 수신 층 LayerSpec 의 CSR (입력군 A/B), NEXT = 원천 층별로 만든 나가는 연결 CSR (송신 local → 수신 local).
    실제 계산에 쓰이는 배열과 같은 것에서 만들므로 NEXT 는 계산 연결과 일치한다. 전체 N×N 행렬을 만들지 않는다."""

    def __init__(self) -> None:
        self.next_csr: dict[str, dict[str, Any]] = {}

    def add(self, sp: LayerSpec, src_sp: LayerSpec) -> None:
        rows_a = np.repeat(np.arange(sp.n, dtype=np.int64), np.diff(sp.a_ptr))
        rows_b = np.repeat(np.arange(sp.n, dtype=np.int64), np.diff(sp.b_ptr))
        src = np.concatenate([sp.a_src, sp.b_src])
        dst = np.concatenate([rows_a, rows_b])
        w = np.concatenate([sp.a_w, sp.b_w])
        grp = np.concatenate([np.zeros(len(rows_a), np.int8), np.ones(len(rows_b), np.int8)])
        order = np.argsort(src, kind="stable")
        cnt = np.bincount(src, minlength=src_sp.n)
        self.next_csr[sp.src_key] = {"dst_key": sp.key, "ptr": np.concatenate([[0], np.cumsum(cnt)]).astype(np.int64),
                                     "dst": dst[order], "w": w[order], "grp": grp[order]}

    def add_routes(self, t: "RouteTable", sp: LayerSpec, src_sp: LayerSpec) -> None:
        """v6 V4/L2: NEXT 에 고정 CSR 연결 (곡선 A 등) 과 비율 후보 그래프의 합법 후보 edge 를 함께 등록한다 (조회에서 후보 B 원천이 빠지지 않게).
        같은 (원천, 목적지, 슬롯) 은 한 번만 남긴다. 실제 전달은 이미지마다 집단당 선택된 후보 하나뿐이다 (kind 로 구분)."""
        legal_e = np.repeat(t.r_legal, np.diff(t.r_ptr))
        dst_e = np.repeat(t.r_dst, np.diff(t.r_ptr))
        src = t.e_src[legal_e].astype(np.int64)
        dst = dst_e[legal_e].astype(np.int64)
        grp = t.e_slot[legal_e].astype(np.int8)
        w = t.e_w[legal_e].astype(np.float32)
        key = (src * np.int64(sp.n) + dst) * 2 + grp
        _u, first = np.unique(key, return_index=True)
        first = np.sort(first)
        src, dst, grp, w = src[first], dst[first], grp[first], w[first]
        order = np.argsort(src, kind="stable")
        cnt = np.bincount(src, minlength=src_sp.n)
        self.next_csr[sp.src_key] = {"dst_key": sp.key, "ptr": np.concatenate([[0], np.cumsum(cnt)]).astype(np.int64),
                                     "dst": dst[order], "w": w[order], "grp": grp[order], "kind": "ratio_candidate"}

    def fan_out(self, key: str, n: int) -> np.ndarray:
        nx = self.next_csr.get(key)
        return np.zeros(n, np.int64) if nx is None else np.diff(nx["ptr"])

    def report(self, layers: dict[str, LayerSpec], order: Sequence[str]) -> list[dict[str, Any]]:
        """팬인·팬아웃, 입력 없는 뉴런, 출력 없는 뉴런, 일대일 여부, 중복 (구조 검증에서 0 확인)."""
        rows = []
        for key in order:
            sp = layers[key]
            fi, fo = sp.fan_in(), self.fan_out(key, sp.n)
            rows.append({"layer": key, "fan_in_min": int(fi.min()), "fan_in_max": int(fi.max()), "fan_in_mean": float(fi.mean()),
                         "n_without_input": int((fi == 0).sum()), "fan_out_min": int(fo.min()), "fan_out_max": int(fo.max()),
                         "n_without_output": int((fo == 0).sum()),
                         "without_output_note_ko": ("마지막 영역 L3 는 prototype 비교기로 출력 (연결 아님)" if key not in self.next_csr else None),
                         "one_to_one_input": bool((fi == 1).all() and sp.n == sp.n_src),
                         "duplicates_remaining": 0, "merged_duplicates_at_build": int(sp.build_stats.get("merged_duplicate_edges", 0))})
        return rows


class NeuronStore:
    """모든 뉴런의 연속 저장소.
    CPU (numpy): 좌표 (N,3) float32 [X, Y, Z], 영역·층·역할·채널·위치 코드 (정수), 수용장 크기.
    장치 텐서: 임계값 (N,), q (N,) — 층마다 neuron_id 범위 [start, end) 의 연속 슬라이스 (view).
    CONF·전송 출력은 배치마다 계산하는 동적 텐서 (B, n_layer) 이다 (표본 사이에 남기지 않는다).
    NEXT (나가는 연결) 는 원천 층별 CSR, INPUT (들어오는 연결) 은 수신 층 CSR 이다. 주소는 int64 (float 에 넣지 않는다)."""

    def __init__(self, be: Backend, cfg: dict[str, Any]):
        self.be, self.cfg = be, cfg
        self.layers: dict[str, LayerSpec] = {}
        self.order: list[str] = []
        self.N = 0
        self.coords = np.zeros((0, 3), np.float32)
        self.area_code = np.zeros(0, np.int8)
        self.layer_code = np.zeros(0, np.int8)
        self.role_code = np.zeros(0, np.int32)
        self.channel = np.zeros(0, np.int32)
        self.pos_id = np.zeros(0, np.int32)
        self.roles: list[str] = []
        self.q = be.f32(np.zeros(0))
        self.thr = be.f32(np.zeros(0))
        self.conn = Connectivity()
        self.next_csr = self.conn.next_csr

    def add_layers(self, specs: Sequence[LayerSpec]) -> None:
        ne = self.cfg["neuron"]
        coords, ac, lc, rc, chs, ps = [], [], [], [], [], []
        for sp in specs:
            if sp.key in self.layers:
                raise StructureError(f"{sp.key} 가 이미 있다.")
            sp.start, sp.end = self.N, self.N + sp.n
            self.N = sp.end
            self.layers[sp.key] = sp
            self.order.append(sp.key)
            coords.append(np.stack([sp.x, sp.y, np.full(sp.n, sp.z, np.float32)], axis=1))
            ac.append(np.full(sp.n, AREA_INDEX[sp.area], np.int8))
            lc.append(np.full(sp.n, LAYER_NUMBER[sp.name], np.int8))
            codes = []
            for r in sp.channel_roles:
                if r not in self.roles:
                    self.roles.append(r)
                codes.append(self.roles.index(r))
            rc.append(np.tile(np.asarray(codes, np.int32), sp.n_pos))
            chs.append(np.tile(np.arange(sp.n_ch, dtype=np.int32), sp.n_pos))
            ps.append(np.repeat(np.arange(sp.n_pos, dtype=np.int32), sp.n_ch))
            if sp.src_key != "LGN":
                src_sp = self.layers.get(sp.src_key)
                if src_sp is None:
                    raise StructureError(f"{sp.key} 의 원천 층 {sp.src_key} 가 아직 없다.")
                if sp.ratio is not None:
                    self.conn.add_routes(sp.ratio, sp, src_sp)
                else:
                    self.conn.add(sp, src_sp)
        n_new = sum(sp.n for sp in specs)
        self.coords = np.concatenate([self.coords] + coords).astype(np.float32)
        self.area_code = np.concatenate([self.area_code] + ac)
        self.layer_code = np.concatenate([self.layer_code] + lc)
        self.role_code = np.concatenate([self.role_code] + rc)
        self.channel = np.concatenate([self.channel] + chs)
        self.pos_id = np.concatenate([self.pos_id] + ps)
        self.q = self.be.cat0([self.q, self.be.f32(np.full(n_new, float(ne["q_init"])))])
        self.thr = self.be.cat0([self.thr, self.be.f32(np.full(n_new, float(ne["threshold"])))])

    def q_view(self, key: str) -> Any:
        sp = self.layers[key]
        return self.q[sp.start:sp.end]

    def thr_view(self, key: str) -> Any:
        sp = self.layers[key]
        return self.thr[sp.start:sp.end]

    def q_numpy(self) -> np.ndarray:
        return self.be.to_np(self.q).astype(np.float32).copy()

    def load_q(self, arr: np.ndarray) -> None:
        arr = np.asarray(arr, np.float32)
        ne = self.cfg["neuron"]
        if arr.shape != (self.N,):
            raise CompatibilityError(f"저장된 q 길이 {arr.shape} != 현재 뉴런 수 {self.N}")
        if not np.isfinite(arr).all() or arr.min() < float(ne["q_min"]) - 1e-7 or arr.max() > float(ne["q_max"]) + 1e-7:
            raise CompatibilityError("저장된 q 에 NaN/Inf 또는 범위 밖 값이 있다.")
        self.be.assign_(self.q, self.be.f32(arr))

    def locate(self, nid: int) -> tuple[str, int]:
        if not (0 <= int(nid) < self.N):
            raise IndexError(f"neuron_id {nid} 가 범위 [0,{self.N}) 밖이다.")
        for key in self.order:
            sp = self.layers[key]
            if sp.start <= nid < sp.end:
                return key, int(nid - sp.start)
        raise IndexError(nid)

    def ids_sha(self, key: str) -> str:
        sp = self.layers[key]
        return sha256_array(np.arange(sp.start, sp.end, dtype=np.int64))

    def fan_out(self, key: str) -> np.ndarray:
        return self.conn.fan_out(key, self.layers[key].n)


class NeuronInspector:
    """inspect_neuron(neuron_id): 3×3 표기와 INPUT/NEXT 연결 목록을 저장소에서 복원한다.
    [ X 좌표,         Y 좌표,        Z 좌표          ]
    [ NEXT 참조,      고정 임계값,    INPUT 참조      ]
    [ 실제 전송 출력,  CONF,          지속 출력 q     ]   (전송 출력·CONF 는 주어진 표본의 동적 값, 없으면 None)"""

    def __init__(self, store: NeuronStore):
        self.store = store

    def inspect_neuron(self, nid: int, dyn: dict[str, dict[str, np.ndarray]] | None = None, max_edges: int = 40) -> dict[str, Any]:
        st = self.store
        key, j = st.locate(int(nid))
        sp = st.layers[key]
        row = sp.row(j)
        src_sp = st.layers.get(sp.src_key)
        base = src_sp.start if src_sp is not None else None

        def addr(local: int) -> Any:
            return int(base + local) if base is not None else f"LGN[{int(local)}]"

        inputs = [{"src": addr(s), "w": float(w), "group": "A"} for s, w in zip(row["a_src"], row["a_w"])] + \
                 [{"src": addr(s), "w": float(w), "group": "B"} for s, w in zip(row["b_src"], row["b_w"])]
        nx = st.next_csr.get(key)
        nexts = []
        if nx is not None:
            dsp = st.layers[nx["dst_key"]]
            a_, b_ = int(nx["ptr"][j]), int(nx["ptr"][j + 1])
            nexts = [{"dst": int(dsp.start + d), "w": float(w), "group": "AB"[int(g)]}
                     for d, w, g in zip(nx["dst"][a_:b_], nx["w"][a_:b_], nx["grp"][a_:b_])]
        routing = None
        if sp.routing is not None and sp.routed is not None and bool(sp.routed[j]):
            t = sp.routing
            ci = int(np.nonzero(t.curve_rows == j)[0][0])
            l4 = st.layers[sp.src_key]
            routing = {"kind": "routed_curve_neuron", "mode": t.mode, "P_position": int(t.P[ci]), "theta_A_deg": float(t.theta_a[ci]),
                       "theta_B_deg": float(t.theta_b[ci]), "curve_sign": int(t.sign[ci]), "expected_chord_deg": float(t.phi_c[ci]),
                       "D_px": float(t.D[ci]), "missing_candidate": bool(t.missing[ci]), "legacy_Q_position": int(t.legacy_q[ci]),
                       "static_candidates": [{"slot": s_, "Q_position": int(t.cand_q[ci, s_]), "src_neuron_id": int(l4.start + t.cand_src[ci, s_]),
                                              "dist_px": float(t.cand_dist[ci, s_]), "dir_err_deg": float(t.cand_dir_err[ci, s_]),
                                              "geo_score": float(t.cand_geo[ci, s_]), "missing_guide": bool(t.missing_guide[ci, s_]),
                                              "valid_path_points": int(t.pt_valid[ci, s_].sum())} for s_ in range(t.K) if t.cand_valid[ci, s_]],
                       "note_ko": "정적 후보 목록이다. 실제 B 입력은 이미지마다 이 중 하나 (동적 선택)."}
            if dyn and "__routing__" in dyn:
                rr = dyn["__routing__"]
                k_ = int(rr["k"][ci])
                routing["selected_in_this_sample"] = {
                    "slot": None if t.missing[ci] else k_, "Q_position": None if t.missing[ci] else int(t.cand_q[ci, k_]),
                    "guide_scores": (rr["S"][ci].tolist() if rr.get("S") is not None else None), "no_guidance": bool(rr["no_guidance"][ci]),
                    "A": float(rr["A"][ci]), "B": float(rr["B"][ci]), "u": 0.0 if t.missing[ci] else float(min(rr["A"][ci], rr["B"][ci])),
                    "guide_score_used_for_selection": bool(rr.get("S_used_for_selection", False)),
                    "selected_path_point_r": (rr["R_sel"][ci].tolist() if rr.get("R_sel") is not None else None),
                    "selected_path_point_valid": (rr["OK_sel"][ci].tolist() if rr.get("OK_sel") is not None else None)}
        if sp.band is not None and sp.routed is not None and bool(sp.routed[j]):
            t = sp.band
            ci = int(np.nonzero(t.curve_rows == j)[0][0])
            l4 = st.layers[sp.src_key]
            cal = getattr(st, "band_calibration", None)
            routing = {"kind": "band_curve_neuron", "mode": t.mode, "P_position": int(t.P[ci]), "theta_A_deg": float(t.theta_a[ci]),
                       "theta_B_deg": float(t.theta_b[ci]), "curve_sign": int(t.sign[ci]), "expected_chord_deg": float(t.phi_c[ci]),
                       "D_px": float(t.D[ci]), "rf_radius_px": float(t.R[ci]), "w0_target_xy_px": [float(v) for v in t.T_xy[ci]],
                       "missing_candidate": bool(t.missing[ci]),
                       "static_candidates": [{"slot": k_, "Q_position": int(t.cand_q[ci, k_]), "src_neuron_id": int(l4.start + t.cand_src[ci, k_]),
                                              "dist_px": float(t.cand_dist[ci, k_]), "dist_over_D": float(t.cand_dist_ratio[ci, k_]),
                                              "chord_dev_deg": float(t.cand_chord_dev[ci, k_]), "w0": float(t.w0[ci, k_]),
                                              "v2_rule": V2_FILTER_REASONS.get(int(t.cand_v2_reason[ci, k_]), "?"),
                                              "mu": (float(cal.mu[ci, k_]) if cal is not None else None),
                                              "sigma": (float(cal.sigma[ci, k_]) if cal is not None else None),
                                              "calibration_count": (int(cal.count[ci, k_]) if cal is not None else None),
                                              "calibration_insufficient": (bool(cal.insufficient[ci, k_]) if cal is not None else None)}
                                             for k_ in range(t.K) if t.cand_valid[ci, k_]],
                       "note_ko": "정적 후보 연결 목록 (주소·w0·구간). 실제 기여 w_eff/Σw_eff 는 이미지마다 다르다 (아래 this_sample)."}
            if dyn and "__band__" in dyn:
                bb = dyn["__band__"]
                routing["this_sample"] = {
                    "A": float(bb["A"][ci]), "B": float(bb["B"][ci]), "u": 0.0 if t.missing[ci] else float(min(bb["A"][ci], bb["B"][ci])),
                    "all_gates_low": bool(bb["all_gates_low"][ci]), "mode": bb["mode"],
                    "per_candidate": [{"slot": k_, "x": float(bb["X"][ci, k_]), "z": float(bb["Z"][ci, k_]), "g": float(bb["G"][ci, k_]),
                                       "contribution_share": float(bb["share"][ci, k_])} for k_ in range(t.K) if t.cand_valid[ci, k_]]
                    if "X" in bb else None}
        if sp.dest is not None:
            routing = dest_inspect_destination(st, sp, j, dyn.get("__dest__") if dyn else None, max_edges)
        nxt_l2 = st.layers.get(f"{sp.area}/L2") if sp.name == "L4" else None
        if nxt_l2 is not None and nxt_l2.dest is not None:
            routing = dest_inspect_source(st, nxt_l2, sp, j, dyn.get("__dest__") if dyn else None,
                                          (dyn[key]["out"][j] if dyn and key in dyn and "out" in dyn[key] else None), max_edges)
        if nxt_l2 is not None and nxt_l2.band is not None:
            t = nxt_l2.band
            hit = np.argwhere((t.cand_src == j) & t.cand_valid)
            routing = {"kind": "band_candidate_source", "mode": t.mode,
                       "candidate_for": [{"curve_neuron_id": int(nxt_l2.start + t.curve_rows[c_]), "slot": int(s_), "w0": float(t.w0[c_, s_])}
                                         for c_, s_ in hit[:max_edges]],
                       "n_candidate_refs": int(len(hit)),
                       "note_ko": "정적 NEXT 와 별도로, 이 뉴런은 위 곡선 뉴런들의 B 후보다. 실제 기여는 이미지마다 게이트로 정해진다."}
        if nxt_l2 is not None and nxt_l2.routing is not None:
            t = nxt_l2.routing
            hit = np.argwhere((t.cand_src == j) & t.cand_valid)
            routing = {"kind": "routing_candidate_source", "mode": t.mode,
                       "candidate_for": [{"curve_neuron_id": int(nxt_l2.start + t.curve_rows[c_]), "slot": int(s_)} for c_, s_ in hit[:max_edges]],
                       "n_candidate_refs": int(len(hit)),
                       "note_ko": "정적 NEXT 와 별도로, 이 뉴런은 위 곡선 뉴런들의 B 입력 후보다 (이미지마다 선택될 때만 실제로 전달)."}
        q = float(st.be.to_np(st.q[int(nid):int(nid) + 1])[0])
        thr = float(st.be.to_np(st.thr[int(nid):int(nid) + 1])[0])
        conf = trans = None
        if dyn and key in dyn:
            conf = float(dyn[key]["conf"][j]) if "conf" in dyn[key] else None
            trans = float(dyn[key]["out"][j]) if "out" in dyn[key] else None
        ch = j % sp.n_ch
        meta = {k: v[ch] for k, v in sp.channel_meta.items()}
        X, Y, Z = (float(v) for v in st.coords[int(nid)])
        nxt_ref = (f"NEXT→{len(nexts)} edges ({nx['dst_key']})" if nx is not None else
                   ("NEXT→0 (활성 영역 L3: prototype 비교기로 출력, 연결 아님)" if sp.name == "L3" else "NEXT→0"))
        inp_ref = f"INPUT←{len(inputs)} edges ({sp.src_key})"
        if routing is not None and routing["kind"] == "band_curve_neuron":
            inp_ref = f"INPUT←{len(inputs)} 정적 edge + 동적 B 가중평균 (후보 {len(routing['static_candidates'])}) ({sp.src_key})"
        elif routing is not None and routing["kind"] == "band_candidate_source":
            nxt_ref += f" + 곡선 B 후보 {routing['n_candidate_refs']} (게이트 가중)"
        if routing is not None and routing["kind"] == "dest_destination":
            ts = routing.get("this_sample")
            inp_ref = (f"INPUT←고정 후보 {routing['n_fixed_candidate_edges']} edge (유효 {routing['n_valid_candidate_edges']})"
                       + (f" / 이번 표본 실제 전달 {len(ts['delivered_edges'])}" if ts else " / 이번 표본 미계산") + f" ({sp.src_key})")
        elif routing is not None and routing["kind"] == "dest_candidate_source":
            ts = routing.get("this_sample")
            nxt_ref += f" · 목적지 선택 후보 {routing['n_candidate_refs']}" + (f" (이번 표본 실제 사용 {ts['n_used']})" if ts else "")
        if routing is not None and routing["kind"] == "routed_curve_neuron":
            inp_ref = f"INPUT←{len(inputs)} 정적 edge + 동적 B {0 if routing['missing_candidate'] else 1} (정적 후보 {len(routing['static_candidates'])}) ({sp.src_key})"
        elif routing is not None and routing["kind"] == "routing_candidate_source":
            nxt_ref += f" + 곡선 B 후보 {routing['n_candidate_refs']} (동적)"
        matrix = [[X, Y, Z], [nxt_ref, thr, inp_ref], [trans, conf, q]]
        return {"neuron_id": int(nid), "layer": key, "local_index": j, "position": j // sp.n_ch, "channel": ch,
                "channel_name": sp.channel_names[ch], "role_tag": sp.channel_roles[ch], "channel_meta": meta,
                "grid_position": [int(sp.ring[j]), int(sp.ang[j])], "receptive_field_px": float(sp.rf[j]),
                "area": sp.area, "layer_name": sp.name, "preferred_orientation_deg": meta.get("orientation_deg"),
                "phase_rad": meta.get("phase_rad"), "polarity": meta.get("polarity"),
                "h_index_if_L3": (j if sp.name == "L3" else None),
                "op": "min2" if bool(sp.op_min[j]) else "linear", "matrix_3x3": matrix,
                "n_input": len(inputs), "n_next": len(nexts), "inputs": inputs[:max_edges], "nexts": nexts[:max_edges], "routing": routing,
                "coordinate_units_ko": "X,Y = 처리 영상 화소 (원점 왼쪽 위, x 오른쪽, y 아래); Z = 영역번호×10+층번호 (무차원)"}

    @staticmethod
    def format(info: dict[str, Any]) -> str:
        m = info["matrix_3x3"]
        lines = [f"neuron {info['neuron_id']}  {info['layer']} local {info['local_index']}  역할 {info['role_tag']}  "
                 f"채널 {info['channel_name']}  연산 {info['op']}",
                 f"[ X={fmt(m[0][0], 2)}, Y={fmt(m[0][1], 2)}, Z={fmt(m[0][2], 1)} ]",
                 f"[ {m[1][0]}, 임계값={fmt(m[1][1])}, {m[1][2]} ]",
                 f"[ 전송 출력={fmt(m[2][0])}, CONF={fmt(m[2][1])}, q={fmt(m[2][2])} ]",
                 f"  격자 위치 {info['grid_position']}, 수용장 {fmt(info['receptive_field_px'], 2)} px, 채널 메타 {info['channel_meta']}",
                 f"  INPUT (처음 {len(info['inputs'])}/{info['n_input']}): " +
                 ", ".join(f"{e['src']}:{e['w']:+.4f}{e['group']}" for e in info["inputs"][:12]) + (" ..." if info["n_input"] > 12 else ""),
                 f"  NEXT (처음 {len(info['nexts'])}/{info['n_next']}): " +
                 ", ".join(f"{e['dst']}:{e['w']:+.4f}{e['group']}" for e in info["nexts"][:12]) + (" ..." if info["n_next"] > 12 else "")]
        ro = info.get("routing")
        if ro and ro["kind"] in ("ratio_destination", "ratio_source"):
            lines += ratio_inspect_lines(ro)
        elif ro and ro["kind"] in ("dest_destination", "dest_candidate_source"):
            lines += dest_inspect_lines(ro)
        elif ro and ro["kind"] == "routed_curve_neuron":
            lines.append(f"  라우팅 ({ro['mode']}): P={ro['P_position']} θA={ro['theta_A_deg']:g} θB={ro['theta_B_deg']:g} 부호 {ro['curve_sign']} "
                         f"현 방향 {ro['expected_chord_deg']:g}° D={ro['D_px']:.2f}px, 후보 없음={ro['missing_candidate']}, legacy Q={ro['legacy_Q_position']}")
            lines.append("  정적 B 후보: " + (", ".join(f"[{c['slot']}] Q{c['Q_position']}→{c['src_neuron_id']} d={c['dist_px']:.1f} "
                                                    f"Δ={c['dir_err_deg']:.1f}°" for c in ro["static_candidates"]) or "없음 (u = 0)"))
            if "selected_in_this_sample" in ro:
                s_ = ro["selected_in_this_sample"]
                lines.append(f"  이번 표본의 실제 선택: slot {s_['slot']} (Q{s_['Q_position']}), no_guidance={s_['no_guidance']}, "
                             f"A={s_['A']:.4g}, B={s_['B']:.4g}, u=min={s_['u']:.4g}, 점수 {s_['guide_scores']}")
        elif ro and ro["kind"] == "band_curve_neuron":
            lines.append(f"  강도 구간 ({ro['mode']}): P={ro['P_position']} θA={ro['theta_A_deg']:g} θB={ro['theta_B_deg']:g} 부호 {ro['curve_sign']} "
                         f"φC={ro['expected_chord_deg']:g}° D={ro['D_px']:.2f}px 수용장 R={ro['rf_radius_px']:.1f}px, 후보 {len(ro['static_candidates'])}, "
                         f"후보 없음={ro['missing_candidate']}")
            lines.append("  정적 B 후보 (주소·w0·구간 μ±σ): " + (", ".join(
                f"[{c['slot']}] Q{c['Q_position']}→{c['src_neuron_id']} w0={c['w0']:.3f}"
                + (f" μ={c['mu']:.2f}±{c['sigma']:.2f}" if c["mu"] is not None else " (보정 전)") for c in ro["static_candidates"][:12])
                or "없음 (u = 0)") + (" ..." if len(ro["static_candidates"]) > 12 else ""))
            ts = ro.get("this_sample")
            if ts:
                lines.append(f"  이번 표본: A={ts['A']:.4g}, B={ts['B']:.4g}, u=min={ts['u']:.4g}, all_gates_low={ts['all_gates_low']} ({ts['mode']})")
                if ts.get("per_candidate"):
                    top = sorted(ts["per_candidate"], key=lambda c: -c["contribution_share"])[:6]
                    lines.append("  실제 기여 상위 (w_eff/Σw_eff): " + ", ".join(
                        f"[{c['slot']}] x={c['x']:.3g} z={c['z']:.2f} g={c['g']:.3f} 몫={c['contribution_share']:.3f}" for c in top))
        elif ro and ro["kind"] == "band_candidate_source":
            lines.append(f"  강도 구간 후보 원천 ({ro['mode']}): {ro['n_candidate_refs']} 개 곡선 뉴런의 B 후보 (게이트 가중) — "
                         + ", ".join(f"{c['curve_neuron_id']}[{c['slot']}]" for c in ro["candidate_for"][:10]))
        elif ro:
            lines.append(f"  라우팅 후보 원천 ({ro['mode']}): {ro['n_candidate_refs']} 개 곡선 뉴런의 B 후보 (동적) — "
                         + ", ".join(f"{c['curve_neuron_id']}[{c['slot']}]" for c in ro["candidate_for"][:10]))
        return "\n".join(lines)


def _fnum(v: Any) -> float | None:
    f = float(v)
    return f if math.isfinite(f) else None


def dest_inspect_destination(store: NeuronStore, sp: LayerSpec, j: int, d: dict[str, Any] | None, max_edges: int = 40) -> dict[str, Any]:
    """V4 L2 목적지 뉴런: 고정 후보 edge 와 이번 표본의 실제 선택·전달을 따로 보인다 (후보만 있는 연결을 전달로 표시하지 않는다)."""
    t: DestTable = sp.dest
    l4 = store.layers[sp.src_key]
    role = DEST_ROLES[int(t.dst_role[j])]
    g, slot = int(t.dst_group[j]), int(t.dst_slot[j])
    es = np.nonzero(t.e_dst == j)[0]

    def edge_info(e: int) -> dict[str, Any]:
        src = int(t.e_src[e])
        return {"edge": int(e), "src_neuron_id": int(l4.start + src), "src_position": src // l4.n_ch, "src_channel": l4.channel_names[src % l4.n_ch],
                "slot": DEST_SLOT_NAME[int(t.e_slot[e])], "role": role,
                "source_xy_px": [float(t.e_src_xy[e, 0]), float(t.e_src_xy[e, 1])], "destination_xy_px": [float(t.e_dst_xy[e, 0]), float(t.e_dst_xy[e, 1])],
                "source_orientation_deg": _fnum(t.e_src_ori[e]), "source_orientation2_deg": _fnum(t.e_src_ori2[e]),
                "required_orientation_deg": _fnum(t.e_req_ori[e]), "base_weight": float(t.e_base_w[e]), "valid": bool(t.e_valid[e]),
                "curve_candidate_k": int(t.e_bundle[e])}

    info: dict[str, Any] = {
        "kind": "dest_destination", "mode": t.mode, "role": role, "group": g, "group_position": int(t.group_pos[g]), "slot_in_group": slot,
        "group_members_neuron_id": [int(sp.start + m) for m in t.group_members[g] if m < t.n_l2], "valid_destination": bool(t.dst_valid[j]),
        "n_fixed_candidate_edges": int(len(es)), "n_valid_candidate_edges": int(t.e_valid[es].sum()),
        "fixed_candidate_edges": [edge_info(int(e)) for e in es[:max_edges]],
        "note_ko": "고정 후보 그래프의 edge 목록이다 (후보에만 있는 연결은 실제 전달이 아니다). 이번 표본의 실제 선택·전달은 this_sample 에 따로 있다."}
    k_role = int(t.dst_role_index[j])
    if role == "curve":
        info["curve"] = {"P_position": int(t.c_P[k_role]), "theta_A_deg": float(t.c_theta_a[k_role]), "theta_B_deg": float(t.c_theta_b[k_role]),
                         "curve_sign": int(t.c_sign[k_role]), "kappa_deg": float(t.c_kappa[k_role]), "n_valid_B_candidates": int(t.c_n_cand[k_role]),
                         "rf_candidates_removed_by_reason": {DEST_CURVE_REASONS[k]: int(((t.ce_row == k_role) & (t.ce_reason == k)).sum())
                                                             for k in range(1, 6)}}
    elif role == "straight":
        info["straight"] = {"P_position": int(t.s_P[k_role]), "Q_position": int(t.s_Q[k_role]), "theta_deg": float(t.s_theta[k_role]),
                            "Q_rule": ("앞쪽 변위", "뒤쪽 변위", "같은 위치 대체")[int(t.s_kind[k_role])], "chord_dev_deg": float(t.s_chord_dev_deg[k_role])}
    elif role == "junction":
        info["junction"] = {"P_position": int(t.j_P[k_role]), "theta1_deg": float(t.j_theta1[k_role]), "theta2_deg": float(t.j_theta2[k_role])}
    else:
        info["lineend"] = {"P_position": int(t.l_P[k_role]), "theta_deg": float(t.l_theta[k_role]),
                           "V2_center_positions": [int(x) for x in t.l_pos2_c[k_role] if x >= 0],
                           "V2_forward_sample_positions": [int(x) for x in t.l_pos2_f[k_role] if x >= 0],
                           "V2_backward_sample_positions": [int(x) for x in t.l_pos2_b[k_role] if x >= 0]}
    if d is not None:
        sel = bool(d["mask"][j])
        has = bool(d["has"][g])
        sc = float(d["S_dst"][j])
        ts: dict[str, Any] = {
            "selected": sel, "group_has_selection": has,
            "group_selected_neuron_id": int(sp.start + t.group_members[g, int(d["kg"][g])]) if has else None,
            "guide_score": (sc if math.isfinite(sc) and sc >= 0 else ("NaN" if not math.isfinite(sc) else "무효 목적지")),
            "group_top_score": float(d["mx"][g]) if has else None, "tie_in_group": bool(d["tie"][g]),
            "top1_minus_top2": _fnum(d["gap"][g]) if has else None,
            "routing_selection_weight_display": (float(d["display_weight"][g, slot]) if d.get("display_weight") is not None else None),
            "A_input": float(d["A"][j]), "B_input": (float(d["B"][j]) if role in ("curve", "straight") else None),
            "u_if_selected": float(d["u_all"][j]), "u": float(d["u"][j]), "s": float(d["s"][j]), "out": float(d["out"][j]),
            "delivered_edges": [],
            "note_ko": ("선택되었다: 아래 edge 만 실제로 X4 값을 전달했다." if sel else "선택되지 않았다: 실제 전달 없음 (u = s = 0, 고정 후보는 그대로).")}
        kq = int(d["kq"][k_role]) if role == "curve" else None
        if role == "curve":
            ts["Q_star_position"] = int(t.c_cand_q[k_role, kq]) if t.c_n_cand[k_role] else None
            ts["Q_star_src_neuron_id"] = int(l4.start + t.c_cand_src[k_role, kq]) if t.c_n_cand[k_role] else None
            if d.get("Sq") is not None:
                ts["candidate_scores"] = [{"k": int(k), "Q_position": int(t.c_cand_q[k_role, k]), "src_neuron_id": int(l4.start + t.c_cand_src[k_role, k]),
                                           "score": _fnum(d["Sq"][k_role, k]), "chosen": int(k) == kq}
                                          for k in range(t.c_cand_src.shape[1]) if t.c_cand_valid[k_role, k]]
        if sel:
            x4 = d.get("x4")
            for e in es:
                if not t.e_valid[e]:
                    continue
                if role == "curve" and int(t.e_slot[e]) == 1 and int(t.e_bundle[e]) != kq:
                    continue
                row = {"src_neuron_id": int(l4.start + t.e_src[e]), "slot": DEST_SLOT_NAME[int(t.e_slot[e])], "base_weight": float(t.e_base_w[e])}
                if x4 is not None:
                    row["X4_value"] = float(x4[int(t.e_src[e])])
                    row["delivered_value"] = float(x4[int(t.e_src[e])]) * float(t.e_base_w[e])
                ts["delivered_edges"].append(row)
        info["this_sample"] = ts
    return info


def dest_inspect_source(store: NeuronStore, l2: LayerSpec, l4: LayerSpec, j: int, d: dict[str, Any] | None, x_out: float | None,
                        max_edges: int = 40) -> dict[str, Any]:
    """V4 L4 원천 뉴런: 고정 후보로 들어간 목적지 목록과 이번 표본에서 실제로 쓰인 목적지를 따로 보인다."""
    t: DestTable = l2.dest
    hits = np.nonzero(t.e_src == j)[0]
    rows = [{"dst_neuron_id": int(l2.start + t.e_dst[e]), "role": DEST_ROLES[int(t.e_role[e])], "slot": DEST_SLOT_NAME[int(t.e_slot[e])],
             "valid": bool(t.e_valid[e]), "curve_candidate_k": int(t.e_bundle[e]), "base_weight": float(t.e_base_w[e])} for e in hits]
    info: dict[str, Any] = {"kind": "dest_candidate_source", "mode": t.mode, "n_candidate_refs": int(len(hits)), "n_valid_refs": int(t.e_valid[hits].sum()),
                            "candidate_for": rows[:max_edges],
                            "note_ko": "정적 NEXT 와 별도로, 이 V4 L4 뉴런이 후보 edge 로 들어간 목적지 목록이다. 실제 전달 여부는 이번 표본의 선택에 따른다."}
    if d is not None:
        cidx = {int(r_): c for c, r_ in enumerate(t.c_rows)}
        used = []
        for e in hits:
            if not t.e_valid[e]:
                continue
            dst = int(t.e_dst[e])
            if not bool(d["mask"][dst]):
                continue
            if DEST_ROLES[int(t.e_role[e])] == "curve" and int(t.e_slot[e]) == 1 and int(d["kq"][cidx[dst]]) != int(t.e_bundle[e]):
                continue
            used.append({"dst_neuron_id": int(l2.start + dst), "slot": DEST_SLOT_NAME[int(t.e_slot[e])], "role": DEST_ROLES[int(t.e_role[e])],
                         "base_weight": float(t.e_base_w[e])})
        info["this_sample"] = {"n_used": len(used), "used_by": used[:max_edges], "transmitted_out": x_out,
                               "note_ko": "같은 출력값이 각 사용 목적지로 그대로 간다 (원천당 한 전선 강제·값 나누기 없음, 전역 신호량 보존을 주장하지 않는다)."}
    return info


def dest_inspect_lines(ro: dict[str, Any]) -> list[str]:
    if ro["kind"] == "dest_candidate_source":
        L = [f"  목적지 선택 후보 원천 ({ro['mode']}): 고정 후보 {ro['n_candidate_refs']} (유효 {ro['n_valid_refs']}) — "
             + ", ".join(f"{c['dst_neuron_id']}[{c['role']}/{c['slot']}{'' if c['valid'] else ' 무효'}]" for c in ro["candidate_for"][:10])]
        ts = ro.get("this_sample")
        if ts:
            L.append(f"  이번 표본 실제 사용 {ts['n_used']}: " + (", ".join(f"{c['dst_neuron_id']}[{c['role']}/{c['slot']}]" for c in ts["used_by"][:10]) or "없음")
                     + f" (전송 출력 {fmt(ts['transmitted_out'])})")
        return L
    L = [f"  목적지 ({ro['mode']}): 역할 {ro['role']}, 집단 {ro['group']} (위치 {ro['group_position']}, 자리 {ro['slot_in_group']}/"
         f"{len(ro['group_members_neuron_id'])}), 유효 목적지 {ro['valid_destination']}, 고정 후보 edge {ro['n_fixed_candidate_edges']} "
         f"(유효 {ro['n_valid_candidate_edges']})"]
    for k in ("curve", "straight", "junction", "lineend"):
        if k in ro:
            L.append(f"  {k}: {ro[k]}")
    L.append("  고정 후보: " + (", ".join(f"{e['src_neuron_id']}[{e['slot']} w={e['base_weight']:g}{'' if e['valid'] else ' 무효'}]"
                                         for e in ro["fixed_candidate_edges"][:12]) or "없음")
             + (" ..." if ro["n_fixed_candidate_edges"] > 12 else ""))
    ts = ro.get("this_sample")
    if ts:
        L.append(f"  이번 표본: 선택 {ts['selected']} (집단 선택 {ts['group_selected_neuron_id']}), 점수 {ts['guide_score']}, 집단 최고 {fmt(ts['group_top_score'])}, "
                 f"동점 {ts['tie_in_group']}, 1·2 위 차 {fmt(ts['top1_minus_top2'])}, 라우팅 선택 가중치 (표시용) {fmt(ts['routing_selection_weight_display'])}")
        L.append(f"  실제 입력 A={fmt(ts['A_input'])}, B={fmt(ts['B_input'])}, 선택 시 u={fmt(ts['u_if_selected'])}, 실제 u={fmt(ts['u'])}, s={fmt(ts['s'])}, "
                 f"출력={fmt(ts['out'])}")
        if "Q_star_position" in ts:
            L.append(f"  곡선 Q* = 위치 {ts['Q_star_position']} (원천 {ts['Q_star_src_neuron_id']})" + (
                ", 후보 점수 " + ", ".join(f"Q{c['Q_position']}={fmt(c['score'], 3)}{'*' if c['chosen'] else ''}" for c in ts.get("candidate_scores", [])[:10])
                if ts.get("candidate_scores") else ""))
        L.append("  실제 전달 edge: " + (", ".join(f"{e['src_neuron_id']}[{e['slot']}]={fmt(e.get('delivered_value'))}" for e in ts["delivered_edges"]) or "없음")
                 + " — " + ts["note_ko"])
    return L


def ratio_group_detail(model: "CortexModel", g: int, dyn: dict[str, Any] | None, max_items: int = 64) -> dict[str, Any]:
    """v6 V4 집단 g: 고정 후보 목록·코드북 참조와 (dyn 이 있으면) 이번 표본의 입력 비율·후보별 점수·선택·실제 전달값 (별도 배열 참조)."""
    be = model.be
    router = model.ratio_routers["V4"]
    t = router.t
    l4, l2 = model.specs["V4/L4"], model.specs["V4/L2"]
    src = t.group_sources(g)
    rr = t.group_routes(g)
    b, gl = int(t.g_bucket[g]), int(t.g_local[g])
    ok = be.to_np(router.ok[b])[gl] if b >= 0 else np.zeros(0, bool)
    C = be.to_np(router.C[b])[gl] if b >= 0 else np.zeros((0, 0))
    cands = []
    for k, r in enumerate(rr[:max_items]):
        es, sl, ws = t.route_edges(int(r))
        d_idx = np.searchsorted(src, es)
        cands.append({"route_id": int(r), "destination_L2_id": int(l2.start + t.r_dst[r]),
                      "destination_channel": l2.channel_names[int(t.r_dst[r]) % l2.n_ch], "op": "min2" if t.r_op_min[r] else "linear",
                      "codebook_ref": {"bucket": b, "group_slot": gl, "candidate_slot": k}, "code_ok": bool(ok[k]),
                      "curve_B_position": int(t.r_q[r]) if t.r_q[r] >= 0 else None,
                      "slots": [{"src_L4_id": int(l4.start + s_), "slot": SLOT_NAMES[int(q_)], "base_weight": float(w_),
                                 "code_value": float(C[k, d_]) if C.size else None} for s_, q_, w_, d_ in zip(es, sl, ws, d_idx)]})
    info: dict[str, Any] = {"area": "V4", "group_id": int(g), "family": t.family_names[int(t.g_family[g])], "space_key": int(t.g_space[g]),
                            "space_kind": t.space_kind, "descriptor_schema_id": int(g), "descriptor_dim": int(len(src)),
                            "degenerate_dim_1": bool(len(src) == 1), "source_L4_ids": [int(l4.start + s_) for s_ in src[:max_items]],
                            "n_candidates": int(len(rr)), "candidates": cands, "n_members": int(len(t.group_members(g)))}
    if dyn is not None and b >= 0:
        rec = dyn["recs"][b]
        i = int(dyn.get("i", 0))
        D = len(src)
        K = len(rr)
        has = bool(be.to_np(rec["has"])[i, gl])
        k_sel = int(be.to_np(rec["k"])[i, gl])
        ts: dict[str, Any] = {"S": float(be.to_np(rec["S"])[i, gl]), "active": bool(be.to_np(rec["active"])[i, gl]),
                              "dominance_max_over_sum": _fnum(be.to_np(rec["dom"])[i, gl]), "has_selection": has,
                              "selected_route_id": int(rr[k_sel]) if has else None,
                              "selected_destination_L2_id": int(l2.start + t.r_dst[rr[k_sel]]) if has else None,
                              "top1_score": _fnum(be.to_np(rec["top1"])[i, gl]),
                              "top1_minus_top2": (_fnum(be.to_np(rec["gap"])[i, gl]) if K >= 2 else None),
                              "note_ko": "코사인 점수는 정답 확률이 아니다. 선택은 hard top-1 이며 점수를 전달값에 곱하지 않는다."}
        if "xhat" in rec:
            xd = be.to_np(rec["xd"])[i, gl, :D]
            ts["input_x"] = [float(v) for v in xd[:max_items]]
            ts["input_total_S"] = float(xd.sum())
            ts["listed_sources"] = int(min(D, max_items))
            ts["sources_truncated"] = bool(D > max_items)
            ts["ratio_p"] = [float(v) for v in be.to_np(rec["p"])[i, gl, :D][:max_items]]
            ts["direction_xhat"] = [float(v) for v in be.to_np(rec["xhat"])[i, gl, :D][:max_items]]
            sc = be.to_np(rec["scores"])[i, gl, :K]
            ts["candidate_scores"] = [{"route_id": int(r), "score": _fnum(sc[k]), "selected": has and k == k_sel}
                                      for k, r in enumerate(rr[:max_items])]
            if has:
                r = int(rr[k_sel])
                es, sl, ws = t.route_edges(r)
                xs = dict(zip(src.tolist(), xd.tolist()))
                ts["delivered_edges"] = [{"src_L4_id": int(l4.start + s_), "dst_L2_id": int(l2.start + t.r_dst[r]), "slot": SLOT_NAMES[int(q_)],
                                          "base_weight": float(w_), "L4_output": float(xs[int(s_)]),
                                          "delivered_value": float(w_) * float(xs[int(s_)])} for s_, q_, w_ in zip(es, sl, ws)]
                ts["u_selected"] = float(be.to_np(rec["u_sel"])[i, gl])
        info["this_sample"] = ts
    return info


def ratio_inspect_destination(model: "CortexModel", j: int, dyn: dict[str, Any] | None, max_edges: int = 40) -> dict[str, Any]:
    """V4 L2 목적지 뉴런: 고정 후보 묶음 (탈락 사유 포함) 과 이번 표본의 실제 선택·전달을 따로 보인다."""
    t = model.ratio_routers["V4"].t
    l4 = model.specs["V4/L4"]
    rr = np.nonzero(t.r_dst == j)[0]
    g = int(t.l2_group[j])
    cand_edges = []
    for r in rr:
        es, sl, ws = t.route_edges(int(r))
        cand_edges += [{"src": int(l4.start + s_), "w": float(w_), "group": SLOT_NAMES[int(q_)], "route_id": int(r), "legal": bool(t.r_legal[r])}
                       for s_, q_, w_ in zip(es, sl, ws)]
    out = {"kind": "ratio_destination", "mode": RATIO_MODE, "group": ratio_group_detail(model, g, dyn),
           "own_routes": [{"route_id": int(r), "legal": bool(t.r_legal[r]), "reason": ROUTE_REASONS[int(t.r_reason[r])],
                           "curve_B_position": int(t.r_q[r]) if t.r_q[r] >= 0 else None} for r in rr],
           "n_fixed_candidate_edges": len(cand_edges), "n_legal_candidate_edges": sum(1 for e in cand_edges if e["legal"]),
           "fixed_candidate_edges": cand_edges[:max_edges], "no_geometric_candidate": bool(t.l2_n_legal[j] == 0)}
    ts = out["group"].get("this_sample")
    if ts is not None:
        sel_here = ts.get("selected_destination_L2_id") == int(model.specs["V4/L2"].start + j)
        out["this_sample_neuron"] = {"selected": bool(sel_here),
                                     "delivered_edges": (ts.get("delivered_edges") if sel_here else []),
                                     "note_ko": ("이번 표본에서 이 뉴런이 집단의 선택 목적지다" if sel_here else
                                                 "이번 표본에서 선택되지 않았다 → u = s = 0 (후보 edge 는 전달되지 않았다)")}
    return out


def ratio_inspect_source(model: "CortexModel", j: int, dyn: dict[str, Any] | None, max_edges: int = 40) -> dict[str, Any]:
    """V4 L4 원천 뉴런: 이 출력이 들어가는 입력 패킷 (집단) 과 후보 슬롯, 이번 표본의 실제 사용처."""
    be = model.be
    t = model.ratio_routers["V4"].t
    l2s = model.specs["V4/L2"].start
    gid_of_src = np.repeat(np.arange(t.n_groups), np.diff(t.g_src_ptr))
    groups = np.unique(gid_of_src[t.g_src == j])
    legal_e = np.repeat(t.r_legal, np.diff(t.r_ptr))
    n_cand = int(((t.e_src == j) & legal_e).sum())
    used = None
    if dyn is not None:
        used = []
        recs, i = dyn["recs"], int(dyn.get("i", 0))
        for g in groups:
            b, gl = int(t.g_bucket[g]), int(t.g_local[g])
            if b < 0 or not bool(be.to_np(recs[b]["has"])[i, gl]):
                continue
            r = int(t.group_routes(int(g))[int(be.to_np(recs[b]["k"])[i, gl])])
            es, sl, ws = t.route_edges(r)
            for s_, q_, w_ in zip(es, sl, ws):
                if int(s_) == j:
                    used.append({"group": int(g), "route_id": r, "dst_L2_id": int(l2s + t.r_dst[r]), "slot": SLOT_NAMES[int(q_)], "base_weight": float(w_),
                                 "delivered_value": (float(w_) * float(dyn["x4"][j]) if dyn.get("x4") is not None else None)})
    return {"kind": "ratio_source", "mode": RATIO_MODE, "descriptor_groups": [int(g) for g in groups[:max_edges]],
            "n_descriptor_groups": int(len(groups)), "n_candidate_refs": n_cand, "this_sample_used_by": used,
            "note_ko": "NEXT 는 후보 그래프의 합법 후보 edge 다 (실제 전달은 이미지마다 집단당 선택된 묶음뿐). 같은 출력값이 각 사용처로 간다."}


def ratio_inspect_lines(ro: dict[str, Any]) -> list[str]:
    lines: list[str] = []
    if ro["kind"] == "ratio_destination":
        g = ro["group"]
        lines.append(f"  [비율 라우팅] 선택 집단 {g['group_id']} ({g['family']}, 위치 {g['space_key']}), 후보 {g['n_candidates']}, 입력 차원 "
                     f"{g['descriptor_dim']}{' (퇴화: 차원 1)' if g['degenerate_dim_1'] else ''}, 기하 후보 없음 {ro['no_geometric_candidate']}")
        lines.append("  이 뉴런의 고정 후보 묶음: " + (", ".join(f"r{c['route_id']}{'' if c['legal'] else '(탈락:' + c['reason'] + ')'}"
                                                      for c in ro["own_routes"][:12]) or "없음"))
        for c in g["candidates"][:8]:
            lines.append(f"    후보 r{c['route_id']} → {c['destination_L2_id']} ({c['destination_channel']}, {c['op']}), 대표 {c['codebook_ref']} "
                         f"유효 {c['code_ok']}: " + ", ".join(f"{s['src_L4_id']}[{s['slot']} w={s['base_weight']:+.3g} c={fmt(s['code_value'], 3)}]"
                                                            for s in c["slots"][:6]) + (" ..." if len(c["slots"]) > 6 else ""))
        ts = g.get("this_sample")
        if ts:
            lines.append(f"  이번 표본: 입력 총합 S={fmt(ts['S'])}, 활성 {ts['active']}, 우세도 {fmt(ts['dominance_max_over_sum'])}, 선택 "
                         f"{('r' + str(ts['selected_route_id']) + ' → ' + str(ts['selected_destination_L2_id'])) if ts['has_selection'] else '없음'}, "
                         f"최고 코사인 {fmt(ts['top1_score'])}, 1·2 위 차 {fmt(ts['top1_minus_top2'])} (코사인은 확률이 아니다)")
            if ts.get("ratio_p") is not None:
                pl = ts["ratio_p"]
                lines.append(f"  입력 비율 p (원천 {g['descriptor_dim']}개 중 앞쪽 {min(12, len(pl))}개, 최대값 {fmt(max(pl) if pl else float('nan'), 3)}): "
                             + ", ".join(fmt(v, 3) for v in pl[:12]))
                lines.append("  후보별 점수: " + ", ".join(f"r{c['route_id']}={fmt(c['score'], 3)}{'*' if c['selected'] else ''}"
                                                      for c in ts["candidate_scores"][:12]))
        ns = ro.get("this_sample_neuron")
        if ns:
            lines.append(f"  이 뉴런: {ns['note_ko']}")
            if ns["delivered_edges"]:
                lines.append("  실제 전달 (기저 가중치 × V4 L4 출력): " + ", ".join(
                    f"{e['src_L4_id']}[{e['slot']}]={fmt(e['delivered_value'])}" for e in ns["delivered_edges"][:12]))
    elif ro["kind"] == "ratio_source":
        lines.append(f"  [비율 라우팅] 입력 패킷에 들어간 집단 {ro['n_descriptor_groups']} 개, 합법 후보 슬롯 {ro['n_candidate_refs']} 개 (고정 후보 그래프)")
        if ro.get("this_sample_used_by") is not None:
            lines.append("  이번 표본 실제 사용: " + (", ".join(f"r{u['route_id']}→{u['dst_L2_id']}[{u['slot']}]={fmt(u['delivered_value'])}"
                                                         for u in ro["this_sample_used_by"][:10]) or "없음 (선택된 묶음에 쓰이지 않음)"))
    return lines


# ======================================================================
# 7b. V1 안내 라우팅 — V4 L2 곡선 뉴런의 두 번째 입력 위치를 이미지마다 제한된 후보 안에서 고른다 (동적 라우팅)
#     후보 목록 자체는 구조 생성 때 한 번 만들고 바꾸지 않는다 (영구 재배선이 아니다).
# ======================================================================
ROUTING_MODES: tuple[str, ...] = ("legacy", "geometry_only", "v1_guided", "expanded_pool", "band_gated", DEST_MODE, RATIO_MODE)
PATH_REASONS = {0: "ok", 1: "curvature_sign", 2: "folded", 3: "zero_tangent", 4: "outside_rf", 5: "direction_conflict"}
ROUTING_CONVENTION_KO = {
    "frame": "기하 계산은 시각 좌표 (vx = x − cx 오른쪽, vy = cy − y 위쪽). 화소 배열의 y 는 아래로 증가하므로 부호를 바꾼다.",
    "angle": "각도는 +x 에서 반시계 (위쪽 y 기준) 양의 방향, 단위 도.",
    "channel_theta": "V1 방향 채널 θ 는 선의 접선 방향 (θ 방향으로 놓인 선에 가장 크게 반응) 이며 180 도 주기다 (자체 검사 R00 에서 합성 직선으로 확인).",
    "direction_vs_orientation": "공간 이동 방향 φ (360 도, 앞/뒤 구분) 와 선 방향 θ (180 도 주기) 를 별도 변수로 다룬다.",
    "curve_forward": "곡선 채널 (θA → θB, 부호 s, 곡률 κ) 은 P 에서 +θA 방향으로 나아가며 접선이 s·κ 만큼 돈다: φA = θA, φB = θA + s·κ (연속 각도), "
                     "기대 현 방향 φC = θA + s·κ/2. 0/180 도 이음매를 산술 평균하지 않는다.",
    "interpolation": "원영상 점 → 로그-극좌표 역사상 (u = log(1+r/r0)/log(1+Rmax/r0)) → (반경 bin, 각도 bin) 쌍선형 보간. 반경은 안쪽·바깥 고리에서 "
                     "자르고 (r > Rmax 는 무효), 각도는 wrap. 방향 채널은 180 도 주기 선형 보간.",
}


def wrap180(x: Any) -> Any:
    return (np.asarray(x, np.float64) + 180.0) % 360.0 - 180.0


def d_ori(a: Any, b: Any) -> Any:
    """180 도 주기 선 방향 차: min(|a−b| mod 180, 180 − (|a−b| mod 180))."""
    d = np.abs(np.asarray(a, np.float64) - np.asarray(b, np.float64)) % 180.0
    return np.minimum(d, 180.0 - d)


def d_dir(a: Any, b: Any) -> Any:
    """360 도 이동 방향 차 (앞/뒤 구분)."""
    return np.abs(wrap180(np.asarray(a, np.float64) - np.asarray(b, np.float64)))


def curve_directions(theta_a: float, sign: int, kappa: float) -> tuple[float, float, float]:
    """연속 각도 표현: φA = θA, φB = θA + s·κ, φC = θA + s·κ/2 (도)."""
    return float(theta_a), float(theta_a + sign * kappa), float(theta_a + sign * kappa / 2.0)


def hermite_path(P: np.ndarray, Q: np.ndarray, phi_a: float, phi_b: float, M: int) -> tuple[np.ndarray, np.ndarray]:
    """cubic Hermite: p(0)=P, p(1)=Q, vA = ‖Q−P‖·tA, vB = ‖Q−P‖·tB.
    p(t) = (2t³−3t²+1)P + (t³−2t²+t)vA + (−2t³+3t²)Q + (t³−t²)vB ;  p'(t) 는 이 기하 경로의 접선 (학습 미분이 아니다)."""
    t = np.linspace(0.0, 1.0, int(M))[:, None]
    L = float(np.hypot(*(Q - P)))
    tA = np.asarray([math.cos(math.radians(phi_a)), math.sin(math.radians(phi_a))])
    tB = np.asarray([math.cos(math.radians(phi_b)), math.sin(math.radians(phi_b))])
    vA, vB = L * tA, L * tB
    p = (2 * t ** 3 - 3 * t ** 2 + 1) * P + (t ** 3 - 2 * t ** 2 + t) * vA + (-2 * t ** 3 + 3 * t ** 2) * Q + (t ** 3 - t ** 2) * vB
    dp = (6 * t ** 2 - 6 * t) * P + (3 * t ** 2 - 4 * t + 1) * vA + (-6 * t ** 2 + 6 * t) * Q + (3 * t ** 2 - 2 * t) * vB
    return p, dp


def path_check(p: np.ndarray, dp: np.ndarray, P: np.ndarray, Q: np.ndarray, phi_a: float, phi_b: float, sign: int,
               tol_deg: float, rf_p: float, rf_q: float) -> tuple[int, float]:
    """경로 유효성 코드와 총 회전각. 1 곡률 부호 불일치·변곡, 2 접힘 (총 |회전| > 180), 3 영 접선, 4 수용장 밖, 5 진행 방향 충돌."""
    L = float(np.hypot(*(Q - P)))
    ch = Q - P
    if L <= 0:
        return 5, 0.0
    for phi in (phi_a, phi_b):
        if ch[0] * math.cos(math.radians(phi)) + ch[1] * math.sin(math.radians(phi)) <= 0:
            return 5, 0.0                                           # 접선이 P→Q 진행과 반대
    nrm = np.hypot(dp[:, 0], dp[:, 1])
    if (nrm < 1e-9 * L).any():
        return 3, 0.0
    psi = np.degrees(np.arctan2(dp[:, 1], dp[:, 0]))
    dpsi = wrap180(np.diff(psi))
    total = float(dpsi.sum())
    if (sign * dpsi < -tol_deg).any() or sign * total <= 0:
        return 1, total
    if float(np.abs(dpsi).sum()) > 180.0:
        return 2, total
    in_rf = (np.hypot(*(p - P).T) <= rf_p) | (np.hypot(*(p - Q).T) <= rf_q)
    if not in_rf.all():
        return 4, total
    return 0, total


class GuideSampler:
    """V1 L3 실제 전송 출력 (휘도 채널) 을 원영상 점·선 방향에서 읽는 보간 표.
    a(점, θ) = Σ_{4 격자 위치} Σ_{2 방향 채널} w·F1 ,  b(점) = Σ_{4 격자 위치} w·Σ_θ F1  (같은 공간 가중치)."""

    def __init__(self, v1_l3: LayerSpec, pre: "RetinaLGNPreprocessor", cfg: dict[str, Any]):
        if v1_l3.grid_shape is None:
            raise StructureError("V1 L3 격자 정보가 없다.")
        self.n_r, self.n_phi = v1_l3.grid_shape
        self.n_pos, self.n_ch, self.n = v1_l3.n_pos, v1_l3.n_ch, v1_l3.n
        oris = np.asarray([float(o) for o in cfg["areas"]["V1"]["orientations_deg"]], np.float64)
        self.n_o = len(oris)
        self.d_o = 180.0 / self.n_o
        if not np.allclose(oris, oris[0] + self.d_o * np.arange(self.n_o), atol=1e-6):
            raise StructureError("V1 방향 채널이 오름차순 180/n 등간격이 아니어서 방향 보간을 지원하지 않는다 (v1_guided 미지원).")
        self.ori0 = float(oris[0])
        colors = []
        for c in v1_l3.channel_meta["color"]:
            if c not in colors:
                colors.append(c)
        if "lum" not in colors:
            raise StructureError("V1 L3 에 휘도 (lum) 채널이 없어 v1_guided 안내를 지원하지 않는다 (임의 채널을 고르지 않는다).")
        self.lum_base = colors.index("lum") * self.n_o
        self.r0, self.L, self.rmax, self.off = pre.r0, pre.grid["L"], pre.rmax, pre.phi_offset
        self.cx, self.cy = pre.cx, pre.cy

    def table(self, vx: np.ndarray, vy: np.ndarray, ori_deg: np.ndarray) -> tuple[np.ndarray, ...]:
        vx, vy, ori_deg = (np.asarray(a, np.float64) for a in (vx, vy, ori_deg))
        r = np.hypot(vx, vy)
        valid = r <= self.rmax
        kt = np.log1p(r / self.r0) / self.L * self.n_r - 0.5
        k0 = np.floor(kt)
        wk = kt - k0
        inner = k0 < 0
        k0 = np.where(inner, 0, k0)
        wk = np.where(inner, 0.0, wk)
        outer = k0 >= self.n_r - 1
        k0 = np.where(outer, self.n_r - 1, k0).astype(np.int64)
        wk = np.where(outer, 0.0, wk)
        k1 = np.minimum(k0 + 1, self.n_r - 1)
        phi = np.mod(np.arctan2(vy, vx), 2 * math.pi)
        mt = phi * self.n_phi / (2 * math.pi) - self.off
        m0f = np.floor(mt)
        wm = mt - m0f
        m0 = np.mod(m0f, self.n_phi).astype(np.int64)
        m1 = np.mod(m0 + 1, self.n_phi)
        pos = np.stack([k0 * self.n_phi + m0, k0 * self.n_phi + m1, k1 * self.n_phi + m0, k1 * self.n_phi + m1], axis=-1)
        wp = np.stack([(1 - wk) * (1 - wm), (1 - wk) * wm, wk * (1 - wm), wk * wm], axis=-1)
        o = np.mod(ori_deg - self.ori0, 180.0) / self.d_o
        c0f = np.floor(o)
        wc = o - c0f
        c0 = np.mod(c0f, self.n_o).astype(np.int64)
        c1 = np.mod(c0 + 1, self.n_o)
        cc = np.stack([c0, c1], axis=-1)
        wcc = np.stack([1 - wc, wc], axis=-1)
        idx_a = (pos[..., :, None] * self.n_ch + self.lum_base + cc[..., None, :]).reshape(pos.shape[:-1] + (8,))
        w_a = (wp[..., :, None] * wcc[..., None, :]).reshape(pos.shape[:-1] + (8,))
        idx_a = np.where(valid[..., None], idx_a, self.n)
        w_a = np.where(valid[..., None], w_a, 0.0)
        idx_b = np.where(valid[..., None], pos, self.n_pos)
        w_b = np.where(valid[..., None], wp, 0.0)
        return idx_a.astype(np.int64), w_a.astype(np.float32), idx_b.astype(np.int64), w_b.astype(np.float32), valid


@dataclass
class RoutingTable:
    """곡선 뉴런별 고정 후보 표 (구조 생성 때 한 번). slot 0..K−1 은 기하 점수 순서 (같은 점수는 원래 입력 주소 순서) 의 유효 후보,
    빈 slot 은 마스크로 표시하고 주소는 0 패딩 열 (n_src) 을 가리킨다 (−1 을 넣지 않는다)."""

    mode: str
    K: int
    M: int
    params: dict[str, Any]
    curve_rows: np.ndarray          # (nc,) V4 L2 local 행
    P: np.ndarray                   # (nc,) V4 L4 위치
    theta_a: np.ndarray
    theta_b: np.ndarray
    sign: np.ndarray
    kappa: np.ndarray
    phi_c: np.ndarray
    D: np.ndarray
    srcA: np.ndarray                # (nc,) 첫 입력 주소 (V4 L4 local)
    cand_q: np.ndarray              # (nc,K) 후보 위치 (빈 slot −1, 기록용)
    cand_src: np.ndarray            # (nc,K) 후보 입력 주소 (빈 slot n_src)
    cand_valid: np.ndarray
    cand_dist: np.ndarray
    cand_dir_err: np.ndarray
    cand_geo: np.ndarray
    path_xy: np.ndarray             # (nc,K,M,2) 화소 좌표
    path_ori: np.ndarray            # (nc,K,M) 경로 접선의 선 방향 (180 주기)
    gA_idx: np.ndarray
    gA_w: np.ndarray
    gB_idx: np.ndarray
    gB_w: np.ndarray
    pt_valid: np.ndarray            # (nc,K,M)
    missing: np.ndarray             # (nc,) 유효 후보 없음
    missing_guide: np.ndarray       # (nc,K) 기하적으로 유효하지만 경로 위에 유효 V1 지도 지점이 하나도 없는 후보 (S 는 늘 0)
    n_geometric: np.ndarray         # (nc,) 거리·방향 조건 통과 수 (경로 검사·K 상한 전)
    n_path_rejected: np.ndarray     # (nc,) 경로 검사 탈락 수
    rejected_q: np.ndarray          # (nc,R) 경로 탈락 후보 위치 (그림·기록용, −1 빈칸)
    rejected_reason: np.ndarray     # (nc,R)
    n_rejected_by_reason: np.ndarray  # (nc,6) 사유별 전체 탈락 수 (열 = 사유 코드, 0 열은 쓰지 않음)
    legacy_q: np.ndarray            # (nc,) 원본 규칙 (최근접, 없으면 같은 위치) 의 위치 — 비교 기록용
    n_src: int
    n_v1: int
    n_pos1: int

    def hash(self) -> str:
        return sha256_text(dumps({"mode": self.mode, "K": self.K, "M": self.M, "params": self.params}, indent=None) + sha256_array(
            self.curve_rows, self.P, self.cand_src, self.cand_valid, self.gA_idx, self.gA_w, self.gB_idx, self.gB_w, self.pt_valid,
            self.missing))

    def arrays(self) -> dict[str, np.ndarray]:
        out = {}
        for f_ in dataclasses.fields(self):
            v = getattr(self, f_.name)
            if isinstance(v, np.ndarray):
                out[f_.name] = v
        return out

    def static_summary(self, l4: LayerSpec, pre: "RetinaLGNPreprocessor") -> dict[str, Any]:
        nc = len(self.curve_rows)
        ring = l4.ring[self.P * l4.n_ch]
        ecc = np.hypot(l4.pos_x[self.P] - pre.cx, pre.cy - l4.pos_y[self.P])
        by_ring = {int(k): {"n": int((ring == k).sum()), "missing_frac": float(self.missing[ring == k].mean())} for k in np.unique(ring)}
        by_ori = {f"{float(t):g}": {"n": int((self.theta_a == t).sum()), "missing_frac": float(self.missing[self.theta_a == t].mean())}
                  for t in np.unique(self.theta_a)}
        by_sign = {int(s): float(self.missing[self.sign == s].mean()) for s in np.unique(self.sign)}
        nv = self.cand_valid.sum(1)
        return {"mode": self.mode, "n_curve_neurons": nc, "K": self.K, "M": self.M, "params": self.params,
                "missing_candidate_frac": float(self.missing.mean()) if nc else None, "n_missing": int(self.missing.sum()),
                "valid_candidates_mean": float(nv.mean()) if nc else None, "valid_candidates_max": int(nv.max()) if nc else 0,
                "geometric_before_cap_mean": float(self.n_geometric.mean()) if nc else None,
                "capped_by_K_frac": float((self.n_geometric - self.n_path_rejected > self.K).mean()) if nc else None,
                "path_rejected_total": int(self.n_path_rejected.sum()),
                "path_reject_reason_rule_ko": "검사 순서 (진행 방향 → 영 접선 → 곡률 부호 → 접힘 → 수용장) 에서 처음 걸린 사유 하나로 센다",
                "missing_guide_candidates": int(self.missing_guide.sum()),
                "missing_guide_candidate_frac": float(self.missing_guide.sum() / max(1, self.cand_valid.sum())),
                "neurons_all_candidates_missing_guide": int(((self.missing_guide.sum(1) == self.cand_valid.sum(1)) & ~self.missing).sum()),
                "valid_path_point_frac_static": float(self.pt_valid[self.cand_valid].mean()) if self.cand_valid.any() else None,
                "path_reject_reasons": {PATH_REASONS[int(k)]: int(self.n_rejected_by_reason[:, k].sum()) for k in range(1, 6)},
                "missing_by_ring": by_ring, "missing_by_theta_a": by_ori, "missing_by_curve_sign": by_sign,
                "eccentricity_px": {"min": float(ecc.min()), "max": float(ecc.max())} if nc else None,
                "legacy_same_position_fallback_frac": float((self.legacy_q == self.P).mean()) if nc else None,
                "geometry_first_differs_from_legacy_frac": float(((self.cand_q[:, 0] != self.legacy_q) & ~self.missing).sum() / max(1, (~self.missing).sum())),
                "extra_gather_elements_per_sample": int(nc * self.K * self.M * 12), "table_sha256": self.hash(),
                "note_ko": "후보 없음은 V4 격자가 성기거나 거리·방향 조건을 만족하는 위치가 없어서다. V1 안내로 해결되지 않으며 학습 실패와 구분한다."}


def build_routing_table(cfg: dict[str, Any], pre: "RetinaLGNPreprocessor", l4: LayerSpec, n_ch2: int,
                        curve_info: list[tuple[int, int, int, int, float]], contour: dict[int, int], D: np.ndarray,
                        v1_l3: LayerSpec, mode: str) -> RoutingTable:
    """curve_info: (V4 L2 채널, θA 인덱스, θB 인덱스, 곡률 부호, κ). 후보 = 같지 않은 V4 L4 위치 중 거리 [dmin·D, dmax·D],
    이동 방향이 기대 현 방향 φC 에서 max_dev 이내 → 기하 점수 (|d−D|/(반폭·D) + 방향오차/max_dev) 와 주소 순 정렬 → 경로 검사 통과만 K 개."""
    rc = cfg["routing"]
    oris = [float(t) for t in cfg["areas"]["V1"]["orientations_deg"]]
    K, M = int(rc["max_candidates"]), int(rc["path_points"])
    dmin_f, dmax_f, dev = float(rc["dist_min_factor"]), float(rc["dist_max_factor"]), float(rc["max_chord_dev_deg"])
    tol = float(rc["curvature_turn_tol_deg"])
    R = 8
    gs = GuideSampler(v1_l3, pre, cfg)
    px, py = l4.pos_x.astype(np.float64), l4.pos_y.astype(np.float64)
    vx, vy = px - pre.cx, pre.cy - py
    rf = l4.pos_rf.astype(np.float64)
    n_pos = l4.n_pos
    n_in = l4.n_ch
    rows, Ps, ta, tb, jb, sg, kp, pc, Dl, sA = [], [], [], [], [], [], [], [], [], []
    for P in range(n_pos):
        for (ch, i, j, s, kap) in curve_info:
            rows.append(P * n_ch2 + ch)
            Ps.append(P)
            ta.append(oris[i])
            tb.append(oris[j])
            jb.append(j)
            sg.append(s)
            kp.append(kap)
            pc.append(curve_directions(oris[i], s, kap)[2])
            Dl.append(D[P])
            sA.append(P * n_in + contour[i])
    nc = len(rows)
    cand_q = np.full((nc, K), -1, np.int64)
    cand_src = np.full((nc, K), l4.n, np.int64)
    cand_valid = np.zeros((nc, K), bool)
    cand_dist = np.zeros((nc, K), np.float32)
    cand_dir = np.zeros((nc, K), np.float32)
    cand_geo = np.full((nc, K), np.inf, np.float32)
    path_xy = np.zeros((nc, K, M, 2), np.float32)
    path_ori = np.zeros((nc, K, M), np.float32)
    gA_idx = np.full((nc, K, M, 8), gs.n, np.int64)
    gA_w = np.zeros((nc, K, M, 8), np.float32)
    gB_idx = np.full((nc, K, M, 4), gs.n_pos, np.int64)
    gB_w = np.zeros((nc, K, M, 4), np.float32)
    pt_valid = np.zeros((nc, K, M), bool)
    n_geo = np.zeros(nc, np.int64)
    n_rej = np.zeros(nc, np.int64)
    rej_q = np.full((nc, R), -1, np.int64)
    rej_r = np.zeros((nc, R), np.int8)
    rej_n = np.zeros((nc, 6), np.int64)
    legacy_q = np.zeros(nc, np.int64)
    idxQ = np.arange(n_pos)
    for c in range(nc):
        P, s, Dp = Ps[c], sg[c], Dl[c]
        phi_a, phi_b, phi_c = curve_directions(ta[c], s, kp[c])
        lq = _displaced(px, py, P, ta[c], Dp, +1)
        legacy_q[c] = P if lq is None else lq
        dx, dy = vx - vx[P], vy - vy[P]
        d = np.hypot(dx, dy)
        psi = np.degrees(np.arctan2(dy, dx))
        derr = d_dir(psi, phi_c)
        ok = (idxQ != P) & (d >= dmin_f * Dp) & (d <= dmax_f * Dp) & (derr <= dev)
        qs = idxQ[ok]
        n_geo[c] = qs.size
        if qs.size == 0:
            continue
        half = 0.5 * (dmax_f - dmin_f) * Dp
        geo = np.abs(d[qs] - Dp) / max(half, 1e-12) + derr[qs] / dev
        src = qs * n_in + contour[jb[c]]
        order = np.lexsort((src, geo))
        slot, nr = 0, 0
        Pv = np.asarray([vx[P], vy[P]])
        for o_ in order:
            Q = int(qs[o_])
            Qv = np.asarray([vx[Q], vy[Q]])
            p, dp = hermite_path(Pv, Qv, phi_a, phi_b, M)
            code, _tot = path_check(p, dp, Pv, Qv, phi_a, phi_b, s, tol, rf[P], rf[Q])
            if code != 0:
                n_rej[c] += 1
                rej_n[c, code] += 1
                if nr < R:
                    rej_q[c, nr], rej_r[c, nr] = Q, code
                    nr += 1
                continue
            if slot >= K:
                continue
            ori_m = np.mod(np.degrees(np.arctan2(dp[:, 1], dp[:, 0])), 180.0)
            ia, wa, ib, wb, val = gs.table(p[:, 0], p[:, 1], ori_m)
            cand_q[c, slot], cand_src[c, slot], cand_valid[c, slot] = Q, int(src[o_]), True
            cand_dist[c, slot], cand_dir[c, slot], cand_geo[c, slot] = d[Q], derr[Q], geo[o_]
            path_xy[c, slot, :, 0] = p[:, 0] + pre.cx
            path_xy[c, slot, :, 1] = pre.cy - p[:, 1]
            path_ori[c, slot] = ori_m
            gA_idx[c, slot], gA_w[c, slot], gB_idx[c, slot], gB_w[c, slot], pt_valid[c, slot] = ia, wa, ib, wb, val
            slot += 1
    missing = ~cand_valid.any(axis=1)
    missing_guide = cand_valid & ~pt_valid.any(axis=-1)
    params = {k: rc[k] for k in ("max_candidates", "dist_min_factor", "dist_max_factor", "max_chord_dev_deg", "path_points",
                                 "curvature_turn_tol_deg", "guide_epsilon", "guide_min_total", "guide_source", "guide_color")}
    return RoutingTable(mode=mode, K=K, M=M, params=params, curve_rows=np.asarray(rows, np.int64), P=np.asarray(Ps, np.int64),
                        theta_a=np.asarray(ta, np.float32), theta_b=np.asarray(tb, np.float32), sign=np.asarray(sg, np.int8),
                        kappa=np.asarray(kp, np.float32), phi_c=np.asarray(pc, np.float32), D=np.asarray(Dl, np.float32),
                        srcA=np.asarray(sA, np.int64), cand_q=cand_q, cand_src=cand_src, cand_valid=cand_valid, cand_dist=cand_dist,
                        cand_dir_err=cand_dir, cand_geo=cand_geo, path_xy=path_xy, path_ori=path_ori, gA_idx=gA_idx, gA_w=gA_w,
                        gB_idx=gB_idx, gB_w=gB_w, pt_valid=pt_valid, missing=missing, missing_guide=missing_guide, n_geometric=n_geo, n_path_rejected=n_rej,
                        rejected_q=rej_q, rejected_reason=rej_r, n_rejected_by_reason=rej_n, legacy_q=legacy_q, n_src=l4.n, n_v1=gs.n, n_pos1=gs.n_pos)


class RoutingRuntime:
    """장치 쪽 라우팅 표와 이미지별 선택 (매 배치: gather, 곱·합, 마스크 argmax, min — 최근접 탐색·후보별 전체 재실행 없음).

        a_m = F1(p(t_m), 경로 접선 방향),  b_m = 같은 위치의 모든 방향 반응 합,  r_m = a_m/(b_m + ε)  (b_m < b_min 또는 무효 점은 0)
        S(P,Q) = (1/M) Σ_m r_m   ∈ [0,1)   — 방향 지지 정도 (곡선일 확률·정답 확률이 아니다)
        Q* = argmax_{유효 후보} S  (같은 점수는 기하 순서). 모든 S ≤ 0 이면 기하 첫 후보 + no_guidance 기록.
        B = transmitted_V4L4[Q*, θB],  u = min(A, B)  — S 를 u 에 곱하지 않고 V1 활동을 더하지 않는다.
    입력에 라벨·prototype·오차가 없다 (함수 인자에 없음). 표본마다 독립 (배치 순서와 무관)."""

    def __init__(self, table: RoutingTable, be: Backend, cfg: dict[str, Any], n_layer: int, v1_n_ch: int, lum_base: int, n_o: int):
        rc = cfg["routing"]
        self.table, self.be, self.mode = table, be, table.mode
        self.K, self.M = table.K, table.M
        self.nc = len(table.curve_rows)
        self.eps, self.b_min = float(rc["guide_epsilon"]), float(rc["guide_min_total"])
        self.cand_src = be.i64(table.cand_src)
        self.cand_valid = be.bool_(table.cand_valid)
        self.gA_idx, self.gA_w = be.i64(table.gA_idx), be.f32(table.gA_w)
        self.gB_idx, self.gB_w = be.i64(table.gB_idx), be.f32(table.gB_w)
        self.pt_valid = be.bool_(table.pt_valid)
        cmap = np.full(n_layer, self.nc, np.int64)
        cmap[table.curve_rows] = np.arange(self.nc)
        self.curve_map = be.i64(cmap)
        self.curve_rows = be.i64(table.curve_rows)
        miss = np.zeros(n_layer, bool)
        miss[table.curve_rows[table.missing]] = True
        self.missing_rows = be.bool_(miss)
        self.n_pos1, self.v1_n_ch, self.lum_base, self.n_o = table.n_pos1, v1_n_ch, lum_base, n_o
        self.slot_weight = be.f32(np.arange(self.K, 0, -1, dtype=np.float32))

    def scores(self, guide: Any, keep_points: bool = False) -> Any:
        """guide: (B, n_V1L3) 이번 이미지들의 V1 L3 실제 전송 출력 → S (B, nc, K) (무효 후보 −1).
        keep_points=True 면 (S, r (B,nc,K,M), 유효 지점 마스크) 를 돌려준다 (기록용)."""
        be = self.be
        B = int(guide.shape[0])
        F1e = be.pad_zero_col(guide)
        Fsum = guide.reshape(B, self.n_pos1, self.v1_n_ch)[:, :, self.lum_base:self.lum_base + self.n_o].sum(-1)
        Fsume = be.pad_zero_col(Fsum)
        per = max(1, self.K * self.M * 12)
        rows = max(1, be.max_gather // max(1, B * per))
        parts, rparts, oparts = [], [], []
        for a in range(0, self.nc, rows):
            ia, wa = self.gA_idx[a:a + rows], self.gA_w[a:a + rows]
            ib, wb = self.gB_idx[a:a + rows], self.gB_w[a:a + rows]
            av = (be.take_cols(F1e, ia) * wa).sum(-1)                 # (B, r, K, M)
            bv = (be.take_cols(Fsume, ib) * wb).sum(-1)
            ok = self.pt_valid[a:a + rows] & (bv >= self.b_min)
            r_ = be.where(ok, av / (bv + self.eps), be.zeros(av.shape))
            parts.append(r_.sum(-1) / float(self.M))
            if keep_points:
                rparts.append(r_)
                oparts.append(ok)
        S = parts[0] if len(parts) == 1 else be.cat1(parts)
        S = be.where(self.cand_valid, S, be.zeros(S.shape) - 1.0)
        if not keep_points:
            return S
        return S, (rparts[0] if len(rparts) == 1 else be.cat1(rparts)), (oparts[0] if len(oparts) == 1 else be.cat1(oparts))

    def select(self, xe_l4: Any, guide: Any | None, *, mode: str | None = None, record: bool = False) -> dict[str, Any]:
        """record=True: 기록용으로 경로 지점 점수 r 와 유효 지점 마스크를 함께 돌려준다. geometry_only 에서도 안내 지도가 있으면
        같은 S 를 기록용으로만 계산한다 (선택에는 쓰지 않는다 — S_used_for_selection=False)."""
        be = self.be
        mode = mode or self.mode
        B = int(xe_l4.shape[0])
        R = OK = None
        if mode == "geometry_only" or guide is None:
            if mode not in ("geometry_only", "v1_guided"):
                raise ValueError(f"알 수 없는 라우팅 모드: {mode}")
            k = be.zeros_i64((B, self.nc))
            S = None
            no_g = be.bool_(np.zeros((B, self.nc), bool)) if mode == "geometry_only" else be.bool_(np.ones((B, self.nc), bool))
            if record and guide is not None:
                S, R, OK = self.scores(guide, keep_points=True)
        elif mode == "v1_guided":
            if record:
                S, R, OK = self.scores(guide, keep_points=True)
            else:
                S = self.scores(guide)
            mx = be.max_last(S)
            no_g = mx <= 0.0
            ismax = (S == mx.reshape(B, self.nc, 1)) & self.cand_valid
            k = be.argmax_last(be.where(ismax, self.slot_weight + be.zeros(S.shape), be.zeros(S.shape)))
            k = be.where(no_g, be.zeros_i64((B, self.nc)), k)
        else:
            raise ValueError(f"알 수 없는 라우팅 모드: {mode}")
        sel_src = be.take_last(self.cand_src, k)
        Bv = be.gather_cols(xe_l4, sel_src)
        return {"k": k, "sel_src": sel_src, "B": Bv, "S": S, "no_guidance": no_g, "mode": mode, "R": R, "OK": OK,
                "S_used_for_selection": mode == "v1_guided" and guide is not None}

    def nbytes(self) -> int:
        t = self.table
        return int(t.gA_idx.size * 12 + t.gB_idx.size * 12 + t.cand_src.size * 9 + t.pt_valid.size)


def routing_rec_np(be: Backend, sel: dict[str, Any]) -> dict[str, np.ndarray | None]:
    k = be.to_np(sel["k"]).astype(np.int64)
    out = {"k": k, "B": be.to_np(sel["B"]).astype(np.float64), "A": be.to_np(sel["A"]).astype(np.float64),
           "S": (be.to_np(sel["S"]).astype(np.float64) if sel.get("S") is not None else None),
           "no_guidance": be.to_np(sel["no_guidance"]).astype(bool), "R_sel": None, "OK_sel": None,
           "S_used_for_selection": bool(sel.get("S_used_for_selection", False))}
    if sel.get("R") is not None:
        out["R_sel"] = np.take_along_axis(be.to_np(sel["R"]), k[:, :, None, None], 2)[:, :, 0, :].astype(np.float64)   # 선택 후보의 경로 지점 r
        out["OK_sel"] = np.take_along_axis(be.to_np(sel["OK"]), k[:, :, None, None], 2)[:, :, 0, :].astype(bool)
    return out


def point_summary(R_sel: np.ndarray, OK_sel: np.ndarray) -> dict[str, np.ndarray]:
    """선택 후보 경로의 지점 점수 요약 (표본×뉴런). 무효 지점의 r 는 0 으로 둔 값이다."""
    M = R_sel.shape[-1]
    inner = R_sel[..., 1:M - 1] if M > 2 else R_sel
    return {"valid_point_frac": OK_sel.mean(-1), "r_min": R_sel.min(-1), "r_median": np.median(R_sel, -1),
            "r_endpoints": 0.5 * (R_sel[..., 0] + R_sel[..., M - 1]), "r_interior": inner.mean(-1)}


def acc_add(acc: dict[str, float], part: dict[str, float]) -> None:
    for k, v in part.items():
        acc[k] = acc.get(k, 0.0) + float(v)


def routing_batch_stats(table: RoutingTable, rec: dict[str, np.ndarray], high: float) -> dict[str, float]:
    """한 배치의 라우팅 기록 (numpy) → 합계 (에폭 끝에 비율로). 후보 없음 뉴런은 선택 통계에서 뺀다."""
    k, Bv, A = rec["k"], rec["B"], rec["A"]
    ok = ~table.missing
    nb = k.shape[0]
    kk = k[:, ok]
    jj = np.nonzero(ok)[0]
    q_sel = table.cand_q[jj[None, :], kk]
    out = {"n_samples": float(nb), "n_pairs": float(kk.size), "n_missing_pairs": float(nb * int((~ok).sum())),
           "no_guidance": float(rec["no_guidance"][:, ok].sum()), "differs_from_geometry_first": float((kk != 0).sum()),
           "differs_from_legacy_position": float((q_sel != table.legacy_q[jj][None, :]).sum()),
           "sum_dist_err": float((np.abs(table.cand_dist[jj[None, :], kk] - table.D[jj][None, :]) / np.maximum(table.D[jj][None, :], 1e-12)).sum()),
           "sum_dir_err": float(table.cand_dir_err[jj[None, :], kk].sum()),
           "zero_B": float((Bv[:, ok] <= 0).sum()), "u_positive": float((np.minimum(A[:, ok], Bv[:, ok]) > 0).sum())}
    for s in range(table.K):
        out[f"k{s}"] = float((kk == s).sum())
    if rec.get("S") is not None:
        S = rec["S"]
        ssel = np.take_along_axis(S[:, ok, :], kk[..., None], -1)[..., 0]
        out["sum_S_selected"] = float(ssel.sum())
        out["high_S_zero_B"] = float(((ssel >= high) & (Bv[:, ok] <= 0)).sum())
    out["missing_guide_selected"] = float(table.missing_guide[jj[None, :], kk].sum())
    if rec.get("R_sel") is not None:
        ps = point_summary(rec["R_sel"][:, ok], rec["OK_sel"][:, ok])
        for key_, v_ in ps.items():
            out[f"sum_{key_}"] = float(v_.sum())
    return out


def routing_finalize(acc: dict[str, float], K: int) -> dict[str, Any]:
    n = max(1.0, acc.get("n_pairs", 0.0))
    freqs = [acc.get(f"k{s}", 0.0) / n for s in range(K)]
    nz = [f for f in freqs if f > 0]
    ent = -sum(f * math.log2(f) for f in nz) / math.log2(K) if K > 1 and nz else 0.0
    tot = acc.get("n_pairs", 0.0) + acc.get("n_missing_pairs", 0.0)
    return {"n_samples": int(acc.get("n_samples", 0)), "missing_candidate_frac": (acc.get("n_missing_pairs", 0.0) / tot) if tot else None,
            "no_guidance_frac": acc.get("no_guidance", 0.0) / n, "selection_freq_by_slot": freqs,
            "selection_top_slot_share": max(freqs) if freqs else None, "selection_entropy_norm": ent,
            "differs_from_geometry_first_frac": acc.get("differs_from_geometry_first", 0.0) / n,
            "differs_from_legacy_position_frac": acc.get("differs_from_legacy_position", 0.0) / n,
            "mean_dist_err_rel": acc.get("sum_dist_err", 0.0) / n, "mean_dir_err_deg": acc.get("sum_dir_err", 0.0) / n,
            "zero_B_frac": acc.get("zero_B", 0.0) / n, "u_positive_frac": acc.get("u_positive", 0.0) / n,
            "mean_S_selected": (acc["sum_S_selected"] / n) if "sum_S_selected" in acc else None,
            "high_S_but_zero_B": int(acc.get("high_S_zero_B", 0.0)) if "high_S_zero_B" in acc else None,
            "missing_guide_selected_frac": acc.get("missing_guide_selected", 0.0) / n,
            **{f"mean_{key_}_selected": (acc[f"sum_{key_}"] / n if f"sum_{key_}" in acc else None)
               for key_ in ("valid_point_frac", "r_min", "r_median", "r_endpoints", "r_interior")}}


def routing_reference_scores(table: RoutingTable, F1: np.ndarray, cfg: dict[str, Any], v1_n_ch: int, lum_base: int, n_o: int) -> np.ndarray:
    """검사용 NumPy float64 기준 구현 (같은 수식, 장치 경로와 독립)."""
    rc = cfg["routing"]
    eps, bmin = float(rc["guide_epsilon"]), float(rc["guide_min_total"])
    F1 = np.asarray(F1, np.float64)
    B = F1.shape[0]
    F1e = np.concatenate([F1, np.zeros((B, 1))], 1)
    Fs = F1.reshape(B, table.n_pos1, v1_n_ch)[:, :, lum_base:lum_base + n_o].sum(-1)
    Fse = np.concatenate([Fs, np.zeros((B, 1))], 1)
    a = (F1e[:, table.gA_idx] * table.gA_w.astype(np.float64)).sum(-1)
    b = (Fse[:, table.gB_idx] * table.gB_w.astype(np.float64)).sum(-1)
    ok = table.pt_valid[None] & (b >= bmin)
    r = np.where(ok, a / (b + eps), 0.0)
    S = r.mean(-1)
    return np.where(table.cand_valid[None], S, -1.0)


# ======================================================================
# 7c. 활동 강도 구간 게이트 (v3) — V4 L2 곡선 뉴런의 두 번째 입력군 B 만 바꾼다
#     수용장 안의 역할 후보 (contour θB) 를 모두 보존하고, 이번 입력의 정규화된 활동 강도 z 와 연결별 허용 구간 (μ, σ) 의
#     일치도 g 로 후보 사이 상대 가중치를 정해 가중평균한다. 고정 후보 그래프 위의 입력 의존적 게이트이며
#     연결을 영구 생성·삭제하는 구조적 재배선이나 생물학적 주파수 공명이 아니다. 시간축·스파이크가 없으므로
#     "발화 frequency/Hz 구간" 이 아니라 "정규화된 활동 강도 구간" 이다.
# ======================================================================
BAND_MODES: tuple[str, ...] = ("expanded_pool", "band_gated")
V2_ROUTED_MODES: tuple[str, ...] = ("geometry_only", "v1_guided")
V2_FILTER_REASONS = {0: "v2_pass", 1: "curvature_sign", 2: "folded", 3: "zero_tangent", 4: "outside_rf", 5: "direction_conflict",
                     6: "distance_range", 7: "chord_direction"}
BAND_CONVENTION_KO = {
    "candidate_rule": "후보 = Q ≠ P 이고 ‖Q − P‖ ≤ R_j (V4 L2 뉴런 j 의 수용장 반경, 처리 영상 화소) 인 V4 L4 위치의 contour θB 채널. "
                      "v2 의 거리 [0.5D, 1.5D]·현 ±45°·Hermite 곡률 부호 검사는 탈락 조건으로 쓰지 않고 진단값으로만 저장한다.",
    "rf_definition": "R_j = V4 L2 의 pos_rf = (V4 L4 블록 수용장 반경: 자식 V2 L3 위치까지 거리 + 자식 수용장 반경의 최댓값) + D(P). "
                     "모두 처리 영상 (S×S) 화소 단위이며 원영상 좌표계 (x 오른쪽, y 아래) 의 거리다.",
    "w0": "T_j = P + D(P)·dir(φC), φC = θA + s·κ/2 (연속 각도). w0 = w_floor + (1 − w_floor)·exp(−‖Q − T_j‖² / (2 D(P)²)). 고정, 학습 안 함.",
    "normalization": "z_i = x_i / (ε + sqrt(mean_{k∈N(i)} x_k²)). N(i) = 같은 contour 방향 채널의 V4 격자 반경 1 이웃 (각도 wrap, 반경 clip, "
                     "자기 자신 포함). 표본마다 따로 (배치의 다른 이미지 미포함). 넘침을 막으려고 이웃 최댓값으로 나눠 계산한다 (값은 같다). "
                     "L6 와 별도 연산이며 q 를 바꾸지 않는다. z 는 구간 판단에만 쓰고 전달은 원래 x 로 한다.",
    "gate": "g = exp(−(z − μ)² / (2σ²)), w_eff = w0·g, B = Σ w_eff·x / Σ w_eff (유효 후보만). log w = log w0 − (z − μ)²/(2σ²) 에서 "
            "행별 최댓값을 빼 안정화한다. max g < gate_floor 이면 w0 가중평균으로 되돌리고 all_gates_low 로 기록한다.",
    "expanded_pool": "같은 후보·w0, g = 1 로 두고 가중평균 (게이트 효과를 분리하는 비교 조건).",
    "frame": "기하 계산은 시각 좌표 (vx = x − cx, vy = cy − y, 반시계 각도). 화소 y 는 아래로 증가하므로 부호를 바꾼다.",
}


@dataclass
class BandTable:
    """곡선 뉴런별 고정 후보 연결 (구조 생성 때 한 번). 빈 칸 주소는 0 패딩 열 (n_src / n_contour) 을 가리키고 마스크로 표시한다."""

    mode: str
    params: dict[str, Any]
    K: int
    curve_rows: np.ndarray          # (nc,) V4 L2 local 행
    P: np.ndarray                   # (nc,) 첫 입력 위치
    theta_a: np.ndarray
    theta_b: np.ndarray
    sign: np.ndarray
    kappa: np.ndarray
    phi_c: np.ndarray
    D: np.ndarray
    R: np.ndarray                   # (nc,) 수용장 반경 (화소)
    T_xy: np.ndarray                # (nc, 2) w0 기준점 (화소 좌표)
    srcA: np.ndarray                # (nc,) 첫 입력 주소 (V4 L4 local)
    cand_q: np.ndarray              # (nc, K) 후보 위치 (빈칸 −1, 기록용)
    cand_src: np.ndarray            # (nc, K) V4 L4 local 주소 (빈칸 n_src)
    cand_zi: np.ndarray             # (nc, K) contour 정규화 벡터 안 위치 (빈칸 n_contour)
    cand_valid: np.ndarray
    w0: np.ndarray                  # (nc, K) 기하 가중치 (빈칸 0)
    cand_dist: np.ndarray           # (nc, K) ‖Q − P‖ 화소
    cand_dist_ratio: np.ndarray     # (nc, K) ‖Q − P‖ / D
    cand_chord_dev: np.ndarray      # (nc, K) 현 방향과 φC 의 차 (도)
    cand_v2_reason: np.ndarray      # (nc, K) v2 규칙이었다면: 0 통과, 6 거리, 7 현 방향, 1–5 경로 검사 사유 (진단용, 탈락 조건 아님)
    n_cand: np.ndarray
    missing: np.ndarray             # (nc,) 수용장·역할 조건을 만족하는 후보가 정말 없음
    contour_src: np.ndarray         # (nC,) 모든 V4 L4 contour 뉴런의 local 주소 (위치 × 방향 순)
    contour_pos: np.ndarray
    contour_ori: np.ndarray
    norm_nb: np.ndarray             # (nC, Knb) 정규화 이웃 (contour 벡터 안 위치, 빈칸 nC)
    norm_cnt: np.ndarray            # (nC,)
    n_src: int
    n_contour: int
    n_pos: int

    def hash(self) -> str:
        return sha256_text(dumps({"mode": self.mode, "K": self.K, "params": self.params}, indent=None) + sha256_array(
            self.curve_rows, self.P, self.srcA, self.cand_src, self.cand_zi, self.cand_valid, self.w0, self.contour_src,
            self.norm_nb, self.norm_cnt, self.missing))

    def arrays(self) -> dict[str, np.ndarray]:
        return {f_.name: getattr(self, f_.name) for f_ in dataclasses.fields(self) if isinstance(getattr(self, f_.name), np.ndarray)}

    def static_summary(self) -> dict[str, Any]:
        nc = len(self.curve_rows)
        n = self.n_cand
        v = self.cand_valid
        v2 = self.cand_v2_reason[v]
        q = np.percentile(n, [0, 25, 50, 75, 100]).tolist() if nc else []
        return {"mode": self.mode, "n_curve_neurons": nc, "K_max": self.K, "params": self.params,
                "candidates_per_neuron": {"min": int(n.min()) if nc else 0, "p25": q[1] if q else None, "median": q[2] if q else None,
                                          "p75": q[3] if q else None, "max": int(n.max()) if nc else 0, "mean": float(n.mean()) if nc else None},
                "n_edges": int(v.sum()), "missing_candidate": int(self.missing.sum()),
                "missing_candidate_frac": float(self.missing.mean()) if nc else None,
                "neurons_with_ge2_candidates": int((n >= 2).sum()),
                "w0": {"mean": float(self.w0[v].mean()) if v.any() else None, "min": float(self.w0[v].min()) if v.any() else None,
                       "max": float(self.w0[v].max()) if v.any() else None},
                "v2_rule_would_keep_frac": float((v2 == 0).mean()) if v2.size else None,
                "v2_rule_reasons_of_kept_candidates": {V2_FILTER_REASONS[k]: int((v2 == k).sum()) for k in V2_FILTER_REASONS},
                "normalization_pool": {"neighbors_min": int(self.norm_cnt.min()), "neighbors_max": int(self.norm_cnt.max()),
                                       "n_contour_neurons": self.n_contour, "includes_self": bool(self.params["norm_include_self"])},
                "extra_gather_elements_per_sample": int(nc * self.K * 3 + self.n_contour * self.norm_nb.shape[1]),
                "table_sha256": self.hash(),
                "note_ko": "후보는 수용장·역할 조건만으로 정한다. v2_rule_* 는 이전 거리·현 방향·곡률 검사를 적용했다면의 결과이며 탈락에 쓰지 않았다."}


@dataclass
class BandCalibration:
    """연결별 구간 (μ, σ) — train 만 쓰는 1회 초기 보정 후 고정 (이미지별 라우팅·에폭 학습이 아니다)."""

    mu: np.ndarray                  # (nc, K)
    sigma: np.ndarray
    count: np.ndarray               # 유효 표본 수
    insufficient: np.ndarray        # count < min_calibration_count (넓은 기본 구간 사용)
    sample_ids: list[str]
    model_hash: str
    table_hash: str
    params: dict[str, Any]
    seconds: float = 0.0
    utc: str = ""
    runtime_info: dict[str, Any] = field(default_factory=dict)      # 장치·메모리 기록 (해시에 넣지 않음)

    def hash(self) -> str:
        return sha256_text(dumps({"model_hash": self.model_hash, "table_hash": self.table_hash, "params": self.params,
                                  "ids": sha256_text("\n".join(self.sample_ids))}, indent=None)
                           + sha256_array(self.mu.astype(np.float32), self.sigma.astype(np.float32), self.count, self.insufficient))

    def summary(self, table: BandTable) -> dict[str, Any]:
        v = table.cand_valid
        c = self.count[v]
        ins = self.insufficient[v]
        mu, sg = self.mu[v & ~self.insufficient], self.sigma[v & ~self.insufficient]
        return {"utc": self.utc, "n_samples": len(self.sample_ids), "seconds": round(self.seconds, 3), "runtime_info": self.runtime_info,
                "n_edges": int(v.sum()),
                "insufficient_edges": int(ins.sum()), "insufficient_frac": float(ins.mean()) if ins.size else None,
                "valid_count": {"min": int(c.min()) if c.size else 0, "median": float(np.median(c)) if c.size else None,
                                "max": int(c.max()) if c.size else 0},
                "mu": {"min": float(mu.min()) if mu.size else None, "median": float(np.median(mu)) if mu.size else None,
                       "max": float(mu.max()) if mu.size else None},
                "sigma": {"min": float(sg.min()) if sg.size else None, "median": float(np.median(sg)) if sg.size else None,
                          "max": float(sg.max()) if sg.size else None, "at_floor_frac": float((sg <= float(self.params["sigma_floor"]) + 1e-12).mean())
                          if sg.size else None},
                "distinct_mu_sigma_pairs": int(len({(round(float(a), 6), round(float(b), 6)) for a, b in zip(mu, sg)})),
                "model_hash": self.model_hash, "table_hash": self.table_hash, "calibration_sha256": self.hash(),
                "sample_ids_sha256": sha256_text("\n".join(self.sample_ids)), "params": self.params,
                "rule_ko": "train 에서 고정 seed 별도 RNG 로 최대 N 장 (라벨·dev·test 미사용). A_j > ε 이고 x_i > ε 인 표본의 z_i 로 "
                           "μ = median(z), σ = max(1.4826·median|z − μ|, σ_floor). 유효 표본 < 최소 수면 μ = 1, σ = 2 (calibration_insufficient). "
                           "보정 뒤 학습·dev·test·추론에서 고정. 같은 입력 분포를 보는 연결은 같은 구간을 가질 수 있으며 이를 전문화라 부르지 않는다."}


def build_band_table(cfg: dict[str, Any], pre: "RetinaLGNPreprocessor", l4: LayerSpec, l2_rf: np.ndarray, n_ch2: int,
                     curve_info: list[tuple[int, int, int, int, float]], contour: dict[int, int], D: np.ndarray, mode: str,
                     grid: tuple[int, int]) -> BandTable:
    bc, rc = cfg["band"], cfg["routing"]
    oris = [float(t) for t in cfg["areas"]["V1"]["orientations_deg"]]
    n_o = len(oris)
    w_floor = float(bc["w_floor"])
    px, py = l4.pos_x.astype(np.float64), l4.pos_y.astype(np.float64)
    vx, vy = px - pre.cx, pre.cy - py
    n_pos, n_in = l4.n_pos, l4.n_ch
    rf2 = l4.pos_rf.astype(np.float64)
    dmin_f, dmax_f, dev = float(rc["dist_min_factor"]), float(rc["dist_max_factor"]), float(rc["max_chord_dev_deg"])
    M, tol = int(rc["path_points"]), float(rc["curvature_turn_tol_deg"])
    rows, Ps, ta, tb, sg, kp, pc, Dl, Rl, Txy, sA, lists = [], [], [], [], [], [], [], [], [], [], [], []
    for P in range(n_pos):
        Rj = float(l2_rf[P])
        dq = np.hypot(px - px[P], py - py[P])
        qs = [int(q) for q in np.nonzero((dq <= Rj) & (np.arange(n_pos) != P))[0]]
        for (ch, i, j, s, kap) in curve_info:
            phi_a, phi_b, phi_c = curve_directions(oris[i], s, kap)
            Tvx = vx[P] + D[P] * math.cos(math.radians(phi_c))
            Tvy = vy[P] + D[P] * math.sin(math.radians(phi_c))
            items = []
            for Q in qs:
                dTx, dTy = vx[Q] - Tvx, vy[Q] - Tvy
                w0 = w_floor + (1.0 - w_floor) * math.exp(-(dTx * dTx + dTy * dTy) / (2.0 * float(D[P]) ** 2))
                d = float(dq[Q])
                chord = float(d_dir(math.degrees(math.atan2(vy[Q] - vy[P], vx[Q] - vx[P])), phi_c))
                if not (dmin_f * D[P] <= d <= dmax_f * D[P]):
                    reason = 6
                elif chord > dev:
                    reason = 7
                else:
                    Pv, Qv = np.asarray([vx[P], vy[P]]), np.asarray([vx[Q], vy[Q]])
                    p_, dp_ = hermite_path(Pv, Qv, phi_a, phi_b, M)
                    reason, _tot = path_check(p_, dp_, Pv, Qv, phi_a, phi_b, s, tol, rf2[P], rf2[Q])
                items.append((Q, Q * n_in + contour[j], Q * n_o + j, w0, d, d / float(D[P]), chord, reason))
            rows.append(P * n_ch2 + ch)
            Ps.append(P)
            ta.append(oris[i])
            tb.append(oris[j])
            sg.append(s)
            kp.append(kap)
            pc.append(phi_c)
            Dl.append(float(D[P]))
            Rl.append(Rj)
            Txy.append((Tvx + pre.cx, pre.cy - Tvy))
            sA.append(P * n_in + contour[i])
            lists.append(items)
    nc = len(rows)
    K = max([len(it) for it in lists] + [1])
    n_src, nC = l4.n, n_pos * n_o
    cand_q = np.full((nc, K), -1, np.int64)
    cand_src = np.full((nc, K), n_src, np.int64)
    cand_zi = np.full((nc, K), nC, np.int64)
    cand_valid = np.zeros((nc, K), bool)
    w0a = np.zeros((nc, K), np.float32)
    cdist = np.zeros((nc, K), np.float32)
    cratio = np.zeros((nc, K), np.float32)
    cchord = np.zeros((nc, K), np.float32)
    creason = np.full((nc, K), -1, np.int8)
    for c, items in enumerate(lists):
        for k, (Q, src, zi, w0, d, ratio, chord, reason) in enumerate(items):
            cand_q[c, k], cand_src[c, k], cand_zi[c, k], cand_valid[c, k] = Q, src, zi, True
            w0a[c, k], cdist[c, k], cratio[c, k], cchord[c, k], creason[c, k] = w0, d, ratio, chord, reason
    n_cand = cand_valid.sum(1).astype(np.int64)
    contour_src = np.asarray([p * n_in + contour[o] for p in range(n_pos) for o in range(n_o)], np.int64)
    contour_pos = np.repeat(np.arange(n_pos), n_o)
    contour_ori = np.tile(np.arange(n_o), n_pos)
    nb, nbc = grid_neighbors(grid[0], grid[1], int(bc["norm_grid_radius"]))
    incl = bool(bc["norm_include_self"])
    Knb = int(nb.shape[1])
    norm_nb = np.full((nC, Knb), nC, np.int64)
    norm_cnt = np.zeros(nC, np.int64)
    for z in range(nC):
        p, o = int(contour_pos[z]), int(contour_ori[z])
        ps = [int(q) for q in nb[p, :nbc[p]] if incl or int(q) != p]
        norm_nb[z, :len(ps)] = [q * n_o + o for q in ps]
        norm_cnt[z] = len(ps)
    params = {k: bc[k] for k in ("w_floor", "epsilon_norm", "norm_grid_radius", "norm_include_self", "gate_floor")}
    params["candidate_rule"] = "in_rf_contour_thetaB_not_P"
    return BandTable(mode=mode, params=params, K=K, curve_rows=np.asarray(rows, np.int64), P=np.asarray(Ps, np.int64),
                     theta_a=np.asarray(ta, np.float32), theta_b=np.asarray(tb, np.float32), sign=np.asarray(sg, np.int8),
                     kappa=np.asarray(kp, np.float32), phi_c=np.asarray(pc, np.float32), D=np.asarray(Dl, np.float32),
                     R=np.asarray(Rl, np.float32), T_xy=np.asarray(Txy, np.float32).reshape(nc, 2), srcA=np.asarray(sA, np.int64),
                     cand_q=cand_q, cand_src=cand_src, cand_zi=cand_zi, cand_valid=cand_valid, w0=w0a, cand_dist=cdist,
                     cand_dist_ratio=cratio, cand_chord_dev=cchord, cand_v2_reason=creason, n_cand=n_cand, missing=n_cand == 0,
                     contour_src=contour_src, contour_pos=contour_pos, contour_ori=contour_ori, norm_nb=norm_nb, norm_cnt=norm_cnt,
                     n_src=n_src, n_contour=nC, n_pos=n_pos)


class BandRuntime:
    """장치 쪽 후보 표와 이미지별 게이트 계산 (배치마다 gather · 제곱합 · exp · 가중평균 · min, 뉴런별 Python 루프 없음).
    입력에 라벨·prototype·오차가 없다. 표본마다 독립 (정규화 이웃은 같은 표본 안에서만)."""

    def __init__(self, table: BandTable, be: Backend, cfg: dict[str, Any], n_layer: int):
        bc = cfg["band"]
        self.table, self.be, self.mode = table, be, table.mode
        self.K, self.nc = table.K, len(table.curve_rows)
        self.eps = float(bc["epsilon_norm"])
        self.gate_floor = float(bc["gate_floor"])
        self.contour_src = be.i64(table.contour_src)
        self.norm_nb = be.i64(table.norm_nb)
        self.norm_div = be.f32(np.maximum(table.norm_cnt, 1).astype(np.float32))
        self.cand_src, self.cand_zi = be.i64(table.cand_src), be.i64(table.cand_zi)
        self.valid = be.bool_(table.cand_valid)
        self.w0 = be.f32(np.where(table.cand_valid, table.w0, 0.0))
        self.log_w0 = be.f32(np.where(table.cand_valid, np.log(np.maximum(table.w0, 1e-30)), 0.0))
        self.has_cand = be.bool_(~table.missing)
        cmap = np.full(n_layer, self.nc, np.int64)
        cmap[table.curve_rows] = np.arange(self.nc)
        self.curve_map = be.i64(cmap)
        self.curve_rows = be.i64(table.curve_rows)
        self.srcA = be.i64(table.srcA)
        self.mu = be.f32(np.zeros((self.nc, self.K), np.float32))
        self.sigma = be.f32(np.ones((self.nc, self.K), np.float32))
        self.calibration: BandCalibration | None = None

    @property
    def calibrated(self) -> bool:
        return self.calibration is not None

    def set_calibration(self, cal: BandCalibration) -> None:
        t = self.table
        if cal.mu.shape != (self.nc, self.K) or cal.table_hash != t.hash():
            raise CompatibilityError("구간 보정 결과가 현재 후보 표와 맞지 않는다 (모양 또는 표 해시).")
        mu = np.where(t.cand_valid, cal.mu, 0.0).astype(np.float32)
        sg = np.where(t.cand_valid, cal.sigma, 1.0).astype(np.float32)
        if not (np.isfinite(mu).all() and np.isfinite(sg).all() and (sg > 0).all()):
            raise ValueError("구간 μ·σ 에 NaN/Inf 또는 σ ≤ 0 이 있다.")
        self.mu, self.sigma = self.be.f32(mu), self.be.f32(sg)
        self.calibration = cal

    def normalize(self, xe: Any) -> Any:
        """xe: (B, n_src+1) V4 L4 전송 출력 (마지막 열 0) → z (B, nC). 이웃 최댓값 s 로 나눠 넘침 없이 sqrt(mean x²) 를 계산한다."""
        be = self.be
        xc = be.take_cols(xe, self.contour_src)                                  # (B, nC) 원래 x
        nbx = be.take_cols(be.pad_zero_col(xc), self.norm_nb)                    # (B, nC, Knb) 빈칸 0
        s = be.max_last(nbx)
        s_safe = be.where(s > 0, s, be.ones_like(s))
        r = nbx / s_safe.reshape(tuple(s_safe.shape) + (1,))
        rms = s * be.sqrt(be.sum_last(r * r) / self.norm_div)
        return xc / (rms + self.eps)

    def combine(self, xe: Any, *, mode: str | None = None, record: bool = False) -> dict[str, Any]:
        """두 번째 입력 B (B, nc). mode = expanded_pool (g = 1) / band_gated (연결별 구간 게이트)."""
        be = self.be
        mode = mode or self.mode
        if mode not in BAND_MODES:
            raise ValueError(f"강도 구간 런타임이 지원하지 않는 모드: {mode}")
        if mode == "band_gated" and not self.calibrated:
            raise RuntimeError("band_gated 는 구간 초기 보정 뒤에만 계산할 수 있다 (V4 추가 때 1회 보정).")
        Bn = int(xe.shape[0])
        z = self.normalize(xe)
        ze = be.pad_zero_col(z)
        rows = max(1, be.max_gather // max(1, Bn * self.K * 6))
        outB, outLow, outMaxG = [], [], []
        recX, recZ, recG, recS = [], [], [], []
        for a in range(0, self.nc, rows):
            sl = slice(a, a + rows)
            X = be.take_cols(xe, self.cand_src[sl])                              # (B, r, K) 원래 x (가중평균 전까지 주소별로 유지)
            Z = be.take_cols(ze, self.cand_zi[sl])                               # (B, r, K) 정규화 z (구간 판단에만)
            valid = self.valid[sl]
            w0 = self.w0[sl]
            if mode == "expanded_pool":
                w = be.where(valid, w0 + be.zeros(X.shape), be.zeros(X.shape))
                g = be.where(valid, be.ones_like(X), be.zeros(X.shape))
                low = be.bool_(np.zeros((Bn, min(rows, self.nc - a)), bool))
                maxg = be.max_last(g)
            else:
                d = (Z - self.mu[sl]) / self.sigma[sl]
                lg = -0.5 * d * d
                g = be.where(valid, be.exp(lg), be.zeros(X.shape))
                maxg = be.max_last(g)
                low = (maxg < self.gate_floor) & self.has_cand[sl]
                logw = be.where(valid, self.log_w0[sl] + lg, be.zeros(X.shape) - 1e30)
                m = be.max_last(logw)
                w_g = be.where(valid, be.exp(logw - m.reshape(tuple(m.shape) + (1,))), be.zeros(X.shape))
                w_0 = be.where(valid, w0 + be.zeros(X.shape), be.zeros(X.shape))
                w = be.where(low.reshape(tuple(low.shape) + (1,)), w_0, w_g)       # 모든 구간이 닫히면 기하 가중평균으로 (기록)
            sw = be.sum_last(w)
            num = be.sum_last(w * X)
            Bv = be.where(sw > 0, num / be.where(sw > 0, sw, be.ones_like(sw)), be.zeros(sw.shape))
            outB.append(Bv)
            outLow.append(low)
            outMaxG.append(maxg)
            if record:
                share = w / be.where(sw > 0, sw, be.ones_like(sw)).reshape(tuple(sw.shape) + (1,))
                recX.append(X)
                recZ.append(Z)
                recG.append(g)
                recS.append(share)
        cat = (lambda xs: xs[0] if len(xs) == 1 else be.cat1(xs))
        out = {"B": cat(outB), "all_gates_low": cat(outLow), "max_g": cat(outMaxG), "mode": mode, "gated": mode == "band_gated"}
        if record:
            out.update(X=cat(recX), Z=cat(recZ), G=cat(recG), share=cat(recS), z_contour=z)
        return out

    def nbytes(self) -> int:
        t = self.table
        return int(t.cand_src.size * 8 * 2 + t.cand_valid.size * 13 + t.norm_nb.size * 8 + t.contour_src.size * 8)


def band_rec_np(be: Backend, rec: dict[str, Any]) -> dict[str, Any]:
    out: dict[str, Any] = {"B": be.to_np(rec["B"]).astype(np.float64), "A": be.to_np(rec["A"]).astype(np.float64),
                           "all_gates_low": be.to_np(rec["all_gates_low"]).astype(bool), "max_g": be.to_np(rec["max_g"]).astype(np.float64),
                           "mode": rec["mode"], "gated": bool(rec["gated"])}
    for k in ("X", "Z", "G", "share"):
        if k in rec:
            out[k] = be.to_np(rec[k]).astype(np.float32)
    return out


def band_batch_stats(table: BandTable, rec: dict[str, Any], act_eps: float) -> dict[str, float]:
    """한 배치의 게이트 기록 → 합계 (에폭 끝에 비율로). 후보 없음 뉴런은 선택 통계에서 빼고 따로 센다."""
    ok = ~table.missing
    A, Bv = rec["A"][:, ok], rec["B"][:, ok]
    nb = A.shape[0]
    u = np.minimum(A, Bv)
    out = {"n_samples": float(nb), "n_pairs": float(A.size), "n_missing_pairs": float(nb * int((~ok).sum())),
           "all_gates_low": float(rec["all_gates_low"][:, ok].sum()),
           "A_zero": float((A <= 0).sum()), "B_zero": float((Bv <= 0).sum()), "both_zero": float(((A <= 0) & (Bv <= 0)).sum()),
           "A_le_B": float((A <= Bv).sum()), "B_lt_A": float((Bv < A).sum()), "u_zero": float((u <= 0).sum()),
           "sum_A": float(A.sum()), "sum_B": float(Bv.sum()), "sum_u": float(u.sum()), "sum_max_g": float(rec["max_g"][:, ok].sum())}
    if "share" in rec:
        sh = rec["share"][:, ok, :].astype(np.float64)
        G = rec["G"][:, ok, :].astype(np.float64)
        valid = np.broadcast_to(table.cand_valid[ok][None], G.shape)
        out["sum_max_share"] = float(sh.max(-1).sum())
        eff = 1.0 / np.maximum((sh * sh).sum(-1), 1e-12)
        out["sum_eff_n"] = float(np.where((sh.sum(-1) > 0), eff, 0.0).sum())
        out["n_edges"] = float(valid.sum())
        out["g_ge_0p5"] = float(((G >= 0.5) & valid).sum())
        out["g_0p05_0p5"] = float(((G >= 0.05) & (G < 0.5) & valid).sum())
        out["g_lt_0p05"] = float(((G < 0.05) & valid).sum())
        X = rec["X"][:, ok, :].astype(np.float64)
        act = (X > act_eps) & valid
        out["edges_active"] = float(act.sum())
        out["edges_active_g_ge_0p5"] = float(((G >= 0.5) & act).sum())
    return out


def band_finalize(acc: dict[str, float], table: BandTable) -> dict[str, Any]:
    n = max(1.0, acc.get("n_pairs", 0.0))
    tot = acc.get("n_pairs", 0.0) + acc.get("n_missing_pairs", 0.0)
    ne = max(1.0, acc.get("n_edges", 0.0))
    out = {"n_samples": int(acc.get("n_samples", 0)), "missing_candidate_frac": (acc.get("n_missing_pairs", 0.0) / tot) if tot else None,
           "candidates_mean": float(table.n_cand[~table.missing].mean()) if (~table.missing).any() else None,
           "all_gates_low_frac": acc.get("all_gates_low", 0.0) / n,
           "A_zero_frac": acc.get("A_zero", 0.0) / n, "B_zero_frac": acc.get("B_zero", 0.0) / n,
           "both_zero_frac": acc.get("both_zero", 0.0) / n, "A_le_B_frac": acc.get("A_le_B", 0.0) / n,
           "B_lt_A_frac": acc.get("B_lt_A", 0.0) / n, "u_zero_frac": acc.get("u_zero", 0.0) / n,
           "mean_A": acc.get("sum_A", 0.0) / n, "mean_B": acc.get("sum_B", 0.0) / n, "mean_u": acc.get("sum_u", 0.0) / n,
           "mean_max_g": acc.get("sum_max_g", 0.0) / n}
    if "sum_max_share" in acc:
        out.update(mean_max_share=acc["sum_max_share"] / n, mean_effective_candidates=acc["sum_eff_n"] / n,
                   edge_g_ge_0p5_frac=acc["g_ge_0p5"] / ne, edge_g_0p05_0p5_frac=acc["g_0p05_0p5"] / ne, edge_g_lt_0p05_frac=acc["g_lt_0p05"] / ne,
                   active_edges_frac=acc["edges_active"] / ne,
                   active_edges_in_band_frac=(acc["edges_active_g_ge_0p5"] / acc["edges_active"]) if acc.get("edges_active") else None)
    return out


def band_reference_B(table: BandTable, cal: BandCalibration | None, xe: np.ndarray, cfg: dict[str, Any], mode: str) -> dict[str, np.ndarray]:
    """검사용 NumPy float64 기준 구현 (같은 수식, 장치 경로와 독립, 루프 없이 직접 식대로)."""
    bc = cfg["band"]
    eps, floor = float(bc["epsilon_norm"]), float(bc["gate_floor"])
    xe = np.asarray(xe, np.float64)
    xc = xe[:, table.contour_src]
    xce = np.concatenate([xc, np.zeros((xc.shape[0], 1))], 1)
    nbx = xce[:, table.norm_nb]
    rms = np.sqrt((nbx * nbx).sum(-1) / np.maximum(table.norm_cnt, 1))
    z = xc / (eps + rms)
    ze = np.concatenate([z, np.zeros((z.shape[0], 1))], 1)
    X = xe[:, table.cand_src]
    Z = ze[:, table.cand_zi]
    v = table.cand_valid[None]
    w0 = np.where(table.cand_valid, table.w0, 0.0).astype(np.float64)[None]
    if mode == "expanded_pool":
        w = np.broadcast_to(w0, X.shape)
        low = np.zeros(X.shape[:2], bool)
    else:
        g = np.where(v, np.exp(-0.5 * ((Z - cal.mu[None]) / cal.sigma[None]) ** 2), 0.0)
        low = (g.max(-1) < floor) & ~table.missing[None]
        w = np.where(low[..., None], w0, w0 * g)
    sw = w.sum(-1)
    with np.errstate(invalid="ignore", divide="ignore"):
        Bv = np.where(sw > 0, (w * X).sum(-1) / np.where(sw > 0, sw, 1.0), 0.0)
    return {"B": Bv, "z": z, "low": low}


def calibration_model_hash(sess: "Session", specs: Sequence[LayerSpec], table: BandTable) -> str:
    m = sess.model
    qn = m.store.q_numpy()
    parts = {"struct": {a: m.struct_hash[a] for a in ("V1", "V2")}, "v4_l4": specs[0].hash(), "band_table": table.hash(),
             "q_V1V2": sha256_array(*(qn[m.specs[f"{a}/{l}"].start:m.specs[f"{a}/{l}"].end] for a in ("V1", "V2") for l in LAYER_ORDER)),
             "preprocessing": sha256_text(dumps(sess.pre.info(), indent=None)), "config_structure": config_structure_sha(sess.cfg),
             "neuron": sess.cfg["neuron"]}
    return sha256_text(dumps(parts, indent=None))


def _static_layer_out(model: "CortexModel", rt: LayerRuntime, xe: Any, q: float, thr: float) -> Any:
    """아직 모델에 넣지 않은 층의 전송 출력 (CortexModel.forward 와 같은 순서: A·B 결합 → θ → q → L6). q·θ 는 생성 직후 값 (q_init, threshold)."""
    be = model.be
    sa = rt.A.apply(be, xe)
    if rt.has_b and rt.Bm is not None:
        sb = rt.Bm.apply(be, xe)
        u = be.where(rt.op_min, be.minimum(sa, sb), sa + sb)
    else:
        u = sa
    conf = q * be.relu(u - thr)
    g = model.l6.gain(conf, rt) if rt.l6 else None
    return conf if g is None else g * conf


class CalibrationInterrupted(KeyboardInterrupt):
    """구간 보정 중 Ctrl+C. 처리한 표본까지 routing/band_calibration_partial.npz 에 남기고, 다시 V4 를 추가하면 이어서 한다."""


def run_band_calibration(sess: "Session", specs: Sequence[LayerSpec]) -> BandCalibration:
    """V1·V2 동결, V4 L4 고정 상태에서 1회 실행 (V4 를 모델에 넣기 전, 읽기 전용 계산). q·prototype 을 바꾸지 않는다.
    처리 순서: 고정 seed 별도 RNG 로 train 표본 선택 → 배치마다 V2 L3 → V4 L4 (q = q_init, θ, L6 없음) → z, A 수집 → 연결별 median/MAD."""
    be, cfg = sess.be, sess.cfg
    bc = cfg["band"]
    l4, l2 = specs[0], specs[1]
    table: BandTable = l2.band
    r = sess.need_rec()
    items = sess.data.items("train")
    rng = np.random.default_rng([int(cfg["seed"]), int(bc["calibration_seed_offset"])])
    n_take = min(int(bc["calibration_max_samples"]), len(items))
    order = rng.permutation(len(items))[:n_take]
    chosen = [items[int(i)] for i in order]
    ids = [it["relpath"] for it in chosen]
    mhash = calibration_model_hash(sess, specs, table)
    partial = r.p("routing/band_calibration_partial.npz")
    Xs, Zs, As, done = [], [], [], 0
    resumed_from = 0
    sess.say(f"  [구간 보정] V4 강도 구간 초기 보정 1회: train {n_take} 장 (최대 {bc['calibration_max_samples']}, 고정 seed, 라벨·dev·test 미사용), "
             f"후보 연결 {int(table.cand_valid.sum())} 개. Ctrl+C 로 멈추면 다음에 이어서 한다.")
    if partial.is_file():
        z0 = load_npz(partial)
        if str(z0["model_hash"]) == mhash and str(z0["table_hash"]) == table.hash() and list(z0["sample_ids"]) == ids:
            done = resumed_from = int(z0["n_done"])
            Xs, Zs, As = [z0["X"]], [z0["Z"]], [z0["A"]]
            sess.say(f"  [구간 보정] 이전 중단 지점부터 이어서 한다: {done}/{n_take} 표본")
        else:
            sess.say("  [구간 보정] 이전 부분 기록의 모델·표·표본이 달라 버리고 처음부터 한다.")
            partial.unlink()
    rt = BandRuntime(table, be, cfg, l2.n)
    l4rt = LayerRuntime(l4, be, cfg)
    q4, thr = float(cfg["neuron"]["q_init"]), float(cfg["neuron"]["threshold"])
    B = int(cfg["learning"]["batch_size"])
    t0 = time.perf_counter()
    if be.is_cuda:
        torch.cuda.reset_peak_memory_stats(be.dev)

    def save_partial(n: int) -> None:
        save_npz(partial, X=np.concatenate(Xs) if Xs else np.zeros((0, table.n_contour), np.float32),
                 Z=np.concatenate(Zs) if Zs else np.zeros((0, table.n_contour), np.float32),
                 A=np.concatenate(As) if As else np.zeros((0, len(table.curve_rows)), np.float32),
                 n_done=np.asarray(n), model_hash=np.asarray(mhash), table_hash=np.asarray(table.hash()), sample_ids=np.asarray(ids))

    step = max(1, (n_take // B) // 10)
    nb_done = 0
    with StopFlag(sess.say) as stop:
        try:
            for a in range(done, n_take, B):
                chunk = chosen[a:a + B]
                lgn, _y_unused = sess.loader.batch(chunk, "train")                 # 라벨은 버린다 (구간 계산에 쓰지 않음)
                v2 = sess.model.forward(lgn, upto="V2")["V2/L3"]["out"]
                x4 = _static_layer_out(sess.model, l4rt, be.pad_zero_col(v2), q4, thr)
                xe = be.pad_zero_col(x4)
                z = rt.normalize(xe)
                Xs.append(be.to_np(be.take_cols(xe, rt.contour_src)).astype(np.float32))
                Zs.append(be.to_np(z).astype(np.float32))
                As.append(be.to_np(be.take_cols(xe, rt.srcA)).astype(np.float32))
                done = a + len(chunk)
                nb_done += 1
                if nb_done % step == 0:
                    sess.say(f"    [구간 보정] {done}/{n_take} 표본")
                if sess.fault == "interrupt_calibration" and nb_done >= 2:
                    sess.fault = None
                    stop.requested = True
                if stop.requested and done < n_take:
                    save_partial(done)
                    raise CalibrationInterrupted(f"구간 보정 중단: {done}/{n_take} 표본까지 저장 (다시 V4 를 추가하면 이어서 한다)")
        except CalibrationInterrupted:
            raise
        except KeyboardInterrupt:
            save_partial(done)
            raise CalibrationInterrupted(f"구간 보정 즉시 중단: {done}/{n_take} 표본까지 저장") from None
    X = np.concatenate(Xs) if Xs else np.zeros((0, table.n_contour), np.float32)
    Z = np.concatenate(Zs) if Zs else np.zeros((0, table.n_contour), np.float32)
    A = np.concatenate(As) if As else np.zeros((0, len(table.curve_rows)), np.float32)
    eps_a = float(bc["activity_epsilon"])
    nc, K = table.cand_valid.shape
    mu = np.full((nc, K), float(bc["default_mu"]), np.float64)
    sg = np.full((nc, K), float(bc["default_sigma"]), np.float64)
    cnt = np.zeros((nc, K), np.int64)
    chunk_rows = max(1, int(4e6 // max(1, X.shape[0] * K)))
    for c0 in range(0, nc, chunk_rows):
        sl = slice(c0, c0 + chunk_rows)
        zi = table.cand_zi[sl]
        valid = table.cand_valid[sl]
        zi_c = np.minimum(zi, table.n_contour - 1)
        Ze = Z[:, zi_c]                                                   # (n, r, K)
        Xe = X[:, zi_c]
        ok = (A[:, sl][:, :, None] > eps_a) & (Xe > eps_a) & valid[None]
        vals = np.where(ok, Ze, np.nan).astype(np.float64)
        c = ok.sum(0)
        cnt[sl] = c
        with np.errstate(all="ignore"), warnings.catch_warnings():
            warnings.simplefilter("ignore", RuntimeWarning)
            med = np.nanmedian(vals, axis=0)
            mad = np.nanmedian(np.abs(vals - med[None]), axis=0)
        good = valid & (c >= int(bc["min_calibration_count"]))
        mu[sl] = np.where(good, med, mu[sl])
        sg[sl] = np.where(good, np.maximum(float(bc["mad_scale"]) * mad, float(bc["sigma_floor"])), sg[sl])
    insufficient = table.cand_valid & (cnt < int(bc["min_calibration_count"]))
    mu = np.where(table.cand_valid, mu, 0.0)
    sg = np.where(table.cand_valid, sg, 1.0)
    params = {k: bc[k] for k in ("calibration_max_samples", "calibration_seed_offset", "activity_epsilon", "min_calibration_count",
                                 "mad_scale", "sigma_floor", "default_mu", "default_sigma")}
    cal = BandCalibration(mu=mu.astype(np.float32), sigma=sg.astype(np.float32), count=cnt, insufficient=insufficient, sample_ids=ids,
                          model_hash=mhash, table_hash=table.hash(), params=params, seconds=time.perf_counter() - t0, utc=utc_now(),
                          runtime_info={"backend": be.kind, "device": str(be.device), "resumed_from_sample": int(resumed_from),
                                        "gpu_max_memory_allocated_mb": (round(torch.cuda.max_memory_allocated(be.dev) / 2 ** 20, 1)
                                                                        if be.is_cuda else None),
                                        "note_ko": "seconds 는 이번 호출의 시간이다 (중단 뒤 이어서 했으면 이전 부분은 빠진다)."})
    if partial.is_file():
        partial.unlink()
    summ = cal.summary(table)
    sess.say(f"  [구간 보정] 완료: 표본 {len(ids)}, 연결 {summ['n_edges']}, 표본 부족 연결 {summ['insufficient_edges']} "
             f"({fmt(summ['insufficient_frac'])}), {summ['seconds']} 초")
    return cal


# ======================================================================
# 7d. V1 안내 목적지 선택 (v4: v1_destination_guided)
#     V4 위치 P × 역할 (곡선·직선·접합·선 끝) 마다 이번 이미지의 V1 L3 안내 점수가 가장 높은 V4 L2 수신 뉴런 하나와
#     그 뉴런의 입력 슬롯 묶음 (A, B) 을 고른다. 실제 전달값은 V4 L4 출력에서만 읽는다 (안내 값을 더하거나 곱하지 않는다).
#     후보 그래프·경로 보간 인덱스·선택 집단은 구조 생성 때 한 번 만들고 바꾸지 않는다 (고정 규칙, 학습하지 않음).
#     U-Net 의 특징 전달 연결에서 착안한 공학적 설계이며 생물학적으로 입증된 피질 규칙이 아니다.
# ======================================================================
DEST_ROLES: tuple[str, ...] = ("curve", "straight", "junction", "lineend")
DEST_ROLE_CODE = {r: i for i, r in enumerate(DEST_ROLES)}
DEST_SLOT_NAME = {0: "A", 1: "B"}
DEST_CURVE_REASONS = {0: "valid", 1: "behind_P", 2: "bend_side", 3: "path_outside_image", 4: "zero_tangent", 5: "folded_path"}
DEST_CURVE_REASONS_KO = {
    "same_position": "Q = P (같은 위치는 두 번째 위치가 아니다)",
    "outside_rf": "‖Q − P‖ > R_j (V4 L2 수용장 밖, 원영상 화소 거리)",
    "behind_P": "진행 방향 조건: (Q − P)·dir(φA) ≤ 0 (곡선 역할은 P 에서 +θA 방향으로 나아간다 — 기존 역할 정의)",
    "bend_side": "뒤집힌 굽힘: s·cross(dir(φA), Q − P) ≤ 0 (Q 가 P 접선의 굽힘 쪽 반평면 밖이면 처음부터 반대로 굽어야 한다)",
    "path_outside_image": "Hermite 경로 점이 로그-극좌표 표본 원 (r > Rmax) 밖 — 안내 지도를 읽을 수 없다",
    "zero_tangent": "경로 접선 크기 0 (방향을 정의할 수 없다)",
    "folded_path": "경로가 P→Q 현 방향으로 되돌아가거나 (p'·(Q−P) ≤ 0) 총 회전 > 180° (접힘·고리)",
}
DEST_CONVENTION_KO = {
    "group": "선택 집단 = V4 위치 P × 역할 (selection_group = position_role). 역할이 다른 점수를 한 순위로 섞지 않는다. 전역 승자 방식이 아니다.",
    "top1": "집단마다 양의 유효 점수 중 최고 1 개 (top_k = 1). 같은 점수는 neuron_id 가 작은 쪽. 후보가 없거나 모두 0 이하·NaN 이면 선택 없음.",
    "bundle": "선택된 목적지와 그 입력 슬롯 (곡선: A = (P, θA), B = (Q*, θB)) 을 한 묶음으로 확정한다. A 와 B 를 따로 뽑지 않는다.",
    "values": "전달값 = 같은 이미지의 V4 L4 실제 전송 출력 X4. 안내 점수는 경로 선택에만 쓰고 u 에 곱하거나 더하지 않는다.",
    "unselected": "선택되지 않은 뉴런: u = 0 이고 s = 0 으로 명시적으로 막는다 (임계값이 음수여도 u = 0 에서 활동이 생기지 않게).",
    "frame": "기하는 처리 영상 (S×S) 의 Cartesian 시각 좌표 (vx = x − cx 오른쪽, vy = cy − y 위쪽, 반시계 각도). 로그-극좌표 격자 인덱스 거리를 쓰지 않는다.",
    "periods": "선 방향 θ 는 180° 주기, 이동 방향 φ·위치 극각은 360° 주기로 따로 다룬다.",
    "guide_interp": "V1 L3 휘도 채널을 원영상 점 → 로그-극좌표 역사상 → (반경, 각도) 4 위치 쌍선형 × 180° 주기 방향 2 채널 선형 보간 (기존 GuideSampler 재사용).",
    "scores": "곡선 S = min(r(P,θA), r(Q,θB))·mean_m r(경로점, 접선), 직선 S = min(r(P,θ), r(Q,θ))·mean_m r(직선 경로점, 현 방향), "
              "접합 S = min(r(P,θ1), r(P,θ2)), 선 끝 S = 0.5·max(r_c − r_f, 0) + 0.5·max(r_c − r_b, 0) (기존 V2 endstop 의 앞·뒤 억제 표본 위치).",
    "heuristic": "점수는 공학적 휴리스틱이며 확률이 아니다. V1 방향 반응만으로 실제 곡선·접합·선 끝을 완벽히 구별할 수 있다고 주장하지 않는다.",
}


@dataclass
class DestTable:
    """고정 후보 그래프와 선택 집단 (구조 생성 때 한 번, CPU numpy). 표본별 선택 결과는 여기 저장하지 않는다.
    빈칸 주소는 0 패딩 열 (원천 n_src, 읽기 n_reads) 을 가리키고 마스크로 표시한다 (0 번 뉴런으로 보내지 않는다)."""

    mode: str
    params: dict[str, Any]
    M: int
    n_l2: int
    n_src: int
    n_pos: int
    n_ch: int
    # 목적지 (V4 L2 local 순서)
    dst_role: np.ndarray            # (n,) int8 역할 코드
    dst_group: np.ndarray           # (n,) 선택 집단 번호
    dst_slot: np.ndarray            # (n,) 집단 안 자리 (neuron_id 오름차순)
    dst_valid: np.ndarray           # (n,) 유효 후보 묶음이 하나라도 있다
    dst_role_index: np.ndarray      # (n,) 역할 배열 안 순번
    perm_inv: np.ndarray            # (n,) 역할 연결 순서 → L2 순서
    # 선택 집단
    group_pos: np.ndarray           # (G,)
    group_role: np.ndarray          # (G,) int8
    group_members: np.ndarray       # (G, Gm) V4 L2 local (빈칸 n)
    group_size: np.ndarray          # (G,)
    group_has_candidate: np.ndarray  # (G,)
    # 안내 읽기 표 (원영상 점·선 방향, 중복 제거)
    read_x_px: np.ndarray
    read_y_px: np.ndarray
    read_ori: np.ndarray
    read_valid: np.ndarray
    gA_idx: np.ndarray              # (R, 8) V1 L3 주소 (빈칸 n_v1)
    gA_w: np.ndarray
    gB_idx: np.ndarray              # (R, 4) V1 위치 주소 (빈칸 n_pos1)
    gB_w: np.ndarray
    # 곡선
    c_rows: np.ndarray
    c_P: np.ndarray
    c_theta_a: np.ndarray
    c_theta_b: np.ndarray
    c_sign: np.ndarray
    c_kappa: np.ndarray
    c_D: np.ndarray                 # (nc,) 국소 간격 D(P) (기록·진단용)
    c_srcA: np.ndarray
    c_readA: np.ndarray             # (nc,)
    c_cand_q: np.ndarray            # (nc, K) 유효 후보 위치 (빈칸 −1), 원천 주소 오름차순
    c_cand_src: np.ndarray          # (nc, K) (빈칸 n_src)
    c_cand_valid: np.ndarray        # (nc, K)
    c_readB: np.ndarray             # (nc, K) (빈칸 n_reads)
    c_path_reads: np.ndarray        # (nc, K, M) (빈칸 n_reads)
    c_path_xy: np.ndarray           # (nc, K, M, 2) 처리 영상 화소
    c_n_cand: np.ndarray
    # 곡선 RF 후보 전체 (무효 포함, 기록용)
    ce_row: np.ndarray              # (E_c,) 곡선 배열 순번
    ce_q: np.ndarray
    ce_src: np.ndarray
    ce_reason: np.ndarray           # int8 (DEST_CURVE_REASONS)
    ce_dist_px: np.ndarray
    ce_chord_dev_deg: np.ndarray    # 현 방향과 φC 의 차
    ce_wedge_ok: np.ndarray         # (진단) 현 방향이 φA 와 φB 사이 (양 끝 볼록 조건) 였다면 남는가
    ce_v2_reason: np.ndarray        # (진단) v2 규칙 (V2_FILTER_REASONS)
    ce_wrong_turn_frac: np.ndarray  # (진단) 경로의 반대 방향 회전 / 전체 회전
    # 직선
    s_rows: np.ndarray
    s_P: np.ndarray
    s_Q: np.ndarray
    s_theta: np.ndarray
    s_srcA: np.ndarray
    s_srcB: np.ndarray
    s_readA: np.ndarray
    s_readB: np.ndarray
    s_path_reads: np.ndarray        # (ns, M)
    s_kind: np.ndarray              # 0 앞쪽 변위, 1 뒤쪽 변위, 2 같은 위치 대체 (기존 규칙)
    s_chord_dev_deg: np.ndarray
    s_valid: np.ndarray
    # 접합
    j_rows: np.ndarray
    j_P: np.ndarray
    j_src: np.ndarray
    j_theta1: np.ndarray
    j_theta2: np.ndarray
    j_read1: np.ndarray
    j_read2: np.ndarray
    j_valid: np.ndarray
    # 선 끝
    l_rows: np.ndarray
    l_P: np.ndarray
    l_theta: np.ndarray
    l_src_f: np.ndarray
    l_src_b: np.ndarray
    l_read_c: np.ndarray            # (nl, C) 자식 V2 위치 (중심)
    l_read_f: np.ndarray            # (nl, C) 기존 V2 endstop 전방 억제 표본 위치
    l_read_b: np.ndarray            # (nl, C) 후방
    l_mask_c: np.ndarray
    l_mask_f: np.ndarray
    l_mask_b: np.ndarray
    l_pos2_c: np.ndarray            # (nl, C) V2 위치 번호 (−1 빈칸)
    l_pos2_f: np.ndarray
    l_pos2_b: np.ndarray
    l_valid: np.ndarray
    # 고정 후보 그래프 (edge 목록)
    e_src: np.ndarray
    e_dst: np.ndarray
    e_slot: np.ndarray              # 0 = A, 1 = B
    e_role: np.ndarray
    e_src_xy: np.ndarray            # (E, 2) 처리 영상 화소
    e_dst_xy: np.ndarray
    e_src_ori: np.ndarray           # 원천 채널 방향 (교차 채널은 θ1)
    e_src_ori2: np.ndarray          # 교차 채널의 θ2 (그 밖 NaN)
    e_req_ori: np.ndarray           # 역할이 요구하는 방향
    e_base_w: np.ndarray            # 기존 결합 가중치 (선 끝 0.5, 그 밖 1)
    e_valid: np.ndarray
    e_bundle: np.ndarray            # 곡선 B: 유효 후보 칸 k (무효 −1), 그 밖 −1
    removed: dict[str, Any]         # 조건별 제거 수 (전체·고리별)
    n_v1: int
    n_pos1: int
    v1_n_ch: int
    lum_base: int
    n_o: int

    def hash(self) -> str:
        return sha256_text(dumps({"mode": self.mode, "params": self.params, "M": self.M}, indent=None) + sha256_array(
            self.dst_role, self.dst_group, self.dst_slot, self.dst_valid, self.group_members, self.read_ori, self.read_valid,
            self.gA_idx, self.gA_w, self.gB_idx, self.gB_w, self.c_rows, self.c_srcA, self.c_readA, self.c_cand_src, self.c_cand_valid,
            self.c_readB, self.c_path_reads, self.s_rows, self.s_srcA, self.s_srcB, self.s_readA, self.s_readB, self.s_path_reads,
            self.j_rows, self.j_src, self.j_read1, self.j_read2, self.l_rows, self.l_src_f, self.l_src_b, self.l_read_c, self.l_read_f,
            self.l_read_b, self.l_mask_c, self.l_mask_f, self.l_mask_b))

    def graph_hash(self) -> str:
        """고정 후보 그래프 (edge 목록) 의 해시 — 원천·목적지·슬롯·역할·좌표·방향·기본 가중치·유효 표시."""
        return sha256_array(self.e_src, self.e_dst, self.e_slot, self.e_role, self.e_src_xy, self.e_dst_xy, self.e_src_ori,
                            np.nan_to_num(self.e_src_ori2, nan=-999.0), self.e_req_ori, self.e_base_w, self.e_valid, self.e_bundle)

    def role_meta_hash(self) -> str:
        return sha256_array(self.dst_role, self.c_theta_a, self.c_theta_b, self.c_sign, self.c_kappa, self.s_theta, self.j_theta1,
                            self.j_theta2, self.l_theta)

    def coord_hash(self) -> str:
        return sha256_array(self.read_x_px, self.read_y_px, self.read_ori, self.e_src_xy, self.e_dst_xy, self.c_path_xy)

    def path_settings(self) -> dict[str, Any]:
        return {"path_points": self.M, "curve": "cubic Hermite p(0)=P, p(1)=Q, 접선 크기 ‖Q−P‖, 끝 접선 φA·φB (curve_directions)",
                "straight": "P→Q 직선, t_m = m/(M−1), 접선 = 현 방향 (Q = P 이면 θ)", "orientation_period_deg": 180.0,
                "polar_angle_period_deg": 360.0, "coordinates": "처리 영상 화소 Cartesian (시각 좌표로 계산)"}

    def arrays(self) -> dict[str, np.ndarray]:
        return {f_.name: getattr(self, f_.name) for f_ in dataclasses.fields(self) if isinstance(getattr(self, f_.name), np.ndarray)}

    @property
    def n_groups(self) -> int:
        return int(len(self.group_pos))

    def candidate_fan_in(self) -> np.ndarray:
        """목적지별 유효 후보 edge 수 (곡선 = A 1 + 유효 B 후보 수)."""
        return np.bincount(self.e_dst[self.e_valid], minlength=self.n_l2)

    def candidate_fan_out(self) -> np.ndarray:
        return np.bincount(self.e_src[self.e_valid], minlength=self.n_src)

    def static_summary(self, l4: LayerSpec) -> dict[str, Any]:
        roles = {}
        fi = self.candidate_fan_in()
        fo = self.candidate_fan_out()
        for r, code in DEST_ROLE_CODE.items():
            sel = self.dst_role == code
            g = self.group_role == code
            roles[r] = {"n_destinations": int(sel.sum()), "n_valid_destinations": int((sel & self.dst_valid).sum()),
                        "n_groups": int(g.sum()), "groups_without_candidate": int((g & ~self.group_has_candidate).sum()),
                        "destinations_per_group": int(self.group_size[g].max()) if g.any() else 0,
                        "candidate_fan_in": {"min": int(fi[sel].min()) if sel.any() else 0, "mean": float(fi[sel].mean()) if sel.any() else None,
                                             "max": int(fi[sel].max()) if sel.any() else 0}}
        n = self.c_n_cand
        q = np.percentile(n, [0, 25, 50, 75, 100]).tolist() if n.size else []
        ring = l4.ring[self.c_P * l4.n_ch] if n.size else np.zeros(0)
        by_ring = {int(k): {"n_curve": int((ring == k).sum()), "no_candidate": int(((ring == k) & (n == 0)).sum()),
                            "candidates_mean": float(n[ring == k].mean())} for k in np.unique(ring)}
        used_src = fo > 0
        return {"mode": self.mode, "params": self.params, "n_destinations": self.n_l2, "n_groups": self.n_groups,
                "groups_without_candidate": int((~self.group_has_candidate).sum()), "roles": roles,
                "curve_candidates_per_neuron": {"min": int(n.min()) if n.size else 0, "p25": q[1] if q else None, "median": q[2] if q else None,
                                                "p75": q[3] if q else None, "max": int(n.max()) if n.size else 0,
                                                "mean": float(n.mean()) if n.size else None},
                "curve_neurons_without_candidate": int((n == 0).sum()), "curve_by_ring": by_ring,
                "curve_removed_by_condition": self.removed["curve_total"], "curve_removed_by_ring": self.removed["curve_by_ring"],
                "curve_conditions_ko": DEST_CURVE_REASONS_KO, "curve_rf_candidates": int(len(self.ce_reason)),
                "curve_valid_candidates": int((self.ce_reason == 0).sum()),
                "diagnostic_alternative_rules_not_applied": {
                    "both_end_convexity_wedge_would_keep": int(((self.ce_reason == 0) & self.ce_wedge_ok).sum()),
                    "v2_strict_rule_would_keep": int(((self.ce_reason == 0) & (self.ce_v2_reason == 0)).sum()),
                    "note_ko": "진단값이다. 양 끝 볼록 조건 (현 방향이 φA 와 φB 사이) 과 v2 규칙 (거리·현 ±45°·Hermite 곡률 부호) 은 후보 탈락에 쓰지 않았다."},
                "curve_valid_wrong_turn_frac": {"mean": float(self.ce_wrong_turn_frac[self.ce_reason == 0].mean()) if (self.ce_reason == 0).any() else None,
                                                "max": float(self.ce_wrong_turn_frac[self.ce_reason == 0].max()) if (self.ce_reason == 0).any() else None},
                "straight_kind_counts": {"forward": int((self.s_kind == 0).sum()), "backward": int((self.s_kind == 1).sum()),
                                         "same_position_fallback": int((self.s_kind == 2).sum())},
                "straight_chord_dev_deg": {"mean": float(self.s_chord_dev_deg.mean()) if self.s_chord_dev_deg.size else None,
                                           "max": float(self.s_chord_dev_deg.max()) if self.s_chord_dev_deg.size else None},
                "lineend_missing_samples": {"forward_child_missing": int((~self.l_mask_f & self.l_mask_c).sum()),
                                            "backward_child_missing": int((~self.l_mask_b & self.l_mask_c).sum()),
                                            "neurons_without_forward_sample": int((self.l_mask_f.sum(1) == 0).sum()),
                                            "neurons_without_backward_sample": int((self.l_mask_b.sum(1) == 0).sum())},
                "n_reads": int(len(self.read_ori)), "n_reads_invalid": int((~self.read_valid).sum()),
                "candidate_graph": {"n_edges": int(len(self.e_src)), "n_valid_edges": int(self.e_valid.sum()),
                                    "duplicate_src_dst_slot": int(len(self.e_src) - len(np.unique(
                                        self.e_src.astype(np.int64) * (self.n_l2 * 2) + self.e_dst.astype(np.int64) * 2 + self.e_slot))),
                                    "candidate_fan_out_per_source": {"n_sources_with_edges": int(used_src.sum()), "of": int(self.n_src),
                                                                     "mean_over_used": float(fo[used_src].mean()) if used_src.any() else None,
                                                                     "max": int(fo.max()) if fo.size else 0}},
                "table_sha256": self.hash(), "candidate_graph_sha256": self.graph_hash(), "role_meta_sha256": self.role_meta_hash(),
                "coordinate_sha256": self.coord_hash(), "path_settings": self.path_settings(), "conventions": DEST_CONVENTION_KO,
                "extra_gather_elements_per_sample": int(len(self.read_ori) * 12 + self.c_path_reads.size + self.c_readB.size + self.s_path_reads.size),
                "note_ko": "후보 그래프는 고정이다. 이미지마다 바뀌는 것은 집단별 선택 (어느 목적지·어느 Q) 뿐이며 별도로 기록한다."}


def build_dest_table(cfg: dict[str, Any], pre: "RetinaLGNPreprocessor", l4: LayerSpec, l2_rf: np.ndarray, n_ch2: int,
                     chans: list[tuple[str, int, int]], curve_info: list[tuple[int, int, int, int, float]], contour: dict[int, int],
                     endf: dict[int, int], endb: dict[int, int], D: np.ndarray, v1_l3: LayerSpec, v2_l2: LayerSpec,
                     children: list[list[int]], straight_q: dict[tuple[int, int], tuple[int, int]], mode: str) -> DestTable:
    """기존 역할 연결에서 고정 후보 그래프를 만든다. 곡선 B 만 수용장 안 θB contour 위치로 확대하고 (조건별 제거 수 기록),
    직선·접합·선 끝은 기존 원천 연결을 그대로 후보로 쓴다 (목적지 선택 마스크만 더한다)."""
    dc, rc = cfg["destination"], cfg["routing"]
    oris = [float(t) for t in cfg["areas"]["V1"]["orientations_deg"]]
    M = int(dc["path_points"])
    gs = GuideSampler(v1_l3, pre, cfg)
    px, py = l4.pos_x.astype(np.float64), l4.pos_y.astype(np.float64)
    vx, vy = px - pre.cx, pre.cy - py
    n_pos, n_in = l4.n_pos, l4.n_ch
    n_l2 = n_pos * n_ch2
    fam = [f for (f, _i, _j) in chans]
    missing_roles = [r for r in DEST_ROLES if r not in fam]
    if missing_roles:
        raise StructureError(f"{DEST_MODE} 는 V4 L2 역할 네 가지가 모두 있어야 한다 (없음: {missing_roles}).")
    meta4 = l4.channel_meta
    cinfo = {ch: (i, j, s, kap) for (ch, i, j, s, kap) in curve_info}
    ring4 = l4.ring[::n_in].astype(np.int64)
    # ---------------------------------------------------------------- 안내 읽기 (중복 제거)
    reads: dict[tuple[float, float, float], int] = {}
    rvx: list[float] = []
    rvy: list[float] = []
    rori: list[float] = []

    def add_read(x_: float, y_: float, o_: float) -> int:
        o_ = float(o_) % 180.0
        key = (round(float(x_), 9), round(float(y_), 9), round(o_, 9))
        k = reads.get(key)
        if k is None:
            k = reads[key] = len(rvx)
            rvx.append(float(x_))
            rvy.append(float(y_))
            rori.append(o_)
        return k

    # V2 endstop 의 실제 억제 표본 위치 (V2 L2 CSR 에서 읽는다 — 생성 규칙 그대로)
    n2ch = v2_l2.n_ch
    v2x, v2y = v2_l2.pos_x.astype(np.float64) - pre.cx, pre.cy - v2_l2.pos_y.astype(np.float64)
    n_o2 = v2_l2.n_src // v2_l2.n_pos

    def endstop_sample(c: int, ch: int) -> tuple[int, int | None]:
        row = c * n2ch + ch
        a0, a1 = int(v2_l2.a_ptr[row]), int(v2_l2.a_ptr[row + 1])
        src, w = v2_l2.a_src[a0:a1], v2_l2.a_w[a0:a1]
        centre = [int(s_) // n_o2 for s_, w_ in zip(src, w) if w_ > 0]
        inh = [int(s_) // n_o2 for s_, w_ in zip(src, w) if w_ < 0]
        if centre != [c]:
            raise StructureError(f"V2 endstop 중심 표본이 위치 {c} 가 아니다 ({centre}).")
        return c, (inh[0] if inh else None)

    # ---------------------------------------------------------------- 목적지·집단
    dst_role = np.zeros(n_l2, np.int8)
    for row in range(n_l2):
        dst_role[row] = DEST_ROLE_CODE[fam[row % n_ch2]]
    groups, g_pos, g_role = [], [], []
    for P in range(n_pos):
        for r in DEST_ROLES:
            mem = [P * n_ch2 + ch for ch in range(n_ch2) if fam[ch] == r]
            groups.append(mem)
            g_pos.append(P)
            g_role.append(DEST_ROLE_CODE[r])
    G = len(groups)
    Gm = max(len(m_) for m_ in groups)
    group_members = np.full((G, Gm), n_l2, np.int64)
    dst_group = np.zeros(n_l2, np.int64)
    dst_slot = np.zeros(n_l2, np.int64)
    for g, mem in enumerate(groups):
        group_members[g, :len(mem)] = mem
        for k_, row in enumerate(mem):
            dst_group[row], dst_slot[row] = g, k_
    # ---------------------------------------------------------------- 곡선
    rem_total = {k: 0 for k in ("same_position", "outside_rf", *[DEST_CURVE_REASONS[c] for c in range(1, 6)])}
    rem_ring: dict[int, dict[str, int]] = {int(k): {kk: 0 for kk in rem_total} for k in np.unique(ring4)}
    dmin_f, dmax_f, dev = float(rc["dist_min_factor"]), float(rc["dist_max_factor"]), float(rc["max_chord_dev_deg"])
    tol = float(rc["curvature_turn_tol_deg"])
    c_rows, c_P, c_ta, c_tb, c_sg, c_kp, c_srcA, c_readA, c_lists = [], [], [], [], [], [], [], [], []
    ce_row, ce_q, ce_src, ce_reason, ce_dist, ce_cdev, ce_wedge, ce_v2, ce_wt = [], [], [], [], [], [], [], [], []
    for P in range(n_pos):
        Rj = float(l2_rf[P])
        for ch in range(n_ch2):
            if fam[ch] != "curve":
                continue
            i, j, s, kap = cinfo[ch]
            phi_a, phi_b, phi_c = curve_directions(oris[i], s, kap)
            ci = len(c_rows)
            c_rows.append(P * n_ch2 + ch)
            c_P.append(P)
            c_ta.append(oris[i])
            c_tb.append(oris[j])
            c_sg.append(s)
            c_kp.append(kap)
            c_srcA.append(P * n_in + contour[i])
            c_readA.append(add_read(vx[P], vy[P], oris[i]))
            ta = np.asarray([math.cos(math.radians(phi_a)), math.sin(math.radians(phi_a))])
            items = []
            for Q in range(n_pos):
                if Q == P:
                    rem_total["same_position"] += 1
                    rem_ring[int(ring4[P])]["same_position"] += 1
                    continue
                d = float(math.hypot(px[Q] - px[P], py[Q] - py[P]))
                if d > Rj:
                    rem_total["outside_rf"] += 1
                    rem_ring[int(ring4[P])]["outside_rf"] += 1
                    continue
                Pv, Qv = np.asarray([vx[P], vy[P]]), np.asarray([vx[Q], vy[Q]])
                chord = Qv - Pv
                L = float(np.hypot(*chord))
                if L <= 1e-12:
                    raise StructureError(f"V4 위치 {P} 와 {Q} 가 같은 좌표다 (곡선 후보 현 길이 0).")
                cang = math.degrees(math.atan2(chord[1], chord[0]))
                cdev = float(d_dir(cang, phi_c))
                wedge = bool(0.0 < s * float(wrap180(cang - phi_a)) < kap)
                p_, dp_ = hermite_path(Pv, Qv, phi_a, phi_b, M)
                psi = np.degrees(np.arctan2(dp_[:, 1], dp_[:, 0]))
                dpsi = wrap180(np.diff(psi))
                tot_abs = float(np.abs(dpsi).sum())
                wt = float(np.maximum(-s * dpsi, 0.0).sum() / tot_abs) if tot_abs > 0 else 0.0
                if not (dmin_f * float(D[P]) <= d <= dmax_f * float(D[P])):
                    v2r = 6
                elif cdev > dev:
                    v2r = 7
                else:
                    v2r, _tot = path_check(p_, dp_, Pv, Qv, phi_a, phi_b, s, tol, float(l4.pos_rf[P]), float(l4.pos_rf[Q]))
                if float(chord @ ta) <= 0.0:
                    reason = 1
                elif s * float(ta[0] * chord[1] - ta[1] * chord[0]) <= 0.0:
                    reason = 2
                elif (np.hypot(p_[:, 0], p_[:, 1]) > pre.rmax).any():
                    reason = 3
                elif (np.hypot(dp_[:, 0], dp_[:, 1]) < 1e-9 * L).any():
                    reason = 4
                elif ((dp_ @ chord) <= 0.0).any() or tot_abs > 180.0:
                    reason = 5
                else:
                    reason = 0
                if reason:
                    nm = DEST_CURVE_REASONS[reason]
                    rem_total[nm] += 1
                    rem_ring[int(ring4[P])][nm] += 1
                src = Q * n_in + contour[j]
                ce_row.append(ci)
                ce_q.append(Q)
                ce_src.append(src)
                ce_reason.append(reason)
                ce_dist.append(d)
                ce_cdev.append(cdev)
                ce_wedge.append(wedge)
                ce_v2.append(v2r)
                ce_wt.append(wt)
                if reason == 0:
                    ori_m = np.mod(np.degrees(np.arctan2(dp_[:, 1], dp_[:, 0])), 180.0)
                    ori_m[0], ori_m[-1] = oris[i] % 180.0, oris[j] % 180.0      # 끝 접선 = φA, φB (수식상 같은 값, 반올림 차이 제거)
                    preads = [add_read(p_[m_, 0], p_[m_, 1], ori_m[m_]) for m_ in range(M)]
                    items.append((src, Q, add_read(vx[Q], vy[Q], oris[j]), preads,
                                  np.stack([p_[:, 0] + pre.cx, pre.cy - p_[:, 1]], 1)))
            items.sort(key=lambda it: it[0])                                # 원천 neuron_id 오름차순 (동점 해소 순서)
            c_lists.append(items)
    nc = len(c_rows)
    K = max([len(it) for it in c_lists] + [1])
    n_src = l4.n
    c_cand_q = np.full((nc, K), -1, np.int64)
    c_cand_src = np.full((nc, K), n_src, np.int64)
    c_cand_valid = np.zeros((nc, K), bool)
    c_readB = np.full((nc, K), -1, np.int64)
    c_path_reads = np.full((nc, K, M), -1, np.int64)
    c_path_xy = np.full((nc, K, M, 2), np.nan, np.float32)
    for c, items in enumerate(c_lists):
        for k, (src, Q, rb, preads, pxy) in enumerate(items):
            c_cand_q[c, k], c_cand_src[c, k], c_cand_valid[c, k], c_readB[c, k] = Q, src, True, rb
            c_path_reads[c, k] = preads
            c_path_xy[c, k] = pxy
    c_n_cand = c_cand_valid.sum(1).astype(np.int64)
    # ---------------------------------------------------------------- 직선 (기존 P/Q 연결)
    s_rows, s_P, s_Q, s_th, s_srcA, s_srcB, s_readA, s_readB, s_path, s_kind, s_cdev = [], [], [], [], [], [], [], [], [], [], []
    for P in range(n_pos):
        for ch in range(n_ch2):
            if fam[ch] != "straight":
                continue
            i = chans[ch][1]
            Q, kind = straight_q[(P, ch)]
            s_rows.append(P * n_ch2 + ch)
            s_P.append(P)
            s_Q.append(Q)
            s_th.append(oris[i])
            s_srcA.append(P * n_in + contour[i])
            s_srcB.append(Q * n_in + contour[i])
            s_readA.append(add_read(vx[P], vy[P], oris[i]))
            s_readB.append(add_read(vx[Q], vy[Q], oris[i]))
            if Q != P:
                cang = math.degrees(math.atan2(vy[Q] - vy[P], vx[Q] - vx[P])) % 180.0
                t_ = np.linspace(0.0, 1.0, M)
                s_path.append([add_read(vx[P] + tt * (vx[Q] - vx[P]), vy[P] + tt * (vy[Q] - vy[P]), cang) for tt in t_])
                s_cdev.append(float(d_ori(cang, oris[i])))
            else:
                s_path.append([add_read(vx[P], vy[P], oris[i])] * M)
                s_cdev.append(0.0)
            s_kind.append(kind)
    # ---------------------------------------------------------------- 접합 (기존 cross 입력)
    j_rows, j_P, j_src, j_t1, j_t2, j_r1, j_r2 = [], [], [], [], [], [], []
    for P in range(n_pos):
        for ch in range(n_ch2):
            if fam[ch] != "junction":
                continue
            k = chans[ch][1]
            t1, t2 = float(meta4["orientation_deg"][k]), float(meta4["orientation2_deg"][k])
            j_rows.append(P * n_ch2 + ch)
            j_P.append(P)
            j_src.append(P * n_in + k)
            j_t1.append(t1)
            j_t2.append(t2)
            j_r1.append(add_read(vx[P], vy[P], t1))
            j_r2.append(add_read(vx[P], vy[P], t2))
    # ---------------------------------------------------------------- 선 끝 (기존 endstop 의 중심·앞·뒤 표본 위치)
    C = max(len(c_) for c_ in children)
    l_rows, l_P, l_th, l_sf, l_sb = [], [], [], [], []
    lc, lf, lb, pc_, pf_, pb_ = [], [], [], [], [], []
    for P in range(n_pos):
        for ch in range(n_ch2):
            if fam[ch] != "lineend":
                continue
            i = chans[ch][1]
            l_rows.append(P * n_ch2 + ch)
            l_P.append(P)
            l_th.append(oris[i])
            l_sf.append(P * n_in + endf[i])
            l_sb.append(P * n_in + endb[i])
            rc_, rf_, rb_ = [-1] * C, [-1] * C, [-1] * C
            qc_, qf_, qb_ = [-1] * C, [-1] * C, [-1] * C
            for k_, c in enumerate(children[P]):
                _c, fpos = endstop_sample(c, endf[i])
                _c, bpos = endstop_sample(c, endb[i])
                rc_[k_], qc_[k_] = add_read(v2x[c], v2y[c], oris[i]), c
                if fpos is not None:
                    rf_[k_], qf_[k_] = add_read(v2x[fpos], v2y[fpos], oris[i]), fpos
                if bpos is not None:
                    rb_[k_], qb_[k_] = add_read(v2x[bpos], v2y[bpos], oris[i]), bpos
            lc.append(rc_)
            lf.append(rf_)
            lb.append(rb_)
            pc_.append(qc_)
            pf_.append(qf_)
            pb_.append(qb_)
    l_read_c, l_read_f, l_read_b = (np.asarray(a_, np.int64) for a_ in (lc, lf, lb))
    l_mask_c, l_mask_f, l_mask_b = l_read_c >= 0, l_read_f >= 0, l_read_b >= 0
    # ---------------------------------------------------------------- 읽기 표 (GuideSampler 재사용)
    R = len(rvx)
    ia, wa, ib, wb, val = gs.table(np.asarray(rvx), np.asarray(rvy), np.asarray(rori))

    def fill(a_: np.ndarray) -> np.ndarray:
        a_ = np.asarray(a_, np.int64)
        return np.where(a_ < 0, R, a_)

    c_readB, c_path_reads = fill(c_readB), fill(c_path_reads)
    l_read_c, l_read_f, l_read_b = fill(l_read_c), fill(l_read_f), fill(l_read_b)
    s_path_reads = fill(np.asarray(s_path, np.int64).reshape(len(s_rows), M))
    readv = np.concatenate([val, [False]])
    # 유효 목적지: 필요한 읽기 지점이 모두 영상 안 (곡선은 경로 검사 3 과 같은 기준이라 여기서 더 빠지는 후보가 없어야 한다)
    before = c_cand_valid.copy()
    c_cand_valid &= readv[c_readB] & readv[c_path_reads].all(-1)
    if (before & ~c_cand_valid).any():
        raise StructureError("곡선 후보의 경로 검사 (영상 안) 와 안내 보간 유효성이 다르다 (좌표 변환 불일치).")
    c_n_cand = c_cand_valid.sum(1).astype(np.int64)
    s_valid = readv[np.asarray(s_readA, np.int64)] & readv[np.asarray(s_readB, np.int64)] & readv[s_path_reads].all(-1)
    j_valid = readv[np.asarray(j_r1, np.int64)] & readv[np.asarray(j_r2, np.int64)]
    l_mask_c &= readv[l_read_c]
    l_mask_f &= readv[l_read_f]
    l_mask_b &= readv[l_read_b]
    l_valid = l_mask_c.any(1)
    dst_valid = np.zeros(n_l2, bool)
    dst_role_index = np.zeros(n_l2, np.int64)
    for rows_, v_ in ((c_rows, c_n_cand > 0), (s_rows, s_valid), (j_rows, j_valid), (l_rows, l_valid)):
        rows_ = np.asarray(rows_, np.int64)
        dst_valid[rows_] = v_
        dst_role_index[rows_] = np.arange(len(rows_))
    perm = np.concatenate([np.asarray(x_, np.int64) for x_ in (c_rows, s_rows, j_rows, l_rows)])
    if not np.array_equal(np.sort(perm), np.arange(n_l2)):
        raise StructureError("목적지 역할 배열이 V4 L2 뉴런을 정확히 한 번씩 덮지 않는다.")
    perm_inv = np.argsort(perm).astype(np.int64)
    g_has = np.asarray([bool(dst_valid[np.asarray(m_, np.int64)].any()) for m_ in groups], bool)
    # ---------------------------------------------------------------- 고정 후보 그래프 (edge 목록)
    E: list[tuple] = []
    pos4x, pos4y = l4.pos_x.astype(np.float64), l4.pos_y.astype(np.float64)
    o4 = [float(v) if v is not None else np.nan for v in meta4["orientation_deg"]]
    o4b = [float(v) if v is not None else np.nan for v in meta4.get("orientation2_deg", [None] * n_in)]

    def edge(src: int, dst: int, slot: int, role: str, req: float, w: float, valid: bool, bundle: int) -> None:
        Psrc = src // n_in
        Pdst = dst // n_ch2
        E.append((src, dst, slot, DEST_ROLE_CODE[role], pos4x[Psrc], pos4y[Psrc], pos4x[Pdst], pos4y[Pdst], o4[src % n_in],
                  o4b[src % n_in], req, w, valid, bundle))

    ce_row_a = np.asarray(ce_row, np.int64)
    ce_reason_a = np.asarray(ce_reason, np.int8)
    for c in range(nc):
        edge(c_srcA[c], c_rows[c], 0, "curve", c_ta[c], 1.0, bool(c_n_cand[c] > 0), -1)
        srcs = {int(sv): k for k, sv in enumerate(c_cand_src[c]) if c_cand_valid[c, k]}
        for e_ in np.nonzero(ce_row_a == c)[0]:
            src = int(ce_src[e_])
            k = srcs.get(src, -1)
            edge(src, c_rows[c], 1, "curve", c_tb[c], 1.0, k >= 0, k)
    for k in range(len(s_rows)):
        edge(s_srcA[k], s_rows[k], 0, "straight", s_th[k], 1.0, bool(s_valid[k]), -1)
        edge(s_srcB[k], s_rows[k], 1, "straight", s_th[k], 1.0, bool(s_valid[k]), -1)
    for k in range(len(j_rows)):
        edge(j_src[k], j_rows[k], 0, "junction", j_t1[k], 1.0, bool(j_valid[k]), -1)
    for k in range(len(l_rows)):
        edge(l_sf[k], l_rows[k], 0, "lineend", l_th[k], 0.5, bool(l_valid[k]), -1)
        edge(l_sb[k], l_rows[k], 0, "lineend", l_th[k], 0.5, bool(l_valid[k]), -1)
    Ea = list(zip(*E))
    e_src, e_dst = np.asarray(Ea[0], np.int64), np.asarray(Ea[1], np.int64)
    e_slot = np.asarray(Ea[2], np.int8)
    keys = e_src * (n_l2 * 2) + e_dst * 2 + e_slot
    if len(np.unique(keys)) != len(keys):
        raise StructureError("후보 그래프에 같은 (원천, 목적지, 슬롯) edge 가 두 번 있다.")
    params = {k: dc[k] for k in dc if k not in DEST_RECORD_ONLY_KEYS}
    params.update(curve_candidate_rule="in_rf_contour_thetaB_not_P_forward_bendside_hermite_valid",
                  straight_rule="existing_P_Q", junction_rule="existing_cross_input", lineend_rule="existing_endstop_fwd_bwd_samples",
                  v2_diag_rule={k: rc[k] for k in ("dist_min_factor", "dist_max_factor", "max_chord_dev_deg", "curvature_turn_tol_deg")})
    removed = {"curve_total": rem_total, "curve_by_ring": rem_ring}
    return DestTable(
        mode=mode, params=params, M=M, n_l2=n_l2, n_src=n_src, n_pos=n_pos, n_ch=n_ch2,
        dst_role=dst_role, dst_group=dst_group, dst_slot=dst_slot, dst_valid=dst_valid, dst_role_index=dst_role_index, perm_inv=perm_inv,
        group_pos=np.asarray(g_pos, np.int64), group_role=np.asarray(g_role, np.int8), group_members=group_members,
        group_size=np.asarray([len(m_) for m_ in groups], np.int64), group_has_candidate=g_has,
        read_x_px=(np.asarray(rvx) + pre.cx).astype(np.float32), read_y_px=(pre.cy - np.asarray(rvy)).astype(np.float32),
        read_ori=np.asarray(rori, np.float32), read_valid=np.asarray(val, bool), gA_idx=ia, gA_w=wa, gB_idx=ib, gB_w=wb,
        c_rows=np.asarray(c_rows, np.int64), c_P=np.asarray(c_P, np.int64), c_theta_a=np.asarray(c_ta, np.float32),
        c_theta_b=np.asarray(c_tb, np.float32), c_sign=np.asarray(c_sg, np.int8), c_kappa=np.asarray(c_kp, np.float32),
        c_D=np.asarray([float(D[p_]) for p_ in c_P], np.float32),
        c_srcA=np.asarray(c_srcA, np.int64), c_readA=np.asarray(c_readA, np.int64), c_cand_q=c_cand_q, c_cand_src=c_cand_src,
        c_cand_valid=c_cand_valid, c_readB=c_readB, c_path_reads=c_path_reads, c_path_xy=c_path_xy, c_n_cand=c_n_cand,
        ce_row=ce_row_a, ce_q=np.asarray(ce_q, np.int64), ce_src=np.asarray(ce_src, np.int64), ce_reason=ce_reason_a,
        ce_dist_px=np.asarray(ce_dist, np.float32), ce_chord_dev_deg=np.asarray(ce_cdev, np.float32), ce_wedge_ok=np.asarray(ce_wedge, bool),
        ce_v2_reason=np.asarray(ce_v2, np.int8), ce_wrong_turn_frac=np.asarray(ce_wt, np.float32),
        s_rows=np.asarray(s_rows, np.int64), s_P=np.asarray(s_P, np.int64), s_Q=np.asarray(s_Q, np.int64), s_theta=np.asarray(s_th, np.float32),
        s_srcA=np.asarray(s_srcA, np.int64), s_srcB=np.asarray(s_srcB, np.int64), s_readA=np.asarray(s_readA, np.int64),
        s_readB=np.asarray(s_readB, np.int64), s_path_reads=s_path_reads, s_kind=np.asarray(s_kind, np.int8),
        s_chord_dev_deg=np.asarray(s_cdev, np.float32), s_valid=np.asarray(s_valid, bool),
        j_rows=np.asarray(j_rows, np.int64), j_P=np.asarray(j_P, np.int64), j_src=np.asarray(j_src, np.int64),
        j_theta1=np.asarray(j_t1, np.float32), j_theta2=np.asarray(j_t2, np.float32), j_read1=np.asarray(j_r1, np.int64),
        j_read2=np.asarray(j_r2, np.int64), j_valid=np.asarray(j_valid, bool),
        l_rows=np.asarray(l_rows, np.int64), l_P=np.asarray(l_P, np.int64), l_theta=np.asarray(l_th, np.float32),
        l_src_f=np.asarray(l_sf, np.int64), l_src_b=np.asarray(l_sb, np.int64), l_read_c=l_read_c, l_read_f=l_read_f, l_read_b=l_read_b,
        l_mask_c=l_mask_c, l_mask_f=l_mask_f, l_mask_b=l_mask_b, l_pos2_c=np.asarray(pc_, np.int64), l_pos2_f=np.asarray(pf_, np.int64),
        l_pos2_b=np.asarray(pb_, np.int64), l_valid=l_valid,
        e_src=e_src, e_dst=e_dst, e_slot=e_slot, e_role=np.asarray(Ea[3], np.int8),
        e_src_xy=np.stack([np.asarray(Ea[4]), np.asarray(Ea[5])], 1).astype(np.float32),
        e_dst_xy=np.stack([np.asarray(Ea[6]), np.asarray(Ea[7])], 1).astype(np.float32),
        e_src_ori=np.asarray(Ea[8], np.float32), e_src_ori2=np.asarray(Ea[9], np.float32), e_req_ori=np.asarray(Ea[10], np.float32),
        e_base_w=np.asarray(Ea[11], np.float32), e_valid=np.asarray(Ea[12], bool), e_bundle=np.asarray(Ea[13], np.int64),
        removed=removed, n_v1=gs.n, n_pos1=gs.n_pos, v1_n_ch=gs.n_ch, lum_base=gs.lum_base, n_o=gs.n_o)


class DestRuntime:
    """장치 쪽 목적지 선택 (배치마다: 안내 보간 gather → 역할별 점수 → 집단 masked argmax → 곡선 B gather).
    뉴런별 Python 루프·3×3 객체·dense N×N 행렬을 쓰지 않는다. 입력에 라벨·prototype·오차가 없다 (함수 인자에 없음).
    표본마다 독립 (배치의 다른 이미지를 보지 않음). 점수는 경로 선택에만 쓰며 전달값에 곱하지 않는다."""

    def __init__(self, table: DestTable, be: Backend, cfg: dict[str, Any], n_layer: int):
        dc = cfg["destination"]
        t = self.table = table
        self.be, self.mode = be, table.mode
        self.eps, self.floor = float(dc["guide_epsilon"]), float(dc["evidence_floor"])
        self.T = float(dc["softmax_temperature"])
        self.M = t.M
        self.n, self.G = t.n_l2, t.n_groups
        self.nc, self.K = t.c_cand_src.shape
        self.n_reads = int(len(t.read_ori))
        self.gA_idx, self.gA_w = be.i64(t.gA_idx), be.f32(t.gA_w)
        self.gB_idx, self.gB_w = be.i64(t.gB_idx), be.f32(t.gB_w)
        self.read_valid = be.bool_(t.read_valid)
        self.c_readA = be.i64(t.c_readA)
        self.c_readB = be.i64(t.c_readB)
        self.c_path = be.i64(t.c_path_reads)
        self.c_cand_src = be.i64(t.c_cand_src)
        self.c_cand_valid = be.bool_(t.c_cand_valid)
        self.Kw = be.f32(np.arange(self.K, 0, -1, dtype=np.float32))
        self.s_readA, self.s_readB, self.s_path = be.i64(t.s_readA), be.i64(t.s_readB), be.i64(t.s_path_reads)
        self.s_valid = be.bool_(t.s_valid)
        self.j_read1, self.j_read2, self.j_valid = be.i64(t.j_read1), be.i64(t.j_read2), be.bool_(t.j_valid)
        self.l_read_c, self.l_read_f, self.l_read_b = be.i64(t.l_read_c), be.i64(t.l_read_f), be.i64(t.l_read_b)
        wc = t.l_mask_c / np.maximum(t.l_mask_c.sum(1, keepdims=True), 1)
        wf = t.l_mask_f / np.maximum(t.l_mask_f.sum(1, keepdims=True), 1)
        wb = t.l_mask_b / np.maximum(t.l_mask_b.sum(1, keepdims=True), 1)
        self.l_wc, self.l_wf, self.l_wb = be.f32(wc), be.f32(wf), be.f32(wb)
        self.l_has_f, self.l_has_b = be.bool_(t.l_mask_f.any(1)), be.bool_(t.l_mask_b.any(1))
        self.l_valid = be.bool_(t.l_valid)
        self.perm_inv = be.i64(t.perm_inv)
        self.group_members = be.i64(t.group_members)
        self.member_valid = be.bool_(np.concatenate([t.dst_valid, [False]])[t.group_members])
        Gm = t.group_members.shape[1]
        self.Gm = Gm
        self.Gw = be.f32(np.arange(Gm, 0, -1, dtype=np.float32))
        self.slot_idx = be.i64(np.arange(Gm))
        self.dst_group, self.dst_slot = be.i64(t.dst_group), be.i64(t.dst_slot)
        self.dst_valid = be.bool_(t.dst_valid)
        cmap = np.full(n_layer, self.nc, np.int64)
        cmap[t.c_rows] = np.arange(self.nc)
        self.curve_map = be.i64(cmap)
        self.curve_rows = be.i64(t.c_rows)
        self.n_pos1, self.v1_n_ch, self.lum_base, self.n_o = t.n_pos1, t.v1_n_ch, t.lum_base, t.n_o

    # ---------------------------------------------------------------- 안내 보간
    def read_r(self, guide: Any) -> tuple[Any, dict[str, Any]]:
        """guide (B, n_V1L3) → r (B, R+1) (마지막 열 = 빈칸 0), b(p) 요약 (장치 축약값).
        r = a/(b+ε) (b ≥ evidence_floor 이고 영상 안), 그 밖 0. a 또는 b 가 NaN 이면 r = NaN 그대로 둔다 (정상 점수로 숨기지 않음)."""
        be = self.be
        B = int(guide.shape[0])
        F1e = be.pad_zero_col(guide)
        Fsum = guide.reshape(B, self.n_pos1, self.v1_n_ch)[:, :, self.lum_base:self.lum_base + self.n_o].sum(-1)
        Fsume = be.pad_zero_col(Fsum)
        rows = max(1, be.max_gather // max(1, B * 12))
        parts, n_low, b_sum, n_val, n_nan = [], [], [], [], []
        for a in range(0, self.n_reads, rows):
            sl = slice(a, a + rows)
            av = (be.take_cols(F1e, self.gA_idx[sl]) * self.gA_w[sl]).sum(-1)
            bv = (be.take_cols(Fsume, self.gB_idx[sl]) * self.gB_w[sl]).sum(-1)
            vld = self.read_valid[sl]
            ok = vld & (bv >= self.floor)
            r_ = be.where(ok, av / (bv + self.eps), be.zeros(av.shape))
            nan = be.isnan(av) | be.isnan(bv)
            r_ = be.where(nan, be.zeros(av.shape) + float("nan"), r_)
            parts.append(r_)
            vf = be.as_f32(vld) + be.zeros(bv.shape)
            n_low.append(be.sum_last(be.as_f32(vld & (bv < self.floor))))
            b_sum.append(be.sum_last(be.where(vld & ~nan, bv, be.zeros(bv.shape))))
            n_val.append(be.sum_last(vf))
            n_nan.append(be.sum_last(be.as_f32(nan & vld)))
        r = parts[0] if len(parts) == 1 else be.cat1(parts)
        add = (lambda xs: xs[0] if len(xs) == 1 else sum(xs[1:], xs[0]))
        stat = {"reads_below_floor": add(n_low), "b_sum": add(b_sum), "reads_valid": add(n_val), "reads_nan": add(n_nan)}
        return be.pad_zero_col(r), stat

    # ---------------------------------------------------------------- 역할별 점수
    def scores(self, r: Any, detail: bool = False) -> dict[str, Any]:
        be = self.be
        B = int(r.shape[0])
        neg = -1.0
        # 곡선: S(j,Q) = min(r(P,θA), r(Q,θB)) · mean_m r(경로점 m, 접선 m) → 유효 Q 중 최댓값 (같은 점수는 원천 주소가 작은 쪽)
        rows = max(1, be.max_gather // max(1, B * self.K * (self.M + 2)))
        Sc_l, kq_l, nanq_l, tieq_l, nvq_l, Sq_l = [], [], [], [], [], []
        for a in range(0, self.nc, rows):
            sl = slice(a, a + rows)
            rA = be.take_cols(r, self.c_readA[sl])                         # (B, r)
            rB = be.take_cols(r, self.c_readB[sl])                         # (B, r, K)
            rP = be.take_cols(r, self.c_path[sl]).mean(-1)                 # (B, r, K)
            Sq = be.minimum(rA[..., None] + be.zeros(rB.shape), rB) * rP
            cv = self.c_cand_valid[sl]
            fin = be.isfinite(Sq)
            vq = cv & fin
            Sm = be.where(vq, Sq, be.zeros(Sq.shape) + neg)
            mx = be.max_last(Sm)
            ism = vq & (Sm == mx[..., None])
            kq = be.argmax_last(be.where(ism, self.Kw + be.zeros(Sq.shape), be.zeros(Sq.shape)))
            nvq = be.sum_last(be.as_f32(vq))
            nanq = be.sum_last(be.as_f32(cv & ~fin))
            Sc = be.where(nvq > 0, mx, be.where(nanq > 0, be.zeros(mx.shape) + float("nan"), be.zeros(mx.shape) + neg))
            Sc_l.append(Sc)
            kq_l.append(kq)
            nanq_l.append(nanq)
            nvq_l.append(nvq)
            tieq_l.append(be.sum_last(be.as_f32(ism)) > 1.5)
            if detail:
                Sq_l.append(be.where(cv, Sq, be.zeros(Sq.shape) + neg))
        cat = (lambda xs: xs[0] if len(xs) == 1 else be.cat1(xs))
        Sc, kq, nanq = cat(Sc_l), cat(kq_l), cat(nanq_l)
        # 직선: min(r(P,θ), r(Q,θ)) · mean_m r(직선 경로점, 현 방향)
        Ss = be.minimum(be.take_cols(r, self.s_readA), be.take_cols(r, self.s_readB)) * be.take_cols(r, self.s_path).mean(-1)
        Ss = be.where(self.s_valid, Ss, be.zeros(Ss.shape) + neg)
        # 접합: min(r(P,θ1), r(P,θ2))
        Sj = be.minimum(be.take_cols(r, self.j_read1), be.take_cols(r, self.j_read2))
        Sj = be.where(self.j_valid, Sj, be.zeros(Sj.shape) + neg)
        # 선 끝: 0.5·max(r_c − r_f, 0) + 0.5·max(r_c − r_b, 0) (표본이 없는 쪽 항은 0, 따로 셈)
        rc = (be.take_cols(r, self.l_read_c) * self.l_wc).sum(-1)
        rf = (be.take_cols(r, self.l_read_f) * self.l_wf).sum(-1)
        rb = (be.take_cols(r, self.l_read_b) * self.l_wb).sum(-1)
        zl = be.zeros(rc.shape)
        tf = be.where(self.l_has_f, be.relu(rc - rf), zl)
        tb = be.where(self.l_has_b, be.relu(rc - rb), zl)
        tf = be.where(be.isnan(rc) | be.isnan(rf), zl + float("nan"), tf)
        tb = be.where(be.isnan(rc) | be.isnan(rb), zl + float("nan"), tb)
        Sl = be.where(self.l_valid, 0.5 * tf + 0.5 * tb, zl + neg)
        S_dst = be.take_cols(be.cat1([Sc, Ss, Sj, Sl]), self.perm_inv)
        out = {"S_dst": S_dst, "Sc": Sc, "kq": kq, "nan_q": nanq, "nvalid_q": cat(nvq_l), "tie_q": cat(tieq_l)}
        if detail:
            out.update(Sq=cat(Sq_l), Ss=Ss, Sj=Sj, Sl=Sl, rc=rc, rf=rf, rb=rb)
        return out

    # ---------------------------------------------------------------- 집단 선택 (hard top-1)
    def choose(self, S_dst: Any, mask_mode: str | None = None, detail: bool = False) -> dict[str, Any]:
        """집단 = 위치 × 역할. 양의 유한 점수 중 최고 1 개 (같은 점수는 neuron_id 가 작은 쪽). 없으면 선택 없음.
        mask_mode: None (실제 선택) | "all_legal" (검사 전용: 유효 목적지 전부) | "none" (검사 전용)."""
        be = self.be
        B = int(S_dst.shape[0])
        Se = be.cat1([S_dst, be.zeros((B, 1)) - 1.0])
        Sg = be.take_cols(Se, self.group_members)                             # (B, G, Gm)
        neg = be.zeros(Sg.shape) - 1.0
        fin = be.isfinite(Sg)
        validg = self.member_valid & fin & (Sg >= 0.0)
        posg = validg & (Sg > 0.0)
        mx = be.max_last(be.where(posg, Sg, neg))
        has = mx > 0.0
        ism = posg & (Sg == mx[..., None])
        kg = be.argmax_last(be.where(ism, self.Gw + be.zeros(Sg.shape), be.zeros(Sg.shape)))
        n_tie = be.sum_last(be.as_f32(ism))
        chosen = self.slot_idx == kg[..., None]
        second = be.max_last(be.where(validg & ~chosen, Sg, neg))
        n_valid = be.sum_last(be.as_f32(validg))
        gap = be.where(has & (n_valid > 1.5), mx - second, be.zeros(mx.shape) + float("nan"))
        n_nan = be.sum_last(be.as_f32(self.member_valid & ~fin))
        if mask_mode is None:
            mask = (be.take_cols(kg, self.dst_group) == self.dst_slot) & be.take_cols(has, self.dst_group)
        elif mask_mode == "all_legal":
            mask = self.dst_valid & be.bool_(np.ones((B, self.n), bool))
        elif mask_mode == "none":
            mask = be.bool_(np.zeros((B, self.n), bool))
        else:
            raise ValueError(f"알 수 없는 목적지 마스크: {mask_mode}")
        out = {"mask": mask, "has": has, "kg": kg, "mx": mx, "gap": gap, "tie": has & (n_tie > 1.5), "n_valid_g": n_valid,
               "n_pos_g": be.sum_last(be.as_f32(posg)), "n_nan_g": n_nan, "mask_mode": mask_mode or "selected"}
        if detail:
            z = (Sg - mx[..., None]) / self.T
            w = be.where(validg & has[..., None], be.exp(be.where(validg, z, neg * 0.0)), be.zeros(Sg.shape))
            sw = be.sum_last(w)
            out["display_weight"] = w / be.where(sw > 0, sw, be.ones_like(sw))[..., None]
            out["S_group"] = Sg
        return out

    # ---------------------------------------------------------------- 전체 선택
    def select(self, xe: Any, guide: Any, *, mask_mode: str | None = None, detail: bool = False, timer: PhaseTimer | None = None,
               gsync: bool = False) -> dict[str, Any]:
        """xe: (B, n_src+1) 같은 이미지의 V4 L4 실제 전송 출력 (마지막 열 0), guide: (B, n_V1L3) 같은 순방향의 V1 L3 실제 전송 출력."""
        be = self.be

        def tm(name: str) -> Any:
            return timer.phase(name, gpu=gsync) if timer is not None else contextlib.nullcontext()

        with tm("dest_guide_interp"):
            r, bstat = self.read_r(guide)
        with tm("dest_score"):
            sc = self.scores(r, detail)
        with tm("dest_select"):
            ch = self.choose(sc["S_dst"], mask_mode, detail)
        with tm("dest_deliver"):
            src = be.take_last(self.c_cand_src, sc["kq"])                     # 후보 없음 → n_src (0 열)
            Bv = be.gather_cols(xe, src)
        out = {**sc, **ch, "B_curve": Bv, "curve_src": src, "bstat": bstat, "mode": self.mode}
        if detail:
            out["r"] = r
        return out

    def nbytes(self) -> int:
        t = self.table
        return int(t.gA_idx.size * 12 + t.gB_idx.size * 12 + t.c_path_reads.size * 8 + t.c_cand_src.size * 17 + t.s_path_reads.size * 8
                   + t.group_members.size * 9 + t.n_l2 * 24 + t.l_read_c.size * 36)


def dest_rec_np(be: Backend, d: dict[str, Any]) -> dict[str, Any]:
    """기록용 numpy 사본 (작은 배열만: (B, n), (B, G), (B, nc)). 안내 읽기 배열 (B, R) 은 detail 일 때만."""
    out: dict[str, Any] = {"mode": d.get("mode"), "mask_mode": d.get("mask_mode")}
    for k in ("mask", "has", "tie"):
        out[k] = be.to_np(d[k]).astype(bool)
    for k in ("kg", "kq"):
        out[k] = be.to_np(d[k]).astype(np.int64)
    for k in ("S_dst", "Sc", "mx", "gap", "n_valid_g", "n_pos_g", "n_nan_g", "nan_q", "B_curve", "A", "B", "u_all", "u", "s", "out", "out3",
              "display_weight", "Sq", "Ss", "Sj", "Sl", "rc", "rf", "rb"):
        if d.get(k) is not None:
            out[k] = be.to_np(d[k]).astype(np.float64)
    out["curve_src"] = be.to_np(d["curve_src"]).astype(np.int64)
    out["bstat"] = {k: be.to_np(v).astype(np.float64) for k, v in d["bstat"].items()}
    if d.get("r") is not None:
        out["r"] = be.to_np(d["r"]).astype(np.float32)
    return out


DEST_ACT_EDGES = (1e-4, 1e-3, 1e-2, 1e-1, 1.0)
DEST_SCORE_EDGES = (0.0, 0.01, 0.02, 0.05, 0.1, 0.2, 0.5, 1.0)


def dest_batch_stats(t: DestTable, rec: dict[str, Any], high: float) -> tuple[dict[str, float], dict[str, np.ndarray]]:
    """한 배치의 선택 기록 → (합계 float, 뉴런·집단·원천별 개수 배열). 비율은 에폭 끝에 dest_finalize 로."""
    mask, has, tie = rec["mask"], rec["has"], rec["tie"]
    B = mask.shape[0]
    A, Bv, u_all, u = rec["A"], rec["B"], rec["u_all"], rec["u"]
    out_ = rec["out"]
    s_ = rec.get("s")
    role = t.dst_role
    gr = t.group_role
    acc: dict[str, float] = {"n_samples": float(B), "n_groups": float(B * t.n_groups),
                             "groups_with_candidate": float(B * int(t.group_has_candidate.sum())),
                             "groups_selected": float(has.sum()), "groups_tie": float(tie.sum()),
                             "groups_no_positive_evidence": float((~has & t.group_has_candidate[None]).sum()),
                             "nan_destination_scores": float(rec["n_nan_g"].sum()), "nan_candidate_scores": float(rec["nan_q"].sum()),
                             "sum_selected_score": float(np.where(has, rec["mx"], 0.0).sum())}
    mxs = rec["mx"][has]
    for a_, b_ in zip(DEST_SCORE_EDGES[:-1], DEST_SCORE_EDGES[1:]):
        acc[f"score_hist_{a_:g}_{b_:g}"] = float(((mxs > a_) & (mxs <= b_)).sum()) if a_ > 0 else float(((mxs > 0) & (mxs <= b_)).sum())
    acc[f"score_hist_gt_{DEST_SCORE_EDGES[-1]:g}"] = float((mxs > DEST_SCORE_EDGES[-1]).sum())
    g_ok = np.isfinite(rec["gap"])
    acc["n_gap"] = float(g_ok.sum())
    acc["sum_gap"] = float(np.where(g_ok, rec["gap"], 0.0).sum())
    acc["gap_lt_1e-3"] = float((g_ok & (np.where(g_ok, rec["gap"], 1.0) < 1e-3)).sum())
    minr = t.dst_role <= DEST_ROLE_CODE["straight"]                  # 곡선·직선 = min(A, B)
    for r, code in DEST_ROLE_CODE.items():
        rm = role == code
        sel = mask[:, rm]
        acc[f"{r}_groups_selected"] = float(has[:, gr == code].sum())
        acc[f"{r}_groups_total"] = float(B * int((gr == code).sum()))
        acc[f"{r}_selected"] = float(sel.sum())
        acc[f"{r}_selected_u_zero"] = float((sel & (u_all[:, rm] <= 0)).sum())
        acc[f"{r}_selected_out_zero"] = float((sel & (out_[:, rm] <= 0)).sum())
        hs = np.where(has, rec["mx"], 0.0)[:, t.dst_group[rm]] >= high
        acc[f"{r}_selected_high_score_u_zero"] = float((sel & hs & (u_all[:, rm] <= 0)).sum())
        if minr[rm].all():
            a_, b_ = A[:, rm] > 0, Bv[:, rm] > 0
            acc[f"{r}_selected_one_sided"] = float((sel & (a_ ^ b_)).sum())
            acc[f"{r}_selected_both_zero"] = float((sel & ~a_ & ~b_).sum())
            acc[f"{r}_selected_A_zero"] = float((sel & ~a_).sum())
            acc[f"{r}_selected_B_zero"] = float((sel & ~b_).sum())
        acc[f"{r}_sum_u_selected"] = float(np.where(sel, u_all[:, rm], 0.0).sum())
        acc[f"{r}_sum_A_selected"] = float(np.where(sel, A[:, rm], 0.0).sum())
        acc[f"{r}_sum_B_selected"] = float(np.where(sel, Bv[:, rm], 0.0).sum())
    acc["selected_total"] = float(mask.sum())
    acc["sum_norm_u_all_legal"] = float(np.linalg.norm(u_all, axis=1).sum())
    acc["sum_norm_u_selected"] = float(np.linalg.norm(u, axis=1).sum())
    acc["sum_norm_out_L2"] = float(np.linalg.norm(out_, axis=1).sum())
    acc["sum_norm_input_A"] = float(np.linalg.norm(A, axis=1).sum())
    acc["L2_zero_vector_samples"] = float((np.abs(out_).max(1) <= 0).sum())
    if rec.get("out3") is not None:
        o3 = rec["out3"]
        acc["L3_zero_vector_samples"] = float((np.abs(o3).max(1) <= 0).sum())
        acc["sum_norm_out_L3"] = float(np.linalg.norm(o3, axis=1).sum())
        acc["L3_active_frac_sum"] = float((o3 > 0).mean(1).sum())
    acc["L2_active_frac_sum"] = float((out_ > 0).mean(1).sum())
    for e_ in DEST_ACT_EDGES:
        acc[f"L2_out_ge_{e_:g}"] = float((out_ >= e_).sum())
    if s_ is not None:
        acc["selected_s_zero"] = float((mask & (s_ <= 0)).sum())
    bs = rec["bstat"]
    acc["reads_valid"] = float(bs["reads_valid"].sum())
    acc["reads_below_floor"] = float(bs["reads_below_floor"].sum())
    acc["reads_nan"] = float(bs["reads_nan"].sum())
    acc["b_sum"] = float(bs["b_sum"].sum())
    # 실제 사용 fan-out (원천별, 선택된 목적지의 입력 edge 만)
    n_src = t.n_src
    used = np.zeros(n_src + 1, np.int64)
    xA_src = np.full(t.n_l2, n_src, np.int64)
    xB_src = np.full(t.n_l2, n_src, np.int64)
    xA_src[t.c_rows] = t.c_srcA
    xA_src[t.s_rows] = t.s_srcA
    xB_src[t.s_rows] = t.s_srcB
    xA_src[t.j_rows] = t.j_src
    xA_src[t.l_rows] = t.l_src_f
    xB_src[t.l_rows] = t.l_src_b
    for b in range(B):
        sel = mask[b]
        srcB = xB_src.copy()
        srcB[t.c_rows] = rec["curve_src"][b]
        for arr in (xA_src[sel], srcB[sel]):
            arr = arr[arr < n_src]
            used += np.bincount(arr, minlength=n_src + 1)
    nz_sel = mask & ((A > 0) | (Bv > 0))                             # 입력군 합 기준 (선 끝은 A 두 항의 합)
    acc["selected_with_nonzero_input"] = float(nz_sel.sum())
    arrays = {"sel": mask.sum(0).astype(np.int64), "sel_u_zero": (mask & (u_all <= 0)).sum(0).astype(np.int64),
              "sel_out_zero": (mask & (out_ <= 0)).sum(0).astype(np.int64), "group_sel": has.sum(0).astype(np.int64),
              "group_tie": tie.sum(0).astype(np.int64), "src_used": used[:n_src]}
    if s_ is not None:
        arrays["active"] = (s_ > 0).sum(0).astype(np.int64)
    kq_hist = np.zeros((t.c_rows.size, t.c_cand_src.shape[1]), np.int64)
    sel_c = mask[:, t.c_rows]
    for b in range(B):
        kq_hist[np.nonzero(sel_c[b])[0], rec["kq"][b][sel_c[b]]] += 1
    arrays["curve_kq_hist"] = kq_hist
    return acc, arrays


def dest_acc_arrays_add(dst: dict[str, np.ndarray], part: dict[str, np.ndarray]) -> None:
    for k, v in part.items():
        if k in dst and dst[k].shape == v.shape:
            dst[k] = dst[k] + v
        else:
            dst[k] = np.asarray(v).copy()


def dest_finalize(acc: dict[str, float], t: DestTable) -> dict[str, Any]:
    n = max(1.0, acc.get("n_samples", 0.0))
    ng = max(1.0, acc.get("n_groups", 0.0))
    sel = max(1.0, acc.get("groups_selected", 0.0))
    out: dict[str, Any] = {
        "n_samples": int(acc.get("n_samples", 0)), "groups_per_sample": t.n_groups,
        "groups_with_candidate_frac": acc.get("groups_with_candidate", 0.0) / ng,
        "groups_selected_frac": acc.get("groups_selected", 0.0) / ng,
        "groups_no_positive_evidence_frac": acc.get("groups_no_positive_evidence", 0.0) / ng,
        "tie_frac_of_selected": acc.get("groups_tie", 0.0) / sel,
        "mean_top1_minus_top2": (acc["sum_gap"] / acc["n_gap"]) if acc.get("n_gap") else None,
        "gap_lt_1e-3_frac": (acc.get("gap_lt_1e-3", 0.0) / acc["n_gap"]) if acc.get("n_gap") else None,
        "mean_selected_score": acc.get("sum_selected_score", 0.0) / sel,
        "selected_neurons_per_sample": acc.get("selected_total", 0.0) / n,
        "nan_destination_scores": int(acc.get("nan_destination_scores", 0)), "nan_candidate_scores": int(acc.get("nan_candidate_scores", 0)),
        "mean_norm_u_all_legal": acc.get("sum_norm_u_all_legal", 0.0) / n, "mean_norm_u_selected": acc.get("sum_norm_u_selected", 0.0) / n,
        "mean_norm_input_A": acc.get("sum_norm_input_A", 0.0) / n, "mean_norm_out_L2": acc.get("sum_norm_out_L2", 0.0) / n,
        "mean_norm_out_L3": (acc["sum_norm_out_L3"] / n) if "sum_norm_out_L3" in acc else None,
        "L2_zero_vector_frac": acc.get("L2_zero_vector_samples", 0.0) / n,
        "L3_zero_vector_frac": (acc["L3_zero_vector_samples"] / n) if "L3_zero_vector_samples" in acc else None,
        "L2_active_frac": acc.get("L2_active_frac_sum", 0.0) / n,
        "L3_active_frac": (acc["L3_active_frac_sum"] / n) if "L3_active_frac_sum" in acc else None,
        "L2_out_distribution_per_sample": {f">={e_:g}": acc.get(f"L2_out_ge_{e_:g}", 0.0) / n for e_ in DEST_ACT_EDGES},
        "guide_reads_below_floor_frac": (acc.get("reads_below_floor", 0.0) / acc["reads_valid"]) if acc.get("reads_valid") else None,
        "guide_mean_b": (acc.get("b_sum", 0.0) / acc["reads_valid"]) if acc.get("reads_valid") else None,
        "guide_reads_nan": int(acc.get("reads_nan", 0)),
        "selected_with_nonzero_input_frac": acc.get("selected_with_nonzero_input", 0.0) / max(1.0, acc.get("selected_total", 0.0)),
        "selected_s_zero_frac": (acc["selected_s_zero"] / max(1.0, acc.get("selected_total", 0.0))) if "selected_s_zero" in acc else None,
        "selected_score_hist": {k[len("score_hist_"):]: acc[k] for k in acc if k.startswith("score_hist_")}}
    roles = {}
    for r in DEST_ROLES:
        k = max(1.0, acc.get(f"{r}_selected", 0.0))
        row = {"groups_selected_frac": acc.get(f"{r}_groups_selected", 0.0) / max(1.0, acc.get(f"{r}_groups_total", 0.0)),
               "selected_per_sample": acc.get(f"{r}_selected", 0.0) / n,
               "guide_selected_but_u_zero_frac": acc.get(f"{r}_selected_u_zero", 0.0) / k,
               "high_score_but_u_zero_frac": acc.get(f"{r}_selected_high_score_u_zero", 0.0) / k,
               "selected_out_zero_frac": acc.get(f"{r}_selected_out_zero", 0.0) / k,
               "mean_u_selected": acc.get(f"{r}_sum_u_selected", 0.0) / k,
               "mean_A_input_selected": acc.get(f"{r}_sum_A_selected", 0.0) / k,
               "mean_B_input_selected": (acc.get(f"{r}_sum_B_selected", 0.0) / k) if r in ("curve", "straight") else None}
        if f"{r}_selected_one_sided" in acc:
            row.update(one_sided_input_frac=acc[f"{r}_selected_one_sided"] / k, both_inputs_zero_frac=acc[f"{r}_selected_both_zero"] / k,
                       A_zero_frac=acc[f"{r}_selected_A_zero"] / k, B_zero_frac=acc[f"{r}_selected_B_zero"] / k)
        roles[r] = row
    out["roles"] = roles
    for r, row in roles.items():
        for k_, v_ in row.items():
            out[f"{r}_{k_}"] = v_
    return out


def dest_neuron_report(t: DestTable, arr: dict[str, np.ndarray], n_samples: int, *, l3: dict[str, np.ndarray] | None = None,
                       change_tol: float = 0.0) -> dict[str, Any]:
    """역할별 선택 빈도·계속 선택되지 않은 뉴런 비율·q 무변화 이유 (미선택 / 실제 입력 없음 / 문턱 미달 / 교정값 0 / 상쇄·클립)."""
    sel = arr.get("sel", np.zeros(t.n_l2, np.int64))
    out: dict[str, Any] = {"n_samples": int(n_samples), "roles": {}}
    have_q = "dq_abs" in arr
    reasons = np.full(t.n_l2, "", object)
    if have_q:
        changed = arr["dq_abs"] > change_tol
        inpos = sel - arr.get("sel_u_zero", np.zeros_like(sel))
        act = arr.get("active", np.zeros_like(sel))
        con = arr.get("contrib", np.zeros_like(sel))
        reasons = np.where(changed, "changed", np.where(sel == 0, "never_selected", np.where(inpos <= 0, "selected_no_input",
                           np.where(act <= 0, "below_threshold", np.where(con <= 0, "zero_correction", "cancelled_or_clipped")))))
    for r, code in DEST_ROLE_CODE.items():
        m = t.dst_role == code
        row = {"n_neurons": int(m.sum()), "n_valid_destinations": int((m & t.dst_valid).sum()),
               "selection_rate_per_sample_mean": float(sel[m].mean() / max(1, n_samples)) if m.any() else None,
               "never_selected_frac": float((sel[m] == 0).mean()) if m.any() else None,
               "never_selected_among_valid_frac": float((sel[m & t.dst_valid] == 0).mean()) if (m & t.dst_valid).any() else None,
               "top_neuron_share_of_role": float(sel[m].max() / max(1, sel[m].sum())) if m.any() and sel[m].sum() else None}
        if have_q:
            vals, cnt = np.unique(reasons[m], return_counts=True)
            row["q_reason_counts"] = {str(v): int(c) for v, c in zip(vals, cnt)}
        out["roles"][r] = row
    if l3 is not None and "dq_abs" in l3:
        ch3 = l3["dq_abs"] > change_tol
        r3 = np.where(ch3, "changed", np.where(l3.get("input_pos", np.zeros_like(l3["dq_abs"])) <= 0, "no_active_input",
                      np.where(l3.get("active", np.zeros_like(l3["dq_abs"])) <= 0, "below_threshold",
                               np.where(l3.get("contrib", np.zeros_like(l3["dq_abs"])) <= 0, "zero_correction", "cancelled_or_clipped"))))
        vals, cnt = np.unique(r3, return_counts=True)
        out["L3_q_reason_counts"] = {str(v): int(c) for v, c in zip(vals, cnt)}
    fi = t.candidate_fan_in()
    used_in = {"curve": 2, "straight": 2, "junction": 1, "lineend": 2}
    out["fan_in"] = {r: {"candidate_mean": float(fi[t.dst_role == c].mean()) if (t.dst_role == c).any() else None,
                         "candidate_max": int(fi[t.dst_role == c].max()) if (t.dst_role == c).any() else 0,
                         "used_edges_when_selected": used_in[r]} for r, c in DEST_ROLE_CODE.items()}
    if "src_used" in arr:
        fo = t.candidate_fan_out()
        su = np.asarray(arr["src_used"], np.float64) / max(1, n_samples)
        out["fan_out"] = {"candidate_mean_over_sources": float(fo.mean()), "candidate_max": int(fo.max()),
                          "used_per_sample_mean_over_sources": float(su.mean()), "used_per_sample_max": float(su.max()),
                          "sources_never_used_frac": float((np.asarray(arr["src_used"]) == 0).mean()),
                          "note_ko": "후보 fan-out = 고정 그래프의 유효 edge 수, 사용 fan-out = 선택된 목적지가 실제로 읽은 edge 수 (표본당 평균)"}
    out["reason_rule_ko"] = ("q 변화 = 에폭 동안 |Δq| 합 > change_tol. 변화 없음의 이유는 순서대로: 한 번도 선택 안 됨 → 선택됐지만 u = 0 (실제 입력 없음) "
                             "→ u > 0 이지만 s = 0 (문턱 미달) → s > 0 이지만 교정값 m = 0 → 기여가 있었지만 합이 0 또는 q 경계 클립")
    return out


def dest_reference(t: DestTable, F1: np.ndarray, xe: np.ndarray, cfg: dict[str, Any], mask_mode: str | None = None) -> dict[str, np.ndarray]:
    """검사용 NumPy float64 기준 구현 — 장치 경로와 독립 (표 배열에서 직접, 집단 선택·u 는 명시적 반복과 edge 목록으로 계산)."""
    dc = cfg["destination"]
    eps, floor = float(dc["guide_epsilon"]), float(dc["evidence_floor"])
    F1 = np.asarray(F1, np.float64)
    xe = np.asarray(xe, np.float64)
    B = F1.shape[0]
    Fs = F1.reshape(B, t.n_pos1, t.v1_n_ch)[:, :, t.lum_base:t.lum_base + t.n_o].sum(-1)
    F1e = np.concatenate([F1, np.zeros((B, 1))], 1)
    Fse = np.concatenate([Fs, np.zeros((B, 1))], 1)
    a = (F1e[:, t.gA_idx] * t.gA_w.astype(np.float64)).sum(-1)
    b = (Fse[:, t.gB_idx] * t.gB_w.astype(np.float64)).sum(-1)
    with np.errstate(invalid="ignore", divide="ignore"):
        r = np.where(t.read_valid[None] & (b >= floor), a / (b + eps), 0.0)
    r = np.where(np.isnan(a) | np.isnan(b), np.nan, r)
    re = np.concatenate([r, np.zeros((B, 1))], 1)
    S = np.full((B, t.n_l2), -1.0)
    kq = np.zeros((B, len(t.c_rows)), np.int64)
    for c in range(len(t.c_rows)):
        ks = np.nonzero(t.c_cand_valid[c])[0]
        for bb in range(B):
            best, bk, anynan = -1.0, 0, False
            for k in ks:
                v = min(re[bb, t.c_readA[c]], re[bb, t.c_readB[c, k]]) * float(np.mean(re[bb, t.c_path_reads[c, k]]))
                if not np.isfinite(v):
                    anynan = True
                    continue
                if v > best:
                    best, bk = v, int(k)
            kq[bb, c] = bk
            S[bb, t.c_rows[c]] = best if best >= 0 else (np.nan if anynan else -1.0)
    for k in range(len(t.s_rows)):
        if t.s_valid[k]:
            S[:, t.s_rows[k]] = np.minimum(re[:, t.s_readA[k]], re[:, t.s_readB[k]]) * re[:, t.s_path_reads[k]].mean(-1)
    for k in range(len(t.j_rows)):
        if t.j_valid[k]:
            S[:, t.j_rows[k]] = np.minimum(re[:, t.j_read1[k]], re[:, t.j_read2[k]])
    for k in range(len(t.l_rows)):
        if not t.l_valid[k]:
            continue
        rc = re[:, t.l_read_c[k][t.l_mask_c[k]]].mean(-1)
        tf = np.maximum(rc - re[:, t.l_read_f[k][t.l_mask_f[k]]].mean(-1), 0.0) if t.l_mask_f[k].any() else np.zeros(B)
        tb = np.maximum(rc - re[:, t.l_read_b[k][t.l_mask_b[k]]].mean(-1), 0.0) if t.l_mask_b[k].any() else np.zeros(B)
        S[:, t.l_rows[k]] = 0.5 * tf + 0.5 * tb
    mask = np.zeros((B, t.n_l2), bool)
    has = np.zeros((B, t.n_groups), bool)
    kg = np.zeros((B, t.n_groups), np.int64)
    for g in range(t.n_groups):
        mem = [int(x) for x in t.group_members[g] if x < t.n_l2]
        for bb in range(B):
            best, bi = 0.0, -1
            for slot, row in enumerate(mem):                         # neuron_id 오름차순: 같은 점수면 먼저 본 (작은 id) 것을 유지
                v = S[bb, row]
                if t.dst_valid[row] and np.isfinite(v) and v > best:
                    best, bi = v, slot
            if bi >= 0:
                has[bb, g], kg[bb, g] = True, bi
                mask[bb, mem[bi]] = True
    if mask_mode == "all_legal":
        mask = np.broadcast_to(t.dst_valid[None], (B, t.n_l2)).copy()
    # u: edge 목록에서 역할 결합식으로 (곡선 B 는 선택 칸 k 의 edge 만)
    u = np.zeros((B, t.n_l2))
    ci_of = {int(row): c for c, row in enumerate(t.c_rows)}
    by_dst: dict[int, list[int]] = {}
    for e_ in np.nonzero(t.e_valid)[0]:
        by_dst.setdefault(int(t.e_dst[e_]), []).append(int(e_))
    for bb in range(B):
        for row in np.nonzero(mask[bb])[0]:
            es = by_dst.get(int(row), [])
            role = DEST_ROLES[int(t.dst_role[row])]
            if role == "curve":
                k = int(kq[bb, ci_of[int(row)]])
                A_ = sum(xe[bb, t.e_src[e_]] * t.e_base_w[e_] for e_ in es if t.e_slot[e_] == 0)
                B_ = sum(xe[bb, t.e_src[e_]] * t.e_base_w[e_] for e_ in es if t.e_slot[e_] == 1 and int(t.e_bundle[e_]) == k)
                u[bb, row] = min(A_, B_)
            elif role == "straight":
                A_ = sum(xe[bb, t.e_src[e_]] * t.e_base_w[e_] for e_ in es if t.e_slot[e_] == 0)
                B_ = sum(xe[bb, t.e_src[e_]] * t.e_base_w[e_] for e_ in es if t.e_slot[e_] == 1)
                u[bb, row] = min(A_, B_)
            else:
                u[bb, row] = sum(xe[bb, t.e_src[e_]] * t.e_base_w[e_] for e_ in es)
    return {"r": r, "S": S, "kq": kq, "mask": mask, "has": has, "kg": kg, "u": u}


DEST_TRAINING_CSV_KEYS = ("groups_selected_frac", "tie_frac_of_selected", "mean_top1_minus_top2", "mean_selected_score", "selected_neurons_per_sample",
                          "L2_zero_vector_frac", "L3_zero_vector_frac", "guide_reads_below_floor_frac", "curve_groups_selected_frac",
                          "straight_groups_selected_frac", "junction_groups_selected_frac", "lineend_groups_selected_frac",
                          "curve_guide_selected_but_u_zero_frac", "curve_one_sided_input_frac", "selected_with_nonzero_input_frac")


def dest_rec_sample(dn: dict[str, Any], i: int) -> dict[str, Any]:
    """dest_rec_np 결과에서 표본 i 하나만 (조회·상세 기록용)."""
    out: dict[str, Any] = {}
    for k, v in dn.items():
        if isinstance(v, np.ndarray) and v.ndim >= 1:
            out[k] = v[i]
        elif isinstance(v, dict):
            out[k] = {kk: (vv[i] if isinstance(vv, np.ndarray) and vv.ndim >= 1 else vv) for kk, vv in v.items()}
        else:
            out[k] = v
    return out


def dest_delivered_edges(t: DestTable, mask: np.ndarray, kq: np.ndarray) -> np.ndarray:
    """한 표본에서 실제로 전달된 edge 번호 (선택된 목적지의 유효 edge, 곡선 B 는 선택 칸 Q* 의 edge 만)."""
    sel_e = t.e_valid & mask[t.e_dst]
    is_cb = (t.e_role == DEST_ROLE_CODE["curve"]) & (t.e_slot == 1)
    ci = np.where(is_cb, t.dst_role_index[t.e_dst], 0)
    keep = sel_e & (~is_cb | (t.e_bundle == kq[ci]))
    return np.nonzero(keep)[0]


def dest_sample_record(t: DestTable, dn: dict[str, Any], x4: np.ndarray, i: int, area: str, epoch: int, batch: int, sample_id: str,
                       label: int) -> dict[str, Any]:
    d = dest_rec_sample(dn, i)
    e = dest_delivered_edges(t, d["mask"], d["kq"])
    ncv = t.c_n_cand > 0
    q_star = np.where(ncv, t.c_cand_q[np.arange(len(t.c_rows)), d["kq"]], -1)
    bs = d["bstat"]
    return {"area": area, "epoch": epoch, "batch": batch, "sample_id": sample_id, "label": label, "has": d["has"], "kg": d["kg"],
            "mx": d["mx"].astype(np.float32), "gap": d["gap"].astype(np.float32), "tie": d["tie"], "n_valid": d["n_valid_g"].astype(np.int16),
            "q_star": q_star, "Sc": d["Sc"].astype(np.float32), "mask": d["mask"], "A": d["A"].astype(np.float32), "B": d["B"].astype(np.float32),
            "u_all": d["u_all"].astype(np.float32), "u": d["u"].astype(np.float32), "out": d["out"].astype(np.float32),
            "below_floor": float(bs["reads_below_floor"]) / max(1.0, float(bs["reads_valid"])),
            "e_src": t.e_src[e], "e_dst": t.e_dst[e], "e_slot": t.e_slot[e], "e_role": t.e_role[e],
            "e_val": (x4[i][t.e_src[e]] * t.e_base_w[e]).astype(np.float32)}


def class_separation(sums: np.ndarray, counts: np.ndarray, eps: float = 1e-12) -> dict[str, Any]:
    """클래스 평균 벡터 사이 코사인 (낮을수록 분리). 표본이 없거나 영벡터인 클래스는 뺀다."""
    S = np.asarray(sums, np.float64)
    c = np.asarray(counts, np.float64)
    ok = c > 0
    M = S[ok] / c[ok][:, None]
    n = np.linalg.norm(M, axis=1)
    M = M[n > eps] / n[n > eps][:, None]
    if len(M) < 2:
        return {"n_classes": int(len(M)), "between_class_mean_cos": None, "between_class_max_cos": None}
    pc = M @ M.T
    off = pc[~np.eye(len(M), dtype=bool)]
    return {"n_classes": int(len(M)), "between_class_mean_cos": float(off.mean()), "between_class_max_cos": float(off.max())}


# ======================================================================
# 8b. V4 입력 비율 라우팅 후보 그래프 (RouteTable, v6 모드의 V4/L2 만) — 구조 생성 때 한 번, 데이터·라벨 미사용
#     집단 g = V4 수신 위치 P × 역할 계열. 후보 = 완전한 입력 배정 묶음 (목적지 L2 하나 + A/B 슬롯 원천·기저 가중치).
#     합법적인 후보는 모두 저장한다 (첫 K 개만 남기지 않는다). 계산은 묶음 (bucket) 과 집단 조각으로 나눈다.
# ======================================================================
ROUTE_REASONS = {0: "legal", 1: "behind_P", 2: "bend_side", 3: "path_outside_field", 4: "zero_tangent", 5: "folded_path",
                 6: "no_A_input", 7: "min2_missing_B"}
ROUTE_REASONS_KO = {**{k: v for k, v in CURVE_REASONS_KO.items() if k not in ("same_position", "outside_rf")},
                    "legal": "합법 후보 (경쟁에 참여)", "no_A_input": "A 슬롯 원천이 없다", "min2_missing_B": "min2 역할인데 B 슬롯 원천이 없다"}
SLOT_NAMES = ("A", "B")
ROUTE_CONVENTION_KO = {
    "group": "집단 = (V4, 수신 L2 위치 P, 역할 계열: 곡선·직선·접합·선 끝). 영역 전체 top-1 이 아니다. V1·V2·IT 에는 후보 그래프를 만들지 않는다.",
    "candidate": "후보 = 목적지 L2 하나와 그 A/B 슬롯 원천 묶음. 곡선은 (곡선 뉴런, Q) 묶음마다 다른 route_id. 목록 순번을 각도·의미로 쓰지 않는다.",
    "source_order": "source_ids[g] = 집단 합법 후보들의 원천 L4 local 주소 합집합의 오름차순 (= 위치 우선·채널 순서, ON/OFF 는 채널). 값 크기 정렬 없음.",
    "no_duplicate": "같은 원천이 A·B 슬롯 모두에 필요하면 슬롯 가중치는 따로 두되 x_g 에는 한 번만 넣는다.",
    "support": "후보의 구조적 지원 = 그 후보의 A·B 슬롯 원천. 대표 벡터는 지원 밖에서 0, 지원 위에서 비음수 단위 노름.",
    "no_candidate": "기하 후보가 없는 목적지·집단은 '후보 없음' 으로 기록한다 (활동 0 과 구분). 0 번 뉴런으로 보내지 않는다.",
    "codebook_id": "codebook_id = (묶음, 묶음 안 집단 칸, 후보 칸). 집단끼리 대표 벡터를 공유하지 않는다. descriptor_schema_id = 집단 번호.",
    "fanout": "같은 L4 가 여러 집단·후보에 들어갈 수 있다 (top-1 은 집단당 하나이며 L4 뉴런당 축삭 하나가 아니다). fan-out 을 기록한다.",
}


@dataclass
class RouteBucket:
    """같은 역할 계열·비슷한 크기의 집단 묶음 (연속 배열, 패딩 + 마스크)."""

    family: int
    groups: np.ndarray        # (G,) 영역 안 집단 번호
    src: np.ndarray           # (G, D) L4 local 주소 (패딩 = n_l4 → 0 열)
    dvalid: np.ndarray        # (G, D)
    route: np.ndarray         # (G, K) route_id (패딩 −1)
    legal: np.ndarray         # (G, K)
    dst: np.ndarray           # (G, K) L2 local (패딩 n_l2)
    support: np.ndarray       # (G, K, D) bool
    WA: np.ndarray            # (G, K, D) float32 A 슬롯 기저 가중치 (부호 유지)
    WB: np.ndarray | None     # (G, K, D) float32 B 슬롯 (min2 후보가 없는 묶음은 None)
    op_min: np.ndarray        # (G, K) bool

    @property
    def G(self) -> int:
        return int(self.src.shape[0])

    @property
    def D(self) -> int:
        return int(self.src.shape[1])

    @property
    def K(self) -> int:
        return int(self.route.shape[1])

    def nbytes(self) -> int:
        n = self.G * self.K * self.D
        return int(n * (4 + 1 + 4 + (4 if self.WB is not None else 0)) + self.src.size * 8 + self.route.size * 18)


@dataclass
class RouteTable:
    area: str
    n_l4: int
    n_l2: int
    family_names: list[str]
    space_kind: str
    params: dict[str, Any]
    # 후보 레코드 (탈락 후보 포함)
    r_dst: np.ndarray
    r_group: np.ndarray             # 집단 번호 (탈락 −1)
    r_legal: np.ndarray
    r_reason: np.ndarray            # int8 (ROUTE_REASONS)
    r_op_min: np.ndarray
    r_ptr: np.ndarray               # (R+1,) → e_*
    e_src: np.ndarray
    e_slot: np.ndarray              # 0 = A, 1 = B
    e_w: np.ndarray
    r_q: np.ndarray                 # 곡선 B 위치 (그 밖 −1)
    r_dist_px: np.ndarray
    r_chord_dev_deg: np.ndarray
    r_bucket: np.ndarray            # codebook_id (묶음, 집단 칸, 후보 칸) — 탈락 −1
    r_bk_g: np.ndarray
    r_bk_k: np.ndarray
    # 집단
    g_space: np.ndarray
    g_family: np.ndarray
    g_n_routes: np.ndarray
    g_D: np.ndarray
    g_bucket: np.ndarray            # 후보 없는 집단 −1
    g_local: np.ndarray
    g_src_ptr: np.ndarray
    g_src: np.ndarray
    g_mem_ptr: np.ndarray
    g_mem: np.ndarray
    l2_group: np.ndarray
    l2_n_legal: np.ndarray
    buckets: list[RouteBucket]
    removed: dict[str, Any]

    @property
    def n_routes(self) -> int:
        return int(len(self.r_dst))

    @property
    def n_groups(self) -> int:
        return int(len(self.g_space))

    def group_sources(self, g: int) -> np.ndarray:
        return self.g_src[self.g_src_ptr[g]:self.g_src_ptr[g + 1]]

    def group_members(self, g: int) -> np.ndarray:
        return self.g_mem[self.g_mem_ptr[g]:self.g_mem_ptr[g + 1]]

    def group_routes(self, g: int) -> np.ndarray:
        return np.nonzero(self.r_group == g)[0]

    def route_edges(self, r: int) -> tuple[np.ndarray, np.ndarray, np.ndarray]:
        a, b = int(self.r_ptr[r]), int(self.r_ptr[r + 1])
        return self.e_src[a:b], self.e_slot[a:b], self.e_w[a:b]

    def hash(self) -> str:
        parts = [self.r_dst, self.r_group, self.r_legal, self.r_reason, self.r_op_min, self.r_ptr, self.e_src, self.e_slot, self.e_w,
                 self.g_space, self.g_family, self.g_src_ptr, self.g_src, self.g_bucket, self.g_local]
        for bk in self.buckets:
            parts += [bk.src, bk.route, bk.legal, bk.dst, bk.support, bk.WA, bk.op_min] + ([bk.WB] if bk.WB is not None else [])
        return sha256_text(dumps({"area": self.area, "families": self.family_names, "space_kind": self.space_kind, "params": self.params},
                                 indent=None) + sha256_array(*parts))

    def nbytes(self) -> int:
        return int(sum(bk.nbytes() for bk in self.buckets))


def ragged(counts: np.ndarray) -> tuple[np.ndarray, np.ndarray]:
    """길이 counts 인 구간들의 (구간 번호, 구간 안 위치) — 가변 길이 목록을 반복문 없이 펼친다."""
    counts = np.asarray(counts, np.int64)
    rep = np.repeat(np.arange(len(counts), dtype=np.int64), counts)
    off = np.arange(int(counts.sum()), dtype=np.int64) - np.repeat(np.cumsum(counts) - counts, counts)
    return rep, off


def build_route_table(area: str, l4: LayerSpec, l2: LayerSpec, cfg: dict[str, Any]) -> RouteTable:
    """L2 의 역할별 기저 연결 (CSR) 과 곡선 B 후보 원천 (ropt) 에서 후보 그래프·집단·묶음을 만든다."""
    if l2.route_space is None or l2.route_family is None:
        raise StructureError(f"{l2.key}: 선택 집단 키가 없다.")
    ro = cfg["routing"]["ratio_codebook"]
    n2, n4 = l2.n, l4.n
    if l2.n_src != n4:
        raise StructureError(f"{l2.key} 의 원천 크기 {l2.n_src} != {l4.key} 뉴런 수 {n4}")
    routed = l2.routed if l2.routed is not None else np.zeros(n2, bool)
    ropt = l2.ropt or {}
    o_row = np.asarray(ropt.get("row", np.zeros(0, np.int64)), np.int64)
    if len(o_row) and ((np.diff(o_row) < 0).any() or not routed[o_row].all()):
        raise StructureError(f"{l2.key}: 곡선 B 후보 원천 목록이 행 순서가 아니거나 routed 가 아닌 행을 가리킨다.")
    fanA = np.diff(l2.a_ptr).astype(np.int64)
    fanB = np.diff(l2.b_ptr).astype(np.int64)
    nr = np.where(routed, 0, 1).astype(np.int64)
    if len(o_row):
        nr += np.bincount(o_row, minlength=n2)
    R = int(nr.sum())
    r_dst_a = np.repeat(np.arange(n2, dtype=np.int64), nr)                    # 후보 순서 = L2 행 순서, 곡선은 원천 주소 순서
    r_routed = routed[r_dst_a] if R else np.zeros(0, bool)
    opt_of = np.full(R, -1, np.int64)
    opt_of[r_routed] = np.arange(int(r_routed.sum()))
    fa = fanA[r_dst_a]
    fb = np.where(r_routed, 1, fanB[r_dst_a])
    r_ptr_a = np.concatenate([[0], np.cumsum(fa + fb)]).astype(np.int64)
    E = int(r_ptr_a[-1])
    e_src_a = np.full(E, -1, np.int64)
    e_slot_a = np.zeros(E, np.int8)
    e_w_a = np.zeros(E, np.float32)

    rep, off = ragged(fa)                                                   # A 슬롯 (모든 후보)
    pos = r_ptr_a[rep] + off
    e_src_a[pos] = l2.a_src[l2.a_ptr[r_dst_a[rep]] + off]
    e_w_a[pos] = l2.a_w[l2.a_ptr[r_dst_a[rep]] + off]
    nb_ = np.where(r_routed, 0, fb)
    rep, off = ragged(nb_)                                                  # B 슬롯 (기존 CSR B)
    pos = r_ptr_a[rep] + fa[rep] + off
    e_src_a[pos] = l2.b_src[l2.b_ptr[r_dst_a[rep]] + off]
    e_w_a[pos] = l2.b_w[l2.b_ptr[r_dst_a[rep]] + off]
    e_slot_a[pos] = 1
    rr_ = np.nonzero(r_routed)[0]                                           # B 슬롯 (곡선: 후보 묶음의 Q 원천 하나)
    pos = r_ptr_a[rr_] + fa[rr_]
    if len(rr_):
        e_src_a[pos] = ropt["src"][opt_of[rr_]]
        e_w_a[pos] = ropt["w"][opt_of[rr_]]
        e_slot_a[pos] = 1
    if (e_src_a < 0).any() or (e_src_a >= n4).any():
        raise StructureError(f"{l2.key} 후보 원천 주소가 범위 밖이다.")
    r_op = np.where(r_routed, True, l2.op_min[r_dst_a] if R else np.zeros(0, bool)).astype(bool)
    r_reason = np.zeros(R, np.int8)
    r_reason[r_routed] = ropt["reason"][opt_of[r_routed]] if len(rr_) else 0
    r_reason[(~r_routed) & r_op & (fb == 0)] = 7
    r_reason[fa == 0] = 6
    r_q = np.full(R, -1, np.int64)
    r_dist = np.full(R, np.nan, np.float32)
    r_cdev = np.full(R, np.nan, np.float32)
    if len(rr_):
        r_q[rr_] = ropt["q"][opt_of[rr_]]
        r_dist[rr_] = ropt["dist_px"][opt_of[rr_]]
        r_cdev[rr_] = ropt["chord_dev_deg"][opt_of[rr_]]
    r_legal_a = r_reason == 0
    # ---------------------------------------------------------------- 집단 (L2 뉴런 순서로 처음 나타난 순서)
    key_of: dict[tuple[int, int], int] = {}
    l2_group = np.zeros(n2, np.int64)
    gkeys: list[tuple[int, int]] = []
    for j in range(n2):
        k_ = (int(l2.route_space[j]), int(l2.route_family[j]))
        if k_ not in key_of:
            key_of[k_] = len(gkeys)
            gkeys.append(k_)
        l2_group[j] = key_of[k_]
    Gt = len(gkeys)
    r_group = np.where(r_legal_a, l2_group[r_dst_a] if R else np.zeros(0, np.int64), -1).astype(np.int64)
    g_routes: list[list[int]] = [[] for _ in range(Gt)]
    for r in range(R):
        if r_legal_a[r]:
            g_routes[int(r_group[r])].append(r)
    g_src_list: list[np.ndarray] = []
    for g in range(Gt):
        ss = [e_src_a[r_ptr_a[r]:r_ptr_a[r + 1]] for r in g_routes[g]]
        g_src_list.append(np.unique(np.concatenate(ss)) if ss else np.zeros(0, np.int64))
    mem = [[] for _ in range(Gt)]
    for j in range(n2):
        mem[int(l2_group[j])].append(j)
    l2_n_legal = np.bincount(r_dst_a[r_legal_a], minlength=n2).astype(np.int64) if R else np.zeros(n2, np.int64)
    # ---------------------------------------------------------------- 묶음 (같은 계열, 크기순, 패딩 상한)
    pad_max = float(ro["bucket_padding_max"])
    max_el = int(ro["bucket_max_elements"])
    g_bucket = np.full(Gt, -1, np.int64)
    g_local = np.full(Gt, -1, np.int64)
    plans: list[tuple[int, list[int]]] = []
    for fam in range(len(l2.route_family_names or [])):
        gs = [g for g in range(Gt) if gkeys[g][1] == fam and g_routes[g]]
        gs.sort(key=lambda g: (len(g_src_list[g]), len(g_routes[g]), g))
        cur: list[int] = []
        for g in gs:
            trial = cur + [g]
            Dm = max(len(g_src_list[x]) for x in trial)
            Km = max(len(g_routes[x]) for x in trial)
            actual = sum(len(g_src_list[x]) * len(g_routes[x]) for x in trial)
            if cur and (len(trial) * Dm * Km > pad_max * actual or len(trial) * Dm * Km > max_el):
                plans.append((fam, cur))
                cur = [g]
            else:
                cur = trial
        if cur:
            plans.append((fam, cur))
    r_bucket = np.full(R, -1, np.int64)
    r_bk_g = np.full(R, -1, np.int64)
    r_bk_k = np.full(R, -1, np.int64)
    buckets: list[RouteBucket] = []
    for b, (fam, gs) in enumerate(plans):
        gs = sorted(gs)
        G = len(gs)
        Dm = max(len(g_src_list[g]) for g in gs)
        Km = max(len(g_routes[g]) for g in gs)
        src = np.full((G, Dm), n4, np.int64)
        dvalid = np.zeros((G, Dm), bool)
        route = np.full((G, Km), -1, np.int64)
        legal = np.zeros((G, Km), bool)
        dst = np.full((G, Km), n2, np.int64)
        support = np.zeros((G, Km, Dm), bool)
        WA = np.zeros((G, Km, Dm), np.float32)
        WB = np.zeros((G, Km, Dm), np.float32)
        op_min = np.zeros((G, Km), bool)
        for gl, g in enumerate(gs):
            ss = g_src_list[g]
            src[gl, :len(ss)] = ss
            dvalid[gl, :len(ss)] = True
            g_bucket[g], g_local[g] = b, gl
            rs = np.asarray(g_routes[g], np.int64)
            nk = len(rs)
            route[gl, :nk], legal[gl, :nk], dst[gl, :nk], op_min[gl, :nk] = rs, True, r_dst_a[rs], r_op[rs]
            r_bucket[rs], r_bk_g[rs], r_bk_k[rs] = b, gl, np.arange(nk)
            rep_, off_ = ragged(r_ptr_a[rs + 1] - r_ptr_a[rs])
            ei = r_ptr_a[rs][rep_] + off_
            d_ = np.searchsorted(ss, e_src_a[ei])
            sl_ = e_slot_a[ei]
            support[gl, rep_, d_] = True
            np.add.at(WA[gl], (rep_[sl_ == 0], d_[sl_ == 0]), e_w_a[ei][sl_ == 0])
            np.add.at(WB[gl], (rep_[sl_ == 1], d_[sl_ == 1]), e_w_a[ei][sl_ == 1])
        buckets.append(RouteBucket(family=fam, groups=np.asarray(gs, np.int64), src=src, dvalid=dvalid, route=route, legal=legal, dst=dst,
                                   support=support, WA=WA, WB=WB if op_min.any() else None, op_min=op_min))
    g_src_ptr = np.concatenate([[0], np.cumsum([len(s_) for s_ in g_src_list])]).astype(np.int64)
    g_mem_ptr = np.concatenate([[0], np.cumsum([len(m_) for m_ in mem])]).astype(np.int64)
    params = {"mode": RATIO_MODE, "bucket_padding_max": pad_max, "bucket_max_elements": max_el, "space_kind": l2.route_space_kind,
              "curve_path_points": int(ro["curve_path_points"])}
    return RouteTable(
        area=area, n_l4=n4, n_l2=n2, family_names=list(l2.route_family_names or []), space_kind=str(l2.route_space_kind), params=params,
        r_dst=r_dst_a, r_group=r_group, r_legal=r_legal_a, r_reason=r_reason, r_op_min=r_op,
        r_ptr=r_ptr_a, e_src=e_src_a, e_slot=e_slot_a, e_w=e_w_a, r_q=r_q, r_dist_px=r_dist,
        r_chord_dev_deg=r_cdev, r_bucket=r_bucket, r_bk_g=r_bk_g, r_bk_k=r_bk_k,
        g_space=np.asarray([k_[0] for k_ in gkeys], np.int64), g_family=np.asarray([k_[1] for k_ in gkeys], np.int64),
        g_n_routes=np.asarray([len(x) for x in g_routes], np.int64), g_D=np.asarray([len(s_) for s_ in g_src_list], np.int64),
        g_bucket=g_bucket, g_local=g_local, g_src_ptr=g_src_ptr,
        g_src=np.concatenate(g_src_list).astype(np.int64) if g_src_list else np.zeros(0, np.int64),
        g_mem_ptr=g_mem_ptr, g_mem=np.concatenate([np.asarray(m_, np.int64) for m_ in mem]) if mem else np.zeros(0, np.int64),
        l2_group=l2_group, l2_n_legal=l2_n_legal, buckets=buckets, removed=dict(l2.ropt_removed or {}))


def route_table_summary(t: RouteTable, l4: LayerSpec, l2: LayerSpec, l3: LayerSpec, batch_size: int) -> dict[str, Any]:
    """structure.json 의 영역 절: 집단·후보·차원·지원·메모리·계산량·fan-out·L2→L3 병합 구조 (모두 구조에서 센 값)."""
    fam_rows: dict[str, Any] = {}
    # L2 → L3 부모 집합 (각 L2 뉴런을 읽는 L3 행들)
    rows3 = np.concatenate([np.repeat(np.arange(l3.n, dtype=np.int64), np.diff(l3.a_ptr)),
                            np.repeat(np.arange(l3.n, dtype=np.int64), np.diff(l3.b_ptr))])
    src3 = np.concatenate([l3.a_src, l3.b_src]).astype(np.int64)
    l3_of: dict[int, tuple[int, ...]] = {}
    order = np.lexsort((rows3, src3))
    for s_, r_ in zip(src3[order], rows3[order]):
        l3_of.setdefault(int(s_), tuple())
        l3_of[int(s_)] = l3_of[int(s_)] + (int(r_),)
    sup_size = np.diff(t.r_ptr)
    for fi, fname in enumerate(t.family_names):
        gsel = np.nonzero(t.g_family == fi)[0]
        rsel = np.nonzero(t.r_legal & (t.r_group >= 0) & np.isin(t.r_group, gsel))[0]
        rall = np.nonzero(np.isin(t.l2_group[t.r_dst], gsel))[0] if t.n_routes else np.zeros(0, np.int64)
        K = t.g_n_routes[gsel]
        D = t.g_D[gsel]
        dsts = np.concatenate([t.group_members(int(g)) for g in gsel]) if len(gsel) else np.zeros(0, np.int64)
        supp = np.concatenate([bk.support.sum(-1)[bk.legal] for bk in t.buckets if bk.family == fi] or [np.zeros(0, np.int64)])
        merge = []
        for g in gsel:
            rr = t.group_routes(int(g))
            if len(rr) == 0:
                continue
            d_ = {int(t.r_dst[r]) for r in rr}
            l3s = {l3_of.get(int(x), ()) for x in d_}
            merge.append((len(rr), len(d_), len(l3s)))
        merge_a = np.asarray(merge, np.int64).reshape(-1, 3)
        fam_rows[fname] = {
            "n_groups": int(len(gsel)), "groups_without_legal_candidate": int((K == 0).sum()),
            "candidates_per_group_K": {"min": int(K.min()) if K.size else 0, "mean": float(K.mean()) if K.size else 0.0, "max": int(K.max()) if K.size else 0},
            "descriptor_dim_D": {"min": int(D.min()) if D.size else 0, "mean": float(D.mean()) if D.size else 0.0, "max": int(D.max()) if D.size else 0},
            "legal_candidates": int(len(rsel)), "rejected_candidates_by_reason": {ROUTE_REASONS[int(c)]: int((t.r_reason[rall] == c).sum())
                                                                                  for c in np.unique(t.r_reason[rall]) if c != 0},
            "destinations": int(len(dsts)), "destinations_without_legal_candidate": int((t.l2_n_legal[dsts] == 0).sum()),
            "support_dim": {"min": int(supp.min()) if supp.size else 0, "mean": float(supp.mean()) if supp.size else 0.0,
                            "max": int(supp.max()) if supp.size else 0},
            "candidates_with_support_1_fixed_code": int((supp == 1).sum()),
            "codebook_floats_sum_KD": int((K * D).sum()),
            "L2_L3_merge_mean_per_group": {"candidates": float(merge_a[:, 0].mean()) if len(merge_a) else 0.0,
                                           "distinct_L2_destinations": float(merge_a[:, 1].mean()) if len(merge_a) else 0.0,
                                           "distinct_L3_parent_sets": float(merge_a[:, 2].mean()) if len(merge_a) else 0.0}}
    KD = int((t.g_n_routes * t.g_D).sum())
    padded = int(sum(bk.G * bk.K * bk.D for bk in t.buckets))
    used = t.e_src[np.repeat(t.r_legal, sup_size)]
    route_fo = np.bincount(used, minlength=t.n_l4)
    desc_fo = np.bincount(t.g_src, minlength=t.n_l4)
    l4_names = l4.channel_names
    return {
        "area": t.area, "mode": RATIO_MODE, "space_kind": t.space_kind, "families": t.family_names, "n_groups": t.n_groups,
        "n_buckets": len(t.buckets), "n_candidate_records": t.n_routes, "n_legal_candidates": int(t.r_legal.sum()),
        "n_rejected_candidates": int((~t.r_legal).sum()), "n_destinations": t.n_l2,
        "destinations_without_legal_candidate": int((t.l2_n_legal == 0).sum()),
        "groups_without_legal_candidate": int((t.g_n_routes == 0).sum()), "families_detail": fam_rows,
        "sum_K_times_D": KD, "padded_K_times_D": padded, "padding_overhead": (padded / KD) if KD else None,
        "codebook_memory_mb_float32": round(padded * 4 / 2 ** 20, 3), "route_arrays_memory_mb": round(t.nbytes() / 2 ** 20, 3),
        "score_macs_per_sample": KD, "score_macs_per_batch": KD * int(batch_size), "role_op_macs_per_sample_upper": 2 * padded,
        "cost_note_ko": "점수 O(batch × Σ_g K_g D_g), 코드북 메모리 O(Σ_g K_g D_g) (묶음 패딩 포함 값 따로). 원핫 전달이어도 후보 비교 비용은 그대로다.",
        "L4_fanout": {"descriptor_groups_per_L4": {"min": int(desc_fo.min()), "mean": float(desc_fo.mean()), "max": int(desc_fo.max()),
                                                   "n_L4_in_no_group": int((desc_fo == 0).sum())},
                      "legal_candidates_per_L4": {"min": int(route_fo.min()), "mean": float(route_fo.mean()), "max": int(route_fo.max())},
                      "note_ko": "같은 L4 출력값이 여러 집단의 패킷과 여러 후보 슬롯에 그대로 쓰인다 (값을 나누지 않는다, 전역 신호량 보존을 주장하지 않는다)."},
        "L4_channels": l4_names[:64], "removed_curve_options": t.removed.get("curve_total") if t.removed else None,
        "route_table_sha256": t.hash(), "conventions": ROUTE_CONVENTION_KO}


def candidate_records(t: RouteTable, l4: LayerSpec, l2: LayerSpec) -> dict[str, np.ndarray]:
    """후보 레코드 전체 (structure/candidates_{영역}.npz). 명세의 필드를 모두 담는다 (탈락 후보 포함)."""
    e_pos = (t.e_src // l4.n_ch).astype(np.int32)
    l2_pos = t.r_dst // l2.n_ch
    meta_cols = {}
    for k_, v_ in l2.channel_meta.items():
        vals = [v_[int(c)] for c in (t.r_dst % l2.n_ch)]
        meta_cols[f"role_param_{k_}"] = np.asarray([("" if x is None else str(x)) for x in vals])
    return {
        "area": np.asarray(t.area), "route_id": np.arange(t.n_routes, dtype=np.int64), "group_id": t.r_group,
        "destination_L2_id": l2.start + t.r_dst, "destination_L2_local": t.r_dst, "destination_position": l2_pos,
        "destination_xy_px": np.stack([l2.x[t.r_dst], l2.y[t.r_dst]], 1) if t.n_routes else np.zeros((0, 2), np.float32),
        "role_family": np.asarray([t.family_names[int(l2.route_family[int(j)])] for j in t.r_dst]),
        "role_channel": np.asarray([l2.channel_names[int(j) % l2.n_ch] for j in t.r_dst]),
        "op_min2": t.r_op_min, "valid_mask": t.r_legal, "rejection_reason": t.r_reason,
        "rejection_reason_names": np.asarray(dumps(ROUTE_REASONS, indent=None)), "curve_B_position_Q": t.r_q,
        "curve_B_dist_px": t.r_dist_px, "curve_chord_dev_deg_diag": t.r_chord_dev_deg,
        "codebook_bucket": t.r_bucket, "codebook_group_slot": t.r_bk_g, "codebook_candidate_slot": t.r_bk_k,
        "descriptor_schema_id": t.r_group, "edge_ptr": t.r_ptr, "source_L4_id": (l4.start + t.e_src).astype(np.int64),
        "input_slot": t.e_slot, "input_slot_names": np.asarray(SLOT_NAMES), "signed_base_weight": t.e_w,
        "source_position": e_pos, "L4_position_xy_px": np.stack([l4.pos_x, l4.pos_y], 1),
        "source_channel_metadata_code": (t.e_src % l4.n_ch).astype(np.int16), "L4_channel_names": np.asarray(l4.channel_names),
        "L4_channel_meta": np.asarray(dumps(l4.channel_meta, indent=None)),
        "group_space": t.g_space, "group_family": t.g_family, "group_family_names": np.asarray(t.family_names),
        "group_n_candidates": t.g_n_routes, "group_descriptor_dim": t.g_D, "group_source_ptr": t.g_src_ptr,
        "group_source_L4_id": l4.start + t.g_src, "group_member_ptr": t.g_mem_ptr, "group_member_L2_id": l2.start + t.g_mem,
        "route_table_sha256": np.asarray(t.hash()), "conventions": np.asarray(dumps(ROUTE_CONVENTION_KO, indent=None)), **meta_cols}


def route_reference(t: RouteTable, codes: Sequence[np.ndarray], ok: Sequence[np.ndarray], x4: np.ndarray, cfg: dict[str, Any]) -> dict[str, np.ndarray]:
    """float64 독립 기준식 (묶음 dense 가중치·행렬곱을 쓰지 않고 후보 레코드의 edge 목록에서 직접 계산).
    반환: 집단별 has·route (−1)·top1·gap·S, L2 u (선택된 목적지만), 선택 마스크."""
    ro = cfg["routing"]["ratio_codebook"]
    mt, eps = float(ro["routing_min_total"]), float(ro["norm_epsilon"])
    B = int(x4.shape[0])
    xs = np.concatenate([np.asarray(x4, np.float64), np.zeros((B, 1))], 1)
    G = t.n_groups
    has = np.zeros((B, G), bool)
    route = np.full((B, G), -1, np.int64)
    top1 = np.full((B, G), np.nan)
    gap = np.full((B, G), np.nan)
    S_all = np.zeros((B, G))
    u2 = np.zeros((B, t.n_l2))
    mask = np.zeros((B, t.n_l2), bool)
    for g in range(G):
        rr = t.group_routes(g)
        if len(rr) == 0:
            continue
        src = t.group_sources(g)
        b_, gl = int(t.g_bucket[g]), int(t.g_local[g])
        Dg = len(src)
        x = xs[:, src]
        S = x.sum(1)
        S_all[:, g] = S
        fin = np.isfinite(x).all(1) & (x >= 0).all(1)
        act = fin & (S > mt)
        with np.errstate(divide="ignore", invalid="ignore"):
            p = x / np.where(act, S, 1.0)[:, None]
            xh = p / np.maximum(np.linalg.norm(p, axis=1), eps)[:, None]
        for b in range(B):
            if not act[b]:
                continue
            best, bk, sc = -np.inf, -1, []
            for k, r in enumerate(rr):
                if not bool(ok[b_][gl, k]):
                    continue
                s_ = float(xh[b] @ np.asarray(codes[b_][gl, k, :Dg], np.float64))
                sc.append(s_)
                if s_ > best:
                    best, bk = s_, k
            if bk < 0:
                continue
            has[b, g] = True
            route[b, g] = int(rr[bk])
            top1[b, g] = best
            if len(sc) >= 2:
                srt = sorted(sc, reverse=True)
                gap[b, g] = srt[0] - srt[1]
            r = int(rr[bk])
            es, sl, ws = t.route_edges(r)
            ua = float((xs[b, es[sl == 0]] * ws[sl == 0]).sum())
            ub = float((xs[b, es[sl == 1]] * ws[sl == 1]).sum())
            u = min(ua, ub) if bool(t.r_op_min[r]) else ua
            j = int(t.r_dst[r])
            u2[b, j] = u
            mask[b, j] = True
    return {"has": has, "route": route, "top1": top1, "gap": gap, "S": S_all, "u": u2, "mask": mask}




# ======================================================================
# 9. 순방향 계산 (CortexArea 런타임, L6 RelativeActivityController, CortexModel)
# ======================================================================
class BucketELL:
    """CSR 입력 목록 → 팬인 크기별 ELL 묶음 (팬인을 2 의 거듭제곱으로 올려 묶는다). 각 행은 정확히 한 묶음에 속하고,
    묶음 결과를 고정 역순열 gather 로 원래 순서에 놓는다 (atomic 누적 없음 → 결정적)."""

    def __init__(self, be: Backend, ptr: np.ndarray, src: np.ndarray, w: np.ndarray, n_src: int):
        n = len(ptr) - 1
        self.n, self.n_src, self.edges = n, int(n_src), int(len(src))
        self.parts: list[tuple[Any, Any]] = []
        self.inv: Any = None
        self.slots = 0
        if self.edges == 0:
            return
        fan = np.diff(ptr)
        K = np.ones(n, np.int64)
        nz = fan > 0
        K[nz] = np.left_shift(1, np.ceil(np.log2(fan[nz])).astype(np.int64))
        row_of_edge = np.repeat(np.arange(n, dtype=np.int64), fan)
        col = np.arange(len(src), dtype=np.int64) - ptr[row_of_edge]
        perm = []
        for k in np.unique(K):
            rows = np.nonzero(K == k)[0]
            local = np.full(n, -1, np.int64)
            local[rows] = np.arange(len(rows))
            idx = np.full((len(rows), int(k)), self.n_src, np.int64)
            ww = np.zeros((len(rows), int(k)), np.float32)
            em = K[row_of_edge] == k
            idx[local[row_of_edge[em]], col[em]] = src[em]
            ww[local[row_of_edge[em]], col[em]] = w[em]
            self.parts.append((be.i64(idx), be.f32(ww)))
            perm.append(rows)
            self.slots += len(rows) * int(k)
        perm_ = np.concatenate(perm)
        if not np.array_equal(perm_, np.arange(n)):
            self.inv = be.i64(np.argsort(perm_))

    def apply(self, be: Backend, xe: Any) -> Any:
        if not self.parts:
            return be.zeros((int(xe.shape[0]), self.n))
        outs = [be.ell(xe, idx, w) for idx, w in self.parts]
        out = outs[0] if len(outs) == 1 else be.cat1(outs)
        return out if self.inv is None else be.take_cols(out, self.inv)

    def nbytes(self) -> int:
        return int(self.slots * 12 + (self.n * 8 if self.inv is not None else 0))


class LayerRuntime:
    """한 층의 장치 쪽 고정 배열 (입력군 A·B 의 ELL 묶음, min2 표시, L6 이웃 위치)."""

    def __init__(self, spec: LayerSpec, be: Backend, cfg: dict[str, Any]):
        self.spec, self.key, self.src_key = spec, spec.key, spec.src_key
        self.n, self.n_pos, self.n_ch = spec.n, spec.n_pos, spec.n_ch
        self.A = BucketELL(be, spec.a_ptr, spec.a_src, spec.a_w, spec.n_src)
        self.has_b = spec.b_src.size > 0
        self.Bm = BucketELL(be, spec.b_ptr, spec.b_src, spec.b_w, spec.n_src) if self.has_b else None
        self.op_min = be.bool_(spec.op_min) if self.has_b else None
        l6 = cfg["l6"]
        self.l6 = bool(l6["enabled"]) and spec.l6_capable and spec.name in l6["layers"]
        self.include_self = bool(l6["include_self"])
        cnt = np.repeat(spec.pos_nb_count * spec.n_ch, spec.n_ch) - (0 if self.include_self else 1)
        self.nb_count = cnt
        self.n_no_neighbor = int((cnt <= 0).sum())
        self.pos_nb = be.i64(spec.pos_nb)
        self.has_nb = be.bool_(cnt > 0)
        self.nb_div = be.f32(np.maximum(cnt, 1))
        self.missing = be.bool_(spec.missing) if (spec.missing is not None and spec.missing.any()) else None
        self.routing: RoutingRuntime | None = None            # v2 모드의 V4/L2 에만 붙는다
        self.band: BandRuntime | None = None                  # v3 강도 구간 모드의 V4/L2 에만 붙는다
        self.dest: DestRuntime | None = None                  # v4 목적지 선택 모드의 V4/L2 에만 붙는다
        self.ratio: RatioRouter | None = None                 # v6 비율 라우팅 모드의 V4/L2 에만 붙는다 (CSR 대신 선택된 후보만 전달)

    def nbytes(self) -> int:
        b = self.A.nbytes() + (self.Bm.nbytes() if self.Bm is not None else 0)
        return int(b + self.spec.pos_nb.size * 8 + self.n * 5 + (self.routing.nbytes() if self.routing is not None else 0)
                   + (self.band.nbytes() if self.band is not None else 0) + (self.dest.nbytes() if self.dest is not None else 0)
                   + (self.ratio.nbytes() if self.ratio is not None else 0))


class RelativeActivityController:
    """L6: 기존 상대 활동 조절만 한다 (방향 선택적 정규화 풀·적응 없음).

        같은 층의 L6 조절 전 CONF 를 모두 계산한 뒤, 그 같은 스냅샷에서 병렬로
        r_j = CONF_j / (mean_{k∈N(j)} CONF_k + ε)
        g_j = clip(1 + κ·(r_j − 1), g_min, g_max)
        transmitted_j = g_j · CONF_j                    (이웃이 없으면 g_j = 1)
    N(j): 같은 층 (같은 Z) 에서 피질 격자 Chebyshev 거리 ≤ R 인 위치의 모든 채널, 기본 자기 자신 제외 (방향 가중치 없음).
    이웃 합 = Σ_{위치∈N} (위치별 채널 합) − CONF_j. 조절된 값을 분모에 다시 넣지 않고 반복하지 않는다.
    라벨·prototype·미래 표본 정보를 쓰지 않으며 q 를 바꾸지 않는다 (g 는 이번 입력의 일시적 값)."""

    def __init__(self, cfg: dict[str, Any], be: Backend):
        l6 = cfg["l6"]
        self.be = be
        self.eps, self.kappa = float(l6["epsilon"]), float(l6["kappa"])
        self.g_min, self.g_max = float(l6["g_min"]), float(l6["g_max"])

    def gain(self, conf: Any, rt: LayerRuntime) -> Any:
        be = self.be
        B = int(conf.shape[0])
        pos_sum = conf.reshape(B, rt.n_pos, rt.n_ch).sum(-1)                  # (B, n_pos)
        nb_sum = be.take_cols(be.pad_zero_col(pos_sum), rt.pos_nb).sum(-1)    # (B, n_pos)
        nb_n = be.repeat_cols(nb_sum, rt.n_ch)                                # (B, n)
        if not rt.include_self:
            nb_n = be.relu(nb_n - conf)                                       # 부동소수 반올림으로 생긴 음수 제거
        mean = nb_n / rt.nb_div
        r = conf / (mean + self.eps)
        g = be.clip(1.0 + self.kappa * (r - 1.0), self.g_min, self.g_max)
        return be.where(rt.has_nb, g, be.ones_like(g))

    def describe(self) -> dict[str, Any]:
        return {"epsilon": self.eps, "kappa": self.kappa, "g_min": self.g_min, "g_max": self.g_max,
                "formula": FORMULAS["l6"], "applies_to": "각 영역 L2·L3 의 실제 전송 출력 (L4 없음)",
                "uses_labels_or_prototypes": False, "modifies_q": False, "runs_in_frozen_areas": True,
                "freeze_ko": "영역 동결은 지속 q·prototype 갱신 중단이다. L6 g와 실제 출력은 입력마다 재계산한다."}


# ----------------------------------------------------------------------
# 9b. V4 입력 비율 라우터·코드북 학습기·초기화 (v6 모드의 V4/L2 만, v5 참조 이식). V1·V2·IT 는 위 ELL 경로 그대로
# ----------------------------------------------------------------------
class RatioRouter:
    """V4 L4 → L2 목적지 선택 (v6 모드의 V4/L2 에만 붙는다. V1·V2·IT 는 기존 ELL 계산).

        x_g = L4 실제 출력[source_ids[g]] ;  S = Σ x ;  S ≤ min_total → 선택 없음 ;  p = x/S ;  x̂ = p/‖p‖
        score = x̂·c ;  무효 = −∞ ;  k* = argmax (첫 최댓값 = 작은 route_id) ;  u(목적지) = 역할 연산 (기저 가중치 × 실제 L4 값)
    장치 계산: gather (고정 인덱스) → 집단별 배치 행렬곱 (bmm) → 마스크 argmax → 선택 칸 gather → L2 위치로 비교 gather.
    atomic 누적 (index_add·scatter_add) 을 쓰지 않는다. 거대한 [batch, 모든 원천, 모든 목적지, 차원] 텐서를 만들지 않는다 (묶음·집단 조각 단위).
    라벨·클래스 판독기·오차는 인자로 받지 않는다 (함수 서명에 없음)."""

    def __init__(self, table: RouteTable, be: Backend, cfg: dict[str, Any]):
        self.t, self.be = table, be
        ro = cfg["routing"]["ratio_codebook"]
        self.min_total = float(ro["routing_min_total"])
        self.eps = float(ro["norm_epsilon"])
        self.near_tie = float(ro["near_tie_gap"])
        self.dev: list[dict[str, Any]] = []
        for bk in table.buckets:
            self.dev.append({"src": be.i64(bk.src), "legal": be.bool_(bk.legal), "dst": be.i64(bk.dst), "support": be.f32(bk.support),
                             "WA": be.f32(bk.WA), "WB": be.f32(bk.WB) if bk.WB is not None else None,
                             "op_min": be.bool_(bk.op_min) if bk.WB is not None else None,
                             "op_f": be.f32(bk.op_min.astype(np.float32)), "G": bk.G, "K": bk.K, "D": bk.D})
        self.C: list[Any] = [be.f32(np.zeros((bk.G, bk.K, bk.D), np.float32)) for bk in table.buckets]
        self.ok: list[Any] = [be.bool_(np.zeros((bk.G, bk.K), bool)) for bk in table.buckets]
        self.initialized = False
        self.version = 0                                                   # 코드북이 바뀔 때마다 1 증가 (모델 버전 표시용)
        offs = np.concatenate([[0], np.cumsum([bk.G for bk in table.buckets])]).astype(np.int64)
        self.offsets = offs
        self.G_total = int(offs[-1])
        gidx = np.full(table.n_l2, self.G_total, np.int64)                # 후보 없는 집단의 목적지 = 더미 열 (항상 선택 없음)
        for b, bk in enumerate(table.buckets):
            for gl, g in enumerate(bk.groups):
                gidx[table.group_members(int(g))] = offs[b] + gl
        self.l2_gidx_np = gidx
        self.l2_gidx = be.i64(gidx)
        self.l2_ids = be.i64(np.arange(table.n_l2, dtype=np.int64))

    # ---------------------------------------------------------------- 코드북
    def set_codebook(self, C: Sequence[np.ndarray], ok: Sequence[np.ndarray]) -> None:
        if len(C) != len(self.t.buckets) or len(ok) != len(self.t.buckets):
            raise CompatibilityError("코드북 묶음 수가 후보 그래프와 다르다.")
        for b, bk in enumerate(self.t.buckets):
            c_ = np.asarray(C[b], np.float32)
            o_ = np.asarray(ok[b], bool)
            if c_.shape != (bk.G, bk.K, bk.D) or o_.shape != (bk.G, bk.K):
                raise CompatibilityError(f"{self.t.area} 묶음 {b} 코드북 모양 {c_.shape} != {(bk.G, bk.K, bk.D)}")
            if not np.isfinite(c_).all() or (c_ < 0).any() or (o_ & ~bk.legal).any():
                raise CompatibilityError(f"{self.t.area} 묶음 {b} 코드북에 NaN·음수 또는 불법 후보의 유효 표시가 있다.")
            self.C[b] = self.be.f32(c_)
            self.ok[b] = self.be.bool_(o_)
        self.initialized = True
        self.version += 1

    def get_codebook(self) -> tuple[list[np.ndarray], list[np.ndarray]]:
        return ([self.be.to_np(c).astype(np.float32).copy() for c in self.C], [self.be.to_np(o).astype(bool).copy() for o in self.ok])

    def codebook_sha(self) -> str:
        C, ok = self.get_codebook()
        return sha256_array(*(C + ok))

    def nbytes(self) -> int:
        return int(self.t.nbytes() + sum(bk.G * bk.K * bk.D * 4 for bk in self.t.buckets))

    # ---------------------------------------------------------------- 순방향
    def route(self, x4: Any, *, learn: bool = False, detail: bool = False) -> dict[str, Any]:
        """x4: (B, n_L4) 이번 입력의 L4 실제 출력 (비음수). 반환 u (B, n_L2) 와 선택 마스크, 묶음별 기록."""
        be = self.be
        B = int(x4.shape[0])
        xe = be.pad_zero_col(x4)
        recs: list[dict[str, Any]] = []
        with np.errstate(divide="ignore", invalid="ignore", over="ignore"):
            for b, d in enumerate(self.dev):
                recs.append(self._bucket(b, d, xe, B, learn, detail))
        dst_parts = [r["dst_sel"] for r in recs] + [be.full_i64((B, 1), -1)]
        u_parts = [r["u_sel"] for r in recs] + [be.zeros((B, 1))]
        dst_all = be.cat1(dst_parts)
        u_allg = be.cat1(u_parts)
        dj = be.take_cols(dst_all, self.l2_gidx)                                  # (B, n_L2): 그 목적지 집단의 선택 목적지
        mask = dj == self.l2_ids
        u = be.where(mask, be.take_cols(u_allg, self.l2_gidx), be.zeros((B, self.t.n_l2)))
        return {"u": u, "mask": mask, "buckets": recs}

    def _bucket(self, b: int, d: dict[str, Any], xe: Any, B: int, learn: bool, detail: bool) -> dict[str, Any]:
        G, K, D = d["G"], d["K"], d["D"]
        per = max(1, B * (3 * D + 7 * K))
        gc = max(1, min(G, self.be.max_gather // per))
        parts = [self._chunk(b, d, xe, B, g0, min(G, g0 + gc), learn, detail) for g0 in range(0, G, gc)]
        if len(parts) == 1:
            return parts[0]
        out: dict[str, Any] = {}
        for k_ in parts[0]:
            out[k_] = self.be.cat0([p[k_] for p in parts]) if k_ in ("wins", "sums") else self.be.cat1([p[k_] for p in parts])
        return out

    def _chunk(self, b: int, d: dict[str, Any], xe: Any, B: int, g0: int, g1: int, learn: bool, detail: bool) -> dict[str, Any]:
        be = self.be
        K = d["K"]
        xd = xe[:, d["src"][g0:g1]]                                                # (B, Gc, D) 실제 L4 출력 (패딩 0)
        fin_e = be.isfinite(xd)
        neg_e = xd < 0
        bad = ~be.all_last(fin_e) | be.any_last(neg_e)
        xd = be.where(fin_e & ~neg_e, xd, be.zeros_like(xd))
        S = be.sum_last(xd)
        active = (~bad) & (S > self.min_total)
        Ss = be.where(active, S, be.ones_like(S))
        p = xd / Ss[..., None]
        pn = be.norm_last(p)
        clamp = active & (pn <= self.eps)
        xhat = p / be.clamp_min(pn, self.eps)[..., None] * be.as_f32(active)[..., None]
        xt = be.permute(xhat, (1, 0, 2))                                          # (Gc, B, D)
        sc = be.permute(be.bmm(xt, be.permute(self.C[b][g0:g1], (0, 2, 1))), (1, 0, 2))     # (B, Gc, K) = x̂·c
        valid = d["legal"][g0:g1] & self.ok[b][g0:g1]
        ninf = be.full(tuple(sc.shape), -math.inf)
        scm = be.where(valid[None], sc, ninf)
        k = be.argmax_last(scm)
        top1 = be.max_last(scm)
        nval = be.sum_last(be.as_f32(valid))
        has = active & (nval > 0)[None]
        oh = be.onehot_last(k, K)
        top2 = be.max_last(be.where(oh > 0, ninf, scm))
        two = has & (nval >= 2)[None]
        nan_ = be.full(tuple(top1.shape), math.nan)
        gap = be.where(two, top1 - top2, nan_)
        top1 = be.where(has, top1, nan_)
        xr = be.permute(xd, (1, 0, 2))
        uA = be.permute(be.bmm(xr, be.permute(d["WA"][g0:g1], (0, 2, 1))), (1, 0, 2))       # 역할 연산 A 합 (부호 있는 기저 가중치 × 실제 값)
        if d["WB"] is not None:
            uB = be.permute(be.bmm(xr, be.permute(d["WB"][g0:g1], (0, 2, 1))), (1, 0, 2))
            uall = be.where(d["op_min"][g0:g1][None], be.minimum(uA, uB), uA)
            uB_sel = be.gather_last(uB, k)
        else:
            uall = uA
            uB_sel = be.zeros(tuple(k.shape))
        zero = be.zeros(tuple(k.shape))
        u_sel = be.where(has, be.gather_last(uall, k), zero)
        dst_sel = be.where(has, be.take_last(d["dst"][g0:g1], k), be.full_i64(tuple(k.shape), -1))
        dom = be.where(active, be.max_last(xd) / Ss, nan_)
        rec = {"k": k, "has": has, "active": active, "bad": bad, "clamp": clamp, "top1": top1, "gap": gap, "S": S, "dom": dom,
               "u_sel": u_sel, "uA_sel": be.where(has, be.gather_last(uA, k), zero), "uB_sel": be.where(has, uB_sel, zero),
               "op_sel": be.where(has, be.take_last(d["op_f"][g0:g1], k), zero), "dst_sel": dst_sel}
        if learn:
            ohm = oh * be.as_f32(has)[..., None]
            rec["wins"] = be.sum0(ohm)                                            # (Gc, K) 유효 승리 수
            rec["sums"] = be.bmm(be.permute(ohm, (1, 2, 0)), xt)                  # (Gc, K, D) 승리한 x̂ 의 합 (평균은 갱신 때)
        if detail:
            rec.update(xhat=xhat, p=p * be.as_f32(active)[..., None], scores=scm, xd=xd, u_all=uall)
        return rec


class CodebookLearner:
    """V4 국소 대표 벡터 갱신 (배치마다 한 번, 같은 배치의 순방향은 갱신 전 코드북을 썼다).
        v = mean(x̂ | k 승리) ⊙ 지원 ;  n > 0, ‖v‖ > ε → c ← normalize((1 − η)c + η·v/‖v‖) ;  그 밖 c 그대로.
    라벨·판독기·오차·미분을 쓰지 않는다. 미선택 후보는 바뀌지 않는다."""

    def __init__(self, router: RatioRouter, cfg: dict[str, Any]):
        self.r, self.be = router, router.be
        self.eta = float(cfg["routing"]["ratio_codebook"]["eta_codebook"])
        self.eps = float(cfg["routing"]["ratio_codebook"]["norm_epsilon"])

    def update(self, rec_buckets: Sequence[dict[str, Any]]) -> list[dict[str, np.ndarray]]:
        """이번 배치에서 이긴 후보 행만 계산하고, 모든 묶음의 새 코드북을 만든 뒤 한꺼번에 바꾼다 (도중 오류면 이전 코드북 그대로)."""
        be = self.be
        out: list[dict[str, np.ndarray]] = []
        new_C = []
        for b, rec in enumerate(rec_buckets):
            d = self.r.dev[b]
            C = self.r.C[b]
            G, K = d["G"], d["K"]
            n_np = be.to_np(rec["wins"]).astype(np.float64)
            gi, ki = np.nonzero(n_np > 0)
            upd = np.zeros((G, K), bool)
            dl = np.zeros((G, K))
            cs = np.ones((G, K))
            if len(gi) == 0:
                new_C.append(C)
                out.append({"upd": upd, "delta": dl, "cos": cs, "wins": n_np})
                continue
            gt, kt = be.i64(gi), be.i64(ki)
            v = rec["sums"][gt, kt] / be.f32(n_np[gi, ki])[:, None] * d["support"][gt, kt]     # 승리 x̂ 평균 ⊙ 지원
            nv = be.norm_last(v)
            u_ = (nv > self.eps) & d["legal"][gt, kt] & self.r.ok[b][gt, kt]
            vhat = v / be.clamp_min(nv, self.eps)[:, None]
            c0 = C[gt, kt]
            craw = (1.0 - self.eta) * c0 + self.eta * vhat
            cnew = craw / be.clamp_min(be.norm_last(craw), self.eps)[:, None]
            rows = be.where(u_[:, None], cnew, c0)
            if not be.all_finite(rows):
                raise NumericalError(f"{self.r.t.area} 묶음 {b}: 코드북 갱신값에 NaN/Inf (적용하지 않는다)")
            Cn = be.clone(C)
            Cn[gt, kt] = rows                                                      # 서로 다른 칸에만 쓴다 (누적 없음)
            upd[gi, ki] = be.to_np(u_).astype(bool)
            dl[gi, ki] = be.to_np(be.norm_last(rows - c0)).astype(np.float64)
            cs[gi, ki] = be.to_np(be.sum_last(rows * c0)).astype(np.float64)
            new_C.append(Cn)
            out.append({"upd": upd, "delta": dl, "cos": cs, "wins": n_np})
        for b, Cn in enumerate(new_C):
            self.r.C[b] = Cn
        self.r.version += 1
        return out


class CodebookInitializer:
    """학습 단계 시작 시 train 패킷으로 대표 벡터를 만든다 (데이터로부터의 학습 과정, 라벨 미사용, NumPy float64).
    후보마다: 고정 역할 연산 u_k > θ 인 비영 패킷 중 역할 선택도 u_k/S 가 큰 순서로, 같은 집단에서 아직 쓰지 않았고 기존 대표와 방향이
    겹치지 않는 (cos < 1 − tol) 첫 패킷 → c = normalize(x̂ ⊙ 지원). 양의 반응 패킷이 없으면 지원 질량 ‖x̂ ⊙ 지원‖² 최대 패킷 (fallback 기록).
    단위 벡터를 만들 수 없으면 초기화 실패 (경쟁 제외). 강제 균등·반발·무작위 초기화를 하지 않는다."""

    KINDS = {0: "failed", 1: "role_positive_packet", 2: "support_mass_fallback"}

    def __init__(self, router: RatioRouter, cfg: dict[str, Any]):
        ro = cfg["routing"]["ratio_codebook"]
        self.r = router
        self.min_total = float(ro["routing_min_total"])
        self.eps = float(ro["norm_epsilon"])
        self.thr = float(cfg["neuron"]["threshold"])
        self.tol = float(ro["init_duplicate_cos_tol"])
        self.alts = int(ro["init_alternatives"])
        self.max_el = int(cfg["compute"]["max_gather_elements"])

    def run(self, X4: np.ndarray) -> dict[str, Any]:
        t = self.r.t
        N = int(X4.shape[0])
        xs = np.concatenate([np.asarray(X4, np.float64), np.zeros((N, 1))], 1)
        if not np.isfinite(xs).all() or (xs < 0).any():
            raise NumericalError(f"{t.area} 초기화 패킷에 NaN/Inf 또는 음수 L4 값이 있다.")
        C_list, ok_list, info = [], [], []
        for bk in t.buckets:
            G, K, D = bk.G, bk.K, bk.D
            C = np.zeros((G, K, D), np.float32)
            ok = np.zeros((G, K), bool)
            rec = {"init_index": np.full((G, K), -1, np.int64), "init_kind": np.zeros((G, K), np.int8),
                   "init_role_selectivity": np.full((G, K), np.nan, np.float32), "dup_packet": np.zeros((G, K), bool),
                   "dup_direction": np.zeros((G, K), bool), "n_role_positive_packets": np.zeros((G, K), np.int64),
                   "group_active_packets": np.zeros(G, np.int64), "group_distinct_directions": np.zeros(G, np.int64)}
            per = max(1, N * (2 * D + 3 * K))
            gc = max(1, min(G, (self.max_el // 2) // per))
            for g0 in range(0, G, gc):
                g1 = min(G, g0 + gc)
                xd = xs[:, bk.src[g0:g1]]                                         # (N, Gc, D)
                S = xd.sum(-1)
                act = S > self.min_total
                p = xd / np.where(act, S, 1.0)[..., None]
                xh = p / np.maximum(np.linalg.norm(p, axis=-1), self.eps)[..., None] * act[..., None]
                xr = np.transpose(xd, (1, 0, 2))
                uA = np.matmul(xr, np.transpose(bk.WA[g0:g1].astype(np.float64), (0, 2, 1)))        # (Gc, N, K)
                if bk.WB is not None:
                    uB = np.matmul(xr, np.transpose(bk.WB[g0:g1].astype(np.float64), (0, 2, 1)))
                    u = np.where(bk.op_min[g0:g1][:, None, :], np.minimum(uA, uB), uA)
                else:
                    u = uA
                for gl in range(g1 - g0):
                    self._group(g0 + gl, xh[:, gl, :], u[gl], S[:, gl], act[:, gl], bk, C, ok, rec)
            C_list.append(C)
            ok_list.append(ok)
            info.append(rec)
        return {"C": C_list, "ok": ok_list, "info": info, "n_samples": N}

    def _group(self, g: int, xh: np.ndarray, u: np.ndarray, S: np.ndarray, act: np.ndarray, bk: RouteBucket,
               C: np.ndarray, ok: np.ndarray, rec: dict[str, np.ndarray]) -> None:
        N = len(S)
        rec["group_active_packets"][g] = int(act.sum())
        sup = bk.support[g].astype(np.float64)                                     # (K, D)
        mass = (xh * xh) @ sup.T                                                    # (N, K) 지원 위 x̂ 에너지
        sel = np.where(act[:, None], u / np.where(act, S, 1.0)[:, None], -np.inf)
        elig = act[:, None] & (u > self.thr) & (mass > 0)
        used = np.zeros(N, bool)
        codes: list[np.ndarray] = []
        distinct = 0

        def unit(n: int, k: int) -> np.ndarray | None:
            v = xh[n] * sup[k]
            nv = float(np.linalg.norm(v))
            return None if nv <= self.eps else v / nv

        for k in range(bk.K):
            if not bk.legal[g, k]:
                continue
            E = elig[:, k]
            nE = int(E.sum())
            rec["n_role_positive_packets"][g, k] = nE
            pick: tuple[int, np.ndarray] | None = None
            kind = 0
            if nE:
                order = np.argsort(-np.where(E, sel[:, k], -np.inf), kind="stable")[:nE]
                kind = 1
            else:
                F = act & (mass[:, k] > 0)
                nF = int(F.sum())
                order = np.argsort(-np.where(F, mass[:, k], -np.inf), kind="stable")[:nF]
                kind = 2 if nF else 0
            if kind:
                fresh = [int(n) for n in order if not used[n]]
                M = np.stack(codes) if codes else None
                for n in fresh[:self.alts]:
                    c = unit(n, k)
                    if c is not None and (M is None or float((M @ c).max()) < 1.0 - self.tol):
                        pick = (n, c)
                        break
                if pick is None:
                    for n in (fresh[:1] or [int(order[0])]):
                        c = unit(n, k)
                        if c is not None:
                            pick = (n, c)
                if pick is None:
                    kind = 0
            rec["init_kind"][g, k] = kind
            if pick is None:
                continue
            n, c = pick
            dupd = bool(codes) and float((np.stack(codes) @ c).max()) >= 1.0 - self.tol
            rec["dup_packet"][g, k] = bool(used[n])
            rec["dup_direction"][g, k] = dupd
            distinct += 0 if dupd else 1
            used[n] = True
            codes.append(c)
            C[g, k] = c.astype(np.float32)
            ok[g, k] = True
            rec["init_index"][g, k] = n
            rec["init_role_selectivity"][g, k] = float(sel[n, k]) if kind == 1 else np.nan
        rec["group_distinct_directions"][g] = distinct


def codebook_init_summary(t: RouteTable, info: Sequence[dict[str, np.ndarray]], ok: Sequence[np.ndarray]) -> dict[str, Any]:
    """계열별 초기화 결과 (후보 수·실패·fallback·중복 패킷·중복 방향·유효 방향 수)."""
    rows: dict[str, Any] = {}
    for fi, fname in enumerate(t.family_names):
        acc = {"n_legal_candidates": 0, "n_code_ok": 0, "n_failed": 0, "n_role_positive": 0, "n_support_mass_fallback": 0,
               "n_duplicate_packet": 0, "n_duplicate_direction": 0, "n_groups": 0, "n_groups_without_active_packet": 0,
               "sum_distinct_directions": 0, "sum_role_positive_packets": 0}
        for b, bk in enumerate(t.buckets):
            if bk.family != fi:
                continue
            r = info[b]
            lg = bk.legal
            acc["n_legal_candidates"] += int(lg.sum())
            acc["n_code_ok"] += int(ok[b].sum())
            acc["n_failed"] += int((lg & ~ok[b]).sum())
            acc["n_role_positive"] += int(((r["init_kind"] == 1) & lg).sum())
            acc["n_support_mass_fallback"] += int(((r["init_kind"] == 2) & lg).sum())
            acc["n_duplicate_packet"] += int((r["dup_packet"] & lg).sum())
            acc["n_duplicate_direction"] += int((r["dup_direction"] & lg).sum())
            acc["n_groups"] += bk.G
            acc["n_groups_without_active_packet"] += int((r["group_active_packets"] == 0).sum())
            acc["sum_distinct_directions"] += int(r["group_distinct_directions"].sum())
            acc["sum_role_positive_packets"] += int(r["n_role_positive_packets"][lg].sum())
        acc["mean_distinct_directions_per_group"] = acc["sum_distinct_directions"] / acc["n_groups"] if acc["n_groups"] else None
        acc["mean_candidates_per_group"] = acc["n_legal_candidates"] / acc["n_groups"] if acc["n_groups"] else None
        acc["mean_role_positive_packets_per_candidate"] = (acc["sum_role_positive_packets"] / acc["n_legal_candidates"]
                                                           if acc["n_legal_candidates"] else None)
        rows[fname] = acc
    return rows


class CortexModel:
    """영역 (CortexArea: V1/V2/V4/IT) 의 층을 순서대로 이어 계산한다. 감각 회로에 재귀 흥분 연결은 없다.
    forward 는 표본마다 동적 상태 (INPUT 합 u, s, CONF, g, 전송 출력) 를 새로 계산하고 남기지 않는다 (q·prototype 만 유지)."""

    def __init__(self, cfg: dict[str, Any], be: Backend, pre: RetinaLGNPreprocessor):
        self.cfg, self.be, self.pre = cfg, be, pre
        self.store = NeuronStore(be, cfg)
        self.inspector = NeuronInspector(self.store)
        self.specs: dict[str, LayerSpec] = {}
        self.rt: dict[str, LayerRuntime] = {}
        self.areas: list[str] = []
        self.active: str | None = None
        self.struct_hash: dict[str, str] = {}
        self.routers: dict[str, "LocalErrorRouter"] = {}          # v4 그대로: 영역별 L1 교정 배분기 (비율 라우터와 다른 저장소)
        self.ratio_routers: dict[str, "RatioRouter"] = {}          # v6: V4 입력 비율 라우터 (v4_only_ratio_codebook 모드의 V4 만)
        self.area_objs: dict[str, CortexArea] = {}
        self.l6 = RelativeActivityController(cfg, be)
        self.timer: PhaseTimer | None = None

    @property
    def routing_mode(self) -> str:
        return str(self.cfg["routing"]["mode"])

    def routing_runtime(self) -> RoutingRuntime | None:
        rt = self.rt.get("V4/L2")
        return rt.routing if rt is not None else None

    def band_runtime(self) -> BandRuntime | None:
        rt = self.rt.get("V4/L2")
        return rt.band if rt is not None else None

    def dest_runtime(self) -> DestRuntime | None:
        rt = self.rt.get("V4/L2")
        return rt.dest if rt is not None else None

    def ratio_runtime(self) -> "RatioRouter | None":
        rt = self.rt.get("V4/L2")
        return rt.ratio if rt is not None else None

    def plan(self, area: str) -> list[LayerSpec]:
        want = AREA_ORDER[len(self.areas)] if len(self.areas) < len(AREA_ORDER) else None
        if area != want:
            raise StructureError(f"다음에 만들 수 있는 영역은 {want} 이다 (요청 {area}).")
        prev = self.specs.get(f"{self.areas[-1]}/L3") if self.areas else None
        return AREA_CLASSES[area].build(self.cfg, self.pre, prev, dict(self.specs)).specs

    def add_area(self, area: str, specs: Sequence[LayerSpec]) -> None:
        if [sp.area for sp in specs] != [area] * 3 or [sp.name for sp in specs] != list(LAYER_ORDER):
            raise StructureError("영역 층 순서는 L4, L2, L3 이다.")
        self.store.add_layers(specs)
        self.area_objs[area] = AREA_CLASSES[area](specs)
        for sp in specs:
            self.specs[sp.key] = sp
            self.rt[sp.key] = LayerRuntime(sp, self.be, self.cfg)
            if sp.routing is not None:
                gs = GuideSampler(self.specs["V1/L3"], self.pre, self.cfg)
                self.rt[sp.key].routing = RoutingRuntime(sp.routing, self.be, self.cfg, sp.n, gs.n_ch, gs.lum_base, gs.n_o)
            if sp.band is not None:
                self.rt[sp.key].band = BandRuntime(sp.band, self.be, self.cfg, sp.n)
            if sp.dest is not None:
                self.rt[sp.key].dest = DestRuntime(sp.dest, self.be, self.cfg, sp.n)
            if sp.ratio is not None:
                router = RatioRouter(sp.ratio, self.be, self.cfg)
                self.rt[sp.key].ratio = router
                self.ratio_routers[area] = router
        if area == "V4" and self.routing_mode == RATIO_MODE:        # V4 의 q 는 영역별 고정값 (V1·V2·IT 의 q 배열·설정은 건드리지 않는다)
            qf = float(self.cfg["routing"]["ratio_codebook"]["v4_q_fixed"])
            for sp in specs:
                self.be.assign_(self.store.q_view(sp.key), self.be.f32(np.full(sp.n, qf)))
        self.areas.append(area)
        self.struct_hash[area] = area_structure_hash(specs)
        le = self.cfg["learning"]
        self.routers[area] = LocalErrorRouter(specs[1], specs[2], float(le["alpha2"]), float(le["alpha3"]), self.be)

    def layer_keys(self, upto: str | None = None) -> list[str]:
        out = []
        for a in self.areas:
            out += [f"{a}/{n}" for n in LAYER_ORDER]
            if a == upto:
                break
        return out

    def forward(self, lgn: Any, *, upto: str | None = None, keep: Sequence[str] = (),
                override: dict[str, LayerRuntime] | None = None, routing_mode: str | None = None,
                guide_transform: Callable[[Any], Any] | None = None, routing_record: bool = False,
                dest_mask: str | None = None, dest_detail: bool = False, ratio_learn: bool = False,
                ratio_detail: bool = False) -> dict[str, dict[str, Any]]:
        """lgn: (B, n_lgn) LGN 표본 (위치 우선). upto: 이 영역까지 계산 (기본 마지막 영역).
        v6 비율 라우팅 (V4/L2): routing_record 또는 V4/L2 keep 이면 res["V4/L2"]["ratio"] 에 묶음별 선택 기록, ratio_learn=True 이면
        승리 x̂ 합·수 (갱신은 하지 않는다), ratio_detail=True 이면 표본별 입력 비율·후보 점수도 남긴다. 라벨을 받지 않는다.
        반환: 각 영역 L3 의 {"out"} 과 keep 층의 {"u","s","conf","g","out"} (모두 (B, n_layer)). "LGN" 을 keep 하면 입력도 돌려준다.
        라우팅 (새 모드의 V4/L2): 같은 순방향에서 이미 계산한 V1 L3 실제 전송 출력을 안내로 쓴다 (V1 을 다시 실행하지 않음, 라벨 입력 없음).
        routing_mode 로 이 호출만 선택 규칙을 바꿀 수 있고 (진단), guide_transform 은 안내 사본만 바꾼다 (감각 경로는 그대로).
        routing_record=True 또는 V4/L2 를 keep 하면 res["V4/L2"]["routing"] 에 이번 표본들의 선택 (k, 주소, S, A, B) 을 남긴다.
        강도 구간 모드 (v3) 는 res["V4/L2"]["band"] 에 B, all_gates_low, (기록 시) 후보별 x · z · g · 기여 몫을 남긴다.
        routing_mode 가 expanded_pool / band_gated 이면 이 호출만 게이트 규칙을 바꾼다 (같은 동결 모델의 즉각적 민감도 검사용).
        목적지 선택 모드 (v4) 는 res["V4/L2"]["dest"] 에 집단별 선택·점수·동점·1·2 위 차이·곡선 Q*·실제 A/B·u (모두 선택 전 u_all 과 함께) 를 남긴다.
        dest_mask = "all_legal"/"none" 은 검사 전용 마스크, dest_detail=True 는 후보별 점수·표시 가중치·안내 읽기 r 도 남긴다."""
        keep_s = set(keep)
        res: dict[str, dict[str, Any]] = {}
        if "LGN" in keep_s:
            res["LGN"] = {"out": lgn}
        prev_key, prev = "LGN", lgn
        for key in self.layer_keys(upto):
            rt = (override or {}).get(key) or self.rt[key]
            if rt.src_key != prev_key:
                raise StructureError(f"{key} 의 원천 {rt.src_key} 가 직전 층 {prev_key} 와 다르다.")
            rec = bool(routing_record or key in keep_s)
            lay = self.layer_step(key, rt, prev, res, routing_mode=routing_mode, guide_transform=guide_transform, record=rec,
                                  dest_mask=dest_mask, dest_detail=dest_detail, ratio_learn=ratio_learn, ratio_detail=ratio_detail)
            if key in keep_s:
                res[key] = {k_: lay[k_] for k_ in ("u", "s", "conf", "g", "out")}
            elif key.endswith("/L3"):
                res[key] = {"out": lay["out"]}
            for k_ in ("routing", "band", "dest"):
                if rec and lay.get(k_) is not None:
                    res.setdefault(key, {})[k_] = lay[k_]
            if lay.get("ratio") is not None:
                res.setdefault(key, {})["ratio"] = lay["ratio"]
            prev_key, prev = key, lay["out"]
        if "dest" in res.get("V4/L2", {}) and "V4/L3" in res:
            res["V4/L2"]["dest"]["out3"] = res["V4/L3"]["out"]
        return res

    def layer_step(self, key: str, rt: LayerRuntime, prev: Any, res: dict[str, dict[str, Any]], *, routing_mode: str | None = None,
                   guide_transform: Callable[[Any], Any] | None = None, record: bool = False, dest_mask: str | None = None,
                   dest_detail: bool = False, ratio_learn: bool = False, ratio_detail: bool = False) -> dict[str, Any]:
        """한 층의 순방향 (forward 와 구현 검사가 같은 코드를 쓴다). prev = 원천 층 전송 출력 (B, n_src), res = 같은 순방향의 앞 층 결과."""
        be, st = self.be, self.store
        if rt.ratio is not None:                                  # v6 V4/L2: 고정 CSR 전체 입력 대신 집단별로 선택된 후보만 전달 (다시 더하지 않는다)
            gsync_ = bool(self.cfg["compute"]["gpu_timing_sync"]) and be.is_cuda
            tm_ = self.timer.phase("ratio_route", gpu=gsync_) if self.timer is not None else contextlib.nullcontext()
            with tm_:
                rr = rt.ratio.route(prev, learn=ratio_learn, detail=ratio_detail)
            u = rr["u"]
            zero_ = be.zeros(tuple(u.shape))
            s = be.where(rr["mask"], be.relu(u - st.thr_view(key)), zero_)          # 선택되지 않은 목적지: u = s = 0 (명시적 마스크)
            conf = st.q_view(key) * s
            g = self.l6.gain(conf, rt) if rt.l6 else None
            out = conf if g is None else g * conf
            keep_rec = record or ratio_learn or ratio_detail
            if keep_rec:
                rr["u_masked"], rr["s"], rr["out"] = u, s, out
            return {"u": u, "s": s, "conf": conf, "g": g, "out": out, "routing": None, "band": None, "dest": None,
                    "ratio": rr if keep_rec else None}
        xe = be.pad_zero_col(prev)
        sa = rt.A.apply(be, xe)
        sel = bsel = dsel = None
        gsync = bool(self.cfg["compute"]["gpu_timing_sync"]) and be.is_cuda
        if rt.has_b or rt.routing is not None or rt.band is not None or rt.dest is not None:
            sb = rt.Bm.apply(be, xe) if rt.Bm is not None else be.zeros((int(xe.shape[0]), rt.n))
            if rt.routing is not None:
                guide = res["V1/L3"]["out"]
                if guide_transform is not None:
                    guide = guide_transform(guide)
                mode = routing_mode or rt.routing.mode
                tm = self.timer.phase("routing", gpu=gsync) if self.timer is not None else contextlib.nullcontext()
                with tm:
                    sel = rt.routing.select(xe, guide, mode=mode, record=record)
                    sb = sb + be.take_cols(be.pad_zero_col(sel["B"]), rt.routing.curve_map)   # 라우팅 행의 정적 B 는 비어 있다
            if rt.band is not None:
                bmode = routing_mode if routing_mode in BAND_MODES else rt.band.mode
                tm = self.timer.phase("band_gate", gpu=gsync) if self.timer is not None else contextlib.nullcontext()
                with tm:
                    bsel = rt.band.combine(xe, mode=bmode, record=record)
                    sb = sb + be.take_cols(be.pad_zero_col(bsel["B"]), rt.band.curve_map)      # 곡선 행의 정적 B 는 비어 있다
            if rt.dest is not None:
                guide = res["V1/L3"]["out"]                                                     # 같은 순방향의 V1 L3 (다시 실행하지 않음)
                if guide_transform is not None:
                    guide = guide_transform(guide)
                dsel = rt.dest.select(xe, guide, mask_mode=dest_mask, detail=dest_detail, timer=self.timer, gsync=gsync)
                sb = sb + be.take_cols(be.pad_zero_col(dsel["B_curve"]), rt.dest.curve_map)     # 곡선 행의 정적 B 는 비어 있다
            u = be.where(rt.op_min, be.minimum(sa, sb), sa + sb)
            if rt.missing is not None:
                u = be.where(rt.missing, be.zeros(u.shape), u)                                   # missing_candidate: u = 0
        else:
            sb = None
            u = sa
        u_all = u
        if dsel is not None:
            u = be.where(dsel["mask"], u_all, be.zeros(u.shape))                                 # 선택되지 않은 목적지: u = 0
        s = be.relu(u - st.thr_view(key))
        if dsel is not None:
            s = be.where(dsel["mask"], s, be.zeros(s.shape))                                     # 명시적 마스크: 임계값 < 0 이어도 우회 활동 없음
        conf = st.q_view(key) * s
        g = self.l6.gain(conf, rt) if rt.l6 else None
        out = conf if g is None else g * conf
        if sel is not None and record:
            sel["A"] = be.take_cols(sa, rt.routing.curve_rows)
        if bsel is not None and record:
            bsel["A"] = be.take_cols(sa, rt.band.curve_rows)
        if dsel is not None and record:
            dsel.update(A=sa, B=sb, u_all=u_all, u=u, s=s, out=out)
        return {"u": u, "s": s, "conf": conf, "g": g, "out": out, "routing": sel if record else None, "band": bsel if record else None,
                "dest": dsel if record else None}

    def device_bytes(self) -> int:
        return int(sum(rt.nbytes() for rt in self.rt.values()) + self.store.N * 8)


def structure_summary(specs: Sequence[LayerSpec], be: Backend, cfg: dict[str, Any], n_classes: int,
                      existing_bytes: int = 0) -> dict[str, Any]:
    """모델 생성 전에 출력하는 뉴런 수·연결 수·예상 텐서 메모리."""
    B = int(cfg["learning"]["batch_size"])
    rows, total_edges, total_slots, total_n = [], 0, 0, 0
    for sp in specs:
        e = len(sp.a_src) + len(sp.b_src)
        slots = 0
        for ptr in (sp.a_ptr, sp.b_ptr):
            fan = np.diff(ptr)
            nz = fan[fan > 0]
            slots += int(np.left_shift(1, np.ceil(np.log2(nz)).astype(np.int64)).sum()) if nz.size else 0
        total_edges += e
        total_slots += slots
        total_n += sp.n
        rows.append({"layer": sp.key, "n_neurons": sp.n, "positions": sp.n_pos, "channels": sp.n_ch, "edges": e,
                     "fan_in_mean": sp.build_stats.get("fan_in_mean"), "fan_in_max": sp.build_stats.get("fan_in_max"),
                     "n_min2": sp.build_stats.get("n_min2"), "ell_slots": slots})
    graph_mb = (total_slots * 12 + total_n * 8) / 2 ** 20
    act_mb = B * total_n * 4 * 6 / 2 ** 20
    gather_mb = min(int(cfg["compute"]["max_gather_elements"]), max(1, B * total_slots)) * 4 * 2 / 2 ** 20
    proto_mb = n_classes * specs[-1].n * 4 * 2 / 2 ** 20
    rc = cfg["records"]
    diag_mb = (int(rc["diagnostic_samples"]) * total_n * 4 * 6 + int(rc["correction_samples_per_epoch"]) * specs[-1].n * 4 * 3) / 2 ** 20
    return {"layers": rows, "total_neurons": total_n, "total_edges": total_edges, "ell_slots": total_slots,
            "memory_mb": {"graph": round(graph_mb, 2), "batch_activations_upper": round(act_mb, 2),
                          "gather_chunk_upper": round(gather_mb, 2), "prototypes": round(proto_mb, 3),
                          "diagnostic_and_record_buffers": round(diag_mb, 3), "existing_model": round(existing_bytes / 2 ** 20, 2),
                          "total_estimate": round(graph_mb + act_mb + gather_mb + proto_mb + diag_mb + existing_bytes / 2 ** 20, 2)},
            "batch_size": B, "backend": be.kind, "device": be.device,
            "note_ko": "추정치다 (활성 영역은 u·s·CONF·g·out 을 보관, 나머지 층은 출력만 잠시 둔다). 실제 사용량은 장치에서 다르다."}


# ======================================================================
# 10. 클래스별 prototype (PrototypeBank) 과 코사인 분류
# ======================================================================
class PrototypeBank:
    """영역마다 독립 클래스별 prototype (C, n_L3). h = 그 영역 L3 실제 전송 출력 (neuron_id 순서).
    초기화·갱신은 train 출력의 클래스 평균만 쓴다 (dev/test·추론 중 갱신 없음). 영벡터 prototype 은 무효로 표시한다."""

    def __init__(self, area: str, classes: Sequence[str], dim: int, be: Backend, eps: float):
        self.area, self.classes, self.dim, self.be, self.eps = area, list(classes), int(dim), be, float(eps)
        C = len(self.classes)
        self.P = be.zeros((C, self.dim))
        self.valid = np.zeros(C, bool)
        self.counts = np.zeros(C, np.int64)
        self.version = 0
        self.history: list[dict[str, Any]] = []

    def set(self, P_new: Any, counts: np.ndarray, *, source: str, split: str, sample_ids_sha256: str, epoch: int | None,
            rho: float | None) -> dict[str, Any]:
        if split != "train":
            raise RuntimeError("prototype 은 train 출력으로만 만든다.")
        norms = self.be.to_np(self.be.norm_last(P_new)).astype(np.float64)
        old = self.be.to_np(self.P).astype(np.float64)
        new = self.be.to_np(P_new).astype(np.float64)
        self.P = P_new
        self.valid = norms > self.eps
        self.counts = np.asarray(counts, np.int64)
        self.version += 1
        rec = {"version": self.version, "source": source, "split": split, "sample_ids_sha256": sample_ids_sha256, "epoch": epoch,
               "rho": rho, "counts": self.counts.tolist(), "norms": norms.tolist(), "valid": self.valid.tolist(),
               "update_l2": float(np.linalg.norm(new - old)), "utc": utc_now(),
               "invalid_classes": [c for c, v in zip(self.classes, self.valid) if not v]}
        self.history.append(rec)
        return rec

    def targets(self, y: np.ndarray) -> Any:
        return self.be.rows(self.P, self.be.i64(y))

    def sha(self) -> str:
        return sha256_array(self.be.to_np(self.P).astype(np.float32), self.valid)

    def pairwise_cos(self) -> np.ndarray:
        P = self.be.to_np(self.P).astype(np.float64)
        n = np.linalg.norm(P, axis=1)
        C = len(self.classes)
        out = np.full((C, C), np.nan)
        ok = n > self.eps
        if ok.any():
            Pn = P[ok] / n[ok, None]
            out[np.ix_(ok, ok)] = Pn @ Pn.T
        return out


def cosine_classify(be: Backend, h: Any, P: Any, valid_P: np.ndarray, eps: float) -> dict[str, np.ndarray]:
    """pred = argmax_c cos(h, P_c). ‖h‖ ≤ eps → unknown (−1). 무효 prototype 클래스는 후보에서 뺀다. 코사인은 확률이 아니다."""
    hn = be.to_np(be.norm_last(h)).astype(np.float64)
    pn = be.to_np(be.norm_last(P)).astype(np.float64)
    dots = be.to_np(be.matmul_t(h, P)).astype(np.float64)
    B, C = dots.shape
    valid_h = hn > eps
    cv = np.asarray(valid_P, bool) & (pn > eps)
    cos = np.full((B, C), np.nan)
    with np.errstate(divide="ignore", invalid="ignore"):
        if cv.any():
            cos[:, cv] = dots[:, cv] / (hn[:, None] * pn[None, cv])
    cos[~valid_h] = np.nan
    pred = np.full(B, -1, np.int64)
    ties = 0
    for i in range(B):
        if valid_h[i] and cv.any():
            row = cos[i]
            m = np.nanmax(row)
            pred[i] = int(np.nanargmax(row))
            ties += int((np.abs(row[cv] - m) <= 1e-12).sum() > 1)
    return {"cos": cos, "pred": pred, "h_norm": hn, "valid_h": valid_h, "n_ties": np.asarray(ties)}


# ======================================================================
# 10b. V4 판독기 (ClassReadout, v6 모드의 V4 만) — 라우팅 코드북과 별개의 통계. V1·V2·IT 는 위 PrototypeBank 그대로
# ======================================================================
class ClassReadout:
    """P_y = μ_y / ‖μ_y‖, μ_y = mean(h | train, label y) (평가 시점마다 고정 모델로 다시 계산). 코드북과 다른 이름·저장 공간·차원이다.
    클래스 평균이 0 이면 그 클래스는 무효 (분류 후보에서 뺀다). 라벨 y 는 이 판독기의 train 통계와 정확도 평가에만 쓴다."""

    def __init__(self, area: str, classes: Sequence[str], dim: int, be: Backend, eps: float):
        self.area, self.classes, self.dim, self.be, self.eps = area, list(classes), int(dim), be, float(eps)
        C = len(self.classes)
        self.P = be.zeros((C, self.dim))
        self.valid = np.zeros(C, bool)
        self.counts = np.zeros(C, np.int64)
        self.norms = np.zeros(C, np.float64)
        self.version = 0
        self.meta: dict[str, Any] = {}

    def fit(self, sums: Any, counts: np.ndarray, *, split: str, sample_ids_sha256: str, epoch_number: int | None,
            codebook_sha256: str) -> dict[str, Any]:
        if split != "train":
            raise RuntimeError("클래스 판독기는 train 출력으로만 만든다 (dev/test 미사용).")
        be = self.be
        counts = np.asarray(counts, np.int64)
        mu = sums * be.f32((1.0 / np.maximum(counts, 1))[:, None])
        norms = be.to_np(be.norm_last(mu)).astype(np.float64)
        valid = (counts > 0) & (norms > self.eps)
        scale = np.where(valid, 1.0 / np.where(norms > 0, norms, 1.0), 0.0)
        self.P = mu * be.f32(scale[:, None])
        self.valid, self.counts, self.norms = valid, counts, norms
        self.version += 1
        self.meta = {"version": self.version, "split": split, "sample_ids_sha256": sample_ids_sha256, "epoch_number": epoch_number,
                     "codebook_sha256": codebook_sha256, "counts": counts.tolist(), "mean_norms": norms.tolist(), "valid": valid.tolist(),
                     "invalid_classes": [c for c, v in zip(self.classes, valid) if not v], "utc": utc_now()}
        return dict(self.meta)

    def sha(self) -> str:
        return sha256_array(self.be.to_np(self.P).astype(np.float32), self.valid)

    def targets(self, y: np.ndarray) -> Any:
        """평가 인터페이스 호환 (PrototypeBank.targets 와 같은 모양). 단위 벡터라 '거리' 는 참고값이다 (분류는 코사인)."""
        return self.be.rows(self.P, self.be.i64(y))

    def state(self, prefix: str) -> dict[str, np.ndarray]:
        return {f"{prefix}P": self.be.to_np(self.P).astype(np.float32), f"{prefix}valid": self.valid, f"{prefix}counts": self.counts,
                f"{prefix}norms": self.norms}

    def load_state(self, arrays: dict[str, np.ndarray], prefix: str, meta: dict[str, Any]) -> None:
        self.P = self.be.f32(arrays[f"{prefix}P"])
        self.valid = np.asarray(arrays[f"{prefix}valid"], bool)
        self.counts = np.asarray(arrays[f"{prefix}counts"], np.int64)
        self.norms = np.asarray(arrays[f"{prefix}norms"], np.float64)
        self.meta = dict(meta or {})
        self.version = int(self.meta.get("version", 0))

    def copy(self) -> "ClassReadout":
        r = ClassReadout(self.area, self.classes, self.dim, self.be, self.eps)
        r.P, r.valid, r.counts, r.norms = self.be.clone(self.P), self.valid.copy(), self.counts.copy(), self.norms.copy()
        r.version, r.meta = self.version, copy.deepcopy(self.meta)
        return r

    def pairwise_cos(self) -> np.ndarray:
        P = self.be.to_np(self.P).astype(np.float64)
        C = len(self.classes)
        out = np.full((C, C), np.nan)
        if self.valid.any():
            Pv = P[self.valid]
            out[np.ix_(self.valid, self.valid)] = Pv @ Pv.T
        return out


# ======================================================================
# 10c. V4 라우팅 집계 (전체 데이터) — 표본 몇 개의 기록을 전체 통계처럼 쓰지 않는다
# ======================================================================
ROUTE_STAT_KEYS = ("n_eval", "n_active", "n_has", "n_active_no_sel", "n_bad", "n_clamp", "n_sel_zero_out", "sum_top1", "n_gap", "sum_gap",
                   "n_tie", "n_near_tie", "sum_dom", "n_min2_sel", "n_A_only", "n_B_only", "n_both", "n_neither")
ROUTE_REC_KEYS = ("k", "has", "active", "bad", "clamp", "top1", "gap", "S", "dom", "u_sel", "uA_sel", "uB_sel", "op_sel", "dst_sel")
LAYER_STAT_KEYS = ("n_samples", "n_zero_vec", "n_active", "n_elements", "n_g_max", "n_g_min", "n_g", "n_g_max_active", "n_g_min_active", "sum_norm")


def route_rec_np(be: Backend, recs: Sequence[dict[str, Any]]) -> list[dict[str, np.ndarray]]:
    return [{k: be.to_np(r[k]) for k in ROUTE_REC_KEYS} for r in recs]


def layer_reduce(be: Backend, lay: dict[str, Any], g_min: float, g_max: float, vector: bool) -> dict[str, Any]:
    out, s, g = lay["out"], lay["s"], lay.get("g")
    B, n = int(out.shape[0]), int(out.shape[1])
    nrm = be.norm_last(out)
    r = {"n_samples": B, "n_zero_vec": float(be.to_np(be.as_f32(nrm <= 0).sum())), "n_active": float(be.to_np(be.as_f32(s > 0).sum())),
         "n_elements": B * n, "sum_norm": float(be.to_np(nrm.sum()))}
    if g is not None:
        act = s > 0
        hi, lo = g >= g_max - 1e-7, g <= g_min + 1e-7
        r.update(n_g=B * n, n_g_max=float(be.to_np(be.as_f32(hi).sum())), n_g_min=float(be.to_np(be.as_f32(lo).sum())),
                 n_g_max_active=float(be.to_np(be.as_f32(hi & act).sum())), n_g_min_active=float(be.to_np(be.as_f32(lo & act).sum())))
    if vector:
        r["vsum"] = be.to_np(be.sum0(out)).astype(np.float64)
        r["vsq"] = be.to_np(be.sum0(out * out)).astype(np.float64)
    return r


class RouteStats:
    """영역·묶음별 (G,) 합계와 후보별 승리 수 (G,K), 층별 영벡터·활성·L6 clip·출력 노름 (+ 판독 층 분산). 체크포인트에 저장·복원된다."""

    def __init__(self, model: "CortexModel", areas: Sequence[str]):
        self.model = model
        self.areas = list(areas)
        self.thr = float(model.cfg["neuron"]["threshold"])
        self.near = float(model.cfg["routing"]["ratio_codebook"]["near_tie_gap"])
        self.g: dict[str, list[dict[str, np.ndarray]]] = {}
        self.wins: dict[str, list[np.ndarray]] = {}
        self.n_samples: dict[str, int] = {}
        for a in self.areas:
            t = model.ratio_routers[a].t
            self.g[a] = [{k: np.zeros(bk.G, np.float64) for k in ROUTE_STAT_KEYS} for bk in t.buckets]
            self.wins[a] = [np.zeros((bk.G, bk.K), np.int64) for bk in t.buckets]
            self.n_samples[a] = 0
        self.layers: dict[str, dict[str, Any]] = {}

    def add_route(self, area: str, recs: Sequence[dict[str, np.ndarray]]) -> None:
        B = 0
        for b, r in enumerate(recs):
            acc = self.g[area][b]
            has, act = r["has"].astype(bool), r["active"].astype(bool)
            B = has.shape[0]
            K = self.wins[area][b].shape[1]
            G = has.shape[1]
            acc["n_eval"] += B
            acc["n_active"] += act.sum(0)
            acc["n_has"] += has.sum(0)
            acc["n_active_no_sel"] += (act & ~has).sum(0)
            acc["n_bad"] += r["bad"].astype(bool).sum(0)
            acc["n_clamp"] += r["clamp"].astype(bool).sum(0)
            acc["n_sel_zero_out"] += (has & (r["u_sel"] <= self.thr)).sum(0)
            acc["sum_top1"] += np.where(has, r["top1"], 0.0).sum(0)
            gap = r["gap"].astype(np.float64)
            two = has & np.isfinite(gap)
            acc["n_gap"] += two.sum(0)
            acc["sum_gap"] += np.where(two, gap, 0.0).sum(0)
            acc["n_tie"] += (two & (gap == 0.0)).sum(0)
            acc["n_near_tie"] += (two & (gap < self.near)).sum(0)
            acc["sum_dom"] += np.where(act, r["dom"], 0.0).sum(0)
            m2 = has & (r["op_sel"] > 0.5)
            a_, b_ = r["uA_sel"] > 0, r["uB_sel"] > 0
            acc["n_min2_sel"] += m2.sum(0)
            acc["n_A_only"] += (m2 & a_ & ~b_).sum(0)
            acc["n_B_only"] += (m2 & ~a_ & b_).sum(0)
            acc["n_both"] += (m2 & a_ & b_).sum(0)
            acc["n_neither"] += (m2 & ~a_ & ~b_).sum(0)
            gi = np.broadcast_to(np.arange(G)[None, :], has.shape)
            flat = (gi[has] * K + r["k"][has].astype(np.int64))
            self.wins[area][b] += np.bincount(flat, minlength=G * K).reshape(G, K)
        self.n_samples[area] += B

    def add_layer(self, key: str, red: dict[str, Any]) -> None:
        cur = self.layers.setdefault(key, {k: 0.0 for k in LAYER_STAT_KEYS})
        for k in LAYER_STAT_KEYS:
            cur[k] = cur.get(k, 0.0) + float(red.get(k, 0.0))
        if "vsum" in red:
            cur["vsum"] = cur.get("vsum", 0.0) + red["vsum"]
            cur["vsq"] = cur.get("vsq", 0.0) + red["vsq"]

    # ---------------------------------------------------------------- 저장·복원 (에폭 중간 재개)
    def state(self, prefix: str) -> dict[str, np.ndarray]:
        out: dict[str, np.ndarray] = {}
        for a in self.areas:
            out[f"{prefix}ns__{a}"] = np.asarray(self.n_samples[a], np.int64)
            for b, acc in enumerate(self.g[a]):
                for k, v in acc.items():
                    out[f"{prefix}g__{a}__{b}__{k}"] = v
                out[f"{prefix}w__{a}__{b}"] = self.wins[a][b]
        for key, cur in self.layers.items():
            kk = key.replace("/", "_")
            for k in LAYER_STAT_KEYS:
                out[f"{prefix}L__{kk}__{k}"] = np.asarray(cur.get(k, 0.0), np.float64)
            if "vsum" in cur:
                out[f"{prefix}L__{kk}__vsum"] = np.asarray(cur["vsum"], np.float64)
                out[f"{prefix}L__{kk}__vsq"] = np.asarray(cur["vsq"], np.float64)
        return out

    def load_state(self, arrays: dict[str, np.ndarray], prefix: str) -> None:
        for a in self.areas:
            if f"{prefix}ns__{a}" not in arrays:
                continue
            self.n_samples[a] = int(arrays[f"{prefix}ns__{a}"])
            for b, acc in enumerate(self.g[a]):
                for k in acc:
                    acc[k] = np.asarray(arrays[f"{prefix}g__{a}__{b}__{k}"], np.float64).copy()
                self.wins[a][b] = np.asarray(arrays[f"{prefix}w__{a}__{b}"], np.int64).copy()
        for name in arrays:
            if name.startswith(f"{prefix}L__"):
                kk, k = name[len(prefix) + 3:].rsplit("__", 1)
                key = kk.replace("_", "/", 1)
                cur = self.layers.setdefault(key, {})
                cur[k] = np.asarray(arrays[name], np.float64).copy() if k in ("vsum", "vsq") else float(arrays[name])

    # ---------------------------------------------------------------- 요약
    def family_rows(self, area: str) -> dict[str, dict[str, Any]]:
        router = self.model.ratio_routers[area]
        t = router.t
        _C, ok = router.get_codebook()
        rows: dict[str, dict[str, Any]] = {}
        for fi, fname in enumerate(t.family_names):
            tot = {k: 0.0 for k in ROUTE_STAT_KEYS}
            ent, eff, mx, unused, nvalid, never, mono, n_used_groups = [], [], [], 0, 0, 0, 0, 0
            for b, bk in enumerate(t.buckets):
                if bk.family != fi:
                    continue
                for k in ROUTE_STAT_KEYS:
                    tot[k] += float(self.g[area][b][k].sum())
                W = self.wins[area][b]
                V = bk.legal & ok[b]
                for gl in range(bk.G):
                    v = V[gl]
                    nv = int(v.sum())
                    if nv == 0:
                        continue
                    w = W[gl][v].astype(np.float64)
                    nvalid += nv
                    unused += int((w == 0).sum())
                    s = float(w.sum())
                    if s <= 0:
                        never += 1
                        continue
                    n_used_groups += 1
                    p = w / s
                    h = float(-(p[p > 0] * np.log(p[p > 0])).sum())
                    ent.append(h)
                    eff.append(math.exp(h))
                    mx.append(float(p.max()))
                    mono += int(p.max() >= 0.9 and s >= 10)
            ne, na, nh = tot["n_eval"], tot["n_active"], tot["n_has"]
            rows[fname] = {
                "group_evaluations": int(ne), "active_input_frac": (na / ne) if ne else None, "selected_frac": (nh / ne) if ne else None,
                "nonzero_input_but_no_selection_frac": (tot["n_active_no_sel"] / na) if na else None,
                "nonfinite_or_negative_frac": (tot["n_bad"] / ne) if ne else None, "norm_clamp_count": int(tot["n_clamp"]),
                "selected_but_zero_output_frac": (tot["n_sel_zero_out"] / nh) if nh else None,
                "mean_max_cosine": (tot["sum_top1"] / nh) if nh else None,
                "mean_1_minus_max_cosine": (1.0 - tot["sum_top1"] / nh) if nh else None,
                "mean_top1_minus_top2": (tot["sum_gap"] / tot["n_gap"]) if tot["n_gap"] else None,
                "exact_tie_frac": (tot["n_tie"] / tot["n_gap"]) if tot["n_gap"] else None,
                "near_tie_frac": (tot["n_near_tie"] / tot["n_gap"]) if tot["n_gap"] else None,
                "mean_dominance_max_over_sum": (tot["sum_dom"] / na) if na else None,
                "min2_selected": int(tot["n_min2_sel"]),
                "min2_A_only_frac": (tot["n_A_only"] / tot["n_min2_sel"]) if tot["n_min2_sel"] else None,
                "min2_B_only_frac": (tot["n_B_only"] / tot["n_min2_sel"]) if tot["n_min2_sel"] else None,
                "min2_both_frac": (tot["n_both"] / tot["n_min2_sel"]) if tot["n_min2_sel"] else None,
                "min2_neither_frac": (tot["n_neither"] / tot["n_min2_sel"]) if tot["n_min2_sel"] else None,
                "valid_candidates": nvalid, "unused_candidate_frac": (unused / nvalid) if nvalid else None,
                "groups_never_selected": never, "mean_usage_entropy_nats": float(np.mean(ent)) if ent else None,
                "mean_effective_used_candidates": float(np.mean(eff)) if eff else None, "mean_max_usage_share": float(np.mean(mx)) if mx else None,
                "monopoly_groups_frac": (mono / n_used_groups) if n_used_groups else None}
        return rows

    def layer_rows(self) -> dict[str, dict[str, Any]]:
        out = {}
        for key, c in self.layers.items():
            ns, ne = c.get("n_samples", 0.0), c.get("n_elements", 0.0)
            row = {"zero_vector_frac": (c["n_zero_vec"] / ns) if ns else None, "active_neuron_frac": (c["n_active"] / ne) if ne else None,
                   "mean_output_norm": (c["sum_norm"] / ns) if ns else None,
                   "L6_g_at_max_frac": (c["n_g_max"] / c["n_g"]) if c.get("n_g") else None,
                   "L6_g_at_min_frac": (c["n_g_min"] / c["n_g"]) if c.get("n_g") else None,
                   "L6_g_at_max_frac_of_active": (c.get("n_g_max_active", 0.0) / c["n_active"]) if c.get("n_g") and c.get("n_active") else None,
                   "L6_g_at_min_frac_of_active": (c.get("n_g_min_active", 0.0) / c["n_active"]) if c.get("n_g") and c.get("n_active") else None}
            if "vsum" in c and ns:
                m = np.asarray(c["vsum"]) / ns
                row["output_variance_mean"] = float(np.maximum(np.asarray(c["vsq"]) / ns - m * m, 0.0).mean())
            out[key] = row
        return out


# ======================================================================
# 11. 교정: LocalErrorRouter → L1Relay → LocalOutputLearner
# ======================================================================
class LocalErrorRouter:
    """영역 수준 교정 배분기. 결과를 L1 패킷으로 넘긴다 (L5/L6 는 오차를 계산·배달하지 않는다).

        δ = prototype_true − h                                   (B, n3)  — StageTrainer 가 계산, L3 neuron_id 순서
        m_L3[:, j] = α3 · δ[:, j]                                (B, n3)
        m_L2[:, i] = α2 · Σ_{j : i ∈ P(j)} δ[:, j] / |P(j)|      (B, n2)   즉 m_L2 = α2 · R δ,  R_ij = 1/|P(j)| (i ∈ P(j))
    P(j) = L3 뉴런 j 의 실제 L2 부모 집합 (L3 의 CSR 입력 목록에서 주소만 읽는다; 가중치·전치·미분·복원기·무작위 피드백 미사용).
    일대일 구간이면 R 은 대응 항등 배달이다. 이 배분은 부호·비선형·상쇄를 역산하지 않는다 (위치 배달 ≠ 유익한 교정)."""

    def __init__(self, spec2: LayerSpec, spec3: LayerSpec, alpha2: float, alpha3: float, be: Backend):
        if spec3.src_key != spec2.key:
            raise StructureError(f"{spec3.key} 의 원천이 {spec2.key} 가 아니다.")
        self.be, self.alpha2, self.alpha3 = be, float(alpha2), float(alpha3)
        self.area = spec3.area
        n2, n3 = spec2.n, spec3.n
        rows = np.concatenate([np.repeat(np.arange(n3, dtype=np.int64), np.diff(spec3.a_ptr)),
                               np.repeat(np.arange(n3, dtype=np.int64), np.diff(spec3.b_ptr))])
        src = np.concatenate([spec3.a_src, spec3.b_src])
        pairs = np.unique(rows * np.int64(n2) + src)
        prow, psrc = pairs // n2, pairs % n2
        cnt = np.bincount(prow, minlength=n3)
        if (cnt == 0).any():
            raise StructureError(f"{spec3.key}: 부모 없는 L3 출력 {int((cnt == 0).sum())} 개 (오류)")
        coef = 1.0 / cnt[prow]
        order = np.argsort(psrc, kind="stable")
        ch_cnt = np.bincount(psrc, minlength=n2)
        Kc = max(int(ch_cnt.max()), 1)
        ptr = np.concatenate([[0], np.cumsum(ch_cnt)])
        col = np.arange(len(order)) - ptr[psrc[order]]
        ch_idx = np.full((n2, Kc), n3, np.int64)
        ch_coef = np.zeros((n2, Kc), np.float32)
        ch_idx[psrc[order], col] = prow[order]
        ch_coef[psrc[order], col] = coef[order]
        self.parent_rows, self.parent_src = prow, psrc
        self.parent_count, self.child_count = cnt, ch_cnt
        self.R_col_sum = np.bincount(prow, weights=coef, minlength=n3)
        self.one_to_one = bool((cnt == 1).all() and (ch_cnt <= 1).all())
        self.n2_without_child = int((ch_cnt == 0).sum())
        self.ch_idx_np, self.ch_coef_np = ch_idx, ch_coef
        self.ch_idx, self.ch_coef = be.i64(ch_idx), be.f32(ch_coef)

    def route(self, delta: Any) -> tuple[Any, Any]:
        be = self.be
        m3 = self.alpha3 * delta
        m2 = self.alpha2 * (be.take_cols(be.pad_zero_col(delta), self.ch_idx) * self.ch_coef).sum(-1)
        return m2, m3

    def describe(self) -> dict[str, Any]:
        pc = self.parent_count
        return {"formula": FORMULAS["router"], "alpha2": self.alpha2, "alpha3": self.alpha3, "one_to_one": self.one_to_one,
                "parents_per_L3": {"min": int(pc.min()), "max": int(pc.max()), "mean": float(pc.mean())},
                "children_per_L2": {"min": int(self.child_count.min()), "max": int(self.child_count.max())},
                "L2_without_L3_child": self.n2_without_child,
                "R_column_sum_max_abs_error": float(np.abs(self.R_col_sum - 1.0).max())}


@dataclass
class L1Packet:
    area: str
    layer: str
    start: int
    end: int
    ids_sha256: str
    m: Any
    batch_size: int
    sample_ids_sha256: str
    model_version: str
    kind: str = "teacher_correction"          # 감각 입력 경로와 구분되는 교사 (prototype 비교) 경로


class L1Relay:
    """L1: 교정 배분기가 계산한 m_L2·m_L3 를 layer_id·neuron_id 범위·모양을 확인해 해당 층 q 학습기로 배달하는 논리 구획.
    거대한 세포체 집단이 아니라 수신 뉴런별 교정 버퍼 (패킷의 m 행) 와 명시적 주소로 나타낸 근사다. 오차를 계산하지 않는다.
    패킷은 배치마다 새로 만들고 남기지 않는다."""

    def __init__(self, area: str, store: NeuronStore):
        self.area = area
        self.addr = {}
        for lay in ("L2", "L3"):
            sp = store.layers[f"{area}/{lay}"]
            self.addr[lay] = (sp.start, sp.end, store.ids_sha(sp.key), sp.n)
        self.delivered = 0
        self.rejected = 0

    def packet(self, layer: str, m: Any, sample_sha: str, version: str) -> L1Packet:
        start, end, sha, _n = self.addr[layer]
        return L1Packet(self.area, layer, start, end, sha, m, int(m.shape[0]), sample_sha, version)

    def deliver(self, pkt: L1Packet, batch_size: int, be: Backend) -> Any:
        def reject(why: str) -> None:
            self.rejected += 1
            raise L1AddressError(f"L1 배달 거부 ({self.area}): {why}")
        if pkt.area != self.area:
            reject(f"영역 {pkt.area} != {self.area}")
        if pkt.layer not in self.addr:
            reject(f"층 {pkt.layer} 은 교정 대상이 아니다 (L2/L3 만)")
        start, end, sha, n = self.addr[pkt.layer]
        if (pkt.start, pkt.end, pkt.ids_sha256) != (start, end, sha):
            reject("neuron_id 범위·해시 불일치")
        if tuple(int(s) for s in pkt.m.shape) != (int(batch_size), int(n)):
            reject(f"모양 {tuple(pkt.m.shape)} != ({batch_size}, {n})")
        if not be.all_finite(pkt.m):
            reject("NaN/Inf")
        self.delivered += 1
        return pkt.m


def _scalar(be: Backend, x: Any) -> float:
    return float(np.asarray(be.to_np(x)).reshape(-1)[0]) if not isinstance(x, (int, float)) else float(x)


class LocalOutputLearner:
    """국소 지속 파라미터 갱신 (local_update).

        e_j  = s_j / (s_j + e0)                         s_j: 같은 순방향 스냅샷의 L6 조절 전 국소 활동 (B, n), e0 > 0
        Δq_j = η · mean_batch(e_j · m_j)
        q_j  ← clip(q_j + Δq_j, q_min, q_max)
    L2·L3 의 Δq 를 같은 스냅샷에서 모두 계산한 뒤 동시에 적용한다. m = 0 이면 Δq = 0 (정확히).
    별도 감쇠·항상성 갱신·eta_commit·임계값 변경·숨은 배율이 없다. e 는 표본의 활동 표시이며 STDP·칼슘 흔적이 아니다."""

    def __init__(self, cfg: dict[str, Any], be: Backend, store: NeuronStore):
        le, ne = cfg["learning"], cfg["neuron"]
        self.be, self.store = be, store
        self.eta, self.e0 = float(le["eta"]), float(le["e0"])
        self.q_min, self.q_max = float(ne["q_min"]), float(ne["q_max"])

    def proposal(self, s: Any, m: Any) -> Any:
        e = s / (s + self.e0)
        return self.eta * self.be.mean0(e * m)

    def apply(self, proposals: dict[str, Any]) -> dict[str, dict[str, float]]:
        be = self.be
        olds = {k: be.clone(self.store.q_view(k)) for k in proposals}
        raws = {k: olds[k] + dq for k, dq in proposals.items()}
        news = {k: be.clip(raws[k], self.q_min, self.q_max) for k in proposals}
        stats: dict[str, dict[str, float]] = {}
        for k in proposals:
            if not be.all_finite(news[k]):
                raise FloatingPointError(f"{k}: q 갱신값에 NaN/Inf (적용하지 않는다)")
            d = news[k] - olds[k]
            stats[k] = {"dq_raw_l2": _scalar(be, be.norm_last(proposals[k])), "dq_applied_l2": _scalar(be, be.norm_last(d)),
                        "dq_raw_abs_max": _scalar(be, abs(proposals[k]).max()),
                        "n_clip_low": _scalar(be, (raws[k] < self.q_min).sum()), "n_clip_high": _scalar(be, (raws[k] > self.q_max).sum()),
                        "n_at_min": _scalar(be, (news[k] <= self.q_min).sum()), "n_at_max": _scalar(be, (news[k] >= self.q_max).sum()),
                        "n_changed": _scalar(be, (d != 0).sum()), "q_mean": _scalar(be, news[k].mean()),
                        "q_min": _scalar(be, news[k].min()), "q_max": _scalar(be, news[k].max())}
        for k in proposals:
            be.assign_(self.store.q_view(k), news[k])
        return stats


# ======================================================================
# 12. 세션 상태·기록·checkpoint (StageTrainer 가 쓰는 공통 상태)
# ======================================================================
def new_stage_state(area: str, cfg: dict[str, Any]) -> dict[str, Any]:
    le = cfg["learning"]
    return {"area": area, "status": "not_started", "epochs_completed": 0, "phase": "training", "next_batch": 0,
            "max_epochs": int(le["max_epochs"]), "patience": int(le["patience"]), "min_delta": float(le["min_delta"]),
            "success_dev_accuracy": le["success_dev_accuracy"], "best_dev_accuracy": None, "best_epoch": None, "bad_epochs": 0,
            "acc": empty_acc(), "dist_start_vs_P": None, "history": [], "corr_saved": 0, "corr_epoch_saved": 0,
            "transitions": [], "started_utc": None, "ended_utc": None, "budget_changes": [], "start_eval": None,
            "routing_acc": {}, "route_epoch_saved": 0, "route_saved": 0, "structure_sha_at_creation": None,
            "band_epoch_saved": 0, "band_saved": 0, "dest_epoch_saved": 0, "dest_saved": 0, **copy.deepcopy(RATIO_STAGE_KEYS)}


def empty_acc() -> dict[str, float]:
    keys = ["n_batches", "n_samples", "n_valid", "n_skipped_invalid_proto", "sum_d0", "sum_d1", "sum_c0", "sum_c1",
            "n_improved", "n_worsened", "n_unchanged", "sum_cos_dh_delta", "n_cos_dh_delta", "n_dh_zero",
            "sum_mag_err", "sum_abs_mag_err", "sum_ang_err", "n_ang", "sum_delta_norm"]
    for lay in ("L2", "L3"):
        keys += [f"{lay}_{k}" for k in ("sum_dq_raw_l2", "sum_dq_applied_l2", "sum_clip_low", "sum_clip_high", "sum_n_changed",
                                        "last_at_min", "last_at_max", "sum_active_frac", "sum_s_mean", "sum_g_min_frac",
                                        "sum_g_max_frac", "sum_conf_mean")]
    return {k: 0.0 for k in keys}


def _numel(x: Any) -> int:
    return int(np.prod([int(s) for s in x.shape]))


# ======================================================================
# 12b. v6 V4 비율 라우팅 세션 기능 (RatioSessionMixin) — v4 Session 에 V4 전용 경로만 더한다
#      V1·V2·IT 의 prototype·q·L1 경로는 Session 의 기존 메서드를 그대로 쓴다.
# ======================================================================
TRAINING_METRICS_CSV = "training_metrics.csv"
ROUTING_CSV = "routing_metrics.csv"
CODEBOOK_CSV = "codebook_metrics.csv"
ROLE_CSV = "role_probe_metrics.csv"
UPD_KEYS = ("n_upd", "sum_delta", "max_delta", "sum_angle", "max_angle")
RATIO_STAGE_KEYS: dict[str, Any] = {"selected_epoch_number": None, "selected_restored": False, "best_epoch_number": None, "stage_policy": None,
                                    "ratio_detail_epoch_saved": 0, "ratio_detail_saved": 0, "codebook_init": None, "completion": None,
                                    "n_nonfinite_events": 0, "ratio_phase_note": None}


def empty_update_acc(t: RouteTable) -> list[dict[str, np.ndarray]]:
    return [{"n_upd": np.zeros((bk.G, bk.K), np.int64), "sum_delta": np.zeros((bk.G, bk.K)), "max_delta": np.zeros((bk.G, bk.K)),
             "sum_angle": np.zeros((bk.G, bk.K)), "max_angle": np.zeros((bk.G, bk.K))} for bk in t.buckets]


class RatioSessionMixin:
    """v4_only_ratio_codebook 모드의 V4 전용 상태: 코드북 (라우터 안), V4 판독기 (readouts), dev 최선 스냅샷 (ratio_best),
    에폭 학습 집계 (ratio_epoch_stats·ratio_upd_acc), 상세 경로 기록 (ratio_buf). 다른 모드·영역에서는 비어 있다."""

    # ---------------------------------------------------------------- 상태 판단
    @property
    def ratio_mode(self) -> bool:
        return self.cfg["routing"]["mode"] == RATIO_MODE

    def is_ratio_area(self, area: str | None) -> bool:
        return bool(self.ratio_mode and area == "V4" and self.model is not None and "V4" in self.model.ratio_routers)

    def ratio_router(self) -> RatioRouter | None:
        return self.model.ratio_routers.get("V4") if self.model is not None else None

    def classifier(self, area: str) -> Any:
        """평가용 판독 객체: v6 모드의 V4 는 ClassReadout (코드북과 별개), 그 밖은 기존 PrototypeBank."""
        if area in self.readouts:
            return self.readouts[area]
        return self.protos[area]

    def stage_policy(self, area: str) -> str:
        return "dev_best_snapshot" if (self.ratio_mode and area == "V4") else "end_state"

    def codebook_sha(self) -> str | None:
        rr = self.ratio_router()
        if rr is None:
            return None
        if self._cb_sha_cache[0] != rr.version or self._cb_sha_cache[2] is not rr:
            self._cb_sha_cache = (rr.version, rr.codebook_sha(), rr)
        return self._cb_sha_cache[1]

    # ---------------------------------------------------------------- V4 생성 (코드북 초기화 → 판독기 → epoch 0 기준 평가 → checkpoint)
    def build_ratio_area(self, area: str, specs: list[LayerSpec], summary: dict[str, Any]) -> dict[str, Any]:
        r = self.need_rec()
        acc0 = dict(self.loader.access) if self.loader is not None else {}
        self.model.add_area(area, specs)
        self.model.active = area
        st = new_stage_state(area, self.cfg)
        st["stage_policy"] = self.stage_policy(area)
        self.stage[area] = st
        r.json(f"structure/{area}_plan_summary.json", summary)
        arrs: dict[str, np.ndarray] = {}
        for sp in specs:
            for nm in ("a_ptr", "a_src", "a_w", "b_ptr", "b_src", "b_w", "op_min", "x", "y", "rf", "pos_nb", "pos_nb_count"):
                arrs[f"{sp.name}__{nm}"] = getattr(sp, nm)
        r.npz(f"structure/{area}_structure.npz", **arrs)
        self.write_architecture()
        self.write_structure_json()
        self.write_ratio_static(area)
        st["structure_sha_at_creation"] = self.model.struct_hash[area]
        try:
            init = self.ratio_init_codebook(area)
        except KeyboardInterrupt:
            r.json(f"codebook/init_{area}_INCOMPLETE.json", {"utc": utc_now(), "area": area, "status": "interrupted",
                                                              "note_ko": "코드북 초기화 중 중단: 부분 상태를 정상 코드북으로 쓰지 않는다. 마지막 checkpoint "
                                                                         "(V4 생성 전) 에서 다시 V4 를 추가한다."})
            r.append_jsonl("stage_transitions.jsonl", {"utc": utc_now(), "kind": "ratio_init_interrupted", "area": area})
            raise
        acc1 = dict(self.loader.access)
        self.ratio_best = None
        self.ratio_epoch_stats, self.ratio_upd_acc = None, None
        row = self.ratio_epoch_evaluation(area, 0, "init_baseline")
        row.update(stage_status="created", best_dev_accuracy_so_far=row["dev_accuracy"], patience_counter=0, selected_epoch_so_far=0)
        st.update(start_eval=row, best_dev_accuracy=row["dev_accuracy"], best_epoch=-1, best_epoch_number=0)
        self.ratio_update_best(area, 0, row)
        self.sync_training_csv()
        acc2 = dict(self.loader.access)
        r.json(f"structure/{area}_data_access.json", {
            "utc": utc_now(), "area": area, "before_creation": acc0, "after_codebook_init": acc1, "after_baseline_eval": acc2,
            "codebook_init_delta": {k: acc1.get(k, 0) - acc0.get(k, 0) for k in acc1},
            "baseline_eval_delta": {k: acc2.get(k, 0) - acc1.get(k, 0) for k in acc2},
            "rule_ko": "후보 그래프·집단은 구조만으로 만든다 (데이터 미사용). 코드북 초기화·판독기는 train 만, 기준 평가는 train·dev 만 읽는다 (test 0)."})
        self.save_checkpoint(f"{area}_created", keep=True)
        r.info(f"{area} 생성 (비율 라우팅): 구조 해시 {self.model.struct_hash[area][:12]}, 코드북 초기화 {init['n_samples']} 표본, "
               f"epoch 0 dev {pct_count(row['dev_correct'], row['dev_n'])}", echo=False)
        ro = self.readouts[area]
        return {"kind": "ratio_codebook", "init": init, "baseline": row, "counts": ro.counts.tolist(), "norms": [float(v) for v in ro.norms],
                "invalid_classes": ro.meta.get("invalid_classes", [])}

    def write_structure_json(self) -> None:
        """structure.json: 영역별 층·뉴런 수·연결·학습 방식, V4 (v6 모드) 의 후보 그래프 요약 (구조에서 센 값)."""
        r = self.need_rec()
        m = self.model
        out: dict[str, Any] = {"program": PROGRAM, "program_version": VERSION, "routing_mode": self.cfg["routing"]["mode"], "utc": utc_now(),
                               "areas_built": m.areas, "total_neurons": m.store.N, "stage_policy_ko": STAGE_POLICY_KO, "areas": {}}
        for a in m.areas:
            layers = {}
            for lay in LAYER_ORDER:
                sp = m.specs[f"{a}/{lay}"]
                rt = m.rt[sp.key]
                layers[lay] = {"layer": sp.key, "neuron_id_range": [sp.start, sp.end], "n_neurons": sp.n, "n_positions": sp.n_pos,
                               "n_channels": sp.n_ch, "grid_shape": list(sp.grid_shape) if sp.grid_shape else None, "source": sp.src_key,
                               "edges": int(len(sp.a_src) + len(sp.b_src)), "fan_in_mean": sp.build_stats.get("fan_in_mean"),
                               "fan_in_max": sp.build_stats.get("fan_in_max"), "n_min2": sp.build_stats.get("n_min2"),
                               "l6_applied": rt.l6, "structure_sha256": sp.hash()}
            ratio = self.ratio_mode and a == "V4" and "V4" in m.ratio_routers
            row: dict[str, Any] = {"layers": layers, "structure_sha256": m.struct_hash[a],
                                   "learning_ko": ("V4 라우팅 대표 벡터 c[g,k] 만 (q 고정 = %s, L1·q 갱신 없음)" % self.cfg["routing"]["ratio_codebook"]["v4_q_fixed"]
                                                   if ratio else "기존 v4: L1 국소 교정 → L2·L3 q 갱신, prototype 원시 평균 + ρ EMA"),
                                   "stage_policy": self.stage_policy(a)}
            if ratio:
                t = m.ratio_routers["V4"].t
                row["routing"] = route_table_summary(t, m.specs["V4/L4"], m.specs["V4/L2"], m.specs["V4/L3"], int(self.cfg["learning"]["batch_size"]))
                row["routing"]["removed_curve_options_by_condition_ko"] = CURVE_REASONS_KO
            out["areas"][a] = row
        r.json("structure.json", out)

    def write_ratio_static(self, area: str) -> None:
        r = self.need_rec()
        m = self.model
        t = m.ratio_routers[area].t
        l4, l2 = m.specs[f"{area}/L4"], m.specs[f"{area}/L2"]
        r.npz(f"structure/candidates_{area}.npz", **candidate_records(t, l4, l2))
        rem = (l2.ropt_removed or {}).get("curve_by_ring") or {}
        if rem:
            buf = io.StringIO()
            rows = [{"ring": int(k), **v} for k, v in rem.items()]
            w = csv.DictWriter(buf, fieldnames=list(rows[0]))
            w.writeheader()
            for row in rows:
                w.writerow(row)
            r.text("structure/V4_curve_removed_by_ring.csv", buf.getvalue())
        s = route_table_summary(t, l4, l2, m.specs[f"{area}/L3"], int(self.cfg["learning"]["batch_size"]))
        r.info(f"{area} 비율 라우팅 후보 그래프: 집단 {s['n_groups']} (후보 없는 집단 {s['groups_without_legal_candidate']}), 후보 레코드 "
               f"{s['n_candidate_records']} (합법 {s['n_legal_candidates']}, 탈락 {s['n_rejected_candidates']}), 후보 없는 목적지 "
               f"{s['destinations_without_legal_candidate']}, Σ K·D {s['sum_K_times_D']}", echo=True)

    def ratio_init_codebook(self, area: str) -> dict[str, Any]:
        """train 만 min(init_samples, n_train) 장 (고정 seed, 라벨 미사용) 의 V4 L4 패킷으로 대표 벡터를 만든다. V1·V2 는 동결 상태로 한 번만 통과."""
        r = self.need_rec()
        rc = self.cfg["routing"]["ratio_codebook"]
        train = self.data.items("train")
        n = min(int(rc["init_samples"]), len(train))
        seed = [int(self.cfg["seed"]), int(rc["init_seed_offset"]), AREA_INDEX[area]]
        rng = np.random.default_rng(seed)
        idx = np.sort(rng.choice(len(train), size=n, replace=False)) if n else np.zeros(0, np.int64)
        items = [train[int(i)] for i in idx]
        B = int(self.cfg["learning"]["batch_size"])
        key4 = f"{area}/L4"
        prev_area = self.model.areas[self.model.areas.index(area) - 1]
        X4 = []
        t0 = time.perf_counter()
        with self.timer.phase("codebook_init"):
            for a in range(0, n, B):
                lgn, _y = self.loader.batch(items[a:a + B], "train")
                res = self.model.forward(lgn, upto=prev_area)                          # V1·V2 출력 재사용 → V4 L4 만 한 번 더 계산
                lay = self.model.layer_step(key4, self.model.rt[key4], res[f"{prev_area}/L3"]["out"], res)
                X4.append(self.be.to_np(lay["out"]).astype(np.float32))
        X4a = np.concatenate(X4) if X4 else np.zeros((0, self.model.specs[key4].n), np.float32)
        router = self.model.ratio_routers[area]
        out = CodebookInitializer(router, self.cfg).run(X4a)
        router.set_codebook(out["C"], out["ok"])
        self.ratio_init_codes = [c.copy() for c in out["C"]]
        t = router.t
        summ = codebook_init_summary(t, out["info"], out["ok"])
        arrays: dict[str, np.ndarray] = {"sample_index_in_train": idx.astype(np.int64), "sample_id": np.asarray([it["relpath"] for it in items]),
                                         "kinds": np.asarray(dumps(CodebookInitializer.KINDS, indent=None))}
        for b in range(len(t.buckets)):
            arrays[f"b{b}__C"] = out["C"][b]
            arrays[f"b{b}__ok"] = out["ok"][b]
            arrays[f"b{b}__route_id"] = t.buckets[b].route
            for k_, v_ in out["info"][b].items():
                arrays[f"b{b}__{k_}"] = v_
        r.npz(f"codebook/init_{area}.npz", **arrays)
        meta = {"utc": utc_now(), "area": area, "split": "train", "labels_used": False, "dev_used": False, "test_used": False,
                "n_samples": n, "n_train": len(train), "seed": seed, "collection_ko": "동결된 V1·V2 를 통과한 V4 L4 실제 출력 (V4 L2 미계산)",
                "sample_ids_sha256": sha256_text("\n".join(it["relpath"] for it in items)),
                "method_ko": FORMULAS["ratio_init"], "kinds": CodebookInitializer.KINDS, "families": summ,
                "seconds": round(time.perf_counter() - t0, 3), "codebook_sha256": router.codebook_sha(),
                "note_ko": "이 초기화도 train 데이터로부터 대표 벡터를 정한 학습 과정이다 (라벨은 쓰지 않았다). 중복·실패·fallback 수를 그대로 기록한다."}
        r.json(f"codebook/init_{area}.json", meta)
        for fam, row in summ.items():
            r.append_csv(CODEBOOK_CSV, {"utc": meta["utc"], "area": area, "epoch_number": 0, "context": "init", "family": fam, **row})
        self.stage[area]["codebook_init"] = {"n_samples": n, "sample_ids_sha256": meta["sample_ids_sha256"], "families": summ,
                                             "codebook_sha256": meta["codebook_sha256"], "seed": seed}
        return {"n_samples": n, "families": summ, "seconds": meta["seconds"]}

    # ---------------------------------------------------------------- V4 판독기·평가
    def _classify_H(self, H: np.ndarray, Y: np.ndarray, ro: Any) -> dict[str, Any]:
        be = self.be
        C = len(self.classes)
        eps = float(self.cfg["learning"]["eps_norm"])
        out = {"n": int(len(Y)), "correct": 0, "n_unknown": 0, "per_class_n": np.bincount(Y, minlength=C).astype(np.int64),
               "per_class_correct": np.zeros(C, np.int64)}
        for a in range(0, len(Y), 4096):
            cl = cosine_classify(be, be.f32(H[a:a + 4096]), ro.P, ro.valid, eps)
            y = Y[a:a + 4096]
            ok = cl["pred"] == y
            out["correct"] += int(ok.sum())
            out["n_unknown"] += int((cl["pred"] < 0).sum())
            np.add.at(out["per_class_correct"], y[ok], 1)
        return out

    def ratio_fit_readout(self, area: str, epoch_number: int) -> tuple[ClassReadout, dict[str, Any], dict[str, Any]]:
        """고정 코드북으로 train 클래스 평균을 다시 계산한다 (dev/test 미사용). train 정확도는 같은 판독기 (저장한 H 또는 두 번째 순방향)."""
        store_h = self.can_store_h(area)
        with self.timer.phase("readout_fit"):
            tp = self.pass_split(area, "train", collect_h=store_h)
        ro = ClassReadout(area, self.classes, self.model.specs[f"{area}/L3"].n, self.be, float(self.cfg["learning"]["eps_norm"]))
        meta = ro.fit(tp["sums"], tp["counts"], split="train", sample_ids_sha256=tp["ids_sha"], epoch_number=epoch_number,
                      codebook_sha256=self.codebook_sha() or "")
        prev = self.readouts.get(area)
        ro.version = (prev.version if prev is not None else 0) + 1
        meta["version"] = ro.meta["version"] = ro.version
        self.counters["readout_fits"] = int(self.counters.get("readout_fits", 0)) + 1
        with self.timer.phase("train_accuracy"):
            if store_h:
                tr = self._classify_H(tp["H"], tp["Y"], ro)
            else:
                t2 = self.pass_split(area, "train", bank=ro)
                tr = {"n": t2["n"], "correct": t2["correct"], "n_unknown": t2["n_unknown"], "per_class_n": t2["per_class_n"],
                      "per_class_correct": t2["per_class_correct"]}
        tr["train_h_stored_in_memory"] = bool(store_h)
        meta["train_zero_vector_frac"] = 1.0 - tp["n_valid_h"] / max(1, tp["n"])
        return ro, meta, tr

    def ratio_epoch_evaluation(self, area: str, epoch_number: int, row_kind: str) -> dict[str, Any]:
        """초기화 직후 (epoch_number 0) 또는 에폭 끝: 같은 코드북 스냅샷으로 V4 판독기 재계산 → train·dev 평가. dev 에는 갱신이 없다."""
        r = self.need_rec()
        ro, meta, tr = self.ratio_fit_readout(area, epoch_number)
        self.readouts[area] = ro
        r.npz(f"readout/{area}_e{epoch_number:03d}.npz", **ro.state(""), classes=np.asarray(self.classes))
        r.json(f"readout/{area}_e{epoch_number:03d}.json", meta)
        with self.timer.phase("dev_eval"):
            dv = self.evaluate(area, "dev", ro, purpose=f"{area}_e{epoch_number}_dev")
        rt_ = dv.get("ratio") or {}
        dl = (rt_.get("layers") or {}).get(f"{area}/L3", {})
        dl2 = (rt_.get("layers") or {}).get(f"{area}/L2", {})
        C = len(self.classes)
        row: dict[str, Any] = {
            "utc": utc_now(), "area": area, "epoch": epoch_number - 1, "epoch_number": epoch_number, "row_kind": row_kind,
            "row_kind_ko": ("초기화 코드북 + train 판독기 (코드북 갱신 전 기준, 라벨은 판독기 통계에만 사용)" if row_kind == "init_baseline"
                            else "에폭 학습 뒤 같은 코드북 스냅샷의 train 판독기 재계산 + 평가"),
            "learning_rule": "v4_codebook_winner_mean", "routing_mode": self.cfg["routing"]["mode"], "model_version": self.model_version(area),
            "readout_version": ro.version, "codebook_version": self.model.ratio_routers[area].version, "codebook_sha256": self.codebook_sha(),
            "train_n": tr["n"], "train_correct": tr["correct"], "train_accuracy": (tr["correct"] / tr["n"]) if tr["n"] else None,
            "train_acc_vs_epoch_prototype": (tr["correct"] / tr["n"]) if tr["n"] else None, "train_correct_vs_epoch_prototype": tr["correct"],
            "train_unclassifiable": tr["n_unknown"],
            "dev_n": dv["n"], "dev_correct": dv["correct"], "dev_accuracy": dv["accuracy_overall"],
            "dev_accuracy_valid_only": dv["accuracy_valid_only"], "dev_n_unknown_zero_vector": dv["n_unknown_zero_vector"],
            "dev_n_ties": dv["n_ties"], "dev_mean_margin": dv["mean_margin"], "dev_mean_cos_to_true_class": dv["mean_cos_to_true_prototype"],
            "readout_invalid_classes": meta["invalid_classes"], "train_zero_vector_fraction": meta["train_zero_vector_frac"],
            "dev_zero_vector_fraction": dv["geometry"].get("zero_vector_fraction"), "dev_output_variance": dv["geometry"].get("output_variance_mean"),
            "dev_output_norm_mean": dv["geometry"].get("output_norm_mean"),
            "dev_within_class_cos": dv["geometry"].get("within_class_mean_cos_to_class_mean"),
            "dev_between_class_cos": dv["geometry"].get("between_class_mean_cos"),
            "dev_L3_zero_vector_frac": dl.get("zero_vector_frac"), "dev_L3_active_frac": dl.get("active_neuron_frac"),
            "dev_L2_zero_vector_frac": dl2.get("zero_vector_frac"), "dev_L2_active_frac": dl2.get("active_neuron_frac"),
            "dev_L2_g_at_max_frac_of_active": dl2.get("L6_g_at_max_frac_of_active"), "dev_L3_g_at_max_frac_of_active": dl.get("L6_g_at_max_frac_of_active"),
            "dev_per_class_accuracy": dv["per_class_accuracy"], "dev_confusion": dv["confusion"],
            "train_per_class_accuracy": {c: (int(tr["per_class_correct"][i]) / int(tr["per_class_n"][i])) if tr["per_class_n"][i] else None
                                         for i, c in enumerate(self.classes)} if C else None,
            "max_gather_elements_now": self.be.max_gather, "cache_mb": round(self.loader.cache_bytes / 2 ** 20, 3),
            "loader_train_reads": self.loader.access.get("train"), "loader_dev_reads": self.loader.access.get("dev"),
            "loader_test_reads": self.loader.access.get("test"), "dev_evaluations": self.counters["dev_evaluations"],
            "test_evaluations": self.counters["test_evaluations"], "readout_fits": self.counters.get("readout_fits", 0),
            "v4_q_fixed": float(self.cfg["routing"]["ratio_codebook"]["v4_q_fixed"])}
        row.update(self.timer.take())
        if self.be.is_cuda:
            row["gpu_max_memory_allocated_mb"] = round(torch.cuda.max_memory_allocated(self.be.dev) / 2 ** 20, 1)
            torch.cuda.reset_peak_memory_stats(self.be.dev)
        ctx = "dev_init_baseline" if row_kind == "init_baseline" else "dev_eval"
        self.write_ratio_routing_rows(area, epoch_number, ctx, dv.get("ratio"), frozen=False)
        if self.ratio_epoch_stats is not None and row_kind == "epoch":
            fr = self.ratio_epoch_stats.family_rows("V4")
            self.write_ratio_routing_rows(area, epoch_number, "train_epoch_learning",
                                          {"families": fr, "layers": self.ratio_epoch_stats.layer_rows()}, frozen=False)
            for fam, frow in fr.items():
                for k_ in ("selected_frac", "selected_but_zero_output_frac", "unused_candidate_frac", "mean_max_cosine", "monopoly_groups_frac"):
                    row[f"train_{fam}_{k_}"] = frow.get(k_)
            rt0 = self.model.ratio_routers["V4"].t
            r.npz(f"codebook/usage_{area}_e{epoch_number:03d}.npz",
                  **{f"b{b}__wins_train": w for b, w in enumerate(self.ratio_epoch_stats.wins["V4"])},
                  **{f"b{b}__route_id": bk.route for b, bk in enumerate(rt0.buckets)},
                  **{f"b{b}__wins_dev": w for b, w in enumerate((rt_.get("wins") or [np.zeros((bk.G, bk.K), np.int64) for bk in rt0.buckets]))},
                  note=np.asarray("wins_train = 이 에폭 학습 배치 (갱신 전 코드북으로 순방향) 의 후보별 선택 횟수, wins_dev = dev 평가, route_id = 후보 칸 (−1 패딩)"))
            self.write_codebook_epoch_rows(area, epoch_number)
        for fam, frow in ((rt_.get("families") or {}).items()):
            for k_ in ("selected_frac", "selected_but_zero_output_frac", "unused_candidate_frac", "mean_max_cosine"):
                row[f"dev_{fam}_{k_}"] = frow.get(k_)
        return row

    def write_ratio_routing_rows(self, active: str, epoch_number: int, ctx: str, rr: dict[str, Any] | None, *, frozen: bool) -> None:
        if not rr:
            return
        r = self.need_rec()
        utc = utc_now()
        for fam, frow in (rr.get("families") or {}).items():
            r.append_csv(ROUTING_CSV, {"utc": utc, "active_area": active, "epoch_number": epoch_number, "context": ctx, "area": "V4",
                                       "family": fam, "frozen": frozen, "model_version": self.model_version(active), **frow})
        for key, lrow in (rr.get("layers") or {}).items():
            r.append_csv(ROUTING_CSV, {"utc": utc, "active_area": active, "epoch_number": epoch_number, "context": ctx,
                                       "area": key.split("/")[0], "family": f"layer_{key.split('/')[1]}", "frozen": frozen,
                                       "model_version": self.model_version(active), **lrow})

    def write_codebook_epoch_rows(self, area: str, epoch_number: int) -> None:
        """codebook_metrics.csv: 이번 에폭 갱신 노름·각도, 갱신된 후보 수, 초기값 대비 각도 (계열별)."""
        r = self.need_rec()
        router = self.model.ratio_routers[area]
        t = router.t
        C, ok = router.get_codebook()
        init = self.ratio_init_codes
        for fi, fam in enumerate(t.family_names):
            n_upd = s_d = s_a = 0.0
            m_d = m_a = 0.0
            n_cand_upd = n_valid = 0
            drift: list[float] = []
            for b, bk in enumerate(t.buckets):
                if bk.family != fi:
                    continue
                ua = self.ratio_upd_acc[b] if self.ratio_upd_acc else None
                v = bk.legal & ok[b]
                n_valid += int(v.sum())
                if ua is not None:
                    n_upd += float(ua["n_upd"].sum())
                    s_d += float(ua["sum_delta"].sum())
                    s_a += float(ua["sum_angle"].sum())
                    m_d = max(m_d, float(ua["max_delta"].max()) if ua["max_delta"].size else 0.0)
                    m_a = max(m_a, float(ua["max_angle"].max()) if ua["max_angle"].size else 0.0)
                    n_cand_upd += int((ua["n_upd"] > 0).sum())
                if init is not None:
                    cs = np.clip((C[b].astype(np.float64) * init[b].astype(np.float64)).sum(-1), -1.0, 1.0)
                    drift += list(np.degrees(np.arccos(cs[v])))
            r.append_csv(CODEBOOK_CSV, {"utc": utc_now(), "area": area, "epoch_number": epoch_number, "context": "epoch_updates", "family": fam,
                                        "valid_candidates": n_valid, "candidate_updates": int(n_upd), "candidates_updated_at_least_once": n_cand_upd,
                                        "candidates_updated_frac": (n_cand_upd / n_valid) if n_valid else None,
                                        "mean_update_norm": (s_d / n_upd) if n_upd else None, "max_update_norm": m_d,
                                        "mean_update_angle_deg": (s_a / n_upd) if n_upd else None, "max_update_angle_deg": m_a,
                                        "mean_angle_from_init_deg": float(np.mean(drift)) if drift else None,
                                        "max_angle_from_init_deg": float(np.max(drift)) if drift else None,
                                        "codebook_version": router.version})

    # ---------------------------------------------------------------- dev 최선 스냅샷 (V4 만)
    def ratio_update_best(self, area: str, epoch_number: int, row: dict[str, Any]) -> None:
        router = self.model.ratio_routers[area]
        C, ok = router.get_codebook()
        self.ratio_best = {"area": area, "epoch_number": int(epoch_number), "C": C, "ok": ok, "readout": self.readouts[area].copy(),
                           "dev_accuracy": row.get("dev_accuracy"), "dev_correct": row.get("dev_correct"), "dev_n": row.get("dev_n"),
                           "codebook_sha256": sha256_array(*(C + ok)), "codebook_version": router.version,
                           "readout_sha256": self.readouts[area].sha(), "utc": utc_now()}
        arrays = {f"b{b}__C": c for b, c in enumerate(C)} | {f"b{b}__ok": o for b, o in enumerate(ok)}
        arrays.update(self.readouts[area].state("readout__"))
        self.need_rec().npz(f"codebook/best_{area}.npz", **arrays, epoch_number=np.asarray(int(epoch_number)),
                            codebook_sha256=np.asarray(self.ratio_best["codebook_sha256"]))

    def ratio_restore_selected(self, area: str, reason: str) -> dict[str, Any]:
        """dev 최선 시점 (동률 → 이른 시점, epoch 0 포함) 의 코드북·판독기 쌍으로 되돌린다. IT 는 이 상태에서 시작한다."""
        st = self.stage[area]
        b = self.ratio_best
        if b is None or b["area"] != area:
            raise RuntimeError(f"{area} 의 dev 최선 스냅샷이 없다 (V4 생성이 끝나지 않았다).")
        router = self.model.ratio_routers[area]
        router.set_codebook(b["C"], b["ok"])
        self.readouts[area] = b["readout"].copy()
        if self.codebook_sha() != b["codebook_sha256"] or self.readouts[area].sha() != b["readout_sha256"]:
            raise CompatibilityError("최선 스냅샷 복원 뒤 코드북·판독기 해시가 기록과 다르다.")
        st["selected_epoch_number"] = b["epoch_number"]
        st["selected_restored"] = True
        info = {"utc": utc_now(), "area": area, "selected_epoch_number": b["epoch_number"], "selected_dev_accuracy": b["dev_accuracy"],
                "selected_dev_correct": b.get("dev_correct"), "selected_dev_n": b.get("dev_n"),
                "codebook_sha256": b["codebook_sha256"], "readout_sha256": b["readout_sha256"], "reason": reason, "stage_status": st["status"],
                "epochs_completed": st["epochs_completed"], "policy": "dev_best_snapshot",
                "note_ko": "epoch_number 0 = 초기화 직후 (코드북 갱신 전). 선택 기준 = dev 정확도, 동률이면 더 이른 시점."}
        st["completion"] = info
        self.need_rec().append_jsonl("stage_transitions.jsonl", {"kind": "ratio_restore_selected", **info})
        return info

    # ---------------------------------------------------------------- 상세 경로 기록 (소수 표본) → routes/ → sample_routes.npz
    def ratio_detail_records(self, recs: Sequence[dict[str, Any]], x4: np.ndarray, items: Sequence[dict[str, Any]], y: np.ndarray,
                             n: int, epoch: int, batch: int, context: str) -> list[dict[str, Any]]:
        be = self.be
        t = self.model.ratio_routers["V4"].t
        l4s, l2s = self.model.specs["V4/L4"].start, self.model.specs["V4/L2"].start
        npb = [{k: be.to_np(v) for k, v in rec.items() if k in ("k", "has", "S", "top1", "gap", "dom", "scores", "xhat")} for rec in recs]
        out = []
        for i in range(min(n, len(items))):
            es, ed, er, esl, ew, ex = [], [], [], [], [], []
            per_b = []
            for b, bk in enumerate(t.buckets):
                d = npb[b]
                per_b.append({"k": d["k"][i], "has": d["has"][i], "S": d["S"][i], "top1": d["top1"][i], "gap": d["gap"][i], "dom": d["dom"][i],
                              "scores": np.where(np.isfinite(d["scores"][i]), d["scores"][i], np.nan), "xhat": d["xhat"][i]})
                for gl in np.nonzero(d["has"][i])[0]:
                    rid = int(bk.route[gl, int(d["k"][i, gl])])
                    s_, sl_, w_ = t.route_edges(rid)
                    es.append(l4s + s_)
                    ed.append(np.full(len(s_), l2s + int(t.r_dst[rid])))
                    er.append(np.full(len(s_), rid))
                    esl.append(sl_)
                    ew.append(w_)
                    ex.append(x4[i, s_])
            cat = lambda xs, dt: np.concatenate(xs).astype(dt) if xs else np.zeros(0, dt)     # noqa: E731
            e_x = cat(ex, np.float32)
            e_w = cat(ew, np.float32)
            out.append({"area": "V4", "epoch": epoch, "batch": batch, "sample_id": items[i]["relpath"], "label": int(y[i]), "context": context,
                        "b": per_b, "e_src": cat(es, np.int64), "e_dst": cat(ed, np.int64), "e_route": cat(er, np.int64),
                        "e_slot": cat(esl, np.int8), "e_w": e_w, "e_x": e_x, "e_val": e_w * e_x})
        return out

    def flush_ratio_details(self) -> None:
        if not self.ratio_buf:
            return
        r = self.need_rec()
        groups: dict[tuple[str, int], list[dict[str, Any]]] = {}
        for c in self.ratio_buf:
            groups.setdefault((c["area"], c["epoch"]), []).append(c)
        t = self.model.ratio_routers["V4"].t
        for (area, ep), rows in groups.items():
            k = len(list(r.p("routes").glob(f"sample_routes_{area}_e{ep:03d}_part*.npz")))
            arr: dict[str, np.ndarray] = {"sample_id": np.asarray([x["sample_id"] for x in rows]),
                                          "batch_index": np.asarray([x["batch"] for x in rows], np.int64),
                                          "label_recorded_not_used_for_routing": np.asarray([x["label"] for x in rows], np.int64),
                                          "context": np.asarray([x["context"] for x in rows]),
                                          "delivered_ptr": np.concatenate([[0], np.cumsum([len(x["e_src"]) for x in rows])]).astype(np.int64),
                                          "delivered_src_L4_id": np.concatenate([x["e_src"] for x in rows]).astype(np.int64),
                                          "delivered_dst_L2_id": np.concatenate([x["e_dst"] for x in rows]).astype(np.int64),
                                          "delivered_route_id": np.concatenate([x["e_route"] for x in rows]).astype(np.int64),
                                          "delivered_slot": np.concatenate([x["e_slot"] for x in rows]).astype(np.int8),
                                          "delivered_base_weight": np.concatenate([x["e_w"] for x in rows]).astype(np.float32),
                                          "delivered_L4_output": np.concatenate([x["e_x"] for x in rows]).astype(np.float32),
                                          "delivered_value": np.concatenate([x["e_val"] for x in rows]).astype(np.float32)}
            for b, bk in enumerate(t.buckets):
                arr[f"b{b}__route_id"] = bk.route
                arr[f"b{b}__source_L4_local"] = bk.src
                arr[f"b{b}__group_id"] = bk.groups
                for key_ in ("k", "has", "S", "top1", "gap", "dom"):
                    arr[f"b{b}__{key_}"] = np.stack([x["b"][b][key_] for x in rows])
                arr[f"b{b}__scores_f16"] = np.stack([x["b"][b]["scores"] for x in rows]).astype(np.float16)
                arr[f"b{b}__xhat_f16"] = np.stack([x["b"][b]["xhat"] for x in rows]).astype(np.float16)
            arr["note"] = np.asarray("표본별 상세 (지정한 소수 표본): 묶음별 집단 S·선택 칸 k·최고 점수·1·2위 차·우세도, 후보별 점수·입력 방향 x̂ (float16), "
                                     "실제 전달 edge (기저 가중치 × V4 L4 출력). 라벨은 기록만 하며 라우팅에 쓰지 않았다. 후보에만 있는 edge 는 넣지 않는다.")
            r.npz(f"routes/sample_routes_{area}_e{ep:03d}_part{k:03d}.npz", **arr)
        self.ratio_buf = []

    def consolidate_sample_routes(self) -> Path | None:
        """routes/ 조각을 sample_routes.npz 하나로 모은다 (키 앞에 조각 이름). 조각이 없으면 빈 색인만 쓴다."""
        r = self.need_rec()
        parts = sorted(r.p("routes").glob("sample_routes_*_part*.npz"))
        arr: dict[str, np.ndarray] = {"parts": np.asarray([p.stem for p in parts])}
        for p in parts:
            for k, v in load_npz(p).items():
                arr[f"{p.stem}__{k}"] = v
        arr["readme"] = np.asarray("키 = <조각 이름>__<배열>. 조각 이름 sample_routes_V4_e<에폭 번호>_part<번호>. V4 학습 배치의 지정 표본 상세 기록 "
                                   "(v6 비율 라우팅 모드만; 다른 모드는 routing/ 의 기존 기록).")
        return r.npz("sample_routes.npz", **arr)

    # ---------------------------------------------------------------- checkpoint 상태
    def ratio_checkpoint_arrays(self) -> dict[str, np.ndarray]:
        out: dict[str, np.ndarray] = {}
        rr = self.ratio_router()
        if rr is None:
            return out
        C, ok = rr.get_codebook()
        for b in range(len(C)):
            out[f"ratio__C__{b}"], out[f"ratio__ok__{b}"] = C[b], ok[b]
        for a, ro in self.readouts.items():
            out.update(ro.state(f"readout__{a}__"))
        if self.ratio_best is not None:
            for b in range(len(self.ratio_best["C"])):
                out[f"ratio_best__C__{b}"], out[f"ratio_best__ok__{b}"] = self.ratio_best["C"][b], self.ratio_best["ok"][b]
            out.update(self.ratio_best["readout"].state("ratio_best__readout__"))
        if self.ratio_init_codes is not None:
            for b, c in enumerate(self.ratio_init_codes):
                out[f"ratio_init__C__{b}"] = c
        if self.ratio_upd_acc is not None:
            for b, ua in enumerate(self.ratio_upd_acc):
                for k, v in ua.items():
                    out[f"ratio_upd__{b}__{k}"] = v
        if self.ratio_epoch_stats is not None:
            out.update(self.ratio_epoch_stats.state("ratio_es__"))
        return out

    def ratio_checkpoint_meta(self) -> dict[str, Any] | None:
        rr = self.ratio_router()
        if rr is None:
            return None
        t = rr.t
        b = self.ratio_best
        return {"mode": RATIO_MODE, "params": self.cfg["routing"]["ratio_codebook"], "table_sha256": t.hash(),
                "codebook_sha256": self.codebook_sha(), "codebook_version": rr.version, "codebook_initialized": rr.initialized,
                "n_buckets": len(t.buckets), "readouts": {a: ro.meta for a, ro in self.readouts.items()},
                "best": ({k: v for k, v in b.items() if k not in ("C", "ok", "readout")} | {"readout_meta": b["readout"].meta}) if b else None,
                "has_epoch_accumulators": self.ratio_epoch_stats is not None, "has_init_codes": self.ratio_init_codes is not None,
                "descriptor_schema_ko": ROUTE_CONVENTION_KO["source_order"], "stage_policy_ko": STAGE_POLICY_KO,
                "role_meta_sha256": sha256_text(dumps(self.model.specs["V4/L2"].channel_meta, indent=None)),
                "coordinate_sha256": sha256_array(self.model.specs["V4/L4"].pos_x, self.model.specs["V4/L4"].pos_y, self.model.specs["V4/L2"].rf)}

    def ratio_load_state(self, arrays: dict[str, np.ndarray], meta: dict[str, Any]) -> None:
        rr = self.ratio_router()
        rm = meta.get("ratio") or {}
        if rr is None:
            return
        if not rm or rm.get("table_sha256") != rr.t.hash():
            raise CompatibilityError("다시 만든 V4 비율 후보 그래프의 해시가 checkpoint 와 다르다 (설정·코드 불일치, 다른 모드 checkpoint 를 이어 가지 않는다).")
        for k_, f_ in (("role_meta_sha256", lambda: sha256_text(dumps(self.model.specs["V4/L2"].channel_meta, indent=None))),
                       ("coordinate_sha256", lambda: sha256_array(self.model.specs["V4/L4"].pos_x, self.model.specs["V4/L4"].pos_y,
                                                                  self.model.specs["V4/L2"].rf))):
            if rm.get(k_) != f_():
                raise CompatibilityError(f"다시 만든 V4 의 {k_} 가 checkpoint 와 다르다.")
        nb = int(rm["n_buckets"])
        if not rm.get("codebook_initialized"):
            raise CompatibilityError("checkpoint 의 V4 코드북이 초기화되지 않은 상태다 (부분 상태를 정상 코드북으로 쓰지 않는다).")
        rr.set_codebook([arrays[f"ratio__C__{b}"] for b in range(nb)], [arrays[f"ratio__ok__{b}"] for b in range(nb)])
        rr.version = int(rm["codebook_version"])
        if rr.codebook_sha() != rm["codebook_sha256"]:
            raise CompatibilityError("불러온 V4 코드북 해시가 checkpoint 기록과 다르다.")
        dim = self.model.specs["V4/L3"].n
        eps = float(self.cfg["learning"]["eps_norm"])
        self.readouts = {}
        for a, rmeta in (rm.get("readouts") or {}).items():
            ro = ClassReadout(a, self.classes, dim, self.be, eps)
            ro.load_state(arrays, f"readout__{a}__", rmeta)
            self.readouts[a] = ro
        bm = rm.get("best")
        self.ratio_best = None
        if bm:
            ro = ClassReadout("V4", self.classes, dim, self.be, eps)
            ro.load_state(arrays, "ratio_best__readout__", bm.get("readout_meta") or {})
            self.ratio_best = {**{k: v for k, v in bm.items() if k != "readout_meta"},
                               "C": [np.asarray(arrays[f"ratio_best__C__{b}"], np.float32) for b in range(nb)],
                               "ok": [np.asarray(arrays[f"ratio_best__ok__{b}"], bool) for b in range(nb)], "readout": ro}
            if sha256_array(*(self.ratio_best["C"] + self.ratio_best["ok"])) != bm["codebook_sha256"]:
                raise CompatibilityError("최선 스냅샷의 코드북 해시가 checkpoint 기록과 다르다.")
        self.ratio_init_codes = ([np.asarray(arrays[f"ratio_init__C__{b}"], np.float32) for b in range(nb)]
                                 if rm.get("has_init_codes") else None)
        if rm.get("has_epoch_accumulators"):
            self.ratio_upd_acc = [{k: np.asarray(arrays[f"ratio_upd__{b}__{k}"]).copy() for k in UPD_KEYS} for b in range(nb)]
            self.ratio_epoch_stats = RouteStats(self.model, ["V4"])
            self.ratio_epoch_stats.load_state(arrays, "ratio_es__")
        self._cb_sha_cache = (-1, None, None)

    def ratio_model_tag(self) -> str:
        rr = self.ratio_router()
        if rr is None:
            return ""
        ro = self.readouts.get("V4")
        return f"-c{rr.version}x{(self.codebook_sha() or '')[:8]}-ro{ro.version if ro else 0}"

    def experiment_checkpoint_info(self) -> dict[str, Any] | None:
        """checkpoint 메타에 넣는 일괄 실행 상태 요약 (experiment_manifest.json 이 있을 때만)."""
        if self.rec is None or not self.rec.p("experiment_manifest.json").is_file():
            return None
        try:
            man = read_json(self.rec.p("experiment_manifest.json"))
        except (OSError, ValueError):
            return None
        return {"run_id": man.get("run_id"), "steps": {k: v.get("status") for k, v in (man.get("steps") or {}).items()},
                "final_test": man.get("final_test"), "plan_sha256": man.get("plan_sha256")}

    # ---------------------------------------------------------------- V4 상세 조회 (3×3 밖의 별도 배열 참조)
    def ratio_dyn(self, res: dict[str, dict[str, Any]], i: int = 0) -> dict[str, Any] | None:
        if "V4/L2" not in res or "ratio" not in res["V4/L2"]:
            return None
        rr = res["V4/L2"]["ratio"]
        return {"recs": rr["buckets"], "i": i, "x4": self.be.to_np(res["V4/L4"]["out"])[i] if "V4/L4" in res else None}


class Session(RatioSessionMixin):
    """한 실행 (run 폴더) 의 상태: 설정·데이터·모델·prototype·단계 상태·동결 해시·평가 횟수·RNG.
    v6 모드의 V4 상태 (코드북·V4 판독기·dev 최선 스냅샷) 는 RatioSessionMixin 이 맡는다 (V1·V2·IT 경로는 그대로)."""

    def __init__(self, cfg: dict[str, Any], be: Backend, *, say: Callable[[str], None] = print,
                 confirm: Callable[[str], bool] | None = None):
        self.cfg = validate_config(cfg)
        self.be = be
        self.say = say
        self.confirm = confirm or (lambda _m: True)
        self.data_root: Path | None = None
        self.output_root: Path | None = None
        self.rec: RunRecorder | None = None
        self.data: DatasetManager | None = None
        self.pre = RetinaLGNPreprocessor(self.cfg)
        self.timer = PhaseTimer(be)
        self.loader: BatchLoader | None = None
        self.model: CortexModel | None = None
        self.protos: dict[str, PrototypeBank] = {}
        self.stage: dict[str, dict[str, Any]] = {}
        self.frozen: dict[str, dict[str, Any]] = {}
        self.counters = {"dev_evaluations": 0, "test_evaluations": 0, "train_passes": 0, "inference_images": 0}
        self.rng = np.random.default_rng([int(self.cfg["seed"]), 99])
        self.ckpt_seq = 0
        self.corr_buf: list[dict[str, Any]] = []
        self.fault: str | None = None              # 자체 검사용 결함 주입 (평소 None)
        self.last_checkpoint: str | None = None
        self.route_buf: list[dict[str, Any]] = []         # routing_samples 버퍼 (checkpoint 경계에서 기록)
        self.band_buf: list[dict[str, Any]] = []          # band_samples 버퍼 (checkpoint 경계에서 기록)
        self._pending_band_cal: BandCalibration | None = None
        self.dest_buf: list[dict[str, Any]] = []          # dest_samples 버퍼 (상세 edge 기록, checkpoint 경계에서 기록)
        self.dest_nacc: dict[str, np.ndarray] = {}        # 활성 영역 에폭의 뉴런·집단·원천별 누적 (checkpoint npz 에 함께 저장)
        self.readouts: dict[str, ClassReadout] = {}       # v6: V4 판독기 (코드북과 별개, PrototypeBank 를 대신하지 않는다)
        self.ratio_best: dict[str, Any] | None = None     # v6: V4 dev 최선 코드북·판독기 스냅샷 (epoch_number 0 포함)
        self.ratio_epoch_stats: RouteStats | None = None  # v6: V4 에폭 학습 배치 집계 (checkpoint 에 저장, 재개 시 복원)
        self.ratio_upd_acc: list[dict[str, np.ndarray]] | None = None
        self.ratio_init_codes: list[np.ndarray] | None = None
        self.ratio_buf: list[dict[str, Any]] = []         # v6: V4 상세 경로 기록 버퍼 (checkpoint 경계에서 routes/ 에 기록)
        self._cb_sha_cache: tuple[int, str | None, Any] = (-1, None, None)
        self.counters.update(readout_fits=0, codebook_updates=0)
        self.batch_internal = False                       # 일괄 실행의 합성 내부 검사 모드 (사전검사 재진입 방지)

    # ---------------------------------------------------------------- 경로·기록
    def set_paths(self, data_root: Path | None, output_root: Path | None) -> None:
        if data_root is not None:
            d = Path(data_root)
            if self.cfg["data"]["source"] == "mnist" and not d.exists():
                d.mkdir(parents=True, exist_ok=True)
            if not d.is_dir():
                raise DataError(f"데이터 폴더가 없다: {d}")
            self.data_root = d.resolve()
        if output_root is not None:
            self.output_root = ensure_writable_dir(Path(output_root))

    def start_run(self) -> RunRecorder:
        if self.output_root is None:
            raise RuntimeError("저장 폴더를 먼저 정한다 (메뉴 1).")
        run = unique_run_dir(self.output_root)
        self.rec = RunRecorder(run, say=self.say)
        self.write_static()
        self.rec.info(f"새 실행 폴더 {run}", echo=True)
        return self.rec

    def program_sha(self) -> str:
        try:
            return sha256_file(Path(__file__))
        except OSError:
            return "unknown"

    def write_static(self) -> None:
        r = self.rec
        r.json("config.json", {"program": PROGRAM, "program_version": VERSION, "program_sha256": self.program_sha(),
                               "config": self.cfg, "config_structure_sha256": config_structure_sha(self.cfg),
                               "config_learning_sha256": config_learning_sha(self.cfg), "formulas": FORMULAS,
                               "backend": self.be.describe(), "utc": utc_now()})
        r.json("environment.json", DeviceManager.environment(self.be))
        r.text("source.sha256", f"{self.program_sha()}  {Path(__file__).name}\n")
        r.text("assumptions.md", assumptions_markdown())
        r.json("effective_config.json", self.effective_config())
        r.json("run_info.json", {"data_root": str(self.data_root) if self.data_root else None,
                                 "output_root": str(self.output_root) if self.output_root else None,
                                 "run_dir": str(r.dir), "created_utc": utc_now(), "program_sha256": self.program_sha()})

    def effective_config(self) -> dict[str, Any]:
        ro = self.cfg["routing"]
        return {"program": PROGRAM, "program_version": VERSION, "utc": utc_now(), "config": self.cfg, "routing_mode": ro["mode"],
                "routing_modes_ko": {"legacy": "v1 의 연결·계산 재현 (θA 방향 최근접 위치, 없으면 같은 위치)",
                                     "geometry_only": "수정된 기하 후보 집합의 고정 첫 후보 (V1 안내 영향 없음)",
                                     "v1_guided": "같은 후보 집합에서 이번 이미지의 V1 L3 경로 지지 점수가 가장 큰 후보",
                                     "expanded_pool": "수용장 안 contour θB 후보 전부를 기하 가중치 w0 로 가중평균 (g = 1)",
                                     "band_gated": "expanded_pool 과 같은 후보·w0 에 연결별 활동 강도 구간 게이트 g 를 곱한 가중평균",
                                     DEST_MODE: "V1 L3 안내로 V4 위치 × 역할마다 수신 목적지 하나와 입력 슬롯 묶음을 고른다 (v4 기본)",
                                     RATIO_MODE: "V4 위치 × 역할마다 L4 입력 비율 방향 x̂ 와 대표 벡터의 코사인 최대 후보 하나 (V1 안내 없음, V4 는 코드북만 학습, v6 새 실행 기본)"},
                "effect_separation_ko": "legacy→geometry_only = 기하 배선 수정 효과, geometry_only→v1_guided = 안내 지도의 추가 효과. "
                                        "expanded_pool→band_gated = 강도 구간 게이트의 추가 효과 (같은 후보·결합). v1_guided→band_gated 차이에는 "
                                        "후보 확대·결합 방식 (hard top-1 → 가중평균)·V1 안내 제외·게이트 효과가 섞여 있다 (합쳐 보고하지 않는다).",
                "band": {"settings": self.cfg["band"], "conventions": BAND_CONVENTION_KO,
                         "formulas": {k: FORMULAS[k] for k in FORMULAS if k.startswith("band_")},
                         "active": self.cfg["routing"]["mode"] in BAND_MODES,
                         "calibration_used_in_forward": self.cfg["routing"]["mode"] == "band_gated",
                         "v1_guide_in_forward": False if self.cfg["routing"]["mode"] in BAND_MODES else self.cfg["routing"]["mode"] == "v1_guided",
                         "not_implemented_ko": "V1 안내와 강도 구간의 결합, μ·σ·w0 학습, 구조적 재배선은 이번 버전에 없다 (꺼진 기능을 켜진 것으로 표시하지 않는다)."},
                "destination": {"settings": self.cfg["destination"], "conventions": DEST_CONVENTION_KO, "curve_conditions_ko": DEST_CURVE_REASONS_KO,
                                "formulas": {k: FORMULAS[k] for k in FORMULAS if k.startswith("dest_")},
                                "active": self.cfg["routing"]["mode"] == DEST_MODE, "base_file": BASE_FILE_INFO,
                                "band_gate_in_forward": False if self.cfg["routing"]["mode"] == DEST_MODE else None,
                                "not_implemented_ko": "라우터 학습, top-k·soft 선택, 강도 구간 게이트와의 결합, 곡선 B 외 원천 확대, 시간축·스파이크, "
                                                      "L5/L6 오차 재전파, 전역 역전파는 이번 버전에 없다 (꺼진 기능을 켜진 것으로 표시하지 않는다).",
                                "gpu_timing_ko": "compute.gpu_timing_sync = True 이면 구간별 시간 측정을 위해 CUDA 동기화를 넣는다 (측정 모드: 일반 실행보다 느릴 수 있다). "
                                                 "False 로 두면 동기화 없이 빠르게 실행하지만 구간 시간은 비동기라 정확하지 않다.",
                                "determinism_ko": "고정 인덱스 gather·마지막 축 합·마스크 argmax 만 쓴다 (atomic 누적 없음). GPU 부동소수 축약 순서는 CPU 와 다를 수 있어 "
                                                  "점수가 거의 같은 동점 근처에서 선택이 달라질 수 있다 (검사 D12 가 허용오차·동점 근처를 따로 센다). 비트 단위 동일성을 주장하지 않는다."},
                "ratio_codebook": {"settings": ro["ratio_codebook"], "active": ro["mode"] == RATIO_MODE, "conventions": ROUTE_CONVENTION_KO,
                                   "formulas": {k: FORMULAS[k] for k in FORMULAS if k.startswith("ratio_")}, "base_file": BASE_FILE_INFO,
                                   "stage_policy_ko": STAGE_POLICY_KO, "v1_guide_in_forward": False, "band_gate_in_forward": False,
                                   "v4_q_learning": False, "v1_v2_it_learning": "v4 그대로 (L1 국소 교정·q·prototype EMA)",
                                   "not_implemented_ko": "V1·V2·IT 코드북, 모든 영역 q 고정, softmax 혼합 전달, top-k, 반발·재초기화, 전역 역전파는 없다."},
                "routing_conventions": ROUTING_CONVENTION_KO, "formulas": FORMULAS,
                "config_structure_sha256": config_structure_sha(self.cfg), "config_learning_sha256": config_learning_sha(self.cfg),
                "cache_rule_ko": "캐시는 LGN 표본 벡터 (RAM) 만 둔다. 키 = 상대 경로 + 전처리 설정 해시. 영역 출력 (V1~IT) 은 캐시하지 않고 매 입력 다시 계산한다 "
                                 "(라우팅·구간·연결 변경 전의 V4/IT 출력을 재사용할 수 없다).",
                "backend": self.be.describe()}

    def log_design_change(self, note: str) -> dict[str, Any]:
        """dev 반복 확인에 따른 설계 변경 기록. test 를 본 뒤의 변경이면 이후 test 는 독립 평가가 아니라고 표시한다."""
        rec = {"utc": utc_now(), "note": note, "model_version": self.model_version() if self.model else None,
               "dev_evaluations_so_far": self.counters["dev_evaluations"], "test_evaluations_so_far": self.counters["test_evaluations"],
               "after_test_seen": self.counters["test_evaluations"] > 0}
        self.need_rec().append_jsonl("design_changes.jsonl", rec)
        return rec

    def need_rec(self) -> RunRecorder:
        if self.rec is None:
            raise RuntimeError("실행 폴더가 없다 (메뉴 2 에서 데이터 분할을 먼저 한다).")
        return self.rec

    # ---------------------------------------------------------------- 데이터
    def scan_and_split(self, progress: Callable[[str], None] | None = None) -> tuple[dict[str, Any], dict[str, Any]]:
        if self.model is not None:
            raise RuntimeError("이미 모델이 있는 세션이다. 다른 분할로 이어 붙이지 않는다 (새 세션에서 다시 시작).")
        if self.data_root is None:
            raise RuntimeError("데이터 폴더를 먼저 정한다 (메뉴 1).")
        dm = make_dataset_manager(self.cfg, self.data_root)
        rep = dm.scan(progress)
        man = dm.split(int(self.cfg["seed"]))
        if self.rec is None:
            self.start_run()
        r = self.need_rec()
        r.json("data_report.json", rep)
        r.json("split_manifest.json", man)
        r.json("class_to_index.json", {"class_to_index": man["class_to_index"], "classes": man["classes"],
                                       "data_fingerprint_sha256": man["data_fingerprint_sha256"], "seed": man["seed"]})
        r.json("run_info.json", {**read_json(r.p("run_info.json")), "data_root": str(self.data_root)})
        r.json("preprocessing.json", {"info": self.pre.info(), "dc_check": self.pre.dc_check()})
        self.data = dm
        self.loader = BatchLoader(dm, self.pre, self.be, self.cfg, self.timer)
        r.info(f"데이터 분할: 클래스 {man['classes']}, 항목 {man['n_items']}, 지문 {man['data_fingerprint_sha256'][:12]}")
        return rep, man

    @property
    def classes(self) -> list[str]:
        if self.data is None:
            raise RuntimeError("데이터 분할이 없다.")
        return list(self.data.classes)

    # ---------------------------------------------------------------- 모델
    def plan_next(self) -> tuple[str, list[LayerSpec], dict[str, Any]]:
        if self.data is None:
            raise RuntimeError("데이터 분할을 먼저 한다 (메뉴 2).")
        if self.model is None:
            self.model = CortexModel(self.cfg, self.be, self.pre)
            self.model.timer = self.timer
        if len(self.model.areas) >= len(AREA_ORDER):
            raise RuntimeError("IT 까지 모두 만들었다.")
        area = AREA_ORDER[len(self.model.areas)]
        specs = self.model.plan(area)
        summ = structure_summary(specs, self.be, self.cfg, len(self.classes), self.model.device_bytes())
        return area, specs, summ

    def build_area(self, area: str, specs: list[LayerSpec], summary: dict[str, Any]) -> dict[str, Any]:
        if len(specs) > 1 and specs[1].ratio is not None:   # v6 V4: 코드북 초기화 → V4 판독기 → epoch 0 평가 (init_prototypes·stage_start_eval 을 쓰지 않는다)
            return self.build_ratio_area(area, specs, summary)
        r = self.need_rec()
        acc0 = dict(self.loader.access) if self.loader is not None else {}
        band_spec = specs[1].band if len(specs) > 1 else None
        if band_spec is not None and self._pending_band_cal is None:
            self._pending_band_cal = run_band_calibration(self, specs)
        self.model.add_area(area, specs)
        self.model.active = area
        if band_spec is not None:
            self.attach_band_calibration(self._pending_band_cal)
            self._pending_band_cal = None
        self.stage[area] = new_stage_state(area, self.cfg)
        r.json(f"structure/{area}_plan_summary.json", summary)
        arrs: dict[str, np.ndarray] = {}
        for sp in specs:
            for nm in ("a_ptr", "a_src", "a_w", "b_ptr", "b_src", "b_w", "op_min", "x", "y", "rf", "pos_nb", "pos_nb_count"):
                arrs[f"{sp.name}__{nm}"] = getattr(sp, nm)
        r.npz(f"structure/{area}_structure.npz", **arrs)
        self.write_architecture()
        self.write_structure_json()
        self.stage[area]["stage_policy"] = self.stage_policy(area)
        l2 = self.model.specs.get(f"{area}/L2")
        if l2 is not None and l2.routing is not None:
            self.write_routing_static(area)
        if l2 is not None and l2.band is not None:
            self.write_band_static(area)
        if l2 is not None and l2.dest is not None:
            self.write_dest_static(area)
        self.stage[area]["structure_sha_at_creation"] = self.model.struct_hash[area]
        rec = self.init_prototypes(area)
        acc1 = dict(self.loader.access)
        self.stage_start_eval(area)
        acc2 = dict(self.loader.access)
        r.json(f"structure/{area}_data_access.json", {
            "utc": utc_now(), "area": area, "before_creation": acc0, "after_prototype_init": acc1, "after_start_eval": acc2,
            "prototype_init_delta": {k: acc1.get(k, 0) - acc0.get(k, 0) for k in acc1},
            "start_eval_delta": {k: acc2.get(k, 0) - acc1.get(k, 0) for k in acc2},
            "rule_ko": "후보 그래프·선택 집단은 구조만으로 만든다 (데이터 미사용). prototype 초기화는 train 만, 학습 전 평가는 dev 와 train 만 읽는다 (test 0)."})
        self.save_checkpoint(f"{area}_created", keep=True)
        r.info(f"{area} 생성: 구조 해시 {self.model.struct_hash[area][:12]}", echo=False)
        return rec

    def write_routing_static(self, area: str) -> None:
        r = self.need_rec()
        t = self.model.specs[f"{area}/L2"].routing
        l4 = self.model.specs[f"{area}/L4"]
        qq = np.maximum(t.cand_q, 0)
        r.npz("routing/routing_candidates.npz", **t.arrays(), conventions=np.asarray(dumps(ROUTING_CONVENTION_KO, indent=None)),
              params=np.asarray(dumps(t.params, indent=None)), P_x_px=l4.pos_x[t.P], P_y_px=l4.pos_y[t.P],
              candidate_x_px=np.where(t.cand_valid, l4.pos_x[qq], np.nan), candidate_y_px=np.where(t.cand_valid, l4.pos_y[qq], np.nan),
              curve_neuron_id=self.model.specs[f"{area}/L2"].start + t.curve_rows, candidate_src_neuron_id=np.where(t.cand_valid, l4.start + t.cand_src, -1),
              table_sha256=np.asarray(t.hash()), interpolation_rule=np.asarray(
                  "V1 L3 휘도 채널: 원영상 점 → 로그-극좌표 역사상 (반경 log1p, 각도 wrap) 쌍선형 4 위치 × 180 주기 방향 선형 2 채널"))
        summ = t.static_summary(l4, self.pre)
        r.json("routing/routing_static_summary.json", summ)
        ring = l4.ring[t.P * l4.n_ch]
        for k in np.unique(ring):
            for th in np.unique(t.theta_a):
                for s in np.unique(t.sign):
                    sel = (ring == k) & (t.theta_a == th) & (t.sign == s)
                    if sel.any():
                        r.append_csv("routing/missing_by_ring_orientation.csv", {
                            "ring": int(k), "eccentricity_px_mean": float(np.hypot(l4.pos_x[t.P[sel]] - self.pre.cx, self.pre.cy - l4.pos_y[t.P[sel]]).mean()),
                            "theta_a_deg": float(th), "curve_sign": int(s), "n": int(sel.sum()), "missing_candidate_frac": float(t.missing[sel].mean()),
                            "valid_candidates_mean": float(t.cand_valid[sel].sum(1).mean())})
        r.info(f"{area} 라우팅 후보 표: 곡선 {summ['n_curve_neurons']}, 후보 없음 {fmt(summ['missing_candidate_frac'])}, "
               f"유효 후보 평균 {fmt(summ['valid_candidates_mean'], 2)}", echo=True)

    def attach_band_calibration(self, cal: BandCalibration) -> None:
        brt = self.model.band_runtime()
        brt.set_calibration(cal)
        self.model.store.band_calibration = cal

    def write_band_static(self, area: str) -> None:
        r = self.need_rec()
        l2, l4 = self.model.specs[f"{area}/L2"], self.model.specs[f"{area}/L4"]
        t: BandTable = l2.band
        brt = self.model.band_runtime()
        cal = brt.calibration
        qq = np.maximum(t.cand_q, 0)
        role = np.asarray([l2.channel_names[int(row % l2.n_ch)] for row in t.curve_rows])
        r.npz("routing/candidate_edges.npz", **t.arrays(),
              dst_neuron_id=l2.start + t.curve_rows, src_neuron_id=np.where(t.cand_valid, l4.start + t.cand_src, -1),
              src_A_neuron_id=l4.start + t.srcA, dst_role=role, P_x_px=l4.pos_x[t.P], P_y_px=l4.pos_y[t.P],
              Q_x_px=np.where(t.cand_valid, l4.pos_x[qq], np.nan), Q_y_px=np.where(t.cand_valid, l4.pos_y[qq], np.nan),
              conventions=np.asarray(dumps(BAND_CONVENTION_KO, indent=None)), params=np.asarray(dumps(t.params, indent=None)),
              table_sha256=np.asarray(t.hash()), v2_reason_codes=np.asarray(dumps(V2_FILTER_REASONS, indent=None)))
        summ = t.static_summary()
        r.json("routing/band_static_summary.json", summ)
        ring = l4.ring[t.P * l4.n_ch]
        for k in np.unique(ring):
            for th in np.unique(t.theta_a):
                sel = (ring == k) & (t.theta_a == th)
                if sel.any():
                    r.append_csv("routing/band_candidates_by_ring_orientation.csv", {
                        "ring": int(k), "eccentricity_px_mean": float(np.hypot(l4.pos_x[t.P[sel]] - self.pre.cx, self.pre.cy - l4.pos_y[t.P[sel]]).mean()),
                        "theta_a_deg": float(th), "n": int(sel.sum()), "missing_candidate_frac": float(t.missing[sel].mean()),
                        "candidates_mean": float(t.n_cand[sel].mean()), "rf_radius_px_mean": float(t.R[sel].mean())})
        if cal is not None:
            r.npz("routing/band_calibration.npz", mu=cal.mu, sigma=cal.sigma, count=cal.count, insufficient=cal.insufficient,
                  sample_ids=np.asarray(cal.sample_ids), dst_neuron_id=l2.start + t.curve_rows,
                  src_neuron_id=np.where(t.cand_valid, l4.start + t.cand_src, -1), cand_valid=t.cand_valid,
                  model_hash=np.asarray(cal.model_hash), table_hash=np.asarray(cal.table_hash), calibration_sha256=np.asarray(cal.hash()))
            r.json("routing/band_calibration.json", {**cal.summary(t), "used_in_forward": self.cfg["routing"]["mode"] == "band_gated",
                                                     "note_ko": ("expanded_pool 모드에서도 같은 보정을 1회 계산해 둔다 (진단 9-6 에서 같은 동결 모델의 "
                                                                 "band_gated 비교용). expanded_pool 의 학습·평가에는 쓰지 않는다 (g = 1)."
                                                                 if self.cfg["routing"]["mode"] == "expanded_pool" else
                                                                 "band_gated 의 학습·dev·test·추론에서 고정된 값으로 쓴다.")})
        r.info(f"{area} 강도 구간 후보: 곡선 {summ['n_curve_neurons']}, 연결 {summ['n_edges']}, 후보 없음 {summ['missing_candidate']}, "
               f"뉴런당 후보 {summ['candidates_per_neuron']['min']}–{summ['candidates_per_neuron']['max']} (평균 {fmt(summ['candidates_per_neuron']['mean'], 2)})",
               echo=True)

    def write_dest_static(self, area: str) -> None:
        """고정 후보 그래프·선택 집단·조건별 제거 수 (구조 생성 때 한 번, 데이터 미사용)."""
        r = self.need_rec()
        l2, l4 = self.model.specs[f"{area}/L2"], self.model.specs[f"{area}/L4"]
        t: DestTable = l2.dest
        summ = t.static_summary(l4)
        r.json("routing/dest_static_summary.json", summ)
        r.npz("routing/dest_candidate_edges.npz",
              source_L4_id=l4.start + t.e_src, destination_L2_id=l2.start + t.e_dst, input_slot=t.e_slot, input_slot_names=np.asarray(["A", "B"]),
              role=t.e_role, role_names=np.asarray(DEST_ROLES), source_xy=t.e_src_xy, destination_xy=t.e_dst_xy,
              source_orientation=t.e_src_ori, source_orientation2=t.e_src_ori2, required_orientation=t.e_req_ori, base_weight=t.e_base_w,
              valid_mask=t.e_valid, curve_candidate_k=t.e_bundle,
              curve_rf_candidate_dst_L2_id=l2.start + t.c_rows[t.ce_row], curve_rf_candidate_src_L4_id=l4.start + t.ce_src,
              curve_rf_candidate_reason=t.ce_reason, curve_reason_names=np.asarray(dumps(DEST_CURVE_REASONS, indent=None)),
              curve_rf_candidate_dist_px=t.ce_dist_px, curve_rf_candidate_chord_dev_deg=t.ce_chord_dev_deg,
              curve_rf_candidate_wedge_ok_diag=t.ce_wedge_ok, curve_rf_candidate_v2_reason_diag=t.ce_v2_reason,
              curve_rf_candidate_wrong_turn_frac_diag=t.ce_wrong_turn_frac,
              group_position=t.group_pos, group_role=t.group_role,
              group_members_L2_id=np.where(t.group_members < t.n_l2, l2.start + t.group_members, -1),
              group_has_candidate=t.group_has_candidate, destination_valid=t.dst_valid, destination_role=t.dst_role,
              curve_L2_id=l2.start + t.c_rows, curve_candidate_Q=t.c_cand_q, curve_candidate_src_L4_id=np.where(t.c_cand_valid, l4.start + t.c_cand_src, -1),
              curve_path_xy_px=t.c_path_xy, read_xy_px=np.stack([t.read_x_px, t.read_y_px], 1), read_orientation_deg=t.read_ori,
              table_sha256=np.asarray(t.hash()), candidate_graph_sha256=np.asarray(t.graph_hash()),
              conventions=np.asarray(dumps(DEST_CONVENTION_KO, indent=None)), params=np.asarray(dumps(t.params, indent=None)),
              coordinate_note=np.asarray("xy = 처리 영상 화소 (원점 왼쪽 위, x 오른쪽, y 아래). 방향 = 원영상 좌표 반시계 (y 위쪽), 선 방향 180° 주기"))
        fi = t.candidate_fan_in()
        ring = l4.ring[::l4.n_ch]
        rows = []
        for g in range(t.n_groups):
            mem = t.group_members[g][t.group_members[g] < t.n_l2]
            rows.append({"group": g, "position": int(t.group_pos[g]), "ring": int(ring[t.group_pos[g]]), "role": DEST_ROLES[int(t.group_role[g])],
                         "n_destinations": int(len(mem)), "n_valid_destinations": int(t.dst_valid[mem].sum()),
                         "n_valid_candidate_edges": int(fi[mem].sum()), "has_candidate": bool(t.group_has_candidate[g])})
        buf = io.StringIO()
        w = csv.DictWriter(buf, fieldnames=list(rows[0]))
        w.writeheader()
        for row in rows:
            w.writerow({k: _csv_cell(v) for k, v in row.items()})
        r.text("routing/dest_candidates_by_position_role.csv", buf.getvalue())
        buf = io.StringIO()
        rr = [{"ring": int(k), **v} for k, v in t.removed["curve_by_ring"].items()]
        w = csv.DictWriter(buf, fieldnames=list(rr[0]))
        w.writeheader()
        for row in rr:
            w.writerow(row)
        r.text("routing/dest_curve_removed_by_ring.csv", buf.getvalue())
        c = summ["curve_candidates_per_neuron"]
        r.info(f"{area} 목적지 후보 그래프: 목적지 {t.n_l2}, 집단 {t.n_groups} (후보 없는 집단 {summ['groups_without_candidate']}), 곡선 B 후보 "
               f"{c['min']}–{c['max']} (평균 {fmt(c['mean'], 2)}, 후보 없는 곡선 뉴런 {summ['curve_neurons_without_candidate']}), "
               f"유효 edge {summ['candidate_graph']['n_valid_edges']}, 곡선 조건별 제거 {summ['curve_removed_by_condition']}", echo=True)

    def write_dest_row(self, area: str, epoch: int, context: str, summ: dict[str, Any]) -> None:
        row = {"utc": utc_now(), "active_area": area, "epoch": epoch, "epoch_number": epoch + 1, "context": context,
               "routing_mode": self.cfg["routing"]["mode"], "model_version": self.model_version(area)}
        row.update({k: v for k, v in summ.items() if k != "roles"})
        self.need_rec().append_csv("routing/dest_summary.csv", row)

    def write_dest_epoch_files(self, area: str, epoch: int, rep: dict[str, Any], dev_rep: dict[str, Any] | None) -> None:
        """에폭 끝: 역할별 선택 빈도·미선택 비율·q 무변화 이유 (train 학습 배치 누적) 와 뉴런별 누적 배열."""
        r = self.need_rec()
        t: DestTable = self.model.specs["V4/L2"].dest
        r.json(f"routing/dest_role_stats_{area}_e{epoch:03d}.json", {"utc": utc_now(), "area": area, "epoch_number": epoch + 1,
                                                                      "train_batches": rep, "dev_eval": dev_rep})
        l2s, l4s = self.model.specs["V4/L2"].start, self.model.specs["V4/L4"].start
        r.npz(f"routing/dest_neuron_stats_{area}_e{epoch:03d}.npz", **{k: np.asarray(v) for k, v in self.dest_nacc.items()},
              L2_neuron_id=l2s + np.arange(t.n_l2), L4_neuron_id=l4s + np.arange(t.n_src), destination_role=t.dst_role,
              destination_valid=t.dst_valid, candidate_fan_in=t.candidate_fan_in(), candidate_fan_out=t.candidate_fan_out(),
              n_train_samples=np.asarray(rep["n_samples"]),
              note=np.asarray("sel = 이 에폭 학습 배치에서 선택된 횟수, active = s>0 횟수, contrib = s>0 이고 m≠0 인 횟수, dq_abs = 적용된 |Δq| 합, "
                              "src_used = 원천이 실제 사용된 edge 수 (후보 수와 별개)"))
        for role, row in rep["roles"].items():
            r.append_csv("routing/dest_role_summary.csv", {"utc": utc_now(), "area": area, "epoch_number": epoch + 1, "role": role, **row})

    def write_band_row(self, area: str, epoch: int, context: str, summ: dict[str, Any]) -> None:
        row = {"utc": utc_now(), "active_area": area, "epoch": epoch, "epoch_number": epoch + 1, "context": context,
               "routing_mode": self.cfg["routing"]["mode"], "model_version": self.model_version(area)}
        row.update(summ)
        self.need_rec().append_csv("routing/band_routing_summary.csv", row)

    def stage_start_eval(self, area: str) -> dict[str, Any]:
        """단계 시작 전 (학습 전) 평가: 초기 구조 성능과 학습 후 성능을 분리한다."""
        bank = self.protos[area]
        dv = self.evaluate(area, "dev", bank, purpose=f"{area}_before_training")
        if dv.get("ratio"):
            self.write_ratio_routing_rows(area, 0, "dev_before_training_frozen_V4", dv["ratio"], frozen=True)
        tr = self.pass_split(area, "train", bank=bank)
        row = {"utc": utc_now(), "area": area, "epoch": -1, "epoch_number": 0, "row_kind": "before_training",
               "model_version": self.model_version(area), "prototype_version_after": bank.version,
               "train_acc_vs_epoch_prototype": (tr["correct"] / tr["n"]) if tr["n"] else None, "train_correct_vs_epoch_prototype": tr["correct"],
               "train_n": tr["n"], "dev_n": dv["n"], "dev_correct": dv["correct"], "dev_accuracy": dv["accuracy_overall"],
               "dev_accuracy_valid_only": dv["accuracy_valid_only"], "dev_n_unknown_zero_vector": dv["n_unknown_zero_vector"],
               "dev_per_class_accuracy": dv["per_class_accuracy"], "dev_confusion": dv["confusion"],
               "dev_output_norm_mean": dv["geometry"].get("output_norm_mean"), "stage_status": "before_training"}
        self.stage[area]["start_eval"] = row
        if dv.get("routing"):
            self.write_routing_row(area, -1, "dev_before_training", dv["routing"])
        if dv.get("band"):
            self.write_band_row(area, -1, "dev_before_training", dv["band"])
        if dv.get("dest"):
            self.write_dest_row(area, -1, "dev_before_training", dv["dest"])
            if dv.get("dest_roles_report"):
                self.need_rec().json(f"routing/dest_role_stats_{area}_dev_before_training.json", dv["dest_roles_report"])
        return row

    def write_routing_row(self, area: str, epoch: int, context: str, summ: dict[str, Any]) -> None:
        row = {"utc": utc_now(), "active_area": area, "epoch": epoch, "epoch_number": epoch + 1, "context": context,
               "routing_mode": self.cfg["routing"]["mode"], "model_version": self.model_version(area)}
        for k, v in summ.items():
            row[k] = v
        self.need_rec().append_csv("routing/routing_summary.csv", row)

    def write_architecture(self) -> None:
        m = self.model
        r = self.need_rec()
        layers = []
        for key in m.store.order:
            sp = m.specs[key]
            fo = m.store.fan_out(key)
            rt = m.rt[key]
            layers.append({"layer": key, "area": sp.area, "name": sp.name, "neuron_id_range": [sp.start, sp.end],
                           "n_neurons": sp.n, "n_positions": sp.n_pos, "n_channels": sp.n_ch, "Z": sp.z,
                           "grid_shape": list(sp.grid_shape) if sp.grid_shape else None, "source": sp.src_key,
                           "channels": sp.channel_names, "roles": sorted(set(sp.channel_roles)), "description": sp.description,
                           "build_stats": sp.build_stats, "fan_out": {"min": int(fo.min()), "max": int(fo.max()),
                                                                      "n_without_output": int((fo == 0).sum())},
                           "learnable_q": sp.learnable, "l6_applied": rt.l6, "l6_neurons_without_neighbor": rt.n_no_neighbor,
                           "structure_sha256": sp.hash()})
        r.json("architecture.json", {
            "program_version": VERSION, "areas": m.areas, "active_area": m.active, "total_neurons": m.store.N,
            "coordinate_systems_ko": {"X_Y": "수용장 중심, 처리 영상 화소 (원점 왼쪽 위 화소 중심, x 오른쪽, y 아래쪽)",
                                      "Z": "영역번호×10 + 피질층 번호 (V1=1, V2=2, V4=3, IT=4; L4=4, L2=2, L3=3), 무차원",
                                      "grid": "피질 격자 (ring, angle) = 로그-극좌표 (반경 bin, 각도 bin)",
                                      "orientation": "원영상 좌표 기준 반시계 각도 (y 위쪽)"},
            "paths_ko": {"sensory": "LGN → V1 L4 → V1 L2 → V1 L3 → V2 L4 → ... → IT L3 (감각 경로)",
                         "teacher": "활성 영역 L3 → prototype 비교기 → LocalErrorRouter → L1Relay → L2/L3 q (교사 교정 경로, 감각 입력을 바꾸지 않는다)",
                         "l6": "각 영역 L2·L3 의 CONF 스냅샷 → g → 실제 전송 출력 (일시적)"},
            "l6_table": [{"layer": k, "applied": m.rt[k].l6} for k in m.store.order],
            "l1_table": [{"area": a, "targets": [f"{a}/L2", f"{a}/L3"], "router": m.routers[a].describe()} for a in m.areas],
            "l6_controller": m.l6.describe(), "layers": layers, "structure_sha256": m.struct_hash, "formulas": FORMULAS,
            "areas_detail": {a: m.area_objs[a].describe() for a in m.areas},
            "connectivity_report": m.store.conn.report(m.specs, m.store.order),
            "role_mapping_note_ko": "역할 배치는 생물학적 층별 기능이 확정되었다는 주장이 아니다."})

    def can_store_h(self, area: str) -> bool:
        n_train = len(self.data.items("train"))
        dim = self.model.specs[f"{area}/L3"].n
        return n_train * dim * 4 <= int(self.cfg["records"]["store_train_h_max_mb"]) * 2 ** 20

    def pass_split(self, area: str, split: str, *, bank: PrototypeBank | None = None, override: dict[str, LayerRuntime] | None = None,
                   collect_h: bool = False, routing_mode: str | None = None, guide_transform: Callable[[Any], Any] | None = None,
                   routing_acc: dict[str, float] | None = None, collect_routing: bool = False,
                   dest_arrays: dict[str, np.ndarray] | None = None, ratio_stats: RouteStats | None = None) -> dict[str, Any]:
        """split 전체 순방향 (갱신 없음). 클래스 합·개수, (bank 가 있으면) 코사인 분류·정답 prototype 거리·혼동행렬.
        routing_acc 를 주면 V4 라우팅 선택 통계를 모은다. routing_mode·guide_transform 은 안내만 바꾸는 진단용 (감각 입력·q·prototype 고정)."""
        be, items = self.be, self.data.items(split)
        B = int(self.cfg["learning"]["batch_size"])
        key = f"{area}/L3"
        dim = self.model.specs[key].n
        C = len(self.classes)
        eps = float(self.cfg["learning"]["eps_norm"])
        sums = be.zeros((C, dim))
        counts = np.zeros(C, np.int64)
        out = {"n": 0, "correct": 0, "n_valid_h": 0, "n_ties": 0, "dist_sum": 0.0, "n_dist": 0, "cos_true_sum": 0.0, "n_cos": 0,
               "margin_sum": 0.0, "n_margin": 0, "per_class_n": np.zeros(C, np.int64), "per_class_correct": np.zeros(C, np.int64),
               "n_unknown": 0, "confusion": np.zeros((C, C + 1), np.int64)}
        H, Y, PR, YY = [], [], [], []
        rr = self.model.routing_runtime()
        want_route = rr is not None and AREA_INDEX[area] >= AREA_INDEX["V4"] and (routing_acc is not None or collect_routing)
        brt = self.model.band_runtime()
        want_band = brt is not None and AREA_INDEX[area] >= AREA_INDEX["V4"] and (routing_acc is not None or collect_routing)
        act_eps = float(self.cfg["band"]["activity_epsilon"])
        high = float(self.cfg["routing"]["high_guide_score"])
        drt = self.model.dest_runtime()
        want_dest = drt is not None and AREA_INDEX[area] >= AREA_INDEX["V4"] and (routing_acc is not None or collect_routing)
        high_d = float(self.cfg["destination"]["high_score"])
        routes: list[dict[str, np.ndarray]] = []
        want_ratio = ratio_stats is not None and self.model.ratio_runtime() is not None and AREA_INDEX[area] >= AREA_INDEX["V4"]
        keep_r = ("V4/L2", "V4/L3") if want_ratio else ()
        l6_ = self.model.l6
        for a in range(0, len(items), B):
            chunk = items[a:a + B]
            lgn, y = self.loader.batch(chunk, split)
            with self.timer.phase("forward", gpu=be.is_cuda and bool(self.cfg["compute"]["gpu_timing_sync"])):
                res_ = self.model.forward(lgn, upto=area, override=override, routing_mode=routing_mode, guide_transform=guide_transform,
                                          routing_record=want_route or want_band or want_dest or want_ratio, keep=keep_r)
                h = res_[key]["out"]
            if want_ratio:
                ratio_stats.add_route("V4", route_rec_np(be, res_["V4/L2"]["ratio"]["buckets"]))
                for k_ in keep_r:
                    ratio_stats.add_layer(k_, layer_reduce(be, res_[k_], l6_.g_min, l6_.g_max, vector=(k_ == "V4/L3")))
            if want_dest:
                dn = dest_rec_np(be, res_["V4/L2"]["dest"])
                if routing_acc is not None:
                    a_, arr_ = dest_batch_stats(drt.table, dn, high_d)
                    acc_add(routing_acc, a_)
                    if dest_arrays is not None:
                        dest_acc_arrays_add(dest_arrays, arr_)
                if collect_routing:
                    routes.append({"has": dn["has"], "kg": dn["kg"], "mx": dn["mx"], "kq": dn["kq"], "n_selected": dn["mask"].sum(1)})
                if dest_arrays is not None:                                  # V4 L2 선택 전 (u_all) · 선택 후 (출력) 의 클래스 합 (분리 지표용)
                    for c in np.unique(y):
                        rows_ = y == c
                        for nm_, arr_ in (("cls_sum_u_all", dn["u_all"]), ("cls_sum_out", dn["out"])):
                            cur = dest_arrays.setdefault(nm_, np.zeros((C, arr_.shape[1])))
                            cur[int(c)] += arr_[rows_].sum(0)
                        cnt_ = dest_arrays.setdefault("cls_count", np.zeros(C))
                        cnt_[int(c)] += int(rows_.sum())
            if want_band:
                bn = band_rec_np(be, res_["V4/L2"]["band"])
                if routing_acc is not None:
                    acc_add(routing_acc, band_batch_stats(brt.table, bn, act_eps))
                if collect_routing:
                    routes.append({"B": bn["B"], "A": bn["A"], "all_gates_low": bn["all_gates_low"], "max_g": bn["max_g"],
                                   "share": bn["share"].astype(np.float16)})
            if want_route:
                rn = routing_rec_np(be, res_["V4/L2"]["routing"])
                if routing_acc is not None:
                    acc_add(routing_acc, routing_batch_stats(rr.table, rn, high))
                if collect_routing:
                    routes.append(rn)
            for c in np.unique(y):
                be.add_row_(sums, int(c), be.sum0(be.rows(h, be.i64(np.nonzero(y == c)[0]))))
            counts += np.bincount(y, minlength=C)
            out["n"] += len(chunk)
            np.add.at(out["per_class_n"], y, 1)
            if bank is not None:
                cl = cosine_classify(be, h, bank.P, bank.valid, eps)
                PR.append(np.asarray(cl["pred"]).astype(np.int64))
                YY.append(np.asarray(y).astype(np.int64))
                np.add.at(out["confusion"], (y, np.where(cl["pred"] >= 0, cl["pred"], C)), 1)
                ok = cl["pred"] == y
                out["correct"] += int(ok.sum())
                np.add.at(out["per_class_correct"], y[ok], 1)
                out["n_valid_h"] += int(cl["valid_h"].sum())
                out["n_unknown"] += int((cl["pred"] < 0).sum())
                out["n_ties"] += int(cl["n_ties"])
                vp = bank.valid[y]
                if vp.any():
                    d = be.to_np(be.norm_last(bank.targets(y) - h)).astype(np.float64)
                    out["dist_sum"] += float(d[vp].sum())
                    out["n_dist"] += int(vp.sum())
                ct = cl["cos"][np.arange(len(y)), y]
                fin = np.isfinite(ct)
                out["cos_true_sum"] += float(ct[fin].sum())
                out["n_cos"] += int(fin.sum())
                for i in np.nonzero(fin)[0]:
                    other = np.delete(cl["cos"][i], y[i])
                    other = other[np.isfinite(other)]
                    if other.size:
                        out["margin_sum"] += float(ct[i] - other.max())
                        out["n_margin"] += 1
            else:
                out["n_valid_h"] += int((be.to_np(be.norm_last(h)) > eps).sum())
            if collect_h:
                H.append(be.to_np(h).astype(np.float32))
                Y.append(y)
        if split == "train":
            self.counters["train_passes"] += 1
        out.update(pred=np.concatenate(PR) if PR else None, y=np.concatenate(YY) if YY else None)
        out.update(sums=sums, counts=counts, ids_sha=self.data.ids_sha(split),
                   H=np.concatenate(H) if H else None, Y=np.concatenate(Y) if Y else None,
                   routes={k: (np.concatenate([r_[k] for r_ in routes]) if routes and routes[0].get(k) is not None else None)
                           for k in (("has", "kg", "mx", "kq", "n_selected") if want_dest else
                                     (("B", "A", "all_gates_low", "max_g", "share") if want_band else ("k", "B", "A", "S", "no_guidance")))}
                   if routes else None)
        return out

    @staticmethod
    def mean_dist(P: np.ndarray, valid: np.ndarray, H: np.ndarray, Y: np.ndarray) -> float | None:
        vp = valid[Y]
        if not vp.any():
            return None
        return float(np.linalg.norm(P[Y[vp]].astype(np.float64) - H[vp].astype(np.float64), axis=1).mean())

    def init_prototypes(self, area: str) -> dict[str, Any]:
        be = self.be
        dim = self.model.specs[f"{area}/L3"].n
        store_h = self.can_store_h(area)
        tp = self.pass_split(area, "train", collect_h=store_h)
        counts = tp["counts"]
        P = tp["sums"] * be.f32((1.0 / np.maximum(counts, 1))[:, None])
        bank = PrototypeBank(area, self.classes, dim, be, float(self.cfg["learning"]["eps_norm"]))
        rec = bank.set(P, counts, source="init_class_mean", split="train", sample_ids_sha256=tp["ids_sha"], epoch=None, rho=None)
        self.protos[area] = bank
        rec["train_zero_vector_fraction"] = 1.0 - tp["n_valid_h"] / max(1, tp["n"])
        if store_h:
            dist = self.mean_dist(be.to_np(bank.P), bank.valid, tp["H"], tp["Y"])
        else:
            dist = self.pass_split(area, "train", bank=bank)
            dist = dist["dist_sum"] / dist["n_dist"] if dist["n_dist"] else None
        self.stage[area]["dist_start_vs_P"] = dist
        self.record_prototypes(area, rec)
        if rec["invalid_classes"]:
            self.rec.warn(f"{area} prototype 무효 (영벡터) 클래스: {rec['invalid_classes']} — 해당 클래스 표본은 교정하지 않는다.")
        return rec

    def record_prototypes(self, area: str, rec: dict[str, Any]) -> None:
        bank = self.protos[area]
        r = self.need_rec()
        Pn = self.be.to_np(bank.P).astype(np.float32)
        r.npz(f"prototype_snapshots/{area}_v{bank.version:04d}.npz", P=Pn, valid=bank.valid, counts=bank.counts,
              classes=np.asarray(self.classes))
        pc = bank.pairwise_cos()
        C = len(self.classes)
        off = pc[~np.eye(C, dtype=bool)] if C > 1 else np.zeros(0)
        min_angle = float(np.degrees(np.arccos(np.clip(np.nanmax(off), -1, 1)))) if off.size and np.isfinite(off).any() else None
        for c, name in enumerate(self.classes):
            others = np.delete(pc[c], c)
            others = others[np.isfinite(others)]
            r.append_csv("prototype_metrics.csv", {
                "utc": rec["utc"], "area": area, "version": bank.version, "source": rec["source"], "epoch": rec["epoch"],
                "split": rec["split"], "class": name, "n_samples": int(bank.counts[c]), "norm": rec["norms"][c],
                "valid": bool(bank.valid[c]), "max_cos_to_other": float(others.max()) if others.size else None,
                "min_pair_angle_deg_all": min_angle, "update_l2_all": rec["update_l2"], "rho": rec["rho"],
                "collapse_warning": bool(min_angle is not None and min_angle < 5.0),
                "train_zero_vector_fraction": rec.get("train_zero_vector_fraction")})

    def model_version(self, area: str | None = None) -> str:
        area = area or (self.model.active if self.model else None)
        if area is None:
            return "no_model"
        st = self.stage.get(area, {})
        bank = self.protos.get(area)
        qsha = sha256_array(self.model.store.q_numpy())[:10]
        tag = ""
        if "V4" in self.model.areas and self.model.routing_mode != "legacy":
            tag = {"geometry_only": "-Rgeo", "v1_guided": "-Rv1g", "expanded_pool": "-Rexp", "band_gated": "-Rbnd", DEST_MODE: "-Rdst",
                   RATIO_MODE: "-Rrat"}[self.model.routing_mode] + self.ratio_model_tag()
        if bank is None and area in self.readouts:
            bank = self.readouts[area]
        return f"{area}-e{st.get('epochs_completed', 0)}-b{st.get('next_batch', 0)}-P{bank.version if bank else 0}-q{qsha}{tag}"

    def evaluate(self, area: str, split: str, bank: PrototypeBank, *, purpose: str,
                 override: dict[str, LayerRuntime] | None = None, log: bool = True, routing_mode: str | None = None,
                 guide_transform: Callable[[Any], Any] | None = None, collect_routing: bool = False) -> dict[str, Any]:
        if split == "dev":
            self.counters["dev_evaluations"] += 1
        elif split == "test":
            self.counters["test_evaluations"] += 1
        dim = self.model.specs[f"{area}/L3"].n
        n_items = len(self.data.items(split))
        collect = n_items * dim * 4 <= int(self.cfg["records"]["store_train_h_max_mb"]) * 2 ** 20
        racc: dict[str, float] = {}
        darr: dict[str, np.ndarray] = {}
        rstats = RouteStats(self.model, ["V4"]) if (self.model.ratio_runtime() is not None and AREA_INDEX[area] >= AREA_INDEX["V4"]) else None
        r = self.pass_split(area, split, bank=bank, override=override, collect_h=collect, routing_mode=routing_mode,
                            guide_transform=guide_transform, routing_acc=racc, collect_routing=collect_routing, dest_arrays=darr,
                            ratio_stats=rstats)
        n = r["n"]
        m: dict[str, Any] = {"split": split, "area": area, "purpose": purpose, "n": n, "correct": r["correct"],
                             "accuracy_overall": (r["correct"] / n) if n else None,
                             "n_valid_h": r["n_valid_h"], "n_unknown_zero_vector": r["n_unknown"],
                             "accuracy_valid_only": (r["correct"] / r["n_valid_h"]) if r["n_valid_h"] else None,
                             "n_ties": r["n_ties"], "mean_dist_to_true_prototype": (r["dist_sum"] / r["n_dist"]) if r["n_dist"] else None,
                             "mean_cos_to_true_prototype": (r["cos_true_sum"] / r["n_cos"]) if r["n_cos"] else None,
                             "mean_margin": (r["margin_sum"] / r["n_margin"]) if r["n_margin"] else None,
                             "per_class": {c: {"n": int(r["per_class_n"][i]), "correct": int(r["per_class_correct"][i])}
                                           for i, c in enumerate(self.classes)},
                             "model_version": self.model_version(area), "prototype_version": bank.version,
                             "per_class_accuracy": {c: (int(r["per_class_correct"][i]) / int(r["per_class_n"][i])) if r["per_class_n"][i] else None
                                                    for i, c in enumerate(self.classes)},
                             "confusion": r["confusion"].tolist(), "confusion_columns": self.classes + ["unknown"],
                             "routing_mode_used": routing_mode or self.cfg["routing"]["mode"], "guide_transformed": guide_transform is not None}
        rr = self.model.routing_runtime()
        if racc and rr is not None:
            m["routing"] = routing_finalize(racc, rr.K)
        brt = self.model.band_runtime()
        if racc and brt is not None:
            m["band"] = band_finalize(racc, brt.table)
            m["band_mode_used"] = routing_mode if routing_mode in BAND_MODES else brt.mode
        drt = self.model.dest_runtime()
        if racc and drt is not None:
            m["dest"] = dest_finalize(racc, drt.table)
            if "cls_count" in darr:
                m["dest"]["V4_L2_class_separation_before_selection"] = class_separation(darr.pop("cls_sum_u_all"), darr["cls_count"])
                m["dest"]["V4_L2_class_separation_after_selection"] = class_separation(darr.pop("cls_sum_out"), darr.pop("cls_count"))
            m["dest_roles_report"] = dest_neuron_report(drt.table, darr, n)
        if rstats is not None:
            m["ratio"] = {"families": rstats.family_rows("V4"), "layers": rstats.layer_rows(), "wins": rstats.wins["V4"],
                          "n_samples": rstats.n_samples["V4"], "V4_frozen": area != "V4" or "V4" in self.frozen}
        if collect_routing:
            m["routing_records"] = r["routes"]
            m["predictions"] = r["pred"]                                    # 진단 비교용 (표본 순서 = split 목록 순서)
        m["geometry"] = self.geometry(r["H"], r["Y"]) if r["H"] is not None else {"status": NOT_RUN, "reason_ko": "메모리 상한으로 h 미보관"}
        if log and self.rec is not None:
            self.rec.append_jsonl("evaluations.jsonl", {"utc": utc_now(), **{k: v for k, v in m.items()
                                                                              if k not in ("per_class", "routing_records", "predictions", "dest_roles_report",
                                                                                           "ratio")},
                                                        "dev_evaluations": self.counters["dev_evaluations"],
                                                        "test_evaluations": self.counters["test_evaluations"]})
        return m

    def geometry(self, H: np.ndarray, Y: np.ndarray) -> dict[str, Any]:
        eps = float(self.cfg["learning"]["eps_norm"])
        C = len(self.classes)
        Hd = H.astype(np.float64)
        n = np.linalg.norm(Hd, axis=1)
        ok = n > eps
        g: dict[str, Any] = {"zero_vector_fraction": float(1.0 - ok.mean()) if len(ok) else None,
                             "output_variance_mean": float(Hd.var(axis=0).mean()) if len(Hd) else None,
                             "output_norm_mean": float(n.mean()) if len(n) else None}
        means = np.zeros((C, H.shape[1]))
        have = np.zeros(C, bool)
        within = []
        for c in range(C):
            sel = (Y == c) & ok
            if sel.any():
                means[c] = Hd[sel].mean(axis=0)
                have[c] = np.linalg.norm(means[c]) > eps
                if have[c]:
                    mu = means[c] / np.linalg.norm(means[c])
                    within += list((Hd[sel] / n[sel, None]) @ mu)
        g["within_class_mean_cos_to_class_mean"] = float(np.mean(within)) if within else None
        if have.sum() >= 2:
            Mn = means[have] / np.linalg.norm(means[have], axis=1, keepdims=True)
            pc = Mn @ Mn.T
            off = pc[~np.eye(len(Mn), dtype=bool)]
            g["between_class_mean_cos"] = float(off.mean())
            g["between_class_max_cos"] = float(off.max())
            d = np.linalg.norm(means[have][:, None, :] - means[have][None, :, :], axis=2)
            g["between_class_mean_distance"] = float(d[~np.eye(len(Mn), dtype=bool)].mean())
        return g

    # ---------------------------------------------------------------- 단계 전환
    def add_next_area_prepare(self) -> tuple[str, list[LayerSpec], dict[str, Any], dict[str, Any]]:
        cur = self.model.active
        st = self.stage[cur]
        info = {"current_area": cur, "current_status": st["status"], "epochs_completed": st["epochs_completed"],
                "best_dev_accuracy": st["best_dev_accuracy"],
                "warning_ko": (None if st["status"] == "success_criterion_met" else
                               f"{cur} 단계 상태가 '{st['status']}' 이다 (설정한 성공 기준 충족이 아니다). 그래도 추가할 수 있으나 기록한다.")}
        area, specs, summ = self.plan_next()
        return area, specs, summ, info

    def freeze_area(self, area: str) -> dict[str, Any]:
        st = self.model.store
        qs = {lay: sha256_array(self.be.to_np(st.q_view(f"{area}/{lay}"))) for lay in LAYER_ORDER}
        if self.is_ratio_area(area) and not self.stage[area].get("selected_restored"):
            raise RuntimeError("V4 (v6 모드) 는 dev 최선 코드북·판독기 스냅샷을 복원한 뒤에만 동결한다.")
        h = {"q_sha256": qs, "prototype_sha256": self.classifier(area).sha(), "prototype_version": self.classifier(area).version,
             "codebook_sha256": self.codebook_sha() if self.is_ratio_area(area) else None, "stage_policy": self.stage_policy(area),
             "selected_epoch_number": self.stage[area].get("selected_epoch_number") if self.is_ratio_area(area) else None,
             "structure_sha256": self.model.struct_hash[area], "preprocessing_sha256": sha256_text(dumps(self.pre.info(), indent=None)),
             "frozen_utc": utc_now(), "model_version_at_freeze": self.model_version(area)}
        self.frozen[area] = h
        return h

    def frozen_check(self) -> dict[str, Any]:
        out = {}
        for area, h in self.frozen.items():
            st = self.model.store
            qs = {lay: sha256_array(self.be.to_np(st.q_view(f"{area}/{lay}"))) for lay in LAYER_ORDER}
            out[area] = {"q_unchanged": qs == h["q_sha256"], "prototype_unchanged": self.classifier(area).sha() == h["prototype_sha256"],
                         **({"codebook_unchanged": self.codebook_sha() == h["codebook_sha256"]} if h.get("codebook_sha256") else {}),
                         "structure_unchanged": self.model.struct_hash[area] == h["structure_sha256"],
                         "preprocessing_unchanged": sha256_text(dumps(self.pre.info(), indent=None)) == h["preprocessing_sha256"]}
        return out

    def add_next_area_commit(self, area: str, specs: list[LayerSpec], summ: dict[str, Any], info: dict[str, Any],
                             *, user_choice: str) -> dict[str, Any]:
        cur = self.model.active
        cal_info = None
        if area == "V4" and specs[1].band is not None:
            # 강도 구간 초기 보정: V1·V2 와 V4 L4 가 고정된 상태에서 1회 (V4 를 모델에 넣기 전 읽기 전용 계산, 중단하면 부분 기록에서 이어감)
            self._pending_band_cal = run_band_calibration(self, specs)
            cal_info = self._pending_band_cal.summary(specs[1].band)
        restore = None
        if self.is_ratio_area(cur) and not self.stage[cur].get("selected_restored"):    # V4 는 dev 최선 스냅샷으로 되돌린 뒤 동결
            restore = self.ratio_restore_selected(cur, f"next_area_{area}")
        hashes = self.freeze_area(cur)
        tr = {"utc": utc_now(), "from": cur, "to": area, "from_status": info["current_status"], "warning_ko": info["warning_ko"],
              "stage_policy": self.stage_policy(cur), "ratio_restore": restore,
              "user_choice": user_choice, "frozen_hashes": hashes,
              "band_calibration": ({k: cal_info[k] for k in ("n_samples", "seconds", "n_edges", "insufficient_edges", "calibration_sha256")}
                                   if cal_info else None)}
        self.stage[cur]["transitions"].append(tr)
        self.need_rec().append_jsonl("stage_transitions.jsonl", tr)
        rec = self.build_area(area, specs, summ)
        return {"transition": tr, "prototype_init": rec}

    # ---------------------------------------------------------------- checkpoint
    def flush_routing_samples(self) -> None:
        if not self.route_buf:
            return
        r = self.need_rec()
        groups: dict[tuple[str, int], list[dict[str, Any]]] = {}
        for c in self.route_buf:
            groups.setdefault((c["area"], c["epoch"]), []).append(c)
        for (area, ep), rows in groups.items():
            k = len(list(r.p("routing").glob(f"routing_samples_{area}_e{ep:03d}_part*.npz")))
            r.npz(f"routing/routing_samples_{area}_e{ep:03d}_part{k:03d}.npz",
                  sample_id=np.asarray([x["sample_id"] for x in rows]), batch_index=np.asarray([x["batch"] for x in rows], np.int64),
                  label_recorded_not_used_for_selection=np.asarray([x["label"] for x in rows], np.int64),
                  P=np.asarray(rows[0]["P"]), candidate_Q=np.asarray(rows[0]["cand_q"]), selected_slot=np.stack([x["k"] for x in rows]),
                  selected_Q=np.stack([x["q_sel"] for x in rows]), guide_score=np.stack([x["S"] for x in rows]) if rows[0]["S"] is not None else np.zeros(0),
                  no_guidance=np.stack([x["no_guidance"] for x in rows]), A=np.stack([x["A"] for x in rows]), B=np.stack([x["B"] for x in rows]),
                  u=np.stack([np.minimum(x["A"], x["B"]) * (~x["missing"]) for x in rows]), missing_candidate=np.asarray(rows[0]["missing"]),
                  routing_mode=np.asarray(rows[0]["mode"]), guide_score_used_for_selection=np.asarray(bool(rows[0]["S_used_for_selection"])),
                  **({f"selected_path_{k_}": np.stack([x["points"][k_] for x in rows]) for k_ in rows[0]["points"]}
                     if rows[0].get("points") is not None else {}))
        self.route_buf = []

    def flush_band_samples(self) -> None:
        if not self.band_buf:
            return
        r = self.need_rec()
        groups: dict[tuple[str, int], list[dict[str, Any]]] = {}
        for c in self.band_buf:
            groups.setdefault((c["area"], c["epoch"]), []).append(c)
        for (area, ep), rows in groups.items():
            k = len(list(r.p("routing").glob(f"band_samples_{area}_e{ep:03d}_part*.npz")))
            r.npz(f"routing/band_samples_{area}_e{ep:03d}_part{k:03d}.npz",
                  sample_id=np.asarray([x["sample_id"] for x in rows]), batch_index=np.asarray([x["batch"] for x in rows], np.int64),
                  label_recorded_not_used_for_gate=np.asarray([x["label"] for x in rows], np.int64),
                  x=np.stack([x["X"] for x in rows]), z=np.stack([x["Z"] for x in rows]), g=np.stack([x["G"] for x in rows]),
                  contribution_share=np.stack([x["share"] for x in rows]), A=np.stack([x["A"] for x in rows]), B=np.stack([x["B"] for x in rows]),
                  u=np.stack([np.minimum(x["A"], x["B"]) * (~x["missing"]) for x in rows]),
                  all_gates_low=np.stack([x["low"] for x in rows]), missing_candidate=np.asarray(rows[0]["missing"]),
                  cand_valid=np.asarray(rows[0]["valid"]), routing_mode=np.asarray(rows[0]["mode"]),
                  note=np.asarray("x = 원래 V4 L4 전송 출력, z = 정규화 강도 (구간 판단용), g = 구간 일치도, contribution_share = w_eff/Σw_eff (float16)"))
        self.band_buf = []

    def flush_dest_samples(self) -> None:
        """상세 edge 기록 (지정한 소수 표본만): 집단별 선택·점수·동점·1·2 위 차, 선택 목적지의 실제 A/B·u·출력, 실제 전달 edge 와 값."""
        if not self.dest_buf:
            return
        r = self.need_rec()
        groups: dict[tuple[str, int], list[dict[str, Any]]] = {}
        for c in self.dest_buf:
            groups.setdefault((c["area"], c["epoch"]), []).append(c)
        drt = self.model.dest_runtime()
        t = drt.table if drt is not None else None
        for (area, ep), rows in groups.items():
            k = len(list(r.p("routing").glob(f"dest_samples_{area}_e{ep:03d}_part*.npz")))
            ptr = np.concatenate([[0], np.cumsum([len(x["e_src"]) for x in rows])]).astype(np.int64)
            l2s = self.model.specs["V4/L2"].start
            l4s = self.model.specs["V4/L4"].start
            r.npz(f"routing/dest_samples_{area}_e{ep:03d}_part{k:03d}.npz",
                  sample_id=np.asarray([x["sample_id"] for x in rows]), batch_index=np.asarray([x["batch"] for x in rows], np.int64),
                  label_recorded_not_used_for_selection=np.asarray([x["label"] for x in rows], np.int64),
                  group_position=t.group_pos, group_role=t.group_role, group_has_selection=np.stack([x["has"] for x in rows]),
                  group_selected_neuron_id=np.stack([np.where(x["has"], l2s + t.group_members[np.arange(t.n_groups), x["kg"]], -1) for x in rows]),
                  group_top_score=np.stack([x["mx"] for x in rows]), group_top1_minus_top2=np.stack([x["gap"] for x in rows]),
                  group_tie=np.stack([x["tie"] for x in rows]), group_n_valid=np.stack([x["n_valid"] for x in rows]),
                  curve_Q_star_position=np.stack([x["q_star"] for x in rows]), curve_score=np.stack([x["Sc"] for x in rows]),
                  selected_mask=np.stack([x["mask"] for x in rows]), A=np.stack([x["A"] for x in rows]), B=np.stack([x["B"] for x in rows]),
                  u_if_selected=np.stack([x["u_all"] for x in rows]), u=np.stack([x["u"] for x in rows]), out=np.stack([x["out"] for x in rows]),
                  guide_reads_below_floor_frac=np.asarray([x["below_floor"] for x in rows]),
                  delivered_ptr=ptr, delivered_src_neuron_id=np.concatenate([l4s + x["e_src"] for x in rows]),
                  delivered_dst_neuron_id=np.concatenate([l2s + x["e_dst"] for x in rows]),
                  delivered_slot=np.concatenate([x["e_slot"] for x in rows]), delivered_role=np.concatenate([x["e_role"] for x in rows]),
                  delivered_value=np.concatenate([x["e_val"] for x in rows]), routing_mode=np.asarray(DEST_MODE),
                  note=np.asarray("delivered_* = 이번 표본에서 실제로 전달된 edge (X4 원천값 × 기존 결합 가중치). 후보에만 있는 edge 는 넣지 않는다. "
                                  "라벨은 기록만 하며 선택에 쓰지 않았다."))
        self.dest_buf = []

    def flush_corrections(self) -> None:
        if not self.corr_buf:
            return
        r = self.need_rec()
        groups: dict[tuple[str, int], list[dict[str, Any]]] = {}
        for c in self.corr_buf:
            groups.setdefault((c["area"], c["epoch"]), []).append(c)
        for (area, ep), rows in groups.items():
            k = len(list(r.p("correction_samples").glob(f"{area}_e{ep:03d}_part*.npz")))
            r.npz(f"correction_samples/{area}_e{ep:03d}_part{k:03d}.npz",
                  sample_id=np.asarray([x["sample_id"] for x in rows]), label=np.asarray([x["label"] for x in rows], np.int64),
                  batch_index=np.asarray([x["batch"] for x in rows], np.int64),
                  sensory_h_before=np.stack([x["h_before"] for x in rows]), teacher_old_target=np.stack([x["target"] for x in rows]),
                  sensory_h_after=np.stack([x["h_after"] for x in rows]),
                  delta_norm=np.asarray([x["delta_norm"] for x in rows]), m_L2_norm=np.asarray([x["m2_norm"] for x in rows]),
                  m_L3_norm=np.asarray([x["m3_norm"] for x in rows]), batch_dq_L2_applied_l2=np.asarray([x["dq2"] for x in rows]),
                  batch_dq_L3_applied_l2=np.asarray([x["dq3"] for x in rows]),
                  model_version_before=np.asarray([x["version"] for x in rows]))
        self.corr_buf = []

    def save_checkpoint(self, tag: str, keep: bool = False) -> Path:
        with self.timer.phase("save"):
            return self._save_checkpoint(tag, keep)

    def _save_checkpoint(self, tag: str, keep: bool) -> Path:
        r = self.need_rec()
        self.flush_corrections()
        self.flush_routing_samples()
        self.flush_band_samples()
        self.flush_dest_samples()
        self.flush_ratio_details()
        rr_ = self.ratio_router()
        if rr_ is not None and not rr_.initialized:
            raise RuntimeError("V4 코드북 초기화 전 상태는 checkpoint 로 저장하지 않는다 (부분 상태를 정상 코드북으로 쓰지 않는다).")
        self.ckpt_seq += 1
        name = f"ckpt_{self.ckpt_seq:06d}_{re.sub(r'[^A-Za-z0-9_]+', '_', tag)}"
        arrays: dict[str, np.ndarray] = {"q": self.model.store.q_numpy()}
        for area, bank in self.protos.items():
            arrays[f"P__{area}"] = self.be.to_np(bank.P).astype(np.float32)
            arrays[f"Pvalid__{area}"] = bank.valid
            arrays[f"Pcounts__{area}"] = bank.counts
        brt = self.model.band_runtime()
        bcal = brt.calibration if brt is not None else None
        if bcal is not None:
            arrays.update(band_mu=bcal.mu, band_sigma=bcal.sigma, band_count=bcal.count, band_insufficient=bcal.insufficient,
                          band_sample_ids=np.asarray(bcal.sample_ids))
        for k_, v_ in self.dest_nacc.items():
            arrays[f"dest_nacc__{k_}"] = np.asarray(v_)
        arrays.update(self.ratio_checkpoint_arrays())
        drt = self.model.dest_runtime()
        npz_path = r.p(f"checkpoints/{name}.npz")
        save_npz(npz_path, **arrays)
        meta = {"format": CKPT_FORMAT, "seq": self.ckpt_seq, "tag": tag, "keep": bool(keep), "utc": utc_now(),
                "program_version": VERSION, "program_sha256": self.program_sha(), "npz": npz_path.name, "npz_sha256": sha256_file(npz_path),
                "areas": self.model.areas, "active_area": self.model.active,
                "layer_ranges": {k: [self.model.specs[k].start, self.model.specs[k].end] for k in self.model.store.order},
                "structure_sha256": self.model.struct_hash, "config_structure_sha256": config_structure_sha(self.cfg),
                "config_learning_sha256": config_learning_sha(self.cfg),
                "data_fingerprint_sha256": self.data.manifest["data_fingerprint_sha256"], "split_sha256": self.data.manifest["split_sha256"],
                "stage": self.stage, "frozen": self.frozen, "counters": self.counters,
                "prototypes": {a: {"version": b.version, "history": b.history} for a, b in self.protos.items()},
                "rng_state": self.rng.bit_generator.state, "model_version": self.model_version(), "q_sha256": sha256_array(arrays["q"]),
                "sampler_ko": "에폭 순서 = default_rng([seed, 영역번호, epoch, 11]).permutation(n_train); 진행 위치 = stage[영역].next_batch",
                "routing": {"mode": self.cfg["routing"]["mode"], "params": self.cfg["routing"],
                            "table_sha256": (self.model.specs["V4/L2"].routing.hash() if ("V4/L2" in self.model.specs and
                                                                                          self.model.specs["V4/L2"].routing is not None) else None),
                            "conventions": ROUTING_CONVENTION_KO, "program_sha256": self.program_sha()},
                "band": ({"mode": self.cfg["routing"]["mode"], "params": self.cfg["band"], "table_sha256": brt.table.hash(),
                          "calibration_sha256": bcal.hash() if bcal else None, "calibration_model_hash": bcal.model_hash if bcal else None,
                          "calibration_params": bcal.params if bcal else None, "calibration_seconds": bcal.seconds if bcal else None,
                          "calibration_utc": bcal.utc if bcal else None, "n_calibration_samples": len(bcal.sample_ids) if bcal else 0,
                          "conventions": BAND_CONVENTION_KO} if brt is not None else None),
                "destination": ({"mode": DEST_MODE, "params": self.cfg["destination"], "table_sha256": drt.table.hash(),
                                 "candidate_graph_sha256": drt.table.graph_hash(), "role_meta_sha256": drt.table.role_meta_hash(),
                                 "coordinate_sha256": drt.table.coord_hash(), "path_settings": drt.table.path_settings(),
                                 "conventions": DEST_CONVENTION_KO, "program_sha256": self.program_sha(), "base_file": BASE_FILE_INFO,
                                 "epoch_accumulators": sorted(self.dest_nacc)} if drt is not None else None),
                "ratio": self.ratio_checkpoint_meta(), "stage_policy": {a: self.stage_policy(a) for a in self.model.areas},
                "experiment": self.experiment_checkpoint_info()}
        r.json(f"checkpoints/{name}.json", meta)
        r.json("checkpoints/latest.json", {"name": name, "utc": meta["utc"], "model_version": meta["model_version"]})
        self.last_checkpoint = name
        self._prune_checkpoints()
        return npz_path

    def _prune_checkpoints(self) -> None:
        r = self.need_rec()
        keep_n = int(self.cfg["records"]["keep_periodic_checkpoints"])
        metas = sorted(r.p("checkpoints").glob("ckpt_*.json"))
        periodic = []
        for p in metas:
            try:
                m = read_json(p)
            except (OSError, json.JSONDecodeError):
                continue
            if not m.get("keep") and p.stem != self.last_checkpoint:
                periodic.append(p)
        for p in periodic[:max(0, len(periodic) - keep_n)]:
            with contextlib.suppress(OSError):
                (p.with_suffix(".npz")).unlink()
                p.unlink()

    @classmethod
    def load(cls, run_dir: Path, be: Backend, *, say: Callable[[str], None] = print, confirm: Callable[[str], bool] | None = None,
             data_root: Path | None = None, checkpoint: str | None = None, read_only: bool = False) -> "Session":
        """read_only=True: 분기 원본으로만 읽는다 (원본 폴더의 교정 조각 정리·csv 동기화·로그를 하지 않는다)."""
        run_dir = Path(run_dir)
        cf = read_json(run_dir / "config.json")
        if str(cf.get("program", "")).startswith("cortex_local_learning_v5"):
            raise CompatibilityError(f"이 run 은 {cf.get('program')} v{cf.get('program_version')} (전 영역 비율 라우팅) 가 만들었다. V1·V2·IT 의 학습 방식이 "
                                     "달라 이 프로그램은 이어 학습·분기 원본으로 읽지 않는다. 새 run 으로 시작한다.")
        sess = cls(saved_config_with_mode(cf["config"]), be, say=say, confirm=confirm)
        sess.rec = RunRecorder(run_dir, say=say)
        info = read_json(run_dir / "run_info.json")
        sess.output_root = Path(info["output_root"]) if info.get("output_root") else run_dir.parent
        droot = Path(data_root) if data_root else (Path(info["data_root"]) if info.get("data_root") else None)
        if droot is None or not droot.is_dir():
            raise CompatibilityError(f"데이터 폴더를 찾을 수 없다 ({droot}). --data-root 또는 메뉴에서 새 위치를 준다.")
        sess.data_root = droot
        if cf.get("program_sha256") and cf["program_sha256"] != sess.program_sha():
            msg = "이 실행을 만든 프로그램 파일과 현재 파일의 SHA256 이 다르다 (코드 변경). 결과 해석에 주의한다."
            if read_only:
                say("[경고] " + msg)
            else:
                sess.rec.warn(msg)
        man = read_json(run_dir / "split_manifest.json")
        sess.data = DatasetManager.from_manifest(sess.cfg, droot, man)
        probs = sess.data.verify_files()
        if probs:
            raise CompatibilityError("데이터가 분할 목록과 다르다: " + "; ".join(probs[:5]))
        sess.loader = BatchLoader(sess.data, sess.pre, be, sess.cfg, sess.timer)
        name = checkpoint or read_json(run_dir / "checkpoints" / "latest.json")["name"]
        meta = read_json(run_dir / "checkpoints" / f"{name}.json")
        if meta.get("format") not in CKPT_FORMATS_READABLE:
            raise CompatibilityError(f"알 수 없는 checkpoint 형식: {meta.get('format')}")
        npz = run_dir / "checkpoints" / meta["npz"]
        if sha256_file(npz) != meta["npz_sha256"]:
            raise CompatibilityError(f"checkpoint 배열 파일 해시가 다르다: {npz}")
        if meta["config_structure_sha256"] != config_structure_sha(sess.cfg) or meta["config_learning_sha256"] != config_learning_sha(sess.cfg):
            raise CompatibilityError("checkpoint 와 config.json 의 설정 해시가 다르다.")
        if meta["data_fingerprint_sha256"] != man["data_fingerprint_sha256"] or meta["split_sha256"] != man["split_sha256"]:
            raise CompatibilityError("checkpoint 와 분할 목록이 다르다.")
        arrays = load_npz(npz)
        sess.model = CortexModel(sess.cfg, be, sess.pre)
        sess.model.timer = sess.timer
        for area in meta["areas"]:
            specs = sess.model.plan(area)
            sess.model.add_area(area, specs)
            if sess.model.struct_hash[area] != meta["structure_sha256"][area]:
                raise CompatibilityError(f"{area} 구조를 다시 만들었더니 해시가 다르다 (설정·코드 불일치).")
        sess.model.store.load_q(arrays["q"])
        sess.model.active = meta["active_area"]
        brt = sess.model.band_runtime()
        if brt is not None:
            bm = meta.get("band") or {}
            if "band_mu" not in arrays or not bm.get("calibration_sha256"):
                raise CompatibilityError("강도 구간 모드 checkpoint 에 구간 보정 결과가 없다 (재개 때 보정을 다시 하지 않는다).")
            cal = BandCalibration(mu=arrays["band_mu"], sigma=arrays["band_sigma"], count=arrays["band_count"],
                                  insufficient=np.asarray(arrays["band_insufficient"], bool),
                                  sample_ids=[str(x) for x in arrays["band_sample_ids"]], model_hash=bm["calibration_model_hash"],
                                  table_hash=brt.table.hash(), params=bm["calibration_params"], seconds=float(bm.get("calibration_seconds") or 0.0),
                                  utc=bm.get("calibration_utc") or "")
            if cal.hash() != bm["calibration_sha256"]:
                raise CompatibilityError("구간 보정 해시가 checkpoint 기록과 다르다.")
            v4 = [sess.model.specs[f"V4/{l}"] for l in LAYER_ORDER]
            if calibration_model_hash(sess, v4, brt.table) != cal.model_hash:
                raise CompatibilityError("구간 보정 때의 V1·V2·V4 L4 상태와 지금 다시 만든 상태가 다르다 (보정 해시 불일치).")
            sess.attach_band_calibration(cal)
        drt = sess.model.dest_runtime()
        if drt is not None:
            dm = meta.get("destination") or {}
            if not dm.get("table_sha256"):
                raise CompatibilityError("목적지 선택 모드 checkpoint 에 후보 그래프 기록이 없다 (다른 모드의 checkpoint 를 새 모드로 이어 가지 않는다).")
            t_ = drt.table
            for k_, f_ in (("table_sha256", t_.hash), ("candidate_graph_sha256", t_.graph_hash), ("role_meta_sha256", t_.role_meta_hash),
                           ("coordinate_sha256", t_.coord_hash)):
                if dm.get(k_) != f_():
                    raise CompatibilityError(f"다시 만든 목적지 후보 그래프의 {k_} 가 checkpoint 와 다르다 (설정·코드 불일치).")
        sess.dest_nacc = {k_[len("dest_nacc__"):]: np.asarray(v_) for k_, v_ in arrays.items() if k_.startswith("dest_nacc__")}
        for area, pinfo in meta["prototypes"].items():
            dim = sess.model.specs[f"{area}/L3"].n
            bank = PrototypeBank(area, sess.classes, dim, be, float(sess.cfg["learning"]["eps_norm"]))
            bank.P = be.f32(arrays[f"P__{area}"])
            bank.valid = np.asarray(arrays[f"Pvalid__{area}"], bool)
            bank.counts = np.asarray(arrays[f"Pcounts__{area}"], np.int64)
            bank.version = int(pinfo["version"])
            bank.history = list(pinfo["history"])
            sess.protos[area] = bank
        sess.ratio_load_state(arrays, meta)
        sess.stage = meta["stage"]
        sess.frozen = meta["frozen"]
        sess.counters = meta["counters"]
        sess.rng.bit_generator.state = meta["rng_state"]
        for st_ in sess.stage.values():                                   # v1 기록에는 새 키가 없다
            for k_, v_ in new_stage_state(st_["area"], sess.cfg).items():
                st_.setdefault(k_, v_)
        sess.ckpt_seq = int(meta["seq"])
        sess.last_checkpoint = name
        if not read_only:
            sess._discard_uncommitted_corrections()
            sess.sync_training_csv()
            sess.rec.info(f"재개: {name} ({meta['model_version']}, 라우팅 {sess.cfg['routing']['mode']})", echo=True)
        return sess

    def _discard_uncommitted_corrections(self) -> None:
        """checkpoint 위치보다 뒤의 교정 표본 조각 (중단 전에 쓰였지만 되돌린 배치) 을 지운다 → 재개 뒤 중복 기록 방지."""
        r = self.need_rec()
        for area, st in self.stage.items():
            for p in r.p("routes").glob(f"sample_routes_{area}_e*_part*.npz"):       # v6: routes/ 의 파일 이름은 에폭 번호 (1 부터)
                ep_n = int(re.search(r"_e(\d+)_part", p.name).group(1))
                if ep_n > int(st["epochs_completed"]) + 1:
                    p.unlink()
                elif ep_n == int(st["epochs_completed"]) + 1 and st["phase"] == "training":
                    z = load_npz(p)
                    if z["batch_index"].size and int(z["batch_index"].max()) >= int(st["next_batch"]):
                        p.unlink()
            for p in r.p("correction_samples").glob(f"{area}_e*_part*.npz"):
                ep = int(re.search(r"_e(\d+)_part", p.name).group(1))
                if ep < st["epochs_completed"]:
                    continue
                if ep > st["epochs_completed"]:
                    p.unlink()
                    continue
                z = load_npz(p)
                if z["batch_index"].size and int(z["batch_index"].max()) >= int(st["next_batch"]) and st["phase"] == "training":
                    p.unlink()
            for p in (list(r.p("routing").glob(f"routing_samples_{area}_e*_part*.npz")) + list(r.p("routing").glob(f"band_samples_{area}_e*_part*.npz"))
                      + list(r.p("routing").glob(f"dest_samples_{area}_e*_part*.npz"))):
                ep = int(re.search(r"_e(\d+)_part", p.name).group(1))
                if ep > st["epochs_completed"]:
                    p.unlink()
                elif ep == st["epochs_completed"] and st["phase"] == "training":
                    z = load_npz(p)
                    if z["batch_index"].size and int(z["batch_index"].max()) >= int(st["next_batch"]):
                        p.unlink()

    def sync_training_csv(self) -> None:
        r = self.need_rec()
        for name in ("training.csv", TRAINING_METRICS_CSV):          # training_metrics.csv = 같은 행 (v6 명세 파일 이름), training.csv = v4 이름
            have = {(row.get("area"), row.get("epoch")) for row in r.read_csv(name)}
            for area in AREA_ORDER:
                st = self.stage.get(area) or {}
                rows = ([st["start_eval"]] if st.get("start_eval") else []) + list(st.get("history", []))
                for row in rows:
                    if (row["area"], str(row["epoch"])) not in have:
                        r.append_csv(name, {**row, "stage_policy": st.get("stage_policy") or self.stage_policy(area)})

    @classmethod
    def branch(cls, src_run: Path, be: Backend, *, mode: str, say: Callable[[str], None] = print,
               confirm: Callable[[str], bool] | None = None, data_root: Path | None = None, output_root: Path | None = None,
               keep_upto: str = "V2") -> "Session":
        """기존 실행의 V1·V2 (q·prototype·동결 상태) 를 재사용하고, 다른 라우팅 모드로 V4 를 새로 만드는 새 실행 (원본은 바꾸지 않는다).
        V4 출력 정의가 바뀌므로 V4 prototype 은 train 으로 새로 초기화하고 IT 는 이후 다시 만든다."""
        src = cls.load(Path(src_run), be, say=say, confirm=confirm, data_root=data_root, read_only=True)
        keep = list(AREA_ORDER[:AREA_INDEX[keep_upto]])
        lack = [a for a in keep if a not in src.model.areas]
        if lack:
            raise CompatibilityError(f"분기 원본에 {lack} 가 없다 (V1·V2 까지 만든 실행이 필요하다).")
        cfg = copy.deepcopy(src.cfg)
        cfg["routing"]["mode"] = mode
        new = cls(validate_config(cfg), be, say=say, confirm=confirm)
        new.set_paths(src.data_root, output_root or src.output_root)
        new.start_run()
        r = new.rec
        for fname in ("data_report.json", "split_manifest.json", "class_to_index.json", "preprocessing.json"):
            p = src.rec.p(fname)
            if p.is_file():
                r.json(fname, read_json(p))
        new.data = DatasetManager.from_manifest(new.cfg, src.data_root, src.data.manifest)
        new.loader = BatchLoader(new.data, new.pre, be, new.cfg, new.timer)
        new.model = CortexModel(new.cfg, be, new.pre)
        new.model.timer = new.timer
        for area in keep:
            new.model.add_area(area, new.model.plan(area))
            if new.model.struct_hash[area] != src.model.struct_hash[area]:
                raise CompatibilityError(f"{area} 구조 해시가 원본과 다르다 (설정·코드 불일치) — 분기하지 않는다.")
        qn, qs = new.model.store.q_numpy(), src.model.store.q_numpy()
        for area in keep:
            for lay in LAYER_ORDER:
                a_, b_ = new.model.specs[f"{area}/{lay}"], src.model.specs[f"{area}/{lay}"]
                qn[a_.start:a_.end] = qs[b_.start:b_.end]
        new.model.store.load_q(qn)
        for area in keep:
            sb = src.protos[area]
            bank = PrototypeBank(area, new.classes, sb.dim, be, sb.eps)
            bank.P, bank.valid, bank.counts = be.f32(be.to_np(sb.P)), sb.valid.copy(), sb.counts.copy()
            bank.version, bank.history = sb.version, copy.deepcopy(sb.history)
            new.protos[area] = bank
            new.stage[area] = copy.deepcopy(src.stage[area])
        new.frozen = {a: copy.deepcopy(v) for a, v in src.frozen.items() if a in keep}
        bad = {a: v for a, v in new.frozen_check().items() if not all(v.values())}
        if bad:
            raise CompatibilityError(f"분기 원본의 동결 해시와 다시 만든 상태가 다르다: {bad}")
        new.model.active = keep[-1]
        info = {"utc": utc_now(), "kind": "branch", "source_run": str(src.rec.dir), "source_checkpoint": src.last_checkpoint,
                "source_model_version": src.model_version(), "source_routing_mode": src.cfg["routing"]["mode"], "new_routing_mode": mode,
                "reused_areas": keep, "source_counters": src.counters,
                "reinitialized_areas": [a for a in AREA_ORDER if a not in keep],
                "source_areas_not_reused": [a for a in src.model.areas if a not in keep],
                "reused_state_hashes": {a: {"structure_sha256": src.model.struct_hash[a], "frozen": src.frozen.get(a)} for a in keep},
                "note_ko": "V1·V2 의 q·prototype·동결 해시를 그대로 옮겼다. 원본 실행 폴더는 바꾸지 않았다. V4 는 새 모드로 새로 만들고 train 출력으로 "
                           "prototype 을 초기화한다 (원본 V4·IT 의 q·prototype 을 재사용하지 않는다). IT 는 이후 다시 만든다."}
        r.json("run_info.json", {**read_json(r.p("run_info.json")), "branched_from": info})
        r.append_jsonl("stage_transitions.jsonl", info)
        new.write_architecture()
        new.save_checkpoint("branch_base", keep=True)
        nxt, specs, summ, pinfo = new.add_next_area_prepare()
        try:
            new.add_next_area_commit(nxt, specs, summ, pinfo, user_choice=f"branch_from:{Path(src_run).name}")
        except CalibrationInterrupted as exc:
            src.rec.close()
            raise CalibrationInterrupted(f"{exc} — 새 run {r.dir} 에 checkpoint branch_base (V1·V2) 와 보정 부분 기록이 있다. 메뉴 4 로 이 run 을 "
                                         "불러온 뒤 (추가 에폭은 Enter 로 취소) 메뉴 5 로 V4 를 추가하면 이어서 보정한다") from None
        src.rec.close()
        return new

    def inspect_neuron(self, nid: int, item: dict[str, Any] | None = None) -> dict[str, Any]:
        dyn = None
        if item is not None:
            key, _j = self.model.store.locate(int(nid))
            lgn, _y = self.loader.batch([item], item.get("split", "external"))
            use_dest = self.model.dest_runtime() is not None and key.startswith("V4")
            keep_ = (key,) + (("V4/L4",) if use_dest and key != "V4/L4" else ())
            res = self.model.forward(lgn, upto=key.split("/")[0], keep=keep_, routing_record=key.startswith("V4"), dest_detail=use_dest)
            dyn = {key: {"conf": self.be.to_np(res[key]["conf"])[0], "out": self.be.to_np(res[key]["out"])[0]}}
            if use_dest and "dest" in res.get("V4/L2", {}):
                dd = dest_rec_sample(dest_rec_np(self.be, res["V4/L2"]["dest"]), 0)
                dd["x4"] = self.be.to_np(res["V4/L4"]["out"])[0]
                dyn["__dest__"] = dd
            if "V4/L2" in res and "band" in res["V4/L2"]:
                bn = band_rec_np(self.be, res["V4/L2"]["band"])
                dyn["__band__"] = {k: (v[0] if isinstance(v, np.ndarray) else v) for k, v in bn.items()}
            if "V4/L2" in res and "routing" in res["V4/L2"]:
                rn = routing_rec_np(self.be, res["V4/L2"]["routing"])
                dyn["__routing__"] = {k: (v[0] if isinstance(v, np.ndarray) else v) for k, v in rn.items()}
        rdyn = None
        if self.model.ratio_runtime() is not None and item is not None and self.model.store.locate(int(nid))[0].startswith("V4"):
            lgn, _y = self.loader.batch([item], item.get("split", "external"))
            res2 = self.model.forward(lgn, upto="V4", keep=("V4/L4", "V4/L2"), routing_record=True, ratio_detail=True)
            rdyn = self.ratio_dyn(res2, 0)
        info = self.model.inspector.inspect_neuron(int(nid), dyn)
        key, j = self.model.store.locate(int(nid))
        if self.model.ratio_runtime() is not None and key in ("V4/L2", "V4/L4"):
            ro = (ratio_inspect_destination(self.model, j, rdyn) if key == "V4/L2" else ratio_inspect_source(self.model, j, rdyn))
            info["routing"] = ro
            m3 = info["matrix_3x3"]
            if key == "V4/L2":
                ts = ro.get("this_sample_neuron")
                m3[1][2] = (f"INPUT←고정 후보 edge {ro['n_fixed_candidate_edges']} (합법 {ro['n_legal_candidate_edges']}) / 이번 표본 실제 전달 "
                            + (str(len(ts["delivered_edges"])) if ts else "미계산") + " (V4/L4, 비율 라우팅)")
            else:
                ts = ro.get("this_sample_used_by")
                m3[1][0] = f"{m3[1][0]} · 비율 후보 슬롯 {ro['n_candidate_refs']}" + (f" (이번 표본 실제 사용 {len(ts)})" if ts is not None else "")
        return info


# ======================================================================
# 13. 단계 학습 (StageTrainer)
# ======================================================================
def epoch_permutation(seed: int, area: str, epoch: int, n: int) -> np.ndarray:
    return np.random.default_rng([int(seed), AREA_INDEX[area], int(epoch), 11]).permutation(n)


OOM_GUIDE_KO = ("GPU 메모리 부족. 현재 배치는 되돌렸고 gather 조각 크기를 반씩 줄여 같은 배치를 다시 시도했지만 실패했다. "
                "마지막 경계에서 checkpoint 를 저장했다. CPU 로 몰래 바꾸지 않는다.\n"
                "  줄이는 방법 (새 실행에서 설정 변경): learning.batch_size ↓, compute.max_gather_elements ↓, "
                "areas.V1.n_r/n_phi ↓ 또는 logpolar.n_r/n_phi ↓ (V1 팬인), areas.V1.rf_radius_sigma ↓, data.image_size ↓.\n"
                "  같은 설정으로 이어 가려면 다른 GPU 프로그램을 닫고 메뉴 4 (재개) 로 다시 시작한다.")


OOM_GUIDE_RATIO_KO = ("GPU 메모리 부족 (V4 비율 라우팅). 현재 배치의 코드북 갱신은 적용하지 않았고 gather 조각 크기를 반씩 줄여 같은 배치를 다시 시도했지만 실패했다. "
                      "마지막 경계에서 checkpoint 를 저장했다. CPU 로 몰래 바꾸지 않는다. 후보는 삭제하지 않는다.\n"
                      "  줄이는 방법 (새 실행에서 설정 변경): learning.batch_size ↓, compute.max_gather_elements ↓, routing.ratio_codebook.bucket_max_elements ↓.\n"
                      "  같은 설정으로 이어 가려면 다른 GPU 프로그램을 닫고 메뉴 4 (재개) 또는 11 (일괄 이어하기) 로 다시 시작한다.")


class RatioTrainerMixin:
    """v6 모드의 V4 학습 경로 (StageTrainer.run 이 v4 의 q 학습 루프에 들어가기 전에 분기한다).

    배치: (1) 같은 학습 전 코드북으로 배치 전체 순방향 (승리 x̂ 합·수 수집, 라벨 미사용) (2) 비유한·음수 입력 검사 (조용히 바꾸지 않음)
          (3) CodebookLearner: 배치마다 한 번 c ← normalize((1−η)c + η·v̂) (4) 집계·상세 기록 커밋 — (3)~(4) 를 같은 배치 경계에서
          commit/rollback 한다 (중단·OOM·오류면 코드북·버전·집계를 배치 전으로).
    에폭 끝: 코드북 고정 → V4 판독기 재계산 (train) → train·dev 평가 → 선택 (dev 최고, 동률 → 이른 시점, epoch 0 포함) → 종료 판단.
    종료 (성공 기준·plateau·예산) 때 선택 시점의 코드북·판독기 쌍으로 되돌린다. V4 의 LocalErrorRouter·L1Relay·LocalOutputLearner 는 만들지 않는다."""

    def _ratio_finish(self, area: str, st: dict[str, Any], why: str = "") -> dict[str, Any]:
        s = self.s
        st["ended_utc"] = utc_now()
        info = s.ratio_restore_selected(area, st["status"])
        st["structure_unchanged_at_end"] = s.model.struct_hash[area] == st.get("structure_sha_at_creation")
        st["frozen_check_at_end"] = s.frozen_check()
        s.save_checkpoint(f"{area}_stage_{st['status']}", keep=True)
        s.rec.info(f"{area} 단계 종료 {st['status']}: 선택 시점 epoch_number {st['selected_epoch_number']} (dev {fmt(st['best_dev_accuracy'])}), "
                   "코드북·판독기 복원", echo=True)
        return {"status": st["status"], "area": area, "epochs_completed": st["epochs_completed"], "best_dev_accuracy": st["best_dev_accuracy"],
                "best_epoch": st.get("best_epoch"), "selected_epoch_number": st["selected_epoch_number"], "checkpoint": s.last_checkpoint,
                "restore": info, "message_ko": why or None, "stage_policy": "dev_best_snapshot"}

    def _ratio_loop(self, area: str, st: dict[str, Any], stop: StopFlag, stop_after: int | None) -> dict[str, Any]:
        s, be = self.s, self.s.be
        items = s.data.items("train")
        n, B = len(items), int(s.cfg["learning"]["batch_size"])
        n_batches = int(math.ceil(n / B))
        router = s.model.ratio_routers[area]
        learner = CodebookLearner(router, s.cfg)
        every = int(s.cfg["records"]["checkpoint_every_batches"])
        done_now = 0
        while st["epochs_completed"] < st["max_epochs"]:
            e = int(st["epochs_completed"])
            perm = epoch_permutation(int(s.cfg["seed"]), area, e, n)
            if st["phase"] == "training":
                if s.ratio_epoch_stats is None or st["next_batch"] == 0:
                    s.ratio_epoch_stats = RouteStats(s.model, ["V4"])
                    s.ratio_upd_acc = empty_update_acc(router.t)
                    st["ratio_detail_epoch_saved"] = 0
                while st["next_batch"] < n_batches:
                    if stop.requested:
                        return self._stop(area, st, "interrupted_manual", "Ctrl+C: 배치 경계에서 멈췄다.")
                    bi = int(st["next_batch"])
                    chunk = [items[i] for i in perm[bi * B:(bi + 1) * B]]
                    retries = 0
                    while True:
                        old_C, old_ver = list(router.C), router.version
                        committed = False
                        try:
                            out = self._ratio_batch(area, chunk, e, bi)
                            with stop.critical():
                                with s.timer.phase("update", gpu=be.is_cuda):
                                    ust = learner.update(out["recs"])
                                if s.fault == "interrupt_after_apply":
                                    s.fault = None
                                    raise KeyboardInterrupt
                                if s.fault == "oom_after_apply":
                                    s.fault = None
                                    raise RuntimeError("CUDA out of memory (자체 검사용 주입: 코드북 갱신 직후·집계 commit 전)")
                                self._ratio_commit(area, st, out, ust)
                                committed = True
                            break
                        except KeyboardInterrupt:
                            if not committed:
                                router.C, router.version = old_C, old_ver
                            raise
                        except BaseException as exc:        # noqa: BLE001
                            if not committed:
                                router.C, router.version = old_C, old_ver
                            if is_oom_error(exc) and retries < int(s.cfg["routing"]["oom_retry_halvings"]) and be.max_gather > 4096:
                                retries += 1
                                old = be.max_gather
                                be.max_gather = max(4096, old // 2)
                                if torch is not None and be.is_cuda:
                                    torch.cuda.empty_cache()
                                s.rec.append_jsonl("oom_events.jsonl", {
                                    "utc": utc_now(), "area": area, "epoch": e, "batch": bi, "retry": retries, "max_gather_from": old,
                                    "max_gather_to": be.max_gather, "batch_size_unchanged": len(chunk), "error": f"{type(exc).__name__}: {exc}"[:300],
                                    "note_ko": "코드북을 배치 전 상태로 두고 같은 배치를 gather 조각만 줄여 다시 계산 (수식·학습률·배치 평균·후보는 같다)"})
                                s.rec.warn(f"메모리 부족 → gather 조각 {old} → {be.max_gather} 로 같은 배치 재시도 ({retries})")
                                continue
                            if is_oom_error(exc):
                                s.rec.error("메모리 부족", exc)
                                r_ = self._stop(area, st, "oom", OOM_GUIDE_RATIO_KO)
                                s.say(OOM_GUIDE_RATIO_KO)
                                return r_
                            status = "failed_nonfinite" if isinstance(exc, NumericalError) else "failed"
                            if isinstance(exc, NumericalError):
                                st["n_nonfinite_events"] = int(st.get("n_nonfinite_events", 0)) + 1
                            s.rec.error(f"{area} epoch {e + 1} batch {bi} 오류 — 이 배치의 코드북 갱신은 적용하지 않았다", exc)
                            st["status"] = status
                            s.save_checkpoint(f"{area}_{status}", keep=True)
                            raise
                    done_now += 1
                    step = max(1, n_batches // 10)
                    if n_batches >= 20 and st["next_batch"] % step == 0 and st["next_batch"] < n_batches:
                        fr = s.ratio_epoch_stats.family_rows("V4")
                        sel = np.nanmean([x["selected_frac"] for x in fr.values() if x["selected_frac"] is not None] or [np.nan])
                        zo = np.nanmean([x["selected_but_zero_output_frac"] for x in fr.values() if x["selected_but_zero_output_frac"] is not None] or [np.nan])
                        s.say(f"    [{area} epoch {e + 1}] 배치 {st['next_batch']}/{n_batches}, 집단 선택 비율 {fmt(sel)}, 선택됐지만 출력 0 비율 {fmt(zo)}")
                    if every and st["next_batch"] % every == 0 and st["next_batch"] < n_batches:
                        with stop.critical():
                            s.save_checkpoint(f"{area}_e{e}_b{st['next_batch']}")
                    if stop_after and done_now >= stop_after:
                        return self._stop(area, st, "interrupted_test", f"검사용: {done_now} 배치 뒤 멈춤")
                with stop.critical():
                    st["phase"] = "train_done"
                    s.save_checkpoint(f"{area}_e{e}_train_done")
            if stop.requested:
                return self._stop(area, st, "interrupted_manual", "Ctrl+C: 에폭 학습 끝, V4 판독기 재계산·dev 평가 전에서 멈췄다 (재개하면 평가부터).")
            if s.fault == "interrupt_before_epoch_end":
                s.fault = None
                return self._stop(area, st, "interrupted_test", "검사용: 에폭 학습 끝, 판독기 재계산 전에서 멈춤")
            row = self._ratio_epoch_end(area, st, stop)
            s.say(f"  [{area} epoch {row['epoch_number']}] train {pct_count(row['train_correct'], row['train_n'])}, dev "
                  f"{pct_count(row['dev_correct'], row['dev_n'])} (분류 불능 {row['dev_n_unknown_zero_vector']}), 최선 시점 epoch_number "
                  f"{st['best_epoch_number']} → {row['stage_status']}")
            if st["status"] in STAGE_TERMINAL:
                break
        if st["status"] not in STAGE_TERMINAL:
            st["status"] = "budget_exhausted"
        return self._ratio_finish(area, st)

    def _ratio_batch(self, area: str, chunk: list[dict[str, Any]], e: int, bi: int) -> dict[str, Any]:
        s, be = self.s, self.s.be
        st = s.stage[area]
        lgn, y = s.loader.batch(chunk, "train")
        if s.fault == "oom_once":
            s.fault = None
            raise RuntimeError("CUDA out of memory (자체 검사용 주입)")
        if s.fault == "nonfinite_once":
            s.fault = None
            x_ = be.to_np(lgn).copy()
            x_[0, :] = np.nan
            lgn = be.f32(x_)
        rc = s.cfg["routing"]["ratio_codebook"]
        quota = min(int(rc["detail_samples_per_epoch"]) - int(st.get("ratio_detail_epoch_saved", 0)),
                    int(rc["detail_samples_max_per_stage"]) - int(st.get("ratio_detail_saved", 0)))
        keys = ("V4/L4", "V4/L2", "V4/L3")
        with s.timer.phase("forward", gpu=be.is_cuda and bool(s.cfg["compute"]["gpu_timing_sync"])):
            res = s.model.forward(lgn, upto=area, keep=keys, routing_record=True, ratio_learn=True, ratio_detail=quota > 0)
        recs = res["V4/L2"]["ratio"]["buckets"]
        rec_np = route_rec_np(be, recs)
        n_bad = int(sum(int(r["bad"].sum()) for r in rec_np))
        if n_bad:
            raise NumericalError(f"{area} 학습 배치 {bi}: 비유한 값 또는 음수 V4 L4 입력이 있는 집단 {n_bad} 개 (조용히 전달·갱신하지 않는다)")
        l6 = s.model.l6
        layers = {k_: layer_reduce(be, res[k_], l6.g_min, l6.g_max, vector=k_.endswith("/L3")) for k_ in keys[1:]}
        details = []
        if quota > 0:
            details = s.ratio_detail_records(recs, be.to_np(res["V4/L4"]["out"]).astype(np.float32), chunk, y, quota, e + 1, bi, "train_batch")
        return {"recs": recs, "rec_np": rec_np, "layers": layers, "details": details, "B": len(chunk)}

    def _ratio_commit(self, area: str, st: dict[str, Any], o: dict[str, Any], ust: list[dict[str, np.ndarray]]) -> None:
        s = self.s
        s.ratio_epoch_stats.add_route("V4", o["rec_np"])
        for k_, red in o["layers"].items():
            s.ratio_epoch_stats.add_layer(k_, red)
        for b, u in enumerate(ust):
            ua = s.ratio_upd_acc[b]
            m = u["upd"]
            ang = np.degrees(np.arccos(np.clip(u["cos"], -1.0, 1.0)))
            ua["n_upd"] += m.astype(np.int64)
            ua["sum_delta"] += np.where(m, u["delta"], 0.0)
            ua["max_delta"] = np.maximum(ua["max_delta"], np.where(m, u["delta"], 0.0))
            ua["sum_angle"] += np.where(m, ang, 0.0)
            ua["max_angle"] = np.maximum(ua["max_angle"], np.where(m, ang, 0.0))
        if o["details"]:
            s.ratio_buf.extend(o["details"])
            st["ratio_detail_saved"] = int(st.get("ratio_detail_saved", 0)) + len(o["details"])
            st["ratio_detail_epoch_saved"] = int(st.get("ratio_detail_epoch_saved", 0)) + len(o["details"])
        s.counters["codebook_updates"] = int(s.counters.get("codebook_updates", 0)) + 1
        st["next_batch"] += 1

    def _ratio_epoch_end(self, area: str, st: dict[str, Any], stop: StopFlag) -> dict[str, Any]:
        s = self.s
        e = int(st["epochs_completed"])
        ep = e + 1
        row = s.ratio_epoch_evaluation(area, ep, "epoch")
        dev_acc = row["dev_accuracy"]
        # 선택 스냅샷 = dev 정확도 최대 (동률 → 이른 시점, epoch_number 0 포함). min_delta 는 patience (정체 판정) 에만 쓴다.
        better = st["best_dev_accuracy"] is None or (dev_acc is not None and dev_acc > st["best_dev_accuracy"])
        improved = st["best_dev_accuracy"] is None or (dev_acc is not None and dev_acc > st["best_dev_accuracy"] + st["min_delta"])
        if better:
            st["best_dev_accuracy"], st["best_epoch"], st["best_epoch_number"] = dev_acc, e, ep
        st["bad_epochs"] = 0 if improved else st["bad_epochs"] + 1
        st["epochs_completed"] = ep
        succ = st["success_dev_accuracy"]
        if succ is not None and dev_acc is not None and dev_acc >= float(succ):
            st["status"] = "success_criterion_met"
        elif st["bad_epochs"] >= st["patience"]:
            st["status"] = "plateau"
        elif st["epochs_completed"] >= st["max_epochs"]:
            st["status"] = "budget_exhausted"
        else:
            st["status"] = "running"
        row.update(stage_status=st["status"], best_dev_accuracy_so_far=st["best_dev_accuracy"], patience_counter=st["bad_epochs"],
                   selected_epoch_so_far=st["best_epoch_number"], improved_this_epoch=bool(improved), new_dev_best_this_epoch=bool(better),
                   n_train_batches=int(math.ceil(len(s.data.items("train")) / int(s.cfg["learning"]["batch_size"]))))
        with stop.critical():
            if better:
                s.ratio_update_best(area, ep, row)
            st["history"].append({k: v for k, v in row.items() if k != "dev_confusion"} | {"dev_confusion": row.get("dev_confusion")})
            st["phase"], st["next_batch"] = "training", 0
            s.ratio_epoch_stats, s.ratio_upd_acc = None, None
            st["ratio_detail_epoch_saved"] = 0
            s.save_checkpoint(f"{area}_e{e}_done", keep=False)
            s.sync_training_csv()
        return row


class StageTrainer(RatioTrainerMixin):
    """현재 활성 영역 하나만 q 학습과 prototype 갱신을 한다. 앞 영역은 동결 (출력·L6 g 는 매 입력 다시 계산).
    v6 모드의 V4 는 run() 에서 q 학습 루프 (_loop: LocalErrorRouter·L1Relay·LocalOutputLearner 생성) 에 들어가기 전에 _ratio_loop 로 분기한다.

    배치 순환 (같은 입력):
      (1) 동적 상태 초기화 (forward 는 표본마다 새로 계산)  (2) 자유 순방향 → h_before, s, CONF, g
      (3) 동결 prototype 과 비교: δ = P_true − h_before      (4) LocalErrorRouter → L1Relay (주소 확인)
      (5) LocalOutputLearner: L2·L3 Δq 를 같은 스냅샷에서 계산해 동시에 적용
      (6) 같은 입력 재순방향 → h_after (실제 네트워크 출력)   (7) 같은 이전 prototype 기준 개선·악화·무변화
    에폭 끝: q 고정, train 재순방향 → 클래스 평균 → P ← (1−ρ)P + ρ·h̄ (한 번만) → dev 평가 (갱신 없음) → 단계 상태 판단.
    """

    def __init__(self, sess: Session):
        self.s = sess

    # ---------------------------------------------------------------- 진입점
    def run(self, *, extra_epochs: int | None = None, stop_after_batches: int | None = None) -> dict[str, Any]:
        s = self.s
        area = s.model.active
        st = s.stage[area]
        ratio = s.is_ratio_area(area)
        if extra_epochs is not None:
            new_max = int(st["epochs_completed"]) + int(extra_epochs)
            st["budget_changes"].append({"utc": utc_now(), "from_max_epochs": st["max_epochs"], "to_max_epochs": new_max,
                                         "from_status": st["status"],
                                         "continues_from_selected_epoch_number": (st.get("selected_epoch_number") if ratio and st.get("selected_restored")
                                                                                  else None)})
            st["max_epochs"] = new_max
            if st["status"] in STAGE_TERMINAL:
                st["bad_epochs"] = 0
                if ratio:
                    st["selected_restored"] = False
        elif st["status"] in STAGE_TERMINAL:
            return {"status": st["status"], "area": area,
                    "message_ko": f"{area} 단계는 이미 '{st['status']}' 로 끝났다. 더 학습하려면 추가 에폭 수를 준다."}
        if st["epochs_completed"] >= st["max_epochs"] and st["phase"] == "training":
            st["status"] = "budget_exhausted"
            if ratio:
                return self._ratio_finish(area, st, "에폭 예산이 0 이다 (추가 에폭을 준다). dev 최선 스냅샷으로 복원했다.")
            return {"status": st["status"], "area": area, "message_ko": "에폭 예산이 0 이다 (추가 에폭을 준다)."}
        st["status"] = "running"
        st["started_utc"] = st["started_utc"] or utc_now()
        with StopFlag(s.say) as stop:
            try:
                if ratio:                                  # V4 (v6 모드): 코드북만 학습 — q 학습기 생성 전에 분기
                    return self._ratio_loop(area, st, stop, stop_after_batches)
                return self._loop(area, st, stop, stop_after_batches)
            except KeyboardInterrupt:
                return self._stop(area, st, "interrupted_manual", "Ctrl+C 즉시 중단: 진행 중 배치는 되돌렸다.")

    def _stop(self, area: str, st: dict[str, Any], status: str, why: str) -> dict[str, Any]:
        st["status"] = status
        self.s.save_checkpoint(f"{area}_{status}", keep=True)
        self.s.rec.info(f"{area} 학습 멈춤 ({status}): {why}", echo=True)
        return {"status": status, "area": area, "message_ko": why, "checkpoint": self.s.last_checkpoint,
                "epochs_completed": st["epochs_completed"], "next_batch": st["next_batch"],
                "best_dev_accuracy": st["best_dev_accuracy"], "best_epoch": st["best_epoch"]}

    # ---------------------------------------------------------------- 에폭 반복
    def _loop(self, area: str, st: dict[str, Any], stop: StopFlag, stop_after: int | None) -> dict[str, Any]:
        s, be = self.s, self.s.be
        items = s.data.items("train")
        n, B = len(items), int(s.cfg["learning"]["batch_size"])
        n_batches = int(math.ceil(n / B))
        k2, k3 = f"{area}/L2", f"{area}/L3"
        router = s.model.routers[area]
        relay = L1Relay(area, s.model.store)
        learner = LocalOutputLearner(s.cfg, be, s.model.store)
        every = int(s.cfg["records"]["checkpoint_every_batches"])
        done_now = 0
        while st["epochs_completed"] < st["max_epochs"]:
            e = int(st["epochs_completed"])
            perm = epoch_permutation(int(s.cfg["seed"]), area, e, n)
            if st["phase"] == "training":
                while st["next_batch"] < n_batches:
                    if stop.requested:
                        return self._stop(area, st, "interrupted_manual", "Ctrl+C: 배치 경계에서 멈췄다.")
                    bi = int(st["next_batch"])
                    chunk = [items[i] for i in perm[bi * B:(bi + 1) * B]]
                    snap = {k: be.clone(s.model.store.q_view(k)) for k in (k2, k3)}
                    retries = 0
                    failure: BaseException | None = None
                    while True:
                        try:
                            out = self._batch(area, chunk, e, bi, router, relay, learner, stop)
                            with stop.critical():
                                self._commit(st, out)
                            failure = None
                            break
                        except KeyboardInterrupt:
                            self._restore(snap)
                            raise
                        except BaseException as exc:        # noqa: BLE001
                            self._restore(snap)
                            if is_oom_error(exc) and retries < int(s.cfg["routing"]["oom_retry_halvings"]) and be.max_gather > 4096:
                                retries += 1
                                old = be.max_gather
                                be.max_gather = max(4096, old // 2)
                                if torch is not None and be.is_cuda:
                                    torch.cuda.empty_cache()
                                s.rec.append_jsonl("oom_events.jsonl", {
                                    "utc": utc_now(), "area": area, "epoch": e, "batch": bi, "retry": retries, "max_gather_from": old,
                                    "max_gather_to": be.max_gather, "batch_size_unchanged": len(chunk), "error": f"{type(exc).__name__}: {exc}"[:300],
                                    "note_ko": "q 를 배치 전으로 되돌리고 같은 배치를 gather 조각만 줄여 다시 계산 (수식·배치 평균은 같다)"})
                                s.rec.warn(f"메모리 부족 → gather 조각 {old} → {be.max_gather} 로 같은 배치 재시도 ({retries})")
                                continue
                            failure = exc
                            break
                    if failure is not None:
                        if is_oom_error(failure):
                            s.rec.error("메모리 부족", failure)
                            r_ = self._stop(area, st, "oom", OOM_GUIDE_KO)
                            s.say(OOM_GUIDE_KO)
                            return r_
                        s.rec.error(f"{area} epoch {e} batch {bi} 오류 — q 를 배치 전으로 되돌리고 checkpoint 저장", failure)
                        st["status"] = "failed"
                        s.save_checkpoint(f"{area}_failed", keep=True)
                        raise failure
                    done_now += 1
                    step = max(1, n_batches // 10)
                    if n_batches >= 20 and st["next_batch"] % step == 0 and st["next_batch"] < n_batches:
                        a_ = st["acc"]
                        s.say(f"    [{area} epoch {e + 1}] 배치 {st['next_batch']}/{n_batches}, 거리 개선 비율 "
                              f"{fmt(a_['n_improved'] / max(1.0, a_['n_valid']))}")
                    if every and st["next_batch"] % every == 0 and st["next_batch"] < n_batches:
                        with stop.critical():
                            s.save_checkpoint(f"{area}_e{e}_b{st['next_batch']}")
                    if stop_after and done_now >= stop_after:
                        return self._stop(area, st, "interrupted_test", f"검사용: {done_now} 배치 뒤 멈춤")
                with stop.critical():
                    st["phase"] = "train_done"
                    s.save_checkpoint(f"{area}_e{e}_train_done")
            if stop.requested:
                return self._stop(area, st, "interrupted_manual", "Ctrl+C: 에폭 학습 끝, prototype 갱신 전에서 멈췄다 (재개하면 갱신부터).")
            row = self._epoch_end(area, st, stop)
            s.say(f"  [{area} epoch {row['epoch'] + 1}] dev 정확도 {pct_count(row['dev_correct'], row['dev_n'])} "
                  f"(유효 출력만 {fmt(row['dev_accuracy_valid_only'])}), 거리 개선 비율 {fmt(row['frac_improved'])}, "
                  f"q 효과 {fmt(row['q_effect_dist'])}, prototype 효과 {fmt(row['prototype_effect_dist'])} → {row['stage_status']}")
            if st["status"] in STAGE_TERMINAL:
                break
        if st["status"] not in STAGE_TERMINAL:
            st["status"] = "budget_exhausted"
        st["ended_utc"] = utc_now()
        st["structure_unchanged_at_end"] = (s.model.struct_hash[area] == st.get("structure_sha_at_creation")) \
            if st.get("structure_sha_at_creation") else None
        st["frozen_check_at_end"] = s.frozen_check()
        s.save_checkpoint(f"{area}_stage_{st['status']}", keep=True)
        return {"status": st["status"], "area": area, "epochs_completed": st["epochs_completed"],
                "best_dev_accuracy": st["best_dev_accuracy"], "best_epoch": st["best_epoch"], "checkpoint": s.last_checkpoint}

    def _restore(self, snap: dict[str, Any]) -> None:
        for k, v in snap.items():
            self.s.be.assign_(self.s.model.store.q_view(k), v)

    # ---------------------------------------------------------------- 한 배치
    def _batch(self, area: str, chunk: list[dict[str, Any]], e: int, bi: int, router: LocalErrorRouter, relay: L1Relay,
               learner: LocalOutputLearner, stop: StopFlag) -> dict[str, Any]:
        s, be = self.s, self.s.be
        k2, k3 = f"{area}/L2", f"{area}/L3"
        bank = s.protos[area]
        tm = s.timer
        lgn, y = s.loader.batch(chunk, "train")
        B = len(chunk)
        sha = sha256_text("\n".join(it["relpath"] for it in chunk))
        version = s.model_version(area)
        gsync = be.is_cuda and bool(s.cfg["compute"]["gpu_timing_sync"])
        rr = s.model.routing_runtime()
        want_route = rr is not None and AREA_INDEX[area] >= AREA_INDEX["V4"]
        brt = s.model.band_runtime()
        want_band = brt is not None and AREA_INDEX[area] >= AREA_INDEX["V4"]
        drt = s.model.dest_runtime()
        want_dest = drt is not None and AREA_INDEX[area] >= AREA_INDEX["V4"]
        if s.fault == "oom_once":
            s.fault = None
            raise RuntimeError("CUDA out of memory (자체 검사용 주입)")
        with tm.phase("forward", gpu=gsync):
            f0 = s.model.forward(lgn, upto=area, keep=(k2, k3) + (("V4/L4",) if want_dest else ()), routing_record=want_route or want_band or want_dest)
        h0 = f0[k3]["out"]
        route_stats, route_samples = None, []
        band_stats, band_samples = None, []
        if want_band:
            bn = band_rec_np(be, f0["V4/L2"]["band"])
            bt = brt.table
            band_stats = band_batch_stats(bt, bn, float(s.cfg["band"]["activity_epsilon"]))
            st_ = s.stage[area]
            bc = s.cfg["band"]
            quota = min(int(bc["samples_per_epoch"]) - int(st_["band_epoch_saved"]), int(bc["samples_max_per_stage"]) - int(st_["band_saved"]))
            for i in range(min(max(0, quota), B)):
                band_samples.append({"area": area, "epoch": e, "batch": bi, "sample_id": chunk[i]["relpath"], "label": int(y[i]),
                                     "X": bn["X"][i].astype(np.float16), "Z": bn["Z"][i].astype(np.float16), "G": bn["G"][i].astype(np.float16),
                                     "share": bn["share"][i].astype(np.float16), "A": bn["A"][i].astype(np.float32),
                                     "B": bn["B"][i].astype(np.float32), "low": bn["all_gates_low"][i], "missing": bt.missing,
                                     "valid": bt.cand_valid, "mode": bn["mode"]})
        if want_route:
            rn = routing_rec_np(be, f0["V4/L2"]["routing"])
            route_stats = routing_batch_stats(rr.table, rn, float(s.cfg["routing"]["high_guide_score"]))
            st_ = s.stage[area]
            ro = s.cfg["routing"]
            quota = min(int(ro["samples_per_epoch"]) - int(st_["route_epoch_saved"]), int(ro["samples_max_per_stage"]) - int(st_["route_saved"]))
            t = rr.table
            ps = point_summary(rn["R_sel"], rn["OK_sel"]) if rn.get("R_sel") is not None else None
            for i in range(min(max(0, quota), B)):
                k_ = rn["k"][i]
                route_samples.append({"area": area, "epoch": e, "batch": bi, "sample_id": chunk[i]["relpath"], "label": int(y[i]),
                                      "P": t.P, "cand_q": t.cand_q, "k": k_, "q_sel": np.where(t.missing, -1, t.cand_q[np.arange(len(k_)), k_]),
                                      "S": (rn["S"][i].astype(np.float32) if rn["S"] is not None else None), "no_guidance": rn["no_guidance"][i],
                                      "A": rn["A"][i].astype(np.float32), "B": rn["B"][i].astype(np.float32), "missing": t.missing, "mode": t.mode,
                                      "points": ({k_p: v_p[i].astype(np.float32) for k_p, v_p in ps.items()} if ps is not None else None),
                                      "S_used_for_selection": rn["S_used_for_selection"]})
        dest_stats, dest_arrays, dest_samples = None, None, []
        if want_dest:
            with tm.phase("dest_record", gpu=gsync):
                dn = dest_rec_np(be, f0["V4/L2"]["dest"])
                dest_stats, dest_arrays = dest_batch_stats(drt.table, dn, float(s.cfg["destination"]["high_score"]))
                st_ = s.stage[area]
                dc_ = s.cfg["destination"]
                quota = min(int(dc_["detail_samples_per_epoch"]) - int(st_.get("dest_epoch_saved", 0)),
                            int(dc_["detail_samples_max_per_stage"]) - int(st_.get("dest_saved", 0)))
                if quota > 0:
                    x4 = be.to_np(f0["V4/L4"]["out"]).astype(np.float32)
                    for i in range(min(quota, B)):
                        dest_samples.append(dest_sample_record(drt.table, dn, x4, i, area, e, bi, chunk[i]["relpath"], int(y[i])))
        with tm.phase("correction", gpu=be.is_cuda):
            vp = bank.valid[y]
            T = bank.targets(y)
            delta = (T - h0) * be.f32(vp.astype(np.float32)[:, None])          # 무효 prototype 표본은 δ=0
            m2_raw, m3_raw = router.route(delta)
            m2 = relay.deliver(relay.packet("L2", m2_raw, sha, version), B, be)
            m3 = relay.deliver(relay.packet("L3", m3_raw, sha, version), B, be)
            dq2 = learner.proposal(f0[k2]["s"], m2)
            dq3 = learner.proposal(f0[k3]["s"], m3)
        q_before = {k2: be.clone(s.model.store.q_view(k2)), k3: be.clone(s.model.store.q_view(k3))} if (want_dest and area == "V4") else None
        with tm.phase("update", gpu=be.is_cuda):
            with stop.critical():
                ust = learner.apply({k2: dq2, k3: dq3})
        if q_before is not None:
            with tm.phase("dest_record", gpu=gsync):                     # q 무변화 이유 기록용 (V4 L2/L3 뉴런별)
                s2, s3, u3 = f0[k2]["s"], f0[k3]["s"], f0[k3]["u"]
                dest_arrays["contrib"] = be.to_np(be.as_f32((s2 > 0) & (m2 != 0)).sum(0)).astype(np.int64)
                dest_arrays["dq_abs"] = np.abs(be.to_np(s.model.store.q_view(k2) - q_before[k2])).astype(np.float64)
                dest_arrays["l3_input_pos"] = be.to_np(be.as_f32(u3 > 0).sum(0)).astype(np.int64)
                dest_arrays["l3_active"] = be.to_np(be.as_f32(s3 > 0).sum(0)).astype(np.int64)
                dest_arrays["l3_contrib"] = be.to_np(be.as_f32((s3 > 0) & (m3 != 0)).sum(0)).astype(np.int64)
                dest_arrays["l3_dq_abs"] = np.abs(be.to_np(s.model.store.q_view(k3) - q_before[k3])).astype(np.float64)
        if s.fault == "interrupt_after_apply":
            s.fault = None
            raise KeyboardInterrupt
        with tm.phase("forward", gpu=be.is_cuda):
            h1 = s.model.forward(lgn, upto=area)[k3]["out"]
        nrm = lambda x: be.to_np(be.norm_last(x)).astype(np.float64)          # noqa: E731
        dot = lambda a, b: be.to_np((a * b).sum(-1)).astype(np.float64)       # noqa: E731
        Tn, hn0, hn1 = nrm(T), nrm(h0), nrm(h1)
        d0, d1 = nrm(T - h0), nrm(T - h1)
        dh = h1 - h0
        dhn, dln = nrm(dh), nrm(delta)
        with np.errstate(divide="ignore", invalid="ignore"):
            c0 = dot(h0, T) / (hn0 * Tn)
            c1 = dot(h1, T) / (hn1 * Tn)
            cdd = dot(dh, delta) / (dhn * dln)
        act = {}
        for lay, key in (("L2", k2), ("L3", k3)):
            ss, gg, cf = f0[key]["s"], f0[key]["g"], f0[key]["conf"]
            ne = _numel(ss)
            act[lay] = {"active_frac": _scalar(be, (ss > 0).sum()) / ne, "s_mean": _scalar(be, ss.mean()),
                        "conf_mean": _scalar(be, cf.mean()),
                        "g_min_frac": (_scalar(be, (gg <= s.model.l6.g_min + 1e-7).sum()) / ne) if gg is not None else 0.0,
                        "g_max_frac": (_scalar(be, (gg >= s.model.l6.g_max - 1e-7).sum()) / ne) if gg is not None else 0.0}
        samples = []
        st = s.stage[area]
        rc = s.cfg["records"]
        quota = min(int(rc["correction_samples_per_epoch"]) - int(st["corr_epoch_saved"]),
                    int(rc["correction_samples_max_per_stage"]) - int(st["corr_saved"]))
        if quota > 0:
            sel = [i for i in range(B) if vp[i]][:quota]
            if sel:
                idx = be.i64(np.asarray(sel))
                H0 = be.to_np(be.rows(h0, idx))
                H1 = be.to_np(be.rows(h1, idx))
                TT = be.to_np(be.rows(T, idx))
                m2n, m3n = nrm(m2), nrm(m3)
                for k_, i in enumerate(sel):
                    samples.append({"area": area, "epoch": e, "batch": bi, "sample_id": chunk[i]["relpath"], "label": int(y[i]),
                                    "h_before": H0[k_].astype(np.float32), "target": TT[k_].astype(np.float32),
                                    "h_after": H1[k_].astype(np.float32), "delta_norm": float(dln[i]), "m2_norm": float(m2n[i]),
                                    "m3_norm": float(m3n[i]), "dq2": ust[k2]["dq_applied_l2"], "dq3": ust[k3]["dq_applied_l2"],
                                    "version": version})
        return {"B": B, "vp": vp, "d0": d0, "d1": d1, "c0": c0, "c1": c1, "cdd": cdd, "dhn": dhn, "dln": dln, "Tn": Tn, "hn0": hn0,
                "ust": ust, "act": act, "samples": samples, "k2": k2, "k3": k3, "route_stats": route_stats, "route_samples": route_samples,
                "band_stats": band_stats, "band_samples": band_samples, "dest_stats": dest_stats, "dest_arrays": dest_arrays,
                "dest_samples": dest_samples}

    def _commit(self, st: dict[str, Any], o: dict[str, Any]) -> None:
        a = st["acc"]
        tol = float(self.s.cfg["learning"]["change_tol"])
        vp = o["vp"]
        a["n_batches"] += 1
        a["n_samples"] += o["B"]
        a["n_valid"] += int(vp.sum())
        a["n_skipped_invalid_proto"] += int((~vp).sum())
        d0, d1 = o["d0"][vp], o["d1"][vp]
        a["sum_d0"] += float(d0.sum())
        a["sum_d1"] += float(d1.sum())
        c0, c1 = o["c0"][vp], o["c1"][vp]
        a["sum_c0"] += float(np.nansum(c0))
        a["sum_c1"] += float(np.nansum(c1))
        a["n_improved"] += int((d1 < d0 - tol).sum())
        a["n_worsened"] += int((d1 > d0 + tol).sum())
        a["n_unchanged"] += int((np.abs(d1 - d0) <= tol).sum())
        cdd = o["cdd"][vp]
        fin = np.isfinite(cdd)
        a["sum_cos_dh_delta"] += float(cdd[fin].sum())
        a["n_cos_dh_delta"] += int(fin.sum())
        a["n_dh_zero"] += int((o["dhn"][vp] == 0).sum())
        mag = o["Tn"][vp] - o["hn0"][vp]
        a["sum_mag_err"] += float(mag.sum())
        a["sum_abs_mag_err"] += float(np.abs(mag).sum())
        ang = np.degrees(np.arccos(np.clip(c0, -1, 1)))
        a["sum_ang_err"] += float(np.nansum(ang))
        a["n_ang"] += int(np.isfinite(ang).sum())
        a["sum_delta_norm"] += float(o["dln"][vp].sum())
        for lay, key in (("L2", o["k2"]), ("L3", o["k3"])):
            u = o["ust"][key]
            a[f"{lay}_sum_dq_raw_l2"] += u["dq_raw_l2"]
            a[f"{lay}_sum_dq_applied_l2"] += u["dq_applied_l2"]
            a[f"{lay}_sum_clip_low"] += u["n_clip_low"]
            a[f"{lay}_sum_clip_high"] += u["n_clip_high"]
            a[f"{lay}_sum_n_changed"] += u["n_changed"]
            a[f"{lay}_last_at_min"] = u["n_at_min"]
            a[f"{lay}_last_at_max"] = u["n_at_max"]
            ac = o["act"][lay]
            a[f"{lay}_sum_active_frac"] += ac["active_frac"]
            a[f"{lay}_sum_s_mean"] += ac["s_mean"]
            a[f"{lay}_sum_conf_mean"] += ac["conf_mean"]
            a[f"{lay}_sum_g_min_frac"] += ac["g_min_frac"]
            a[f"{lay}_sum_g_max_frac"] += ac["g_max_frac"]
        if o["samples"]:
            self.s.corr_buf.extend(o["samples"])
            st["corr_saved"] += len(o["samples"])
            st["corr_epoch_saved"] += len(o["samples"])
        if o.get("route_stats"):
            acc_add(st["routing_acc"], o["route_stats"])
        if o.get("route_samples"):
            self.s.route_buf.extend(o["route_samples"])
            st["route_saved"] += len(o["route_samples"])
            st["route_epoch_saved"] += len(o["route_samples"])
        if o.get("band_stats"):
            acc_add(st["routing_acc"], o["band_stats"])
        if o.get("band_samples"):
            self.s.band_buf.extend(o["band_samples"])
            st["band_saved"] = int(st.get("band_saved", 0)) + len(o["band_samples"])
            st["band_epoch_saved"] = int(st.get("band_epoch_saved", 0)) + len(o["band_samples"])
        if o.get("dest_stats"):
            acc_add(st["routing_acc"], o["dest_stats"])
            dest_acc_arrays_add(self.s.dest_nacc, o["dest_arrays"])
        if o.get("dest_samples"):
            self.s.dest_buf.extend(o["dest_samples"])
            st["dest_saved"] = int(st.get("dest_saved", 0)) + len(o["dest_samples"])
            st["dest_epoch_saved"] = int(st.get("dest_epoch_saved", 0)) + len(o["dest_samples"])
        st["next_batch"] += 1

    # ---------------------------------------------------------------- 에폭 끝
    def _epoch_end(self, area: str, st: dict[str, Any], stop: StopFlag) -> dict[str, Any]:
        s, be = self.s, self.s.be
        bank = s.protos[area]
        rho = float(s.cfg["learning"]["rho"])
        e = int(st["epochs_completed"])
        store_h = s.can_store_h(area)
        P_old = be.clone(bank.P)
        ver_old = bank.version
        tp = s.pass_split(area, "train", bank=bank, collect_h=store_h)        # q 고정, train 만
        counts = tp["counts"]
        hbar = tp["sums"] * be.f32((1.0 / np.maximum(counts, 1))[:, None])
        has = be.f32((counts > 0).astype(np.float32)[:, None])
        P_new = P_old + has * (rho * (hbar - P_old))                         # = (1−ρ)P + ρ·h̄ (표본 있는 클래스만)
        dist_end_old = (tp["dist_sum"] / tp["n_dist"]) if tp["n_dist"] else None
        train_acc_old = (tp["correct"] / tp["n"]) if tp["n"] else None
        with stop.critical():
            rec = bank.set(P_new, counts, source="epoch_ema_update", split="train", sample_ids_sha256=tp["ids_sha"], epoch=e, rho=rho)
            rec["train_zero_vector_fraction"] = 1.0 - tp["n_valid_h"] / max(1, tp["n"])
            s.record_prototypes(area, rec)
        if store_h:
            dist_end_new = s.mean_dist(be.to_np(bank.P), bank.valid, tp["H"], tp["Y"])
        else:
            t2 = s.pass_split(area, "train", bank=bank)
            dist_end_new = (t2["dist_sum"] / t2["n_dist"]) if t2["n_dist"] else None
        dv = s.evaluate(area, "dev", bank, purpose=f"{area}_epoch{e}_dev")
        if dv.get("ratio"):
            s.write_ratio_routing_rows(area, e + 1, "dev_eval_frozen_V4", dv["ratio"], frozen=True)
        a = st["acc"]
        nv = max(1.0, a["n_valid"])
        nb = max(1.0, a["n_batches"])
        q_effect = (dist_end_old - st["dist_start_vs_P"]) if (dist_end_old is not None and st["dist_start_vs_P"] is not None) else None
        proto_effect = (dist_end_new - dist_end_old) if (dist_end_new is not None and dist_end_old is not None) else None
        qn = s.model.store.q_numpy()
        row: dict[str, Any] = {
            "utc": utc_now(), "area": area, "epoch": e, "epoch_number": e + 1, "model_version": s.model_version(area),
            "prototype_version_used_in_epoch": ver_old, "prototype_version_after": bank.version,
            "n_train_batches": int(a["n_batches"]), "n_train_samples": int(a["n_samples"]), "n_skipped_invalid_prototype": int(a["n_skipped_invalid_proto"]),
            "mean_dist_before": a["sum_d0"] / nv, "mean_dist_after": a["sum_d1"] / nv,
            "mean_cos_before": a["sum_c0"] / nv, "mean_cos_after": a["sum_c1"] / nv,
            "frac_improved": a["n_improved"] / nv, "frac_worsened": a["n_worsened"] / nv, "frac_unchanged": a["n_unchanged"] / nv,
            "mean_cos_dh_vs_delta": (a["sum_cos_dh_delta"] / a["n_cos_dh_delta"]) if a["n_cos_dh_delta"] else None,
            "n_dh_zero": int(a["n_dh_zero"]), "mean_magnitude_error": a["sum_mag_err"] / nv, "mean_abs_magnitude_error": a["sum_abs_mag_err"] / nv,
            "mean_direction_error_deg": (a["sum_ang_err"] / a["n_ang"]) if a["n_ang"] else None, "mean_delta_norm": a["sum_delta_norm"] / nv,
            "train_acc_vs_epoch_prototype": train_acc_old, "train_correct_vs_epoch_prototype": tp["correct"], "train_n": tp["n"],
            "train_dist_start_vs_P_old": st["dist_start_vs_P"], "train_dist_end_vs_P_old": dist_end_old, "train_dist_end_vs_P_new": dist_end_new,
            "q_effect_dist": q_effect, "prototype_effect_dist": proto_effect, "prototype_update_l2": rec["update_l2"],
            "dev_n": dv["n"], "dev_correct": dv["correct"], "dev_accuracy": dv["accuracy_overall"], "dev_accuracy_valid_only": dv["accuracy_valid_only"],
            "dev_n_unknown_zero_vector": dv["n_unknown_zero_vector"], "dev_n_ties": dv["n_ties"], "dev_mean_margin": dv["mean_margin"],
            "dev_within_class_cos": dv["geometry"].get("within_class_mean_cos_to_class_mean"),
            "dev_between_class_cos": dv["geometry"].get("between_class_mean_cos"),
            "dev_between_class_distance": dv["geometry"].get("between_class_mean_distance"),
            "dev_zero_vector_fraction": dv["geometry"].get("zero_vector_fraction"), "dev_output_variance": dv["geometry"].get("output_variance_mean"),
            "prototype_min_pair_angle_deg": None}
        pc = bank.pairwise_cos()
        C = pc.shape[0]
        off = pc[~np.eye(C, dtype=bool)] if C > 1 else np.zeros(0)
        if off.size and np.isfinite(off).any():
            row["prototype_min_pair_angle_deg"] = float(np.degrees(np.arccos(np.clip(np.nanmax(off), -1, 1))))
        for lay in ("L2", "L3"):
            sp = s.model.specs[f"{area}/{lay}"]
            q = qn[sp.start:sp.end]
            row.update({f"{lay}_dq_raw_l2_mean": a[f"{lay}_sum_dq_raw_l2"] / nb, f"{lay}_dq_applied_l2_mean": a[f"{lay}_sum_dq_applied_l2"] / nb,
                        f"{lay}_n_clip_low_total": int(a[f"{lay}_sum_clip_low"]), f"{lay}_n_clip_high_total": int(a[f"{lay}_sum_clip_high"]),
                        f"{lay}_q_mean": float(q.mean()), f"{lay}_q_min": float(q.min()), f"{lay}_q_max": float(q.max()),
                        f"{lay}_n_q_at_min": int((q <= float(s.cfg['neuron']['q_min'])).sum()),
                        f"{lay}_n_q_at_max": int((q >= float(s.cfg['neuron']['q_max'])).sum()),
                        f"{lay}_active_frac_mean": a[f"{lay}_sum_active_frac"] / nb, f"{lay}_s_mean": a[f"{lay}_sum_s_mean"] / nb,
                        f"{lay}_conf_mean": a[f"{lay}_sum_conf_mean"] / nb, f"{lay}_g_at_min_frac": a[f"{lay}_sum_g_min_frac"] / nb,
                        f"{lay}_g_at_max_frac": a[f"{lay}_sum_g_max_frac"] / nb})
        row.update(s.timer.take())
        row.update(dev_per_class_accuracy=dv["per_class_accuracy"], dev_confusion=dv["confusion"],
                   dev_output_norm_mean=dv["geometry"].get("output_norm_mean"), routing_mode=s.cfg["routing"]["mode"],
                   cache_mb=round(s.loader.cache_bytes / 2 ** 20, 3), max_gather_elements_now=be.max_gather)
        if be.is_cuda:
            row["gpu_max_memory_allocated_mb"] = round(torch.cuda.max_memory_allocated(be.dev) / 2 ** 20, 1)
            torch.cuda.reset_peak_memory_stats(be.dev)
        rr = s.model.routing_runtime()
        if rr is not None and AREA_INDEX[area] >= AREA_INDEX["V4"]:
            tr_r = routing_finalize(st["routing_acc"], rr.K)
            s.write_routing_row(area, e, "train_epoch", tr_r)
            if dv.get("routing"):
                s.write_routing_row(area, e, "dev_eval", dv["routing"])
            row.update({f"routing_train_{k}": v for k, v in tr_r.items() if not isinstance(v, list)})
            if dv.get("routing"):
                row.update({f"routing_dev_{k}": v for k, v in dv["routing"].items() if not isinstance(v, list)})
        drt = s.model.dest_runtime()
        if drt is not None and AREA_INDEX[area] >= AREA_INDEX["V4"]:
            tr_d = dest_finalize(st["routing_acc"], drt.table)
            s.write_dest_row(area, e, "train_epoch", tr_d)
            if dv.get("dest"):
                s.write_dest_row(area, e, "dev_eval", dv["dest"])
            for ctx_, src_ in (("train", tr_d), ("dev", dv.get("dest"))):
                if src_:
                    row.update({f"dest_{ctx_}_{k}": src_.get(k) for k in DEST_TRAINING_CSV_KEYS})
            rep_ = dest_neuron_report(drt.table, s.dest_nacc, int(a["n_samples"]),
                                      l3={k_[3:]: v_ for k_, v_ in s.dest_nacc.items() if k_.startswith("l3_")},
                                      change_tol=float(s.cfg["learning"]["change_tol"]))
            s.write_dest_epoch_files(area, e, rep_, dv.get("dest_roles_report"))
            s.dest_nacc = {}
        st["dest_epoch_saved"] = 0
        brt = s.model.band_runtime()
        if brt is not None and AREA_INDEX[area] >= AREA_INDEX["V4"]:
            tr_b = band_finalize(st["routing_acc"], brt.table)
            s.write_band_row(area, e, "train_epoch", tr_b)
            if dv.get("band"):
                s.write_band_row(area, e, "dev_eval", dv["band"])
            row.update({f"band_train_{k}": v for k, v in tr_b.items() if not isinstance(v, (list, dict))})
            if dv.get("band"):
                row.update({f"band_dev_{k}": v for k, v in dv["band"].items() if not isinstance(v, (list, dict))})
        st["routing_acc"], st["route_epoch_saved"], st["band_epoch_saved"] = {}, 0, 0
        dev_acc = dv["accuracy_overall"]
        improved = st["best_dev_accuracy"] is None or (dev_acc is not None and dev_acc > st["best_dev_accuracy"] + st["min_delta"])
        if improved:
            st["best_dev_accuracy"], st["best_epoch"], st["bad_epochs"] = dev_acc, e, 0
        else:
            st["bad_epochs"] += 1
        st["epochs_completed"] = e + 1
        succ = st["success_dev_accuracy"]
        if succ is not None and dev_acc is not None and dev_acc >= float(succ):
            st["status"] = "success_criterion_met"
        elif st["bad_epochs"] >= st["patience"]:
            st["status"] = "plateau"
        elif st["epochs_completed"] >= st["max_epochs"]:
            st["status"] = "budget_exhausted"
        else:
            st["status"] = "running"
        row["stage_status"] = st["status"]
        row["best_dev_accuracy_so_far"] = st["best_dev_accuracy"]
        row["patience_counter"] = st["bad_epochs"]
        st["history"].append(row)
        st["phase"], st["next_batch"], st["acc"] = "training", 0, empty_acc()
        st["dist_start_vs_P"] = dist_end_new
        st["corr_epoch_saved"] = 0
        with stop.critical():
            s.save_checkpoint(f"{area}_e{e}_done", keep=False)
            s.sync_training_csv()
        return row


# ======================================================================
# 14. 진단 (Diagnostics) — 원본 상태를 복원하거나 복제 구조 (override) 에서 수행한다
# ======================================================================
FORBIDDEN_GRAD_PATTERNS = (r"\.backward\s*\(", r"\bautograd\b", r"torch\.func\b", r"\bjacrev\b", r"\bjacfwd\b", r"\bvjp\b", r"\bjvp\b",
                           r"requires_grad\s*=\s*True", r"requires_grad_\(\s*True", r"enable_grad", r"retain_graph", r"\bfunctorch\b")


class Diagnostics:
    def __init__(self, sess: Session):
        self.s = sess

    # ---------------------------------------------------------------- 공통
    def _probe(self, n: int | None = None, split: str = "train") -> tuple[Any, np.ndarray, list[dict[str, Any]]]:
        n = n or int(self.s.cfg["records"]["diagnostic_samples"])
        items = self.s.data.items(split)[:n]
        lgn, y = self.s.loader.batch(items, split)
        return lgn, y, items

    def _snapshot(self) -> dict[str, Any]:
        be = self.s.be
        rr = self.s.ratio_router()
        snap = {"q": be.clone(self.s.model.store.q), "P": {a: be.clone(b.P) for a, b in self.s.protos.items()},
                "valid": {a: b.valid.copy() for a, b in self.s.protos.items()}, "rng": copy.deepcopy(self.s.rng.bit_generator.state),
                "q_sha": sha256_array(self.s.model.store.q_numpy()), "P_sha": {a: b.sha() for a, b in self.s.protos.items()},
                "readouts": {a: ro.copy() for a, ro in self.s.readouts.items()}, "R_sha": {a: ro.sha() for a, ro in self.s.readouts.items()},
                "max_gather": be.max_gather}
        if rr is not None:
            snap.update(C=[be.clone(c) for c in rr.C], ok=[be.clone(o) for o in rr.ok], cver=rr.version, cinit=rr.initialized, C_sha=rr.codebook_sha(),
                        ratio_best=self.s.ratio_best, ratio_es=self.s.ratio_epoch_stats, ratio_ua=copy.deepcopy(self.s.ratio_upd_acc),
                        ratio_buf=list(self.s.ratio_buf))
        return snap

    def _restore(self, snap: dict[str, Any]) -> bool:
        be = self.s.be
        be.assign_(self.s.model.store.q, snap["q"])
        for a, b in self.s.protos.items():
            b.P = be.clone(snap["P"][a])
            b.valid = snap["valid"][a].copy()
        self.s.readouts = {a: ro.copy() for a, ro in snap["readouts"].items()}
        self.s.rng.bit_generator.state = snap["rng"]
        be.max_gather = snap["max_gather"]
        rr = self.s.ratio_router()
        ok_c = True
        if rr is not None and "C" in snap:
            rr.C, rr.ok = [be.clone(c) for c in snap["C"]], [be.clone(o) for o in snap["ok"]]
            rr.version, rr.initialized = snap["cver"], snap["cinit"]
            self.s.ratio_best, self.s.ratio_epoch_stats, self.s.ratio_upd_acc = snap["ratio_best"], snap["ratio_es"], snap["ratio_ua"]
            self.s.ratio_buf = list(snap["ratio_buf"])
            self.s._cb_sha_cache = (-1, None, None)
            ok_c = rr.codebook_sha() == snap["C_sha"]
        return sha256_array(self.s.model.store.q_numpy()) == snap["q_sha"] and all(
            b.sha() == snap["P_sha"][a] for a, b in self.s.protos.items()) and ok_c and all(
            ro.sha() == snap["R_sha"][a] for a, ro in self.s.readouts.items())

    def _all_sha(self) -> dict[str, str]:
        out = {f"P_{x}": bk.sha() for x, bk in self.s.protos.items()}
        out.update({f"R_{x}": ro.sha() for x, ro in self.s.readouts.items()})
        cs = self.s.codebook_sha()
        if cs:
            out["codebook_V4"] = cs
        return out

    def _ratio_na(self, what: str) -> dict[str, Any] | None:
        if self.s.is_ratio_area(self.s.model.active):
            return {"status": NOT_APPLICABLE, "reason_ko": f"활성 영역이 V4 (v6 비율 라우팅 모드) 다. V4 는 q 를 학습하지 않으므로 {what} 은 해당 없다 "
                                                          "(V4 학습은 코드북만 — 검사 V01~V23 이 확인). IT 단계에서는 이 검사가 IT 의 q 학습을 검사한다."}
        return None

    @staticmethod
    def _run(name: str, fn: Callable[[], dict[str, Any]], out: dict[str, Any]) -> None:
        try:
            out[name] = fn()
        except Exception as exc:                             # noqa: BLE001  — 검사 실패는 FAILED 로 남긴다 (성공으로 표시하지 않음)
            out[name] = {"status": FAILED, "error": f"{type(exc).__name__}: {exc}", "traceback": traceback.format_exc(limit=6)}

    # ---------------------------------------------------------------- 기본 검사 1~14
    def run_basic(self) -> dict[str, Any]:
        s = self.s
        if s.model is None:
            raise RuntimeError("모델이 없다 (메뉴 3).")
        snap = self._snapshot()
        out: dict[str, Any] = {}
        try:
            for name, fn in (("C01_repeat_forward_and_eval_invariance", self.c01), ("C02_zero_m_no_change_and_q_bounds", self.c02),
                             ("C03_l1_address", self.c03), ("C04_routing_one_to_one_and_convergence", self.c04),
                             ("C05_input_contribution_sum", self.c05), ("C06_frozen_areas_unchanged", self.c06),
                             ("C07_prototype_train_only", self.c07), ("C08_l6_does_not_change_q", self.c08),
                             ("C09_q_change_persists_in_next_forward", self.c09), ("C10_unresponsive_neurons", self.c10),
                             ("C11_h_before_after_one_step", self.c11), ("C12_prototype_and_output_geometry", self.c12),
                             ("C13_role_responses_quick", lambda: self.role_responses(quick=True)),
                             ("C14_no_global_gradient", self.c14)):
                self._run(name, fn, out)
                if not self._restore(snap):
                    out[name + "_RESTORE"] = {"status": FAILED, "error": "진단 뒤 q/prototype 복원 실패"}
        finally:
            restored = self._restore(snap)
        summary = {"utc": utc_now(), "model_version": s.model_version(), "probe_scope_ko": "train 앞쪽 표본 몇 개 (갱신은 복원)",
                   "restored": restored, "n_failed": sum(1 for v in out.values() if isinstance(v, dict) and v.get("status") == FAILED),
                   "checks": out}
        summary["status"] = FAILED if (summary["n_failed"] or not restored) else PASSED
        if s.rec is not None:
            s.rec.json(f"diagnostics/basic_{local_stamp()}_{time.time_ns() % 100000}.json", summary)
            self._append_index("basic", summary)
        return summary

    def _append_index(self, kind: str, summary: dict[str, Any]) -> None:
        r = self.s.rec
        p = r.p("diagnostics.json")
        cur = read_json(p) if p.is_file() else {"runs": []}
        cur["runs"].append({"kind": kind, "utc": summary.get("utc"), "model_version": summary.get("model_version"),
                            "status": summary.get("status"),
                            "checks": {k: (v.get("status") if isinstance(v, dict) else v) for k, v in (summary.get("checks") or {}).items()}})
        r.json("diagnostics.json", cur)

    def c01(self) -> dict[str, Any]:
        s, be = self.s, self.s.be
        lgn, _y, _ = self._probe()
        keys = s.model.layer_keys()
        a = s.model.forward(lgn, keep=keys)
        b = s.model.forward(lgn, keep=keys)
        diff = {k: float(np.abs(be.to_np(a[k]["out"]) - be.to_np(b[k]["out"])).max()) for k in keys}
        q0, p0 = sha256_array(s.model.store.q_numpy()), self._all_sha()
        area = s.model.active
        bank = s.classifier(area)
        cosine_classify(be, a[f"{area}/L3"]["out"], bank.P, bank.valid, float(s.cfg["learning"]["eps_norm"]))
        q1, p1 = sha256_array(s.model.store.q_numpy()), self._all_sha()
        ok = all(v == 0.0 for v in diff.values()) and q0 == q1 and p0 == p1
        return {"status": PASSED if ok else FAILED, "max_abs_diff_by_layer": diff, "eval_q_unchanged": q0 == q1,
                "eval_prototypes_unchanged": p0 == p1, "rule_ko": "같은 상태·입력의 반복 순방향 차이 0, 평가 전후 q·prototype 해시 동일"}

    def c02(self) -> dict[str, Any]:
        s, be = self.s, self.s.be
        area = s.model.active
        if s.is_ratio_area(area):                          # V4 (v6): q 고정 확인으로 대신한다 (L1·q 갱신 경로를 호출하지 않는다)
            qf = float(s.cfg["routing"]["ratio_codebook"]["v4_q_fixed"])
            q0 = s.model.store.q_numpy()
            lgn, _y, _ = self._probe()
            s.model.forward(lgn, keep=s.model.layer_keys())
            q1 = s.model.store.q_numpy()
            v4 = np.concatenate([q1[s.model.specs[f"V4/{l}"].start:s.model.specs[f"V4/{l}"].end] for l in LAYER_ORDER])
            ok = bool(np.array_equal(q0, q1) and (v4 == qf).all())
            return {"status": PASSED if ok else FAILED, "adapted_for_v6_ratio_V4": True, "V4_q_all_fixed": bool((v4 == qf).all()),
                    "q_unchanged_by_forward": bool(np.array_equal(q0, q1)), "v4_q_fixed": qf}
        lgn, _y, _ = self._probe()
        k2, k3 = f"{area}/L2", f"{area}/L3"
        f = s.model.forward(lgn, keep=(k2, k3))
        L = LocalOutputLearner(s.cfg, be, s.model.store)
        dq2 = L.proposal(f[k2]["s"], be.zeros(f[k2]["s"].shape))
        dq3 = L.proposal(f[k3]["s"], be.zeros(f[k3]["s"].shape))
        mx = max(float(np.abs(be.to_np(dq2)).max()), float(np.abs(be.to_np(dq3)).max()))
        before = s.model.store.q_numpy()
        L.apply({k2: dq2, k3: dq3})
        after = s.model.store.q_numpy()
        ne = s.cfg["neuron"]
        l4 = np.concatenate([after[s.model.specs[f"{a}/L4"].start:s.model.specs[f"{a}/L4"].end] for a in s.model.areas])
        l4_ref = np.concatenate([np.full(s.model.specs[f"{a}/L4"].n, float(s.cfg["routing"]["ratio_codebook"]["v4_q_fixed"])
                                         if (a == "V4" and s.ratio_mode) else float(ne["q_init"])) for a in s.model.areas])
        bounds_ok = bool(np.isfinite(after).all() and after.min() >= float(ne["q_min"]) and after.max() <= float(ne["q_max"]))
        ok = mx == 0.0 and np.array_equal(before, after) and bounds_ok and bool((l4 == l4_ref).all())
        return {"status": PASSED if ok else FAILED, "max_abs_dq_for_m0": mx, "q_identical_after_apply": bool(np.array_equal(before, after)),
                "q_finite_and_in_bounds": bounds_ok, "L4_q_fixed_at_init": bool((l4 == l4_ref).all()),
                "q_range": [float(after.min()), float(after.max())]}

    def c03(self) -> dict[str, Any]:
        na = self._ratio_na("L1 주소 배달 검사")
        if na:
            return na
        s, be = self.s, self.s.be
        area = s.model.active
        relay = L1Relay(area, s.model.store)
        n3 = s.model.specs[f"{area}/L3"].n
        B = 3
        delta = be.f32(self.s.rng.normal(0, 0.1, size=(B, n3)))
        m2, m3 = s.model.routers[area].route(delta)
        ok_deliver = True
        try:
            relay.deliver(relay.packet("L2", m2, "x", "v"), B, be)
            relay.deliver(relay.packet("L3", m3, "x", "v"), B, be)
        except L1AddressError:
            ok_deliver = False
        bad = {}
        tamper = {"wrong_layer": lambda p: dataclasses.replace(p, layer="L4"),
                  "wrong_area": lambda p: dataclasses.replace(p, area="ZZ"),
                  "wrong_ids": lambda p: dataclasses.replace(p, ids_sha256="0" * 64),
                  "wrong_range": lambda p: dataclasses.replace(p, start=p.start + 1),
                  "wrong_shape": lambda p: dataclasses.replace(p, m=p.m[:, :-1])}
        for nm, fn in tamper.items():
            try:
                relay.deliver(fn(relay.packet("L3", m3, "x", "v")), B, be)
                bad[nm] = "accepted (FAIL)"
            except L1AddressError:
                bad[nm] = "rejected"
        before = s.model.store.q_numpy()
        lgn, _y, _ = self._probe(B)
        k2, k3 = f"{area}/L2", f"{area}/L3"
        f = s.model.forward(lgn, keep=(k2, k3))
        L = LocalOutputLearner(s.cfg, be, s.model.store)
        L.apply({k2: L.proposal(f[k2]["s"], m2), k3: L.proposal(f[k3]["s"], m3)})
        after = s.model.store.q_numpy()
        changed = np.nonzero(after != before)[0]
        lo, hi = s.model.specs[k2].start, s.model.specs[k3].end
        inside = bool(((changed >= lo) & (changed < hi)).all())
        ok = ok_deliver and all(v == "rejected" for v in bad.values()) and inside
        return {"status": PASSED if ok else FAILED, "valid_packets_delivered": ok_deliver, "tampered_packets": bad,
                "n_q_changed": int(changed.size), "changes_only_inside_active_L2_L3": inside, "active_id_range": [int(lo), int(hi)]}

    def c04(self) -> dict[str, Any]:
        s, be = self.s, self.s.be
        rows = {}
        ok = True
        for area in s.model.areas:
            rt = s.model.routers[area]
            n3 = s.model.specs[f"{area}/L3"].n
            colsum_err = float(np.abs(rt.R_col_sum - 1.0).max())
            d = self.s.rng.normal(0, 1, size=(2, n3)).astype(np.float32)
            m2, _m3 = rt.route(be.f32(d))
            m2 = be.to_np(m2).astype(np.float64)
            ref = np.zeros_like(m2)
            for j_row, i_src in zip(rt.parent_rows, rt.parent_src):
                ref[:, i_src] += rt.alpha2 * d[:, j_row] / rt.parent_count[j_row]
            ref_err = float(np.abs(ref - m2).max())
            tot_err = float(np.abs(m2.sum(1) - rt.alpha2 * d.astype(np.float64).sum(1)).max())
            r = {"one_to_one": rt.one_to_one, "R_column_sum_max_abs_error": colsum_err, "max_abs_vs_explicit_parent_loop": ref_err,
                 "total_mass_error": tot_err, "parents_per_L3": rt.describe()["parents_per_L3"],
                 "L2_without_child": rt.n2_without_child}
            if rt.one_to_one:
                exact = np.zeros_like(m2)
                exact[:, rt.parent_src] = rt.alpha2 * d[:, rt.parent_rows]
                r["one_to_one_exact"] = bool(np.array_equal(exact.astype(np.float32), m2.astype(np.float32)))
                ok &= r["one_to_one_exact"]
            ok &= colsum_err < 1e-6 and ref_err < 1e-5 and (tot_err < 1e-3 * (1 + n3) or rt.n2_without_child > 0)
            rows[area] = r
        return {"status": PASSED if ok else FAILED, "areas": rows,
                "rule_ko": "R_ij = 1/|P(j)| 열 합 1, 명시적 부모 반복과 일치, 일대일 구간은 m_L2 = α2·δ (대응 위치) 정확히"}

    def c05(self) -> dict[str, Any]:
        s, be = self.s, self.s.be
        lgn, _y, _ = self._probe(2)
        keys = s.model.layer_keys()
        res = s.model.forward(lgn, keep=["LGN"] + keys)
        worst, rows = 0.0, []
        for key in keys:
            sp = s.model.specs[key]
            src = be.to_np(res[sp.src_key]["out"]).astype(np.float64)
            if sp.ratio is not None:                       # v6 V4/L2: float64 독립 기준식 (후보 edge 목록에서 직접) 과 장치 경로 비교
                rr_ = s.model.rt[key].ratio
                C_, ok_ = rr_.get_codebook()
                ref = route_reference(sp.ratio, C_, ok_, src, s.cfg)
                u_ = be.to_np(res[key]["u"]).astype(np.float64)
                gap = ref["gap"][:, sp.ratio.l2_group]
                okm = ~(np.isfinite(gap) & (gap < 1e-5))   # 거의 동점 집단의 목적지는 따로 센다 (부동소수 축약 순서 차이)
                err = float((np.abs(ref["u"] - u_) * okm).max() / (1.0 + np.abs(ref["u"]).max())) if u_.size else 0.0
                worst = max(worst, err)
                rows.append({"layer": key, "local": -1, "op": "ratio_route_vs_float64_reference", "rel_err": err,
                             "n_input": int(sp.ratio.e_src.size), "routed": True, "missing_candidate": False,
                             "near_tie_destinations_excluded": int((~okm).sum())})
                continue
            band_ref = None
            if sp.band is not None:                                # 강도 구간 행: NumPy float64 기준식으로 따로 계산한 B (장치 경로와 독립)
                brt = s.model.rt[key].band
                band_ref = band_reference_B(sp.band, brt.calibration, np.concatenate([src, np.zeros((src.shape[0], 1))], 1), s.cfg, brt.mode)["B"]
            u = be.to_np(res[key]["u"]).astype(np.float64)
            pick = self.s.rng.choice(sp.n, size=min(6, sp.n), replace=False)
            routed = sp.routed if sp.routed is not None else np.zeros(sp.n, bool)
            if routed.any():                                       # 라우팅 행도 표본에 섞어 넣는다
                pick = np.unique(np.concatenate([pick, self.s.rng.choice(np.nonzero(routed)[0], size=min(6, int(routed.sum())), replace=False)]))
            for j in pick:
                r = sp.row(int(j))
                ua = (src[:, r["a_src"]] * r["a_w"]).sum(1)
                ub = (src[:, r["b_src"]] * r["b_w"]).sum(1) if r["b_src"].size else np.zeros(src.shape[0])
                if routed[j] and band_ref is not None:             # 후보 x 를 연결별 게이트로 가중평균한 B (기준식)
                    ub = band_ref[:, int(np.nonzero(sp.band.curve_rows == j)[0][0])]
                elif routed[j] and sp.dest is not None:            # 목적지 선택: 이번 표본의 곡선 Q* 원천 (선택 기록)
                    ci = int(sp.dest.dst_role_index[j])
                    sel = be.to_np(res[key]["dest"]["curve_src"])[:, ci]
                    srcp = np.concatenate([src, np.zeros((src.shape[0], 1))], 1)
                    ub = srcp[np.arange(src.shape[0]), sel]
                elif routed[j]:                                    # 이번 표본에서 실제로 고른 B 주소 (정적 후보가 아니라 선택 기록)
                    t = sp.routing
                    ci = int(np.nonzero(t.curve_rows == j)[0][0])
                    sel = be.to_np(res[key]["routing"]["sel_src"])[:, ci]
                    srcp = np.concatenate([src, np.zeros((src.shape[0], 1))], 1)
                    ub = srcp[np.arange(src.shape[0]), sel]
                ue = np.minimum(ua, ub) if sp.op_min[j] else ua + ub
                if sp.missing is not None and sp.missing[j]:
                    ue = np.zeros_like(ue)
                if sp.dest is not None:                            # 선택되지 않은 목적지는 u = 0 (이번 표본의 선택 마스크)
                    ue = ue * be.to_np(res[key]["dest"]["mask"])[:, j]
                err = float(np.abs(ue - u[:, j]).max() / (1.0 + np.abs(ue).max()))
                worst = max(worst, err)
                rows.append({"layer": key, "local": int(j), "op": "min2" if sp.op_min[j] else "linear", "rel_err": err,
                             "n_input": int(r["a_src"].size + r["b_src"].size), "routed": bool(routed[j]),
                             "missing_candidate": bool(sp.missing is not None and sp.missing[j])})
        dups = {k: s.model.specs[k].build_stats.get("merged_duplicate_edges", 0) for k in keys}
        return {"status": PASSED if worst < 1e-5 else FAILED, "worst_rel_error": worst, "samples": rows,
                "duplicate_policy": "merge_sum (같은 수신·입력군·송신은 가중치 합으로 하나), 구조 검증에서 남은 중복 0 확인",
                "merged_duplicates_at_build": dups}

    def c06(self) -> dict[str, Any]:
        if not self.s.frozen:
            return {"status": NOT_APPLICABLE, "reason_ko": "동결된 앞 영역이 아직 없다 (V1 단계)."}
        chk = self.s.frozen_check()
        ok = all(all(v.values()) for v in chk.values())
        return {"status": PASSED if ok else FAILED, "areas": chk}

    def c07(self) -> dict[str, Any]:
        s = self.s
        train_sha = s.data.ids_sha("train")
        n_train = len(s.data.items("train"))
        rows = {}
        ok = True
        for area, bank in s.protos.items():
            hs = bank.history
            splits = sorted({h["split"] for h in hs})
            same_ids = all(h["sample_ids_sha256"] == train_sha for h in hs)
            counts_ok = all(sum(h["counts"]) == n_train for h in hs)
            rows[area] = {"n_updates": len(hs), "splits_used": splits, "sample_ids_equal_train": same_ids, "counts_sum_equal_n_train": counts_ok}
            ok &= splits == ["train"] and same_ids and counts_ok
        for area, ro in s.readouts.items():                  # v6 V4 판독기: train 만으로 적합
            mt = ro.meta or {}
            same_ids = mt.get("sample_ids_sha256") == sha256_text("\n".join(sorted(it["relpath"] for it in s.data.items("train")))) or \
                mt.get("sample_ids_sha256") == train_sha
            rows[f"{area}_readout"] = {"split": mt.get("split"), "sample_ids_equal_train": bool(same_ids),
                                       "counts_sum_equal_n_train": int(sum(mt.get("counts", []))) == n_train}
            ok &= mt.get("split") == "train" and bool(same_ids) and int(sum(mt.get("counts", []))) == n_train
        return {"status": PASSED if ok else FAILED, "areas": rows, "loader_access": dict(s.loader.access)}

    def c08(self) -> dict[str, Any]:
        s, be = self.s, self.s.be
        lgn, _y, _ = self._probe()
        keys = [k for k in s.model.layer_keys() if s.model.rt[k].l6]
        q0 = s.model.store.q_numpy()
        res = s.model.forward(lgn, keep=keys)
        q1 = s.model.store.q_numpy()
        gstats, ok_g = {}, True
        for k in keys:
            g = be.to_np(res[k]["g"])
            conf, out = be.to_np(res[k]["conf"]), be.to_np(res[k]["out"])
            ok_g &= bool(np.allclose(out, g * conf, atol=1e-7)) and g.min() >= s.model.l6.g_min - 1e-7 and g.max() <= s.model.l6.g_max + 1e-7
            gstats[k] = {"g_min": float(g.min()), "g_max": float(g.max()), "g_mean": float(g.mean()),
                         "frac_at_g_min": float((g <= s.model.l6.g_min + 1e-7).mean()), "frac_at_g_max": float((g >= s.model.l6.g_max - 1e-7).mean()),
                         "neurons_without_neighbor": s.model.rt[k].n_no_neighbor}
        ok = np.array_equal(q0, q1) and ok_g
        return {"status": PASSED if ok else FAILED, "q_unchanged_by_l6": bool(np.array_equal(q0, q1)), "out_equals_g_times_conf": ok_g,
                "layers": gstats}

    def c09(self) -> dict[str, Any]:
        na = self._ratio_na("q 변화의 지속 검사")
        if na:
            return na
        s, be = self.s, self.s.be
        area = s.model.active
        k3 = f"{area}/L3"
        lgn, _y, _ = self._probe(1)
        f0 = s.model.forward(lgn, keep=(k3,))
        sv = be.to_np(f0[k3]["s"])[0]
        q = be.to_np(s.model.store.q_view(k3)).copy()
        qmax = float(s.cfg["neuron"]["q_max"])
        cand = np.nonzero((sv > 0) & (q < qmax - 0.1))[0]
        if cand.size == 0:
            return {"status": MEASURED, "reason_ko": "탐침 표본에서 s>0 이고 q 를 올릴 수 있는 L3 뉴런이 없다 (s=0 또는 q 포화).",
                    "n_active_L3": int((sv > 0).sum())}
        j = int(cand[0])
        q2 = q.copy()
        q2[j] = min(qmax, q[j] + 0.5)
        be.assign_(s.model.store.q_view(k3), be.f32(q2))
        o1 = be.to_np(s.model.forward(lgn)[k3]["out"])[0]
        o2 = be.to_np(s.model.forward(lgn)[k3]["out"])[0]
        o0 = be.to_np(f0[k3]["out"])[0]
        changed = bool(o1[j] != o0[j])
        persist = bool(np.array_equal(o1, o2))
        return {"status": PASSED if (changed and persist) else FAILED, "neuron_local": j, "q_before": float(q[j]), "q_after": float(q2[j]),
                "out_before": float(o0[j]), "out_after": float(o1[j]), "effect_persists_next_forward": persist,
                "n_other_neurons_changed_via_l6": int((o1 != o0).sum() - (1 if changed else 0))}

    def c10(self) -> dict[str, Any]:
        s, be = self.s, self.s.be
        area = s.model.active
        lgn, _y, _ = self._probe()
        keys = (f"{area}/L2", f"{area}/L3")
        res = s.model.forward(lgn, keep=keys)
        ne = s.cfg["neuron"]
        rows = {}
        for k in keys:
            sv = be.to_np(res[k]["s"])
            q = be.to_np(s.model.store.q_view(k))
            g = be.to_np(res[k]["g"]) if res[k]["g"] is not None else np.ones_like(sv)
            never = (sv <= 0).all(axis=0)
            qz = q <= float(ne["q_min"])
            rows[k] = {"n": int(sv.shape[1]), "s_zero_all_probe": int(never.sum()), "q_at_min": int(qz.sum()),
                       "q_at_min_but_s_positive_recoverable_if_delta_positive": int((qz & ~never).sum()),
                       "q_at_max": int((q >= float(ne["q_max"])).sum()),
                       "g_at_bound_all_probe": int(((g <= s.model.l6.g_min + 1e-7) | (g >= s.model.l6.g_max - 1e-7)).all(axis=0).sum()),
                       "cause_ko": "s=0 이면 e=0 이라 이 입력들로는 q 가 바뀌지 않는다; q=q_min 이면 출력 0 (s>0 이면 δ>0 일 때 회복 가능, 보장 아님)"}
        return {"status": MEASURED, "probe_samples": int(lgn.shape[0]), "layers": rows}

    def c11(self) -> dict[str, Any]:
        na = self._ratio_na("한 번의 q 갱신 전후 비교")
        if na:
            return na
        s, be = self.s, self.s.be
        area = s.model.active
        bank = s.protos[area]
        lgn, y, _ = self._probe()
        k2, k3 = f"{area}/L2", f"{area}/L3"
        f0 = s.model.forward(lgn, keep=(k2, k3))
        h0 = f0[k3]["out"]
        T = bank.targets(y)
        vp = bank.valid[y]
        delta = (T - h0) * be.f32(vp.astype(np.float32)[:, None])
        m2, m3 = s.model.routers[area].route(delta)
        L = LocalOutputLearner(s.cfg, be, s.model.store)
        ust = L.apply({k2: L.proposal(f0[k2]["s"], m2), k3: L.proposal(f0[k3]["s"], m3)})
        h1 = s.model.forward(lgn)[k3]["out"]
        H0, H1, TT, D = (be.to_np(x).astype(np.float64) for x in (h0, h1, T, delta))
        d0, d1 = np.linalg.norm(TT - H0, axis=1), np.linalg.norm(TT - H1, axis=1)
        dh = H1 - H0
        with np.errstate(divide="ignore", invalid="ignore"):
            cdd = (dh * D).sum(1) / (np.linalg.norm(dh, axis=1) * np.linalg.norm(D, axis=1))
        tol = float(s.cfg["learning"]["change_tol"])
        return {"status": MEASURED, "dist_before": d0.tolist(), "dist_after": d1.tolist(),
                "improved": int((d1 < d0 - tol).sum()), "worsened": int((d1 > d0 + tol).sum()), "unchanged": int((np.abs(d1 - d0) <= tol).sum()),
                "cos_dh_vs_delta": [None if not np.isfinite(v) else float(v) for v in cdd], "update_stats": ust,
                "note_ko": "한 번의 국소 갱신 뒤 실제 재순방향 결과 (같은 이전 prototype 기준). 개선을 통과 조건으로 쓰지 않는다. 진단 뒤 q 를 되돌린다."}

    def c12(self) -> dict[str, Any]:
        s, be = self.s, self.s.be
        area = s.model.active
        bank = s.classifier(area)
        items = s.data.items("train")[:64]
        lgn, y = s.loader.batch(items, "train")
        H = be.to_np(s.model.forward(lgn, upto=area)[f"{area}/L3"]["out"])
        pc = bank.pairwise_cos()
        C = pc.shape[0]
        off = pc[~np.eye(C, dtype=bool)] if C > 1 else np.zeros(0)
        g = s.geometry(H, y)
        return {"status": MEASURED, "prototype_pairwise_cos": pc.tolist(),
                "prototype_max_offdiag_cos": float(np.nanmax(off)) if off.size and np.isfinite(off).any() else None,
                "collapse_warning": bool(off.size and np.isfinite(off).any() and np.nanmax(off) > 0.996),
                "prototype_norms": be.to_np(be.norm_last(bank.P)).tolist(), "train_subset_geometry": g, "n_subset": len(items)}

    def c14(self) -> dict[str, Any]:
        s, be = self.s, self.s.be
        hits = {}
        for obj in (CortexModel, RelativeActivityController, BucketELL, LayerRuntime, LocalErrorRouter, L1Relay, LocalOutputLearner,
                    PrototypeBank, StageTrainer, Session, Backend, cosine_classify, DestRuntime, build_dest_table, RatioRouter, CodebookLearner,
                    CodebookInitializer, ClassReadout, RatioSessionMixin, RatioTrainerMixin, build_route_table):
            src = inspect.getsource(obj)
            found = [p for p in FORBIDDEN_GRAD_PATTERNS if re.search(p, src)]
            if found:
                hits[getattr(obj, "__name__", str(obj))] = found
        tensors = [s.model.store.q, s.model.store.thr] + [b.P for b in s.protos.values()] + [ro.P for ro in s.readouts.values()]
        rr_ = s.ratio_router()
        if rr_ is not None:
            tensors += list(rr_.C)
        for rt in s.model.rt.values():
            tensors += [w for _i, w in rt.A.parts] + ([w for _i, w in rt.Bm.parts] if rt.Bm else [])
        rg = be.requires_grad_any(tensors)
        ge = be.grad_enabled()
        ok = not hits and not rg and not ge
        return {"status": PASSED if ok else FAILED, "static_forbidden_patterns": hits, "any_tensor_requires_grad": rg,
                "grad_mode_enabled": ge, "backend": be.kind,
                "note_ko": "정적 검사 (학습 경로 소스) + 실행 검사 (requires_grad, grad mode). backward 가 없다는 이유만으로 역전파가 없다고 판단하지 않도록 "
                           "LocalErrorRouter·LocalOutputLearner 의 수식을 주석과 config.json 에 그대로 남겼다."}

    # ---------------------------------------------------------------- 역할 반응 (통제 자극)
    def role_responses(self, quick: bool = False) -> dict[str, Any]:
        s, be = self.s, self.s.be
        S = s.pre.S
        fac = StimulusFactory(S, supersample=2 if quick else 3)
        model = s.model
        areas = list(model.areas)
        lw = max(1.5, S / 48.0)

        def run(imgs: list[np.ndarray], keep: Sequence[str]) -> dict[str, np.ndarray]:
            X = be.f32(np.stack([s.pre.from_array(im) for im in imgs]))
            r = model.forward(X, keep=keep)
            return {k: be.to_np(v["out"]).astype(np.float64) for k, v in r.items()}

        out: dict[str, Any] = {"utc": utc_now(), "model_version": s.model_version(), "image_size": S, "quick": quick}
        const = run([fac.constant(v) for v in (0.0, 0.25, 0.5, 0.75, 1.0)], [f"{a}/L2" for a in areas])
        out["constant_images"] = {k: {"max_abs_out": float(np.abs(v).max())} for k, v in const.items()}
        oris = [float(t) for t in s.cfg["areas"]["V1"]["orientations_deg"]]
        sp2, sp3 = model.specs["V1/L2"], model.specs["V1/L3"]
        o2 = np.asarray(sp2.channel_meta["orientation_deg"])
        o3 = np.asarray(sp3.channel_meta["orientation_deg"])
        lines = [fac.line(t, width=lw) for t in oris] + [fac.line(t, width=lw, fg=0.0, bg=1.0) for t in oris]
        r = run(lines, ["V1/L2", "V1/L3"])

        def tuning(resp: np.ndarray, sp: LayerSpec, chan_ori: np.ndarray) -> np.ndarray:
            m = resp.reshape(resp.shape[0], sp.n_pos, sp.n_ch).mean(axis=1)
            return np.stack([m[:, np.isclose(chan_ori, o)].mean(axis=1) for o in oris], axis=1)

        res_ori = {}
        for key, sp, co in (("V1/L2", sp2, o2), ("V1/L3", sp3, o3)):
            tb = tuning(r[key], sp, co)
            pref = np.asarray(oris)[np.argmax(tb, axis=1)]
            stim = np.asarray(oris * 2)
            err = np.abs(((pref - stim) + 90.0) % 180.0 - 90.0)
            res_ori[key] = {"preferred_matches_stimulus_fraction": float((err <= 7.5).mean()), "mean_abs_error_deg": float(err.mean()),
                            "selectivity_mean": float(((tb.max(1) - tb.mean(1)) / (tb.max(1) + 1e-12)).mean()),
                            "tuning_matrix_bright_lines": tb[:len(oris)].tolist()}
        out["V1_orientation_lines"] = res_ori
        lam = float(np.median(np.asarray(model.specs["V1/L2"].rf))) * float(s.cfg["areas"]["V1"]["gabor_wavelength_factor"])
        lam = max(lam, 4.0)
        phases = [2 * math.pi * k / 8 for k in range(8)]
        rg = run([fac.grating(0.0, lam, ph) for ph in phases], ["V1/L2", "V1/L3"])

        def mod_depth(resp: np.ndarray, sp: LayerSpec, mask: np.ndarray) -> float:
            m = resp.reshape(resp.shape[0], sp.n_pos, sp.n_ch)[:, :, mask].mean(axis=(1, 2))
            return float((m.max() - m.min()) / (m.max() + m.min() + 1e-12))

        out["V1_phase_modulation"] = {
            "grating_wavelength_px": lam, "orientation_deg": 0.0,
            "L2_modulation_depth_by_phase_channel": {str(p): mod_depth(rg["V1/L2"], sp2, np.isclose(o2, 0.0) &
                                                                         np.isclose(np.asarray(sp2.channel_meta["phase_rad"]), p))
                                                     for p in sorted(set(sp2.channel_meta["phase_rad"]))},
            "L3_modulation_depth": mod_depth(rg["V1/L3"], sp3, np.isclose(o3, 0.0)),
            "note_ko": "L3 는 위상×극성 정류 반응의 평균이라 L2 보다 위상 변조가 작을 수 있으나 완전한 위상 불변성은 아니다."}
        if "V2" in areas:
            sp = model.specs["V2/L2"]
            fam = np.asarray(sp.channel_meta["family"])
            ori = np.asarray(sp.channel_meta["orientation_deg"], dtype=object)
            o_arr = np.asarray([float(v) for v in ori])
            seg_len = 2.0 * float(np.median(model.specs["V2/L4"].pos_rf))
            rv = run([fac.line(0.0, width=lw, length=seg_len), fac.line(0.0, width=lw), fac.cross(0.0, 90.0, width=lw)], ["V2/L2"])
            m = rv["V2/L2"].reshape(3, sp.n_pos, sp.n_ch).mean(axis=1)
            es = (fam == "endstop") & np.isclose(o_arr, 0.0)
            cr = (fam == "cross") & np.asarray([sp.channel_meta["orientation2_deg"][k] is not None and
                                                 abs(float(sp.channel_meta["orientation2_deg"][k]) - 90.0) < 1e-6 and abs(o_arr[k]) < 1e-6
                                                 for k in range(sp.n_ch)])
            ct = (fam == "contour") & np.isclose(o_arr, 0.0)
            out["V2_roles"] = {"segment_length_px": seg_len,
                               "endstop_short_over_long": float(m[0, es].mean() / (m[1, es].mean() + 1e-12)) if es.any() else None,
                               "cross_0_90_cross_over_line": float(m[2, cr].mean() / (m[1, cr].mean() + 1e-12)) if cr.any() else None,
                               "contour_0_long_over_short": float(m[1, ct].mean() / (m[0, ct].mean() + 1e-12)) if ct.any() else None}
        if "V4" in areas:
            sp = model.specs["V4/L2"]
            fam = np.asarray(sp.channel_meta["family"])
            rv = run([fac.arc(S / 4.0, width=lw, start_deg=0.0, span_deg=360.0), fac.line(0.0, width=lw), fac.line(90.0, width=lw)], ["V4/L2"])
            m = rv["V4/L2"].reshape(3, sp.n_pos, sp.n_ch).mean(axis=1)
            cv, st_ = fam == "curve", fam == "straight"
            out["V4_roles"] = {"curve_over_straight_for_circle": float(m[0, cv].mean() / (m[0, st_].mean() + 1e-12)) if cv.any() and st_.any() else None,
                               "curve_over_straight_for_lines": float(m[1:, cv].mean() / (m[1:, st_].mean() + 1e-12)) if cv.any() and st_.any() else None}
        shapes = ["circle", "square", "triangle"]
        sz = S * 0.45
        shift = S / 10.0
        imgs = [fac.shape(k, sz) for k in shapes] + [fac.shape(k, sz, center=(shift, 0.0)) for k in shapes]
        rt_ = run(imgs, [])
        trans = {}
        for a in areas:
            H = rt_[f"{a}/L3"]
            n = np.linalg.norm(H, axis=1)
            Hn = H / np.where(n > 0, n, 1.0)[:, None]
            same = [float(Hn[i] @ Hn[i + 3]) for i in range(3)]
            diff = [float(Hn[i] @ Hn[j]) for i in range(3) for j in range(i + 1, 3)]
            trans[a] = {"cos_same_shape_shifted_mean": float(np.mean(same)), "cos_different_shapes_center_mean": float(np.mean(diff)),
                        "zero_vectors": int((n == 0).sum())}
        out["translation"] = {"shift_px": shift, "areas": trans}
        out["status"] = MEASURED
        out["note_ko"] = "역할 반응 측정값이다. 통과 기준이 아니며 역할 설계의 일반적 우월성을 증명하지 않는다."
        if s.rec is not None and not quick:
            s.rec.json(f"diagnostics/role_responses_{local_stamp()}.json", out)
            self._append_index("role_responses", {"utc": out["utc"], "model_version": out["model_version"], "status": MEASURED})
            save_role_figure(s, out)
        return out

    # ---------------------------------------------------------------- 역할 교란 비교 (같은 저장 모델, 비교 모델 학습 없음)
    def perturbation(self, kind: str = "l2_rows_within_position", fraction: float = 0.5, area: str | None = None) -> dict[str, Any]:
        s, be = self.s, self.s.be
        area = area or s.model.active
        if kind == "l2_rows_within_position" and s.model.specs[f"{area}/L2"].ratio is not None:
            return {"utc": utc_now(), "kind": kind, "area": area, "status": NOT_APPLICABLE,
                    "reason_ko": "V4 L2 (v6 비율 라우팅) 는 고정 CSR 행이 아니라 후보 그래프의 선택 묶음으로 전달된다. l4_spatial 교란을 쓴다."}
        snap = self._snapshot()
        rng = np.random.default_rng([int(s.cfg["seed"]), 31, AREA_INDEX[area], int(1000 * fraction)])
        if kind == "l2_rows_within_position":
            key = f"{area}/L2"
            sp = s.model.specs[key]
            sel = rng.choice(sp.n_pos, size=max(1, int(round(fraction * sp.n_pos))), replace=False)
            order = np.arange(sp.n)
            for p in sel:
                order[p * sp.n_ch:(p + 1) * sp.n_ch] = p * sp.n_ch + rng.permutation(sp.n_ch)
            new = self._reorder_rows(sp, order)
            what = f"{key}: 선택 위치 {len(sel)}/{sp.n_pos} 에서 채널 행 (입력 목록·연산) 을 섞음 — q 는 neuron_id 에 남는다"
        elif kind == "l4_spatial":
            key = f"{area}/L4"
            sp = s.model.specs[key]
            src_sp = s.model.specs.get(sp.src_key)
            nps, nch = (src_sp.n_pos, src_sp.n_ch) if src_sp is not None else (s.pre.n_pos, s.pre.n_maps)
            pick = rng.choice(nps, size=max(2, int(round(fraction * nps))), replace=False)
            pm = np.arange(nps)
            pm[pick] = rng.permutation(pick)
            remap = (pm[np.arange(sp.n_src) // nch] * nch + np.arange(sp.n_src) % nch).astype(np.int64)
            new = dataclasses.replace(sp, a_src=remap[sp.a_src], b_src=remap[sp.b_src])
            what = f"{key}: 원천 위치 {len(pick)}/{nps} 를 서로 바꿈 (공간 배치 교란)"
        else:
            raise ValueError(f"알 수 없는 교란 종류: {kind}")
        h_before = s.model.struct_hash[area]
        override = {key: LayerRuntime(new, be, s.cfg)}
        bank = s.classifier(area)

        def remean(ov: dict[str, LayerRuntime] | None) -> PrototypeBank:
            tp = s.pass_split(area, "train", override=ov)
            b = PrototypeBank(area, s.classes, bank.dim, be, bank.eps)
            b.P = tp["sums"] * be.f32((1.0 / np.maximum(tp["counts"], 1))[:, None])
            b.valid = be.to_np(be.norm_last(b.P)) > bank.eps
            return b

        try:
            res = {"original_with_current_prototypes": s.evaluate(area, "dev", bank, purpose="perturbation_original"),
                   "original_with_remeaned_prototypes": s.evaluate(area, "dev", remean(None), purpose="perturbation_original_remean"),
                   "perturbed_with_current_prototypes": s.evaluate(area, "dev", bank, purpose="perturbation_perturbed", override=override),
                   "perturbed_with_remeaned_prototypes": s.evaluate(area, "dev", remean(override), purpose="perturbation_perturbed_remean",
                                                                    override=override)}
        finally:
            restored = self._restore(snap)
        out = {"utc": utc_now(), "kind": kind, "fraction": fraction, "area": area, "what_ko": what,
               "model_version": s.model_version(area), "structure_unchanged_after": s.model.struct_hash[area] == h_before and restored,
               "dev_accuracy": {k: {"overall": v["accuracy_overall"], "correct": v["correct"], "n": v["n"],
                                    "valid_only": v["accuracy_valid_only"]} for k, v in res.items()},
               "status": MEASURED,
               "note_ko": "같은 저장 모델의 고정 평가 비교다 (비교 모델을 학습하지 않음). 이 모델의 역할 의존성을 보여 줄 뿐 역할 설계의 일반적 우월성을 증명하지 않는다. "
                          "remeaned = q 를 바꾸지 않고 train 출력 평균으로 다시 만든 임시 prototype (저장하지 않음)."}
        if s.rec is not None:
            s.rec.json(f"diagnostics/perturbation_{kind}_{local_stamp()}.json", out)
            self._append_index("perturbation", {"utc": out["utc"], "model_version": out["model_version"], "status": MEASURED})
        return out

    @staticmethod
    def _reorder_rows(sp: LayerSpec, order: np.ndarray) -> LayerSpec:
        def csr(ptr: np.ndarray, src: np.ndarray, w: np.ndarray) -> tuple[np.ndarray, np.ndarray, np.ndarray]:
            lens = np.diff(ptr)[order]
            nptr = np.concatenate([[0], np.cumsum(lens)]).astype(np.int64)
            ns = np.concatenate([src[ptr[i]:ptr[i + 1]] for i in order]) if len(src) else src.copy()
            nw = np.concatenate([w[ptr[i]:ptr[i + 1]] for i in order]) if len(w) else w.copy()
            return nptr, ns, nw
        a = csr(sp.a_ptr, sp.a_src, sp.a_w)
        b = csr(sp.b_ptr, sp.b_src, sp.b_w)
        return dataclasses.replace(sp, a_ptr=a[0], a_src=a[1], a_w=a[2], b_ptr=b[0], b_src=b[1], b_w=b[2], op_min=sp.op_min[order])

    # ---------------------------------------------------------------- 최종 test 평가
    def test_evaluation(self) -> dict[str, Any]:
        s = self.s
        area = s.model.active
        prior = int(s.counters["test_evaluations"])
        dc_path = s.rec.p("design_changes.jsonl")
        changes = [json.loads(x) for x in dc_path.read_text(encoding="utf-8").splitlines() if x.strip()] if dc_path.is_file() else []
        info = read_json(s.rec.p("run_info.json")).get("branched_from") if s.rec.p("run_info.json").is_file() else None
        src_tests = int(((info or {}).get("source_counters") or {}).get("test_evaluations", 0))
        test_sha = s.data.ids_sha("test")
        proj = project_test_history(s, test_sha)                   # 이 실행 밖에서 같은 test 집합을 본 이력 (평가 전 상태)
        key = final_test_key(s)
        s.rec.json("diagnostics/test_eval_in_progress.json", {"utc": utc_now(), "key": key, "test_evaluations_before": prior,
                                                             "note_ko": "평가 시작 표시. 결과 저장 전에 끝나면 이 파일이 남는다 (완료로 보지 않는다)."})
        if s.fault == "interrupt_during_test":
            s.fault = None
            s.counters["test_evaluations"] += 1                    # v4 처럼 카운터는 평가 시작 때 오른다 — 미완료 평가를 완료로 오인하지 않는지 검사용
            raise KeyboardInterrupt
        m = s.evaluate(area, "test", s.classifier(area), purpose="final_test_fixed_model")
        indep = {"prior_test_evaluations_this_run": prior, "design_changes_logged": len(changes),
                 "design_changes_after_test_seen": sum(1 for c in changes if c.get("after_test_seen")),
                 "branched_from_run": (info or {}).get("source_run"), "source_run_test_evaluations_before_branch": src_tests,
                 "routing_mode": s.cfg["routing"]["mode"], "test_ids_sha256": test_sha,
                 "project_prior_test_evaluations_same_test_set": proj["n_prior_evaluations"],
                 "project_runs_that_saw_this_test_set": proj["runs"], "project_history_sources": proj["sources"],
                 "counter_definitions_ko": "prior_test_evaluations_this_run = 이 실행 폴더의 test 평가 횟수 (실행 단위 카운터). "
                                           "project_prior_test_evaluations_same_test_set = 같은 저장 폴더의 다른 실행들과 프로젝트 장부 "
                                           "(test_set_history.jsonl) 에서 같은 test 표본 집합을 이미 평가한 횟수 (이 실행 제외). 저장 폴더 밖이나 "
                                           "장부 이전 실행은 알 수 없다."}
        indep["independent_first_look"] = (prior == 0 and src_tests == 0 and indep["design_changes_after_test_seen"] == 0
                                           and proj["n_prior_evaluations"] == 0)
        out = {"utc": utc_now(), "area": area, "model_version": m["model_version"], "checkpoint": s.last_checkpoint,
               "test_evaluation_number": s.counters["test_evaluations"], "metrics": m, "independence": indep,
               "note_ko": "test 는 고정 모델 평가용이다. 이 결과로 설정·에폭·모델·라우팅 모드를 고르지 않는다. 반복 평가, test 를 본 뒤의 설계 변경, "
                          "test 를 본 실행에서의 분기, 같은 test 집합을 다른 실행에서 이미 본 경우는 독립 시험이 아니며 independence 에 기록된다."}
        s.rec.json(f"diagnostics/test_eval_{s.counters['test_evaluations']:03d}.json", out)
        write_final_test_metrics(s, out, key)
        with contextlib.suppress(OSError):
            s.rec.p("diagnostics/test_eval_in_progress.json").unlink()
        if s.fault == "interrupt_after_test_saved":
            s.fault = None
            raise KeyboardInterrupt
        self._append_index("test_eval", {"utc": out["utc"], "model_version": out["model_version"], "status": MEASURED})
        led = project_ledger_path(s)
        if led is not None:
            try:
                with led.open("a", encoding="utf-8") as fh:
                    fh.write(dumps({"utc": out["utc"], "run_dir": str(s.rec.dir), "run_test_evaluation_number": out["test_evaluation_number"],
                                    "test_ids_sha256": test_sha, "model_version": out["model_version"], "routing_mode": s.cfg["routing"]["mode"],
                                    "program_version": VERSION}, indent=None) + "\n")
            except OSError as exc:
                s.rec.warn(f"프로젝트 test 장부 쓰기 실패 ({led}): {exc}")
        try:
            build_result_summary(s)                                # 최종 test 뒤 보고서 갱신 ('미실행' 으로 남지 않게)
        except Exception as exc:                                   # noqa: BLE001  (test 기록은 이미 저장됨)
            s.rec.warn(f"test 평가 뒤 보고서 갱신 실패: {type(exc).__name__}: {exc}")
        return out

    def state_summary(self) -> dict[str, Any]:
        s = self.s
        q = s.model.store.q_numpy()
        ne = s.cfg["neuron"]
        out = {"model_version": s.model_version(), "areas": {}}
        for a in s.model.areas:
            row = {"stage_status": s.stage[a]["status"], "epochs_completed": s.stage[a]["epochs_completed"],
                   "best_dev_accuracy": s.stage[a]["best_dev_accuracy"], "frozen": a in s.frozen,
                   "prototype_version": s.classifier(a).version, "prototype_valid": s.classifier(a).valid.tolist(),
                   "stage_policy": s.stage_policy(a), "learning": ("V4 codebook only (q fixed)" if s.is_ratio_area(a) else "v4 L1 local q + prototype EMA")}
            if s.is_ratio_area(a):
                row.update(selected_epoch_number=s.stage[a].get("selected_epoch_number"), selected_restored=s.stage[a].get("selected_restored"),
                           codebook_sha256=s.codebook_sha(), codebook_version=s.ratio_router().version)
            for lay in LAYER_ORDER:
                sp = s.model.specs[f"{a}/{lay}"]
                qq = q[sp.start:sp.end]
                row[lay] = {"q_mean": float(qq.mean()), "q_min": float(qq.min()), "q_max": float(qq.max()),
                            "n_at_q_min": int((qq <= float(ne["q_min"])).sum()), "n_at_q_max": int((qq >= float(ne["q_max"])).sum())}
            out["areas"][a] = row
        return out


def project_ledger_path(sess: Session) -> Path | None:
    root = sess.output_root or (sess.rec.dir.parent if sess.rec else None)
    return Path(root) / "test_set_history.jsonl" if root else None


def project_test_history(sess: Session, test_sha: str) -> dict[str, Any]:
    """같은 저장 폴더에서 같은 test 표본 집합을 이미 평가한 이력 (이 실행 제외).
    원천: 프로젝트 장부 test_set_history.jsonl + 형제 실행 폴더의 diagnostics/test_eval_*.json (장부 이전 v1·v2 실행 포함)."""
    me = str(sess.rec.dir.resolve()) if sess.rec else ""
    seen: dict[tuple[str, int], str] = {}
    led = project_ledger_path(sess)
    sources = []
    if led is not None and led.is_file():
        sources.append(str(led))
        for line in led.read_text(encoding="utf-8", errors="replace").splitlines():
            try:
                e = json.loads(line)
            except ValueError:
                continue
            rd = str(Path(e.get("run_dir", "")).resolve()) if e.get("run_dir") else ""
            if e.get("test_ids_sha256") == test_sha and rd and rd != me:
                seen[(rd, int(e.get("run_test_evaluation_number", 0)))] = "ledger"
    root = led.parent if led is not None else None
    if root is not None and root.is_dir():
        sources.append(f"{root}/*/diagnostics/test_eval_*.json")
        for d in sorted(x for x in root.iterdir() if x.is_dir()):
            rd = str(d.resolve())
            if rd == me:
                continue
            man = d / "split_manifest.json"
            tests = sorted((d / "diagnostics").glob("test_eval_*.json")) if (d / "diagnostics").is_dir() else []
            if not tests or not man.is_file():
                continue
            try:
                items = read_json(man).get("items", [])
                sha = sha256_text("\n".join(sorted(it["relpath"] for it in items if it.get("split") == "test")))
            except (OSError, ValueError, KeyError, TypeError):
                continue
            if sha != test_sha:
                continue
            for t in tests:
                try:
                    n = int(read_json(t).get("test_evaluation_number", 0))
                except (OSError, ValueError, TypeError):
                    continue
                seen.setdefault((rd, n), "run_folder_scan")
    return {"n_prior_evaluations": len(seen), "runs": sorted({k[0] for k in seen}), "sources": sources}


# ======================================================================
# 16b. 최종 test 결과 저장 (중복 방지 키) · V4 역할·정보 보존 측정 · 전체 실험 일괄 실행기 · REPORT.md
# ======================================================================
FINAL_TEST_FILE = "final_test_metrics.json"
EXPERIMENT_FILE = "experiment_manifest.json"
VALIDATION_FILE = "validation_results.json"


def final_test_key(sess: Session) -> dict[str, str]:
    """최종 평가의 중복 방지 키 = 전체 최종 모델 상태 해시 + test 표본 집합 해시 + 평가 설정 (카운터만으로 완료를 판단하지 않는다)."""
    s = sess
    model = {"q": sha256_array(s.model.store.q_numpy()), "structure": s.model.struct_hash, "active": s.model.active,
             "prototypes": {a: b.sha() for a, b in s.protos.items()}, "readouts": {a: ro.sha() for a, ro in s.readouts.items()},
             "codebook_V4": s.codebook_sha(), "routing_mode": s.cfg["routing"]["mode"]}
    model_sha = sha256_text(dumps(model, indent=None))
    test_sha = s.data.ids_sha("test")
    settings = {"area": s.model.active, "classifier": "cosine_argmax", "eps_norm": s.cfg["learning"]["eps_norm"],
                "preprocessing_sha256": sha256_text(dumps(s.pre.info(), indent=None)), "config_structure_sha256": config_structure_sha(s.cfg)}
    set_sha = sha256_text(dumps(settings, indent=None))
    return {"model_state_sha256": model_sha, "test_ids_sha256": test_sha, "eval_settings_sha256": set_sha,
            "key": sha256_text(model_sha + test_sha + set_sha)}


def write_final_test_metrics(sess: Session, out: dict[str, Any], key: dict[str, str]) -> Path:
    """final_test_metrics.json (원자적 저장) 과 final_test_history.jsonl. 같은 run 의 보고서·이어하기는 이 결과를 재사용한다."""
    m = out["metrics"]
    rec = {"format": f"{PROGRAM}/final_test/1", "utc": out["utc"], "key": key, "area": out["area"], "model_version": out["model_version"],
           "checkpoint": out["checkpoint"], "test_evaluation_number": out["test_evaluation_number"],
           "accuracy": m["accuracy_overall"], "correct": m["correct"], "n": m["n"], "accuracy_valid_only": m["accuracy_valid_only"],
           "n_unknown_zero_vector": m["n_unknown_zero_vector"], "per_class": m["per_class"], "per_class_accuracy": m["per_class_accuracy"],
           "confusion": m["confusion"], "confusion_columns": m["confusion_columns"], "independence": out["independence"],
           "stage_policy_ko": STAGE_POLICY_KO, "v4_selected_epoch_number": (sess.stage.get("V4") or {}).get("selected_epoch_number"),
           "note_ko": out["note_ko"]}
    p = sess.rec.json(FINAL_TEST_FILE, rec)
    sess.rec.append_jsonl("final_test_history.jsonl", {k: rec[k] for k in ("utc", "key", "model_version", "checkpoint", "test_evaluation_number",
                                                                             "accuracy", "correct", "n")})
    return p


def read_final_test(sess: Session) -> dict[str, Any] | None:
    p = sess.rec.p(FINAL_TEST_FILE) if sess.rec is not None else None
    if p is None or not p.is_file():
        return None
    try:
        return read_json(p)
    except (OSError, ValueError):
        return None


def append_validation(sess: Session, context: str, summary: dict[str, Any]) -> None:
    """validation_results.json: 검사 실행마다 PASSED/FAILED/NOT_RUN (측정은 MEASURED) 과 실행 환경·허용 오차·원인을 누적한다."""
    r = sess.need_rec()
    p = r.p(VALIDATION_FILE)
    cur = read_json(p) if p.is_file() else {"program": PROGRAM, "program_version": VERSION, "runs": []}
    cur["runs"].append({"utc": utc_now(), "context": context, "status": summary.get("status"), "model_version": summary.get("model_version"),
                        "environment": summary.get("environment") or sess.be.describe(), "n_failed": summary.get("n_failed"),
                        "n_not_run": summary.get("n_not_run"),
                        "checks": {k: {kk: vv for kk, vv in v.items() if kk in ("status", "reason_ko", "error", "tolerance", "seconds", "rule_ko")}
                                   for k, v in (summary.get("checks") or {}).items() if isinstance(v, dict)}})
    cur["utc"] = utc_now()
    r.json(p.name, cur)


class RatioRoleProbes:
    """V4 (v6 모드) 통제 자극 측정: 역할 계열별 선택·양의 출력 비율, 선택됐지만 출력 0, V4 L4 → L2 → L3 를 지나며 방향·공간·형상 구별이
    사라지는지 (최근접 복호·서로 다른 패턴 수·평균 코사인), 서로 다른 L2 선택 코드가 L3 이웃 평균 뒤 같아지는 쌍. 측정값 (MEASURED) 이며 통과 기준이 아니다."""

    def __init__(self, sess: Session):
        self.s = sess

    def stimuli(self) -> dict[str, list[tuple[str, np.ndarray, dict[str, Any]]]]:
        S = self.s.pre.S
        fac = StimulusFactory(S, supersample=2)
        lw = max(1.5, S / 48.0)
        oris = [float(t) for t in self.s.cfg["areas"]["V1"]["orientations_deg"]]
        out: dict[str, list[tuple[str, np.ndarray, dict[str, Any]]]] = {"orientation": [], "position": [], "shape": []}
        for off in (0, 1):
            for o in oris:
                t_ = math.radians(o + 90.0)
                c = (off * S / 10.0 * math.cos(t_), off * S / 10.0 * math.sin(t_))
                out["orientation"].append((f"line_{o:g}_off{off}", fac.line(o, width=lw, center=c), {"orientation": o, "offset": off}))
        for k in range(8):
            a_ = 2 * math.pi * k / 8
            c = (S / 4.0 * math.cos(a_), S / 4.0 * math.sin(a_))
            out["position"].append((f"disc_{k}", fac.shape("circle", S / 8.0, center=c, fg=1.0, bg=0.0), {"position": k}))
        out["shape"] = [("arc", fac.arc(S / 4.0, width=lw, start_deg=0.0, span_deg=150.0), {"kind": "curve"}),
                        ("line", fac.line(0.0, width=lw), {"kind": "straight"}),
                        ("corner", fac.corner(0.0, 90.0, width=lw), {"kind": "corner"}),
                        ("cross", fac.cross(0.0, 90.0, width=lw), {"kind": "cross"}),
                        ("line_end", fac.rgb(fac.line_mask(0.0, width=lw, half=True)), {"kind": "line_end"})]
        return out

    def run(self, context: str = "manual") -> dict[str, Any]:
        s, be = self.s, self.s.be
        m = s.model
        if m is None or m.ratio_runtime() is None or "V4" not in m.areas:
            return {"status": NOT_RUN, "reason_ko": "v6 비율 라우팅 V4 가 아직 없다."}
        t = m.ratio_routers["V4"].t
        keys = ["V4/L4", "V4/L2", "V4/L3"]
        rows: list[dict[str, Any]] = []
        res_all: dict[str, Any] = {"utc": utc_now(), "context": context, "model_version": s.model_version(), "probes": {}}
        oris = np.asarray([float(x) for x in s.cfg["areas"]["V1"]["orientations_deg"]])
        thr = float(s.cfg["neuron"]["threshold"])

        def add(probe: str, key: str, metric: str, value: Any, n: int) -> None:
            v = _fnum(value) if not isinstance(value, (int, np.integer)) else int(value)
            rows.append({"utc": res_all["utc"], "context": context, "model_version": res_all["model_version"], "probe": probe,
                         "area": key.split("/")[0], "layer": key.split("/")[1] if "/" in key else key, "metric": metric, "value": v, "n_stimuli": n})

        for probe, stims in self.stimuli().items():
            X = be.f32(np.stack([s.pre.from_array(im) for _n, im, _m in stims]))
            res = m.forward(X, upto="V4", keep=keys, routing_record=True)
            n = len(stims)
            pr: dict[str, Any] = {}
            for key in keys:
                H = be.to_np(res[key]["out"]).astype(np.float64)
                nr = np.linalg.norm(H, axis=1)
                ok = nr > 0
                Hn = H[ok] / nr[ok, None]
                pc = Hn @ Hn.T if ok.sum() >= 2 else np.zeros((0, 0))
                off = pc[~np.eye(len(Hn), dtype=bool)] if len(Hn) >= 2 else np.zeros(0)
                scale = np.abs(H).max() if H.size else 0.0
                distinct = len({tuple(np.round(h / scale, 6)) for h in H}) if scale > 0 else (1 if n else 0)
                d = {"zero_vector_frac": float(1.0 - ok.mean()), "mean_pairwise_cos": float(off.mean()) if off.size else None, "distinct_patterns": distinct}
                if probe == "orientation":
                    k_ = len(oris)
                    tr, te = H[:k_], H[k_:]
                    trn, ten = np.linalg.norm(tr, axis=1), np.linalg.norm(te, axis=1)
                    hit = 0
                    for i in range(k_):
                        if ten[i] > 0 and (trn > 0).any():
                            cs = np.where(trn > 0, (tr @ te[i]) / np.where(trn > 0, trn, 1.0) / ten[i], -np.inf)
                            hit += int(int(np.argmax(cs)) == i)
                    d["nn_orientation_decoding_across_offset"] = hit / k_
                for mk, mv in d.items():
                    add(probe, key, mk, mv, n)
                pr[key] = d
            recs = route_rec_np(be, res["V4/L2"]["ratio"]["buckets"])
            codes = [tuple(np.concatenate([np.where(r_["has"][i], r_["k"][i], -1) for r_ in recs]).tolist()) for i in range(n)]
            H3 = be.to_np(res["V4/L3"]["out"]).astype(np.float64)
            diff_code = merged = 0
            for i in range(n):
                for j in range(i + 1, n):
                    if codes[i] != codes[j]:
                        diff_code += 1
                        merged += int(np.allclose(H3[i], H3[j], rtol=1e-7, atol=1e-12))
            add(probe, "V4/L2", "distinct_selection_codes", len(set(codes)), n)
            add(probe, "V4/L2", "pairs_with_different_L2_codes", diff_code, n)
            add(probe, "V4/L3", "pairs_different_L2_code_but_same_L3", merged, n)
            sel = sum(int(r_["has"].sum()) for r_ in recs)
            zero = sum(int((r_["has"] & (r_["u_sel"] <= thr)).sum()) for r_ in recs)
            add(probe, "V4/L2", "selected_but_zero_output_frac", (zero / sel) if sel else None, n)
            pr["V4/codes"] = {"distinct": len(set(codes)), "pairs_diff": diff_code, "pairs_merged_at_L3": merged}
            if probe == "shape":
                for i, (nm, _im, _meta) in enumerate(stims):
                    for fname in t.family_names:
                        pos = tot = 0
                        for b, bk in enumerate(t.buckets):
                            if t.family_names[bk.family] != fname:
                                continue
                            h_ = recs[b]["has"][i]
                            tot += int(h_.sum())
                            pos += int((h_ & (recs[b]["u_sel"][i] > thr)).sum())
                        add(f"shape_{nm}", "V4/L2", f"{fname}_selected_positive_output_frac", (pos / tot) if tot else None, 1)
            res_all["probes"][probe] = pr
        dev = s.data.items("dev")[:min(64, len(s.data.items("dev")))]
        if dev:
            lgn, y = s.loader.batch(dev, "dev")
            s.counters["dev_evaluations"] = int(s.counters["dev_evaluations"])     # 진단도 dev 를 읽는다 (loader 읽기 수에 남는다, 갱신 없음)
            res = m.forward(lgn, upto="V4", keep=keys)
            sep = {}
            for key in keys:
                H = be.to_np(res[key]["out"]).astype(np.float64)
                sep[key] = s.geometry(H, y)
                for mk in ("between_class_mean_cos", "within_class_mean_cos_to_class_mean", "zero_vector_fraction"):
                    add("dev_class_separation", key, mk, sep[key].get(mk), len(dev))
            res_all["dev_class_separation"] = sep
        for row in rows:
            s.need_rec().append_csv(ROLE_CSV, row)
        res_all["status"] = MEASURED
        res_all["note_ko"] = ("통제 자극·dev 일부의 측정값이다. 통과 기준이 아니며 역할 설계의 우월성·생물학적 기능을 입증하지 않는다. "
                              "pairs_different_L2_code_but_same_L3 = 서로 다른 L2 선택이 L3 이웃 평균 뒤 같아진 쌍 (구별력 손실).")
        s.need_rec().json(f"diagnostics/role_probes_V4_{re.sub(r'[^A-Za-z0-9_]+', '_', context)}_{local_stamp()}.json", res_all)
        return res_all


