class BatchStop(RuntimeError):
    """일괄 실행을 멈춰야 하는 조건 (검사 실패·중단·수치 손상 등). 후속 단계는 실행하지 않는다."""

    def __init__(self, status: str, msg: str):
        super().__init__(msg)
        self.status = status


class ExperimentRunner:
    """메뉴 10·11 과 --run-all 이 같이 쓰는 공용 실행기. 수동 메뉴가 쓰는 내부 함수 (set_paths → scan_and_split → plan_next/build_area →
    StageTrainer.run → add_next_area_prepare/commit → Diagnostics·비율 검사 → test_evaluation → save_all_figures/build_result_summary) 를 그대로 부른다.
    처음 설정 이후 단계마다 입력을 묻지 않는다. 상태는 experiment_manifest.json 에 단계별로 남기고, 이어하기는 완료 단계를 건너뛴다."""

    def __init__(self, sess: Session, *, say: Callable[[str], None] = print, internal: bool = False):
        self.s = sess
        self.say = say
        self.internal = bool(internal)
        self.man: dict[str, Any] = {}

    # ---------------------------------------------------------------- 계획·manifest
    @staticmethod
    def default_plan(cfg: dict[str, Any]) -> dict[str, Any]:
        le = cfg["learning"]
        return {"stage_max_epochs": {a: int(le["max_epochs"]) for a in AREA_ORDER}, "patience": int(le["patience"]),
                "batch_size": int(le["batch_size"]), "seed": int(cfg["seed"]), "download_allowed": bool(cfg["data"]["mnist_download"]),
                "dataset": cfg["data"]["source"], "routing_mode": cfg["routing"]["mode"],
                "advance_policy_ko": ("비V4 (V1·V2·IT) 는 유효한 종료 상태 (success_criterion_met·plateau·budget_exhausted), V4 는 유효한 선택 스냅샷을 "
                                      "확보하면 묻지 않고 다음 단계로 간다. 중단·비유한 수치·검사 FAILED 는 멈춘다."),
                "stage_policy_ko": STAGE_POLICY_KO}

    def _mpath(self) -> Path:
        return self.s.need_rec().p(EXPERIMENT_FILE)

    def _save(self) -> None:
        self.man["updated_utc"] = utc_now()
        write_json(self._mpath(), self.man)

    def _new_manifest(self, plan: dict[str, Any]) -> None:
        s = self.s
        self.man = {"format": f"{PROGRAM}/experiment/1", "run_id": s.rec.dir.name, "run_dir": str(s.rec.dir), "program": PROGRAM,
                    "program_version": VERSION, "source_sha256": s.program_sha(), "created_utc": utc_now(), "updated_utc": utc_now(),
                    "internal_test_mode": self.internal, "plan": plan, "plan_sha256": sha256_text(dumps(plan, indent=None)),
                    "config_structure_sha256": config_structure_sha(s.cfg), "config_learning_sha256": config_learning_sha(s.cfg),
                    "environment": s.be.describe(), "resume_count": 0, "final_test": None,
                    "steps": {sid: {"status": "PENDING", "title_ko": title, "started_utc": None, "ended_utc": None, "attempts": 0,
                                    "input_checkpoint": None, "input_checkpoint_sha256": None, "output_checkpoint": None, "artifacts": [],
                                    "error": None, "note": None} for sid, title in EXP_STEPS}}
        self._save()

    def _ckpt_sha(self) -> tuple[str | None, str | None]:
        s = self.s
        name = s.last_checkpoint
        if not name or s.rec is None:
            return None, None
        p = s.rec.p(f"checkpoints/{name}.npz")
        return name, (sha256_file(p) if p.is_file() else None)

    def _begin(self, sid: str) -> None:
        st = self.man["steps"][sid]
        st["status"] = "RUNNING"
        st["attempts"] = int(st.get("attempts", 0)) + 1
        st["started_utc"] = st["started_utc"] or utc_now()
        st["input_checkpoint"], st["input_checkpoint_sha256"] = self._ckpt_sha()
        st["error"] = None
        self._save()
        self.say(f"\n[일괄 {sid}] {st['title_ko']} (시도 {st['attempts']})")

    def _end(self, sid: str, status: str, *, note: str | None = None, artifacts: Sequence[str] = (), error: str | None = None) -> None:
        st = self.man["steps"][sid]
        st["status"] = status
        st["ended_utc"] = utc_now()
        st["output_checkpoint"] = self.s.last_checkpoint
        if note:
            st["note"] = note
        if artifacts:
            st["artifacts"] = sorted(set(list(st.get("artifacts") or []) + [str(a) for a in artifacts]))
        if error:
            st["error"] = error
        self._save()
        self.say(f"[일괄 {sid}] {status}" + (f" — {note}" if note else "") + (f" — 오류: {error}" if error else ""))

    # ---------------------------------------------------------------- 시작·이어하기
    @classmethod
    def start_new(cls, cfg: dict[str, Any], be: Backend, data_root: Path, output_root: Path, plan: dict[str, Any] | None = None, *,
                  say: Callable[[str], None] = print, internal: bool = False) -> "ExperimentRunner":
        sess = Session(cfg, be, say=say, confirm=lambda _m: True)
        sess.batch_internal = bool(internal)
        sess.set_paths(data_root, output_root)
        run = cls(sess, say=say, internal=internal)
        sess.start_run()
        run._new_manifest(plan or cls.default_plan(sess.cfg))
        return run

    @classmethod
    def resume(cls, run_dir: Path, be: Backend, *, say: Callable[[str], None] = print, data_root: Path | None = None) -> "ExperimentRunner":
        run_dir = Path(run_dir)
        mp = run_dir / EXPERIMENT_FILE
        if not mp.is_file():
            raise CompatibilityError(f"{run_dir} 에 {EXPERIMENT_FILE} 이 없다 (일괄 실행으로 만든 run 이 아니다). 메뉴 4 로 수동 재개한다.")
        man = read_json(mp)
        if man.get("program") != PROGRAM:
            raise CompatibilityError(f"다른 프로그램 ({man.get('program')}) 의 일괄 실행이다.")
        has_ckpt = (run_dir / "checkpoints" / "latest.json").is_file()
        if has_ckpt:
            sess = Session.load(run_dir, be, say=say, confirm=lambda _m: True, data_root=data_root)
        else:                                                        # 데이터 분할 전 (모델·checkpoint 없음) 에 멈춘 run
            cf = read_json(run_dir / "config.json")
            sess = Session(saved_config_with_mode(cf["config"]), be, say=say, confirm=lambda _m: True)
            info = read_json(run_dir / "run_info.json")
            sess.rec = RunRecorder(run_dir, say=say)
            sess.set_paths(Path(data_root or info.get("data_root") or man["plan"].get("data_root") or "."), Path(info["output_root"]))
            if (run_dir / "split_manifest.json").is_file():
                smf = read_json(run_dir / "split_manifest.json")
                sess.data = DatasetManager.from_manifest(sess.cfg, sess.data_root, smf)
                probs = sess.data.verify_files()
                if probs:
                    raise CompatibilityError("데이터가 분할 목록과 다르다: " + "; ".join(probs[:5]))
                sess.loader = BatchLoader(sess.data, sess.pre, be, sess.cfg, sess.timer)
        sess.batch_internal = bool(man.get("internal_test_mode"))
        if man.get("config_structure_sha256") != config_structure_sha(sess.cfg) or man.get("config_learning_sha256") != config_learning_sha(sess.cfg):
            raise CompatibilityError("experiment_manifest 와 실행 설정 해시가 다르다 (설정을 바꾸면 새 run 으로 분기한다).")
        if man.get("source_sha256") != sess.program_sha():
            sess.rec.warn("일괄 실행을 시작한 프로그램 파일과 지금 파일의 SHA256 이 다르다 (코드 변경). 결과 해석에 주의한다.")
        run = cls(sess, say=say, internal=bool(man.get("internal_test_mode")))
        run.man = man
        man["resume_count"] = int(man.get("resume_count", 0)) + 1
        for sid, st in man["steps"].items():
            if st["status"] == "RUNNING":                       # 프로세스가 단계 도중 끝났다 (Stop 버튼·전원) → 중단으로 본다
                st["status"] = "INTERRUPTED"
                st["note"] = (st.get("note") or "") + " [이어하기 시점에 RUNNING 이었다: 중단으로 처리]"
        man.setdefault("resumes", []).append({"utc": utc_now(), "checkpoint": sess.last_checkpoint, "model_version": sess.model_version() if sess.model else None})
        run._save()
        return run

    # ---------------------------------------------------------------- 실행
    def run(self) -> dict[str, Any]:
        steps = {"s01_setup": self.step_setup, "s02_checks": self.step_checks, "s03_data": self.step_data,
                 "s04_V1": lambda: self.step_area("V1"), "s05_V2": lambda: self.step_area("V2"), "s06_V4": lambda: self.step_area("V4"),
                 "s07_IT": lambda: self.step_area("IT"), "s08_diagnostics": self.step_diagnostics, "s09_test": self.step_test,
                 "s10_report": self.step_report}
        final = "COMPLETED"
        for sid, _title in EXP_STEPS:
            st = self.man["steps"][sid]
            if st["status"] == "COMPLETED":
                continue
            self._begin(sid)
            try:
                note = steps[sid]() or None
                self._end(sid, "COMPLETED", note=note)
            except BatchStop as exc:
                self._end(sid, exc.status, error=str(exc))
                final = exc.status
                break
            except KeyboardInterrupt:
                rr_ = self.s.ratio_router()
                if self.s.model is not None and self.s.model.areas and (rr_ is None or rr_.initialized):
                    with contextlib.suppress(Exception):
                        self.s.save_checkpoint(f"batch_{sid}_interrupted", keep=True)
                self._end(sid, "INTERRUPTED", error="사용자 중단 (Ctrl+C). 11) 이어하기 또는 --run-all --resume 으로 이 단계부터 이어 간다.")
                final = "INTERRUPTED"
                break
            except Exception as exc:                             # noqa: BLE001
                with contextlib.suppress(Exception):
                    self.s.rec.error(f"일괄 {sid} 실패", exc)
                self._end(sid, "FAILED", error=f"{type(exc).__name__}: {exc}"[:800])
                final = "FAILED"
                break
        if final != "COMPLETED":
            for sid, _t in EXP_STEPS:
                if self.man["steps"][sid]["status"] == "PENDING":
                    self.man["steps"][sid]["note"] = "앞 단계가 끝나지 않아 실행하지 않았다 (의존 단계 중단)."
            self._save()
            with contextlib.suppress(Exception):
                build_report(self.s, partial=True)
        self.man["final_status"] = final
        self._save()
        return {"status": final, "manifest": str(self._mpath()), "run_dir": str(self.s.rec.dir), "steps": {k: v["status"] for k, v in self.man["steps"].items()},
                "final_test": self.man.get("final_test"), "report": str(self.s.rec.p("REPORT.md"))}

    # ---------------------------------------------------------------- 단계
    def step_setup(self) -> str:
        s = self.s
        env = DeviceManager.environment(s.be)
        s.rec.json("environment.json", env)
        plan = self.man["plan"]
        s.rec.json("experiment_plan.json", {"utc": utc_now(), "plan": plan, "plan_sha256": self.man["plan_sha256"], "data_root": str(s.data_root),
                                             "output_root": str(s.output_root), "backend": s.be.describe(), "internal_test_mode": self.internal,
                                             "steps": [{"id": a, "title_ko": b} for a, b in EXP_STEPS]})
        self.man["plan"]["data_root"], self.man["plan"]["output_root"] = str(s.data_root), str(s.output_root)
        return f"뒷단 {s.be.kind}/{s.be.device}, 데이터 {s.data_root}, 저장 {s.rec.dir}, PyTorch {'있음' if torch is not None else '없음 (NumPy 경로)'}"

    def step_checks(self) -> str:
        s = self.s
        rc = RatioChecks(s)
        if self.internal:                                           # 합성 내부 검사 모드: 일괄 검사 (V18·V19·V23) 로 다시 들어가지 않는다
            summ = rc.structure_checks(context="batch_internal_step2")
            append_validation(s, "batch_internal_step2_structure", summ)
            if summ["status"] == FAILED:
                raise BatchStop("FAILED", f"구조 검사 FAILED {summ['n_failed']} 개 (validation_results.json)")
            return f"내부 검사 모드: 구조 검사 {summ['status']}"
        syn = rc.synthetic_suite(s.rec.p("validation"), context="batch_step2")
        append_validation(s, "batch_step2_synthetic_V01_V23", syn)
        st_ = rc.structure_checks(context="batch_step2_real_config")
        append_validation(s, "batch_step2_real_config_structure", st_)
        nf = int(syn["n_failed"]) + int(st_["n_failed"])
        if nf:
            raise BatchStop("FAILED", f"구현 필수 검사 FAILED {nf} 개 — 후속 학습을 멈춘다 (validation_results.json 의 원인 확인)")
        nr = int(syn["n_not_run"]) + int(st_["n_not_run"])
        return f"합성 검사 실패 0, 미실행 {nr} (환경상 선택 검사; '모든 검사 통과' 가 아니다)" if nr else "합성·구조 검사 실패 0"

    def step_data(self) -> str:
        s = self.s
        if s.data is not None:
            return "이미 분할이 있다 (재사용)"
        rep, man = s.scan_and_split(progress=self.say)
        self.say(f"  클래스 {man['classes']}, 항목 {man['n_items']}")
        return f"클래스 {len(man['classes'])}, 항목 {man['n_items']}, 분할 해시 {man['split_sha256'][:12]}"

    def _check_after(self, area: str, when: str) -> dict[str, Any]:
        """영역 생성 직후·학습 종료 후 기본 검사·상태·동결 검사 (어느 단계에서 문제가 생겼는지 남긴다). 구현 필수 FAILED 는 멈춘다."""
        s = self.s
        d = Diagnostics(s)
        r = d.run_basic()
        append_validation(s, f"{area}_{when}_basic", r)
        out = {"basic": r["status"]}
        out["role_responses"] = "MEASURED (run_basic C13_role_responses_quick)"
        if s.is_ratio_area(area):
            rr = RatioChecks(s).model_checks(context=f"{area}_{when}", subset="stage")
            append_validation(s, f"{area}_{when}_ratio", rr)
            out["ratio"] = rr["status"]
            if rr["status"] == FAILED:
                raise BatchStop("FAILED", f"{area} {when} V4 비율 검사 FAILED (validation_results.json)")
        if r["status"] == FAILED:
            raise BatchStop("FAILED", f"{area} {when} 기본 검사 FAILED (diagnostics/basic_*.json)")
        bad = {a: v for a, v in s.frozen_check().items() if not all(v.values())}
        if bad:
            raise BatchStop("FAILED", f"동결 영역 상태가 바뀌었다: {bad}")
        return out

    def step_area(self, area: str) -> str:
        s = self.s
        plan = self.man["plan"]
        limit = int(plan["stage_max_epochs"][area])
        if s.model is None or area not in s.model.areas:
            if area == "V1":
                a, specs, summ = s.plan_next()
                print_summary_table(summ, say=self.say)
                s.build_area(a, specs, summ)
            else:
                cur = s.model.active
                stc = s.stage[cur]
                ok_prev = stc["status"] in STAGE_TERMINAL and (not s.is_ratio_area(cur) or stc.get("selected_restored") or s.ratio_best is not None)
                if not ok_prev:
                    raise BatchStop("FAILED", f"앞 단계 {cur} 가 유효하게 끝나지 않았다 (상태 {stc['status']}) — 다음 영역을 만들지 않는다.")
                a, specs, summ, info = s.add_next_area_prepare()
                print_summary_table(summ, say=self.say)
                s.add_next_area_commit(a, specs, summ, info, user_choice="batch_auto_progress")
            st = s.stage[area]
            st["max_epochs"] = limit                                 # 절대 에폭 한도 (이어하기에서 다시 더하지 않는다)
            st["patience"] = int(plan["patience"])
            st["budget_changes"].append({"utc": utc_now(), "kind": "batch_plan_absolute_limit", "to_max_epochs": limit})
            s.save_checkpoint(f"{area}_batch_planned", keep=True)
            self._check_after(area, "created")
        st = s.stage[area]
        if st["status"] == "not_started" and int(st["epochs_completed"]) == 0 and int(st["max_epochs"]) != limit:
            st["max_epochs"] = limit                                 # 생성 직후 (학습 전) 에 멈춘 경우만: 계획 한도를 다시 적용 (예산 증가 아님)
        if st["status"] in STAGE_TERMINAL and (not s.is_ratio_area(area) or st.get("selected_restored")):
            note = f"이미 '{st['status']}' 로 끝났다 (추가 학습 없음)"
        else:
            if int(st["max_epochs"]) != limit:
                raise BatchStop("FAILED", f"{area} 에폭 한도 {st['max_epochs']} 가 계획 {limit} 와 다르다 (예산 변조 방지).")
            self.say(f"  {area} 학습: 절대 에폭 한도 {limit}, 완료 {st['epochs_completed']}, 다음 배치 {st['next_batch']} (Ctrl+C 한 번: 배치 경계에서 멈춤)")
            stop_after = None
            if s.fault == "interrupt_during_V2_after_batches" and area == "V2":    # 일괄 이어하기 검사 (V19) 용 주입
                s.fault = None
                stop_after = 1
            res = StageTrainer(s).run(stop_after_batches=stop_after)
            print_train_result(res, say=self.say)
            if res["status"] not in STAGE_TERMINAL:
                if str(res["status"]).startswith("interrupted"):
                    raise BatchStop("INTERRUPTED", f"{area} 학습 중단 ({res['status']}) — checkpoint {res.get('checkpoint')}")
                raise BatchStop("FAILED", f"{area} 학습 실패 ({res['status']}): {res.get('message_ko')}")
            note = (f"{res['status']}, 완료 에폭 {res.get('epochs_completed')}, best dev {fmt(res.get('best_dev_accuracy'))}"
                    + (f", 선택 epoch_number {res.get('selected_epoch_number')} 복원" if s.is_ratio_area(area) else ", 종료 상태 사용"))
        chk = self._check_after(area, "trained")
        with contextlib.suppress(Exception):
            save_training_figure(s, area)
            save_prototype_figure(s, area)
        return f"{note}; 검사 {chk}"

    def step_diagnostics(self) -> str:
        s = self.s
        d = Diagnostics(s)
        rr = d.role_responses()
        out = [f"역할 반응 {rr['status']}"]
        if s.model.ratio_runtime() is not None:
            rp = RatioRoleProbes(s).run(context="batch_final")
            out.append(f"V4 역할·정보 보존 {rp['status']}")
            iso = RatioChecks(s).model_checks(context="batch_final_isolation", subset="isolation")
            append_validation(s, "batch_final_isolation", iso)
            out.append(f"상태 격리 {iso['status']}")
            if iso["status"] == FAILED:
                raise BatchStop("FAILED", "최종 모델 상태 격리 검사 FAILED")
        bad = {a: v for a, v in s.frozen_check().items() if not all(v.values())}
        if bad:
            raise BatchStop("FAILED", f"동결 상태가 바뀌었다: {bad}")
        s.save_checkpoint("batch_diagnostics_done", keep=True)
        return ", ".join(out)

    def step_test(self) -> str:
        s = self.s
        if s.model is None or s.model.active != "IT" or s.stage["IT"]["status"] not in STAGE_TERMINAL:
            raise BatchStop("FAILED", "IT 학습이 끝나지 않았다 — test 를 평가하지 않는다.")
        if s.ratio_mode and not (s.frozen.get("V4") and s.frozen_check().get("V4", {}).get("codebook_unchanged")):
            raise BatchStop("FAILED", "V4 동결 (선택 스냅샷) 을 확인할 수 없다 — test 를 평가하지 않는다.")
        key = final_test_key(s)
        prev = read_final_test(s)
        if prev is not None and (prev.get("key") or {}).get("key") == key["key"]:
            self.man["final_test"] = {"status": "COMPLETED", "reused": True, "key": key, "test_evaluation_number": prev["test_evaluation_number"],
                                      "accuracy": prev["accuracy"], "correct": prev["correct"], "n": prev["n"], "checkpoint": prev["checkpoint"]}
            self._save()
            return f"이미 완료된 최종 평가를 재사용 (#{prev['test_evaluation_number']}, test 재호출 없음)"
        inprog = s.rec.p("diagnostics/test_eval_in_progress.json")
        rerun = None
        if inprog.is_file():
            ip = read_json(inprog)
            rerun = {"previous_attempt": ip, "note_ko": "이전 최종 평가가 결과 저장 전에 끝났다 (미완료). 다시 실행한 사실을 기록한다."}
            self.man.setdefault("final_test_reruns", []).append(rerun)
        out = Diagnostics(s).test_evaluation()
        self.man["final_test"] = {"status": "COMPLETED", "reused": False, "key": key, "test_evaluation_number": out["test_evaluation_number"],
                                  "accuracy": out["metrics"]["accuracy_overall"], "correct": out["metrics"]["correct"], "n": out["metrics"]["n"],
                                  "checkpoint": out["checkpoint"], "rerun_after_incomplete": bool(rerun)}
        self._save()
        s.save_checkpoint("batch_test_done", keep=True)
        m = out["metrics"]
        return f"test {pct_count(m['correct'], m['n'])} (#{out['test_evaluation_number']})" + (" — 미완료 평가 뒤 재실행" if rerun else "")

    def step_report(self) -> str:
        s = self.s
        figs = save_all_figures(s)
        s.consolidate_sample_routes()
        build_result_summary(s)
        p = build_report(s)
        return f"그림 {len(figs)}, 보고서 {p.name}"


# ---------------------------------------------------------------- REPORT.md (저장된 JSON/CSV 에서만 만든다)
def _md_table(header: Sequence[str], rows: Sequence[Sequence[Any]]) -> list[str]:
    out = ["| " + " | ".join(header) + " |", "|" + "|".join("---" for _ in header) + "|"]
    for r_ in rows:
        out.append("| " + " | ".join("" if v is None else str(v) for v in r_) + " |")
    return out


def build_report(sess: Session, partial: bool = False) -> Path:
    s = sess
    r = s.need_rec()
    L: list[str] = [f"# REPORT — {PROGRAM} v{VERSION}" + (" (부분 보고서: 실행이 끝나지 않았다)" if partial else ""), "",
                    f"- 생성 UTC {utc_now()}, 실행 폴더 `{r.dir}`, 모드 `{s.cfg['routing']['mode']}`, 뒷단 {s.be.kind}/{s.be.device}",
                    f"- 현재 모델 `{s.model_version() if s.model else '없음'}`, 마지막 checkpoint `{s.last_checkpoint}`",
                    f"- {STAGE_POLICY_KO}",
                    "- 이 보고서의 숫자는 저장된 파일 (training_metrics.csv·routing_metrics.csv·codebook_metrics.csv·role_probe_metrics.csv·"
                    "validation_results.json·final_test_metrics.json·experiment_manifest.json) 에서 읽었다. 성능 개선을 보장하지 않는다.", ""]
    mp = r.p(EXPERIMENT_FILE)
    if mp.is_file():
        man = read_json(mp)
        L += ["## 일괄 실행 단계", ""]
        L += _md_table(["단계", "상태", "시도", "시작", "끝", "메모·오류"],
                       [[k, v["status"] + (" (이 보고서를 만드는 단계)" if k == "s10_report" and v["status"] == "RUNNING" else ""), v.get("attempts"),
                         v.get("started_utc"), v.get("ended_utc"), (v.get("error") or v.get("note") or "")[:160]]
                        for k, v in man["steps"].items()])
