        return {"status": r["status"], "checks": st, "errors": {k: v.get("error") for k, v in r["checks"].items() if v.get("error")},
                "not_run": {k: v.get("reason_ko") for k, v in r["checks"].items() if v.get("status") == NOT_RUN}}

