    def st19() -> dict[str, Any]:
        mod = v1_module()
        if mod is None:
            return {"status": NOT_RUN, "reason_ko": "원본 v1 파일 (cortex_local_learning_v1.py) 이 같은 폴더에 없다 (routing.legacy_reference_path 로 지정)."}
        c1 = mod.validate_config({k: v for k, v in SELFTEST_CONFIG.items() if k != "routing"})
        b1 = mod.DeviceManager.create("numpy", "cpu", c1)
        S1 = mod.Session(c1, b1, say=quiet)
        S1.set_paths(data_dir, runs)
        S1.scan_and_split()
        a_, sp_, su_ = S1.plan_next()
        S1.build_area(a_, sp_, su_)
        S1.stage["V1"]["max_epochs"] = 1
        mod.StageTrainer(S1).run()
        nx, sp_, su_, inf_ = S1.add_next_area_prepare()
        S1.add_next_area_commit(nx, sp_, su_, inf_, user_choice="self_test")
        S1.save_checkpoint("v1_program_run", keep=True)
        src_sha = tree_sha(S1.rec.dir)
        Lv = Session.load(S1.rec.dir, be, say=quiet, read_only=True)
        same_q = bool(np.array_equal(Lv.model.store.q_numpy(), S1.model.store.q_numpy()))
        same_hash = dict(Lv.model.struct_hash) == dict(S1.model.struct_hash)
        it = Lv.data.items("dev")[:3]
        x1, _ = S1.loader.batch(it, "dev")
        x2, _ = Lv.loader.batch(it, "dev")
        o1 = np.asarray(S1.model.forward(x1)["V2/L3"]["out"])
        o2 = be.to_np(Lv.model.forward(x2)["V2/L3"]["out"])
        diff = float(np.abs(o1 - o2).max())
        N = Session.branch(S1.rec.dir, be, mode="v1_guided", say=quiet)
        ok = (Lv.cfg["routing"]["mode"] == "legacy" and same_q and same_hash and diff <= (1e-6 if be.kind == "numpy" else 1e-4)
              and "-R" not in Lv.model_version() and N.model.routing_runtime() is not None and tree_sha(S1.rec.dir) == src_sha)
        return {"status": PASSED if ok else FAILED, "loaded_mode": Lv.cfg["routing"]["mode"], "q_identical": same_q, "structure_hash_identical": same_hash,
                "max_abs_V2L3_diff": diff, "model_version": Lv.model_version(), "branch_to_v1_guided_V4": N.model.routing_runtime() is not None,
                "v1_run_unchanged": tree_sha(S1.rec.dir) == src_sha, "v1_file": str(Path(mod.__file__))}

    def st20() -> dict[str, Any]:
        A = new_session()
        A.stage["V1"]["max_epochs"] = 1
        StageTrainer(A).run()
        B = new_session()
        B.stage["V1"]["max_epochs"] = 1
        g0 = be.max_gather
        B.fault = "oom_once"
        try:
            r = StageTrainer(B).run()
        finally:
            g1 = be.max_gather
            be.max_gather = g0
        ev = [json.loads(x) for x in B.rec.p("oom_events.jsonl").read_text(encoding="utf-8").splitlines()] if B.rec.p("oom_events.jsonl").is_file() else []
        same = bool(np.array_equal(A.model.store.q_numpy(), B.model.store.q_numpy()))
        ok = r["status"] in STAGE_TERMINAL and len(ev) == 1 and g1 < g0 and same and be.kind == B.be.kind
        return {"status": PASSED if ok else FAILED, "oom_events": len(ev), "max_gather_before": g0, "max_gather_after_retry": g1,
                "q_identical_to_run_without_fault": same, "backend_unchanged": B.be.kind, "result": r["status"],
                "note_ko": "주입한 메모리 부족 1 회 → 같은 배치를 줄인 gather 조각으로 다시 계산 (CPU 로 바꾸지 않음)."}

    def st21() -> dict[str, Any]:
        s = main.get("branch_band_gated")
        if s is None:
            return {"status": NOT_RUN, "reason_ko": "ST23 의 band_gated 분기 실행이 없다."}
        build_result_summary(s)
        need = ["effective_config.json", "routing/candidate_edges.npz", "routing/band_static_summary.json", "routing/band_routing_summary.csv",
                "routing/band_calibration.npz", "routing/band_calibration.json", "routing/band_candidates_by_ring_orientation.csv"]
        have = {f: s.rec.p(f).is_file() for f in need}
        samples = sorted(s.rec.p("routing").glob("band_samples_V4_*.npz"))
        rows = s.rec.read_csv("routing/band_routing_summary.csv")
        ctx = sorted({r_["context"] for r_ in rows})
        before = [r_ for r_ in s.rec.read_csv("training.csv") if r_.get("row_kind") == "before_training"]
        z = load_npz(samples[0]) if samples else {}
        keys_ok = all(k in z for k in ("sample_id", "x", "z", "g", "contribution_share", "A", "B", "u", "all_gates_low", "missing_candidate", "cand_valid")) if samples else False
        ce = load_npz(s.rec.p("routing/candidate_edges.npz")) if have["routing/candidate_edges.npz"] else {}
        ce_ok = all(k in ce for k in ("dst_neuron_id", "src_neuron_id", "src_A_neuron_id", "w0", "cand_valid", "P_x_px", "P_y_px", "Q_x_px", "Q_y_px", "dst_role"))
        summ = s.rec.p("result_summary.md").read_text(encoding="utf-8") if s.rec.p("result_summary.md").is_file() else ""
        eff = read_json(s.rec.p("effective_config.json")) if have["effective_config.json"] else {}
        sp = s.model.specs["V4/L2"]
        j = int(sp.band.curve_rows[int(np.argmax(sp.band.n_cand))])
        info = s.inspect_neuron(sp.start + j, s.data.items("train")[0])
        ro = info.get("routing") or {}
        ts = ro.get("this_sample") or {}
        share_sum = sum(c_["contribution_share"] for c_ in (ts.get("per_candidate") or []))
        txt = NeuronInspector.format(info)
        ok = (all(have.values()) and bool(samples) and keys_ok and ce_ok and {"dev_before_training", "train_epoch", "dev_eval"} <= set(ctx)
              and len(before) == len(s.model.areas) and "생물학적 주파수 공명을 구현한 것이 아니며" in summ and "band" in eff
              and ro.get("kind") == "band_curve_neuron" and abs(share_sum - 1.0) < 1e-3 and len(ro.get("static_candidates", [])) == int(sp.band.n_cand.max())
              and bool(txt))
        return {"status": PASSED if ok else FAILED, "files": have, "band_sample_parts": len(samples), "sample_keys": sorted(z) if samples else [],
                "candidate_edges_keys_ok": ce_ok, "summary_contexts": ctx, "before_training_rows": len(before),
                "inspect_curve_neuron_share_sum": share_sum, "inspect_static_candidates": len(ro.get("static_candidates", []))}

    def st23() -> dict[str, Any]:
        L = main.get("legacy_run")
        if L is None:
            return {"status": NOT_RUN, "reason_ko": "ST18 의 legacy 실행이 없다."}
        src_sha = tree_sha(L.rec.dir)
        out, ok = {}, True
        for mode in ("band_gated", "expanded_pool"):
            msgs: list[str] = []
            N = Session.branch(L.rec.dir, be, mode=mode, say=msgs.append)
            br = N.model.band_runtime()
            same_q = all(np.array_equal(N.model.store.q_numpy()[N.model.specs[f"{a}/{l}"].start:N.model.specs[f"{a}/{l}"].end],
                                        L.model.store.q_numpy()[L.model.specs[f"{a}/{l}"].start:L.model.specs[f"{a}/{l}"].end])
                         for a in ("V1", "V2") for l in LAYER_ORDER)
            cal_msg = [m_ for m_ in msgs if "구간 보정" in m_]
            lgn, _y = N.loader.batch(N.data.items("dev")[:3], "dev")
            r = N.model.forward(lgn, keep=("V4/L4", "V4/L2"))
            ref = band_reference_B(br.table, br.calibration, be.to_np(be.pad_zero_col(r["V4/L4"]["out"])).astype(np.float64), N.cfg, mode)["B"]
            good_B, err = _close(be.to_np(r["V4/L2"]["band"]["B"]), ref, 2e-5)
            cj = read_json(N.rec.p("routing/band_calibration.json"))
            N.stage["V4"]["max_epochs"] = 1
            res = StageTrainer(N).run()
            fc = N.frozen_check()
            g = (same_q and br is not None and br.mode == mode and br.calibration is not None and bool(cal_msg) and good_B
                 and cj["used_in_forward"] == (mode == "band_gated") and res["status"] in STAGE_TERMINAL and all(all(v.values()) for v in fc.values())
                 and N.model_version().endswith("-Rbnd" if mode == "band_gated" else "-Rexp"))
            ok &= g
            out[mode] = {"ok": g, "q_V1V2_identical": same_q, "calibration_messages": cal_msg[:3], "B_rel_err_vs_reference": err,
                         "used_in_forward": cj["used_in_forward"], "V4_train": res["status"], "model_version": N.model_version()}
            main[f"branch_{mode}"] = N
        ok &= tree_sha(L.rec.dir) == src_sha
        return {"status": PASSED if ok else FAILED, "source_run_unchanged": tree_sha(L.rec.dir) == src_sha, **out}

